        bool showApplicationCloseDialog = HasArgument(args, "--show-application-close-dialog");
        bool showCrashRecoveryDialog = HasArgument(args, "--show-crash-recovery-dialog");
        bool showGraphicsCapabilityDialog = HasArgument(args, "--show-graphics-capability-dialog");
        bool labelsOnly = HasArgument(args, "--labels-only");
        bool segmentationCandidates = HasArgument(args, "--segmentation-candidates");
        bool smartMaskCandidate = HasArgument(args, "--smart-mask-candidate");
        bool smartMaskCandidateComparison = HasArgument(args, "--smart-mask-candidate-comparison");
        bool smartMaskShowInitialCandidate = HasArgument(args, "--smart-mask-show-initial-candidate");
        bool smartMaskPromptOnly = HasArgument(args, "--smart-mask-prompt-only");
        bool smartMaskCorrectionExpanded = HasArgument(args, "--smart-mask-correction-expanded");
        bool smartMaskAutoContourEnabled = HasArgument(args, "--smart-mask-auto-contour-enabled");
        string smartMaskPromptBox = GetArgumentValue(args, "--smart-mask-prompt-box", string.Empty);
        string smartMaskPositivePoint = GetArgumentValue(args, "--smart-mask-positive-point", string.Empty);
        string smartMaskNegativePoint = GetArgumentValue(args, "--smart-mask-negative-point", string.Empty);
        bool preserveDatasetOutput = roiOnly &&
            !string.IsNullOrWhiteSpace(datasetOutputRoot) &&
            Directory.Exists(datasetOutputRoot);
        var temporaryVisualSmokeRoots = new List<string>();
        if (preserveDatasetOutput)
        {
            string sourceOutputRoot = Path.GetFullPath(datasetOutputRoot);
            datasetOutputRoot = Path.Combine(Path.GetTempPath(), "ovl-visual-dataset-" + Guid.NewGuid().ToString("N"));
            temporaryVisualSmokeRoots.Add(datasetOutputRoot);
            foreach (string sourcePath in Directory.EnumerateFiles(sourceOutputRoot, "*", SearchOption.AllDirectories))
            {
                string relativePath = Path.GetRelativePath(sourceOutputRoot, sourcePath);
                if (relativePath.Replace('\\', '/').Contains("/images/", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string targetPath = Path.Combine(datasetOutputRoot, relativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(targetPath) ?? datasetOutputRoot);
                File.Copy(sourcePath, targetPath, overwrite: true);
            }
        }
        if (roiOnly)
        {
            reviewTab = string.IsNullOrWhiteSpace(reviewTab) ? "objects" : reviewTab;
            annotationTool = string.IsNullOrWhiteSpace(annotationTool) ? "rectangle" : annotationTool;
        }

        try
        {
            if (System.Windows.Application.Current == null)
            {
                _ = new System.Windows.Application
                {
                    ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
                };
            }

            string root = null;
            try
            {
                string imagePath = GetArgumentValue(args, "--image", string.Empty);
                if (string.IsNullOrWhiteSpace(imagePath) || !File.Exists(imagePath))
                {
                    imagePath = ResolveVisualSmokeImagePath();
                }

                if (string.IsNullOrWhiteSpace(imagePath) || !File.Exists(imagePath))
                {
                    root = CreateTempRoot();
                    imagePath = Path.Combine(root, "visual-check.jpg");
                    CreateVisualSmokeImage(imagePath);
                }

                Size imageSize = GetImageSize(imagePath);

                if (!string.IsNullOrWhiteSpace(datasetOutputRoot) && Directory.Exists(datasetOutputRoot))
                {
                    CGlobal.Inst.Data.ConfigureOutputRoot(Path.GetFullPath(datasetOutputRoot));
                    if (!string.IsNullOrWhiteSpace(datasetPurpose))
                    {
                        CGlobal.Inst.Data.ProjectSettings.DatasetPurpose = ParseVisualSmokeDatasetPurpose(datasetPurpose);
                    }

                    string[] classNames = datasetClasses
                        .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
                        .Select(name => name.Trim())
                        .Where(name => name.Length > 0)
                        .ToArray();
                    if (classNames.Length > 0)
                    {
                        CGlobal.Inst.Data.ClassNamedList.Clear();
                        for (int i = 0; i < classNames.Length; i++)
                        {
                            CGlobal.Inst.Data.ClassNamedList.Add(new CClassItem
                            {
                                Text = classNames[i],
                                DrawColor = i switch
                                {
                                    0 => Color.FromArgb(46, 194, 106),
                                    1 => Color.FromArgb(239, 68, 68),
                                    _ => Color.DeepSkyBlue
                                }
                            });
                        }
                    }
                }

                if (openDatasetInterchange)
                {
                    string interchangeDatasetRoot = CGlobal.Inst.Data.OutputRootPath;
                    bool hasInterchangeImages = !string.IsNullOrWhiteSpace(datasetOutputRoot)
                        && Directory.Exists(interchangeDatasetRoot)
                        && Directory.EnumerateFiles(
                            interchangeDatasetRoot,
                            "*",
                            SearchOption.AllDirectories)
                            .Any(path => ExeSmokeImageArtifactExtensions.Contains(
                                Path.GetExtension(path),
                                StringComparer.OrdinalIgnoreCase));
                    if (!hasInterchangeImages)
                    {
                        interchangeDatasetRoot = Path.Combine(
                            Path.GetTempPath(),
                            "ovl-interchange-source-" + Guid.NewGuid().ToString("N"));
                        temporaryVisualSmokeRoots.Add(interchangeDatasetRoot);
                        CGlobal.Inst.Data.ConfigureOutputRoot(interchangeDatasetRoot);
                        CGlobal.Inst.Data.ProjectSettings.DatasetPurpose = LabelingDatasetPurpose.ObjectDetection;
                        CGlobal.Inst.Data.ProjectSettings.YoloDataset.ValidationPercent = 0;
                        CGlobal.Inst.Data.ProjectSettings.YoloDataset.TestPercent = 0;
                        CGlobal.Inst.Data.ClassNamedList.Clear();
                        var visualClass = new CClassItem
                        {
                            Text = "Defect",
                            DrawColor = Color.FromArgb(239, 68, 68)
                        };
                        CGlobal.Inst.Data.ClassNamedList.Add(visualClass);
                        using Bitmap interchangeImage = CreateSolidBitmap(320, 220, Color.FromArgb(35, 42, 52));
                        var visualRois = new Dictionary<string, List<CRectangleObject>>
                        {
                            ["Defect"] = new List<CRectangleObject>
                            {
                                new CRectangleObject
                                {
                                    Roi = new Rectangle(72, 48, 116, 92),
                                    cClassItem = visualClass
                                }
                            }
                        };
                        YoloAnnotationService.SaveAnnotations(
                            "interchange-sample.png",
                            interchangeImage,
                            visualRois,
                            CGlobal.Inst.Data.ClassNamedList,
                            CGlobal.Inst.Data);
                    }
                }

                WpfLabelingShellWindow window = new WpfLabelingShellWindow
                {
                    Width = Math.Max(VisualSmokeMinimumWindowWidth, windowWidth),
                    Height = Math.Max(VisualSmokeMinimumWindowHeight, windowHeight),
                    Left = screenCapture ? 0 : 24,
                    Top = screenCapture ? 0 : 24,
                    WindowStartupLocation = System.Windows.WindowStartupLocation.Manual,
                    Topmost = true
                };

                try
                {
                    window.Show();
                    if (screenCapture)
                    {
                        PlaceExeSmokeWindowOnLeftmostMonitor(
                            new System.Windows.Interop.WindowInteropHelper(window).Handle,
                            windowWidth,
                            windowHeight);
                    }
                    ApplyVisualSmokeTheme(window, theme);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    AssertTrue(
                        window.TryLoadImage(
                            imagePath,
                            populateQueue: !preserveDatasetOutput,
                            refreshQueueDetails: false,
                            refreshActiveStatus: !preserveDatasetOutput,
                            appendLoadLog: !preserveDatasetOutput && !savedAnnotationsOnly),
                        "WPF visual smoke image load failed");
                    if (!preserveDatasetOutput && !string.IsNullOrWhiteSpace(datasetPurpose))
                    {
                        InvokePrivateResult<object>(
                            window,
                            "ApplyDatasetPurposeToCurrentProject",
                            ParseVisualSmokeDatasetPurpose(datasetPurpose));
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(150));
                    }

                    if (anomalyDashboard)
                    {
                        ApplyVisualSmokeAnomalyDashboard(window, imagePath, temporaryVisualSmokeRoots);
                    }

                    if (qualityDashboard)
                    {
                        ApplyVisualSmokeQualityDashboard(window, imagePath, temporaryVisualSmokeRoots);
                    }

                    if (missingModelRuntime)
                    {
                        string missingRuntimeRoot = Path.Combine(Path.GetTempPath(), "ovl-missing-model-runtime-" + Guid.NewGuid().ToString("N"));
                        temporaryVisualSmokeRoots.Add(missingRuntimeRoot);
                        string missingRuntimePython = Path.Combine(missingRuntimeRoot, ".venv", "Scripts", "python.exe");
                        Directory.CreateDirectory(Path.GetDirectoryName(missingRuntimePython) ?? missingRuntimeRoot);
                        Directory.CreateDirectory(Path.Combine(missingRuntimeRoot, ".venv", "Lib", "site-packages"));
                        File.WriteAllText(missingRuntimePython, "python");
                        CGlobal.Inst.Data.ProjectSettings ??= new LabelingProjectSettings();
                        CGlobal.Inst.Data.ProjectSettings.PythonModel = new PythonModelSettings
                        {
                            PythonExecutablePath = missingRuntimePython,
                            ModelEngine = PythonModelSettings.EngineYolo11,
                            ProjectRootPath = missingRuntimeRoot,
                            ClientScriptPath = Path.Combine(missingRuntimeRoot, "labelling_tcp_client.py"),
                            WeightsPath = Path.Combine(missingRuntimeRoot, "best.pt"),
                            ImageRootPath = Path.GetDirectoryName(imagePath) ?? string.Empty
                        };
                        window.YoloModelSettingsViewModel?.LoadFrom(CGlobal.Inst.Data.ProjectSettings.PythonModel);
                        InvokePrivateResult<object>(window, "RefreshYoloStatus");
                        InvokePrivateResult<object>(window, "UpdateYoloCommandButtons");
                    }
                    else if (ultralyticsRuntimeReady)
                    {
                        ApplyVisualSmokeUltralyticsRuntimeReady(window, imagePath, temporaryVisualSmokeRoots);
                    }
                    else if (unetRuntimeReady)
                    {
                        ApplyVisualSmokeUnetRuntimeReady(window, imagePath);
                    }

                    if (!string.IsNullOrWhiteSpace(modelEngine)
                        && window.YoloModelSettingsViewModel != null)
                    {
                        window.YoloModelSettingsViewModel.SelectedModelEngine =
                            PythonModelSettings.NormalizeModelEngine(modelEngine);
                        InvokePrivateResult<object>(window, "RefreshYoloStatus");
                        InvokePrivateResult<object>(window, "UpdateYoloCommandButtons");
                    }

                    var candidates = roiOnly || savedAnnotationsOnly
                        ? new List<YoloWorkerSmokeCandidate>()
                        : string.IsNullOrWhiteSpace(patchCoreHeatmapPath)
                            ? CreateVisualSmokeCandidates(imageSize, segmentationCandidates)
                            : CreateVisualSmokePatchCoreCandidate(imageSize, patchCoreHeatmapPath);
                    if (!roiOnly && seedDuplicate)
                    {
                        SeedVisualSmokeDuplicateLabel(window, candidates);
                    }

                    if (!roiOnly
                        && !savedAnnotationsOnly
                        && !anomalyReviewOnly
                        && window.FindName("InferenceModeButton") is System.Windows.Controls.Control inferenceModeButton)
                    {
                        window.ShellViewModel.InferenceModeCommand.Execute(null);
                    }

                    if (!roiOnly && !savedAnnotationsOnly && !anomalyReviewOnly)
                    {
                        InvokePrivateResult<object>(window, "ApplyDetectionCandidates", candidates, true);
                        if (openPatchCoreHeatmap)
                        {
                            window.CandidateReviewViewModel.TogglePatchCoreHeatmapCommand.Execute(null);
                            AssertTrue(
                                window.CandidateReviewViewModel.IsPatchCoreHeatmapOpen,
                                "PatchCore heatmap visual fixture did not open the explicit preview");
                            PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                            WpfPatchCoreHeatmapWindow heatmapWindow = System.Windows.Application.Current.Windows
                                .OfType<WpfPatchCoreHeatmapWindow>()
                                .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                            AssertTrue(heatmapWindow != null, "PatchCore heatmap visual fixture did not create the owned evidence window");
                            IntPtr heatmapHandle = new System.Windows.Interop.WindowInteropHelper(heatmapWindow).Handle;
                            AssertTrue(GetWindowRect(heatmapHandle, out NativeRect heatmapRect), "PatchCore heatmap evidence window bounds were unavailable");
                            Screen leftmostScreen = Screen.AllScreens.OrderBy(screen => screen.Bounds.Left).First();
                            var heatmapBounds = Rectangle.FromLTRB(heatmapRect.Left, heatmapRect.Top, heatmapRect.Right, heatmapRect.Bottom);
                            AssertTrue(leftmostScreen.Bounds.IntersectsWith(heatmapBounds), "PatchCore heatmap evidence window should inherit the leftmost owner monitor");
                            Console.WriteLine($"EXE_SMOKE_CHILD_WINDOW=PatchCoreHeatmap MONITOR={leftmostScreen.DeviceName} BOUNDS={heatmapBounds.Left},{heatmapBounds.Top},{heatmapBounds.Width},{heatmapBounds.Height}");
                            heatmapWindow.Activate();
                            heatmapWindow.UpdateLayout();
                            CaptureWindow(heatmapWindow, outputPath);
                            patchCoreHeatmapCaptured = true;
                        }
                        if (confirmAllCandidates)
                        {
                            InvokePrivate(window, "ExecuteConfirmAllCandidatesCommand");
                            PumpWpfDispatcher(TimeSpan.FromMilliseconds(350));
                            if (editConfirmedLabelClass)
                            {
                                EditVisualSmokeConfirmedLabelClass(window);
                                if (saveAfterConfirmedLabelEdit)
                                {
                                    SaveVisualSmokeCurrentAnnotations(window);
                                }
                            }
                        }
                        else
                        {
                            SeedVisualSmokeObjects(window, reviewTab, imageSize);
                            if (showQualityNeedsFix)
                            {
                                SaveVisualSmokeCurrentAnnotations(window);
                            }
                        }
                    }

                    if (selectMaskObject)
                    {
                        SelectVisualSmokeMaskObject(window);
                    }
                    if (selectMergeSegments)
                    {
                        foreach (WpfObjectReviewListItem item in window.ObjectReviewViewModel.Objects
                            .Where(item => item.IsManualSegment)
                            .Take(2))
                        {
                            item.IsMergeSelected = true;
                            window.ObjectReviewViewModel.MergeSelectionChangedCommand.Execute(item);
                        }
                    }

                    if (showObjectMetadata)
                    {
                        WpfObjectMetadataStateService metadataState =
                            GetPrivateField<WpfObjectMetadataStateService>(
                                window,
                                "objectMetadataStateService");
                        metadataState.ToggleManualRoiOccluded(0);
                        metadataState.ToggleManualRoiTag(0, "\uAC80\uC218 \uD544\uC694");
                        window.ObjectReviewViewModel.SetMetadataTagDefinitions(
                            new[] { "\uAC80\uC218 \uD544\uC694", "\uACBD\uACC4 \uD655\uC778" });
                        InvokePrivateResult<object>(window, "RefreshObjectList");
                        window.ObjectReviewViewModel.SelectedMetadataTagFilter = "\uAC80\uC218 \uD544\uC694";
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(150));
                    }

                    if (showObjectGroup)
                    {
                        WpfObjectMetadataStateService metadataState =
                            GetPrivateField<WpfObjectMetadataStateService>(
                                window,
                                "objectMetadataStateService");
                        List<System.Drawing.Rectangle> visualRois =
                            GetPrivateField<List<System.Drawing.Rectangle>>(window, "manualRois");
                        List<string> visualRoiClasses =
                            GetPrivateField<List<string>>(window, "manualRoiClassNames");
                        if (visualRois.Count == 1)
                        {
                            System.Drawing.Rectangle firstBounds = visualRois[0];
                            visualRois.Add(new System.Drawing.Rectangle(
                                firstBounds.X + Math.Max(12, firstBounds.Width / 2),
                                firstBounds.Y + Math.Max(12, firstBounds.Height / 2),
                                firstBounds.Width,
                                firstBounds.Height));
                            visualRoiClasses.Add(visualRoiClasses.FirstOrDefault() ?? "Defect");
                            InvokePrivate(window, "RedrawReviewRois");
                        }
                        string groupId = Guid.NewGuid().ToString("N");
                        if (visualRois.Count > 1)
                        {
                            metadataState.SetManualRoiGroupId(0, groupId);
                            metadataState.SetManualRoiGroupId(1, groupId);
                        }
                        window.ObjectReviewViewModel.SetMetadataTagDefinitions(
                            new[] { "\uAC80\uC218 \uD544\uC694", "\uACBD\uACC4 \uD655\uC778" });
                        InvokePrivateResult<object>(window, "RefreshObjectList");
                        window.ObjectReviewViewModel.SelectedObject =
                            window.ObjectReviewViewModel.Objects.FirstOrDefault(item =>
                                string.Equals(item.GroupId, groupId, StringComparison.Ordinal));
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(150));
                    }

                    SelectVisualSmokeReviewTab(window, reviewTab);
                    EnsureVisualSmokeRightWorkflowExpanded(window, expandRightWorkflow);
                    PrepareVisualSmokeGuidePanel(window, reviewTab, expandLearningConcepts, focusTemplateWorkflow, expandLabelingDetails, focusYoloValidationReport, focusDatasetDashboard);
                    if (showQualityNeedsFix)
                    {
                        const string visualQualityNote = "경계가 흐려 마스크 수정 필요";
                        window.ObjectReviewViewModel.QualityReviewNoteText = visualQualityNote;
                        window.ObjectReviewViewModel.MarkQualityNeedsFixCommand.Execute(null);
                        window.ObjectReviewViewModel.ExportQualityReviewReportCommand.Execute(null);
                        var qualityFilterBox = window.FindName("ImageQueueFilterBox") as System.Windows.Controls.ComboBox;
                        if (qualityFilterBox != null)
                        {
                            qualityFilterBox.SelectedItem = qualityFilterBox.Items
                                .OfType<WpfImageQueueFilterOption>()
                                .FirstOrDefault(option => option.Filter == WpfImageQueueFilter.NeedsFix);
                        }

                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                        AssertTrue(window.ObjectReviewViewModel.IsQualityNeedsFixActive,
                            "quality visual smoke did not activate the needs-fix state");
                        AssertEqual(visualQualityNote, window.ObjectReviewViewModel.QualityReviewNoteText);
                        AssertTrue(window.ObjectReviewViewModel.IsMarkQualityReviewedEnabled,
                            "saved needs-fix image should allow the operator to mark quality review complete");
                        AssertTrue(qualityFilterBox?.SelectedItem is WpfImageQueueFilterOption selectedQualityFilter
                            && selectedQualityFilter.Filter == WpfImageQueueFilter.NeedsFix,
                            "quality visual smoke did not select the issue-only queue filter");
                        string qualityReportPath = YoloImageQualityReviewReportExportService.ResolveDefaultOutputPath(CGlobal.Inst.Data);
                        AssertTrue(File.Exists(qualityReportPath), "quality visual smoke did not export the local QA report");
                        AssertTrue(File.ReadAllText(qualityReportPath).Contains(visualQualityNote, StringComparison.Ordinal),
                            "quality visual smoke report did not contain the current issue reason");
                    }
                    if (showTrainingRecoveryStatus)
                    {
                        ApplyVisualSmokeTrainingRecoveryStatus(window);
                    }

                    window.UpdateLayout();
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(1200));
                    ApplyVisualSmokeZoom(window, zoomSteps);
                    CloseAuxiliaryVisualSmokeWindows(window);
                    BringVisualSmokeWindowToFront(window);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    CloseAuxiliaryVisualSmokeWindows(window);
                    BringVisualSmokeWindowToFront(window);
                    SelectVisualSmokeReviewTab(window, reviewTab);
                    EnsureVisualSmokeRightWorkflowExpanded(window, expandRightWorkflow);
                    PrepareVisualSmokeGuidePanel(window, reviewTab, expandLearningConcepts, focusTemplateWorkflow, expandLabelingDetails, focusYoloValidationReport, focusDatasetDashboard);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(350));
                    CloseAuxiliaryVisualSmokeWindows(window);
                    BringVisualSmokeWindowToFront(window);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    CloseAuxiliaryVisualSmokeWindows(window);
                    BringVisualSmokeWindowToFront(window);
                    if (showBusyInferenceStatus)
                    {
                        InvokePrivateResult<object>(window, "SetGlobalInferenceStatus", "AI inference visual check", true, false);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    if (showFailedInferenceStatus)
                    {
                        InvokePrivateResult<object>(
                            window,
                            "SetGlobalInferenceStatus",
                            "실패: Python 모델 클라이언트가 연결되지 않아 현재 검사 요청을 보내지 못했습니다.",
                            false,
                            true);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    if (showBatchFailedBaselineStatus)
                    {
                        InvokePrivateResult<object>(
                            window,
                            "SetGlobalInferenceStatus",
                            "\uC77C\uAD04 \uC2E4\uD328: 0/3",
                            false,
                            true);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    if (showBatchFailedInferenceStatus)
                    {
                        InvokePrivateResult<object>(
                            window,
                            "SetGlobalInferenceStatus",
                            "\uC77C\uAD04 \uC2E4\uD328: 0/3 / Python \uBAA8\uB378 \uD074\uB77C\uC774\uC5B8\uD2B8\uAC00 \uC5F0\uACB0\uB418\uC9C0 \uC54A\uC544 \uC77C\uAD04 \uAC80\uC0AC \uC694\uCCAD\uC744 \uBCF4\uB0B4\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4.",
                            false,
                            true);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    if (showBatchFailureResultCard)
                    {
                        InvokePrivateResult<object>(
                            window,
                            "ShowBatchDetectionFailureResult",
                            WpfImageQueueItem.CreateShell(imagePath),
                            new YoloWorkerSmokeTestResult
                            {
                                Succeeded = false,
                                ImagePath = imagePath,
                                Summary = "Detection request failed.",
                                Candidates = Array.Empty<YoloWorkerSmokeCandidate>()
                            });
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    if (showAnomalyEvaluationLeakageStatus)
                    {
                        const string leakageStatus =
                            "\uC774\uC0C1 \uBD84\uB958 \uD3C9\uAC00 \uC2E4\uD589 \uBD88\uAC00: \uD3C9\uAC00 \uB370\uC774\uD130 \uB204\uC218: test normal/abnormal\uC5D0 \uAE38\uC774+SHA-256\uC774 \uAC19\uC740 \uC774\uBBF8\uC9C0 \uCF58\uD150\uCE20 1\uAC74\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uAC19\uC740 \uC774\uBBF8\uC9C0\uB97C \uC815\uC0C1\uACFC \uC774\uC0C1\uC5D0 \uB3D9\uC2DC\uC5D0 \uB450\uC9C0 \uB9C8\uC138\uC694.";
                        InvokePrivateResult<object>(window, "SetYoloCommandStatus", leakageStatus, false);
                        InvokePrivateResult<object>(window, "AppendLog", leakageStatus);
                        AssertEqual(leakageStatus, window.YoloStatusViewModel.CommandStatusText);
                        if (window.FindName("ShellLogPanelControl") is WpfShellLogPanel logPanel
                            && !logPanel.ViewModel.IsLogPaneExpanded)
                        {
                            logPanel.ViewModel.ToggleLogPaneCommand.Execute(null);
                        }

                        window.UpdateLayout();
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    ApplyVisualSmokeAnnotationTool(window, annotationTool, imageSize);
                    if (!string.IsNullOrWhiteSpace(boxDrawingMethod))
                    {
                        LabelingBoxDrawingMethod visualBoxMethod =
                            boxDrawingMethod.Contains("four", StringComparison.OrdinalIgnoreCase)
                                || boxDrawingMethod.Contains("4", StringComparison.OrdinalIgnoreCase)
                                ? LabelingBoxDrawingMethod.FourPointExtreme
                                : LabelingBoxDrawingMethod.TwoPointDrag;
                        window.CanvasPanelViewModel.RestoreBoxDrawingMethod(visualBoxMethod);
                        InvokePrivateResult<object>(window, "SelectAnnotationTool", WpfAnnotationTool.Rectangle, true);
                        InvokePrivateResult<object>(window, "ApplyRectangleDrawingInputMode");
                        foreach (Point point in ParseVisualSmokePoints(fourPointBoxClicks))
                        {
                            InvokePrivateResult<object>(
                                window,
                                "MainCanvasViewModel_ImagePointClicked",
                                window.MainCanvasViewModel,
                                new CanvasImagePointEventArgs(
                                    CanvasPointerButton.Left,
                                    1,
                                    0,
                                    0,
                                    point,
                                    PointF.Empty));
                        }
                    }
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    if (smartMaskAutoContourEnabled
                        && !window.CanvasPanelViewModel.IsSmartMaskAutoContourEnabled)
                    {
                        window.CanvasPanelViewModel.ToggleSmartMaskAutoContourCommand.Execute(null);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    if (smartMaskCandidateComparison)
                    {
                        MobileSamBoxPromptTests.ApplyVisualSmokeSmartMaskCandidateComparison(
                            window,
                            imageSize,
                            smartMaskPromptBox);
                        if (smartMaskShowInitialCandidate)
                        {
                            window.CanvasPanelViewModel.ShowInitialSmartMaskCandidateCommand.Execute(null);
                            PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                        }
                    }
                    else if (smartMaskCandidate)
                    {
                        MobileSamBoxPromptTests.ApplyVisualSmokeSmartMaskCandidate(
                            window,
                            imageSize,
                            smartMaskPromptBox,
                            smartMaskPositivePoint,
                            smartMaskNegativePoint);
                        if (smartMaskCorrectionExpanded)
                        {
                            window.CanvasPanelViewModel.ToggleSmartMaskCorrectionOptionsCommand.Execute(null);
                        }
                    }
                    else if (smartMaskPromptOnly)
                    {
                        MobileSamBoxPromptTests.ApplyVisualSmokeSmartMaskPrompt(window, imageSize, smartMaskPromptBox);
                    }
                    SelectVisualSmokeReviewTab(window, reviewTab);
                    EnsureVisualSmokeRightWorkflowExpanded(window, expandRightWorkflow);
                    PrepareVisualSmokeGuidePanel(window, reviewTab, expandLearningConcepts, focusTemplateWorkflow, expandLabelingDetails, focusYoloValidationReport, focusDatasetDashboard);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(150));
                    if (openHeaderToolsMenu || showWorkspaceLayoutControls)
                    {
                        OpenVisualSmokeHeaderToolsMenu(window);
                        if (showWorkspaceLayoutControls)
                        {
                            ShowVisualSmokeWorkspaceLayoutControls(window);
                        }
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (runRuntimeSelfTest)
                    {
                        if (showFailedGraphicsCapability)
                        {
                            window.RuntimeDiagnosticsViewModel.AttachGraphicsCapabilityProvider(
                                CreateVisualSmokeFailedGraphicsCapabilityCheck);
                        }

                        window.RuntimeDiagnosticsViewModel.RunSelfTestCommand.Execute(null);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(150));
                    }

                    if (createSupportBundle)
                    {
                        window.RuntimeDiagnosticsViewModel.CreateSupportBundleCommand.Execute(null);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (showCandidateDisclosure)
                    {
                        ApplyVisualSmokeCandidateDisclosure(window);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (!string.IsNullOrWhiteSpace(modelComparisonSummaryPath))
                    {
                        ApplyVisualSmokeModelComparisonSummary(window, modelComparisonSummaryPath, modelComparisonHistoryIndex);
                        if (string.Equals(reviewTab, "training", StringComparison.OrdinalIgnoreCase))
                        {
                            SelectVisualSmokeReviewTab(window, reviewTab);
                            if (window.FindName("YoloSettingsScrollViewer") is System.Windows.Controls.ScrollViewer modelCenterScroller)
                            {
                                window.UpdateLayout();
                                modelCenterScroller.ScrollToTop();
                            }
                        }
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (!string.IsNullOrWhiteSpace(anomalyClassificationEvaluationSummaryPath))
                    {
                        ApplyVisualSmokeAnomalyClassificationEvaluationSummary(window, anomalyClassificationEvaluationSummaryPath);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (missingModelRuntime)
                    {
                        string missingRuntimeRoot = Path.Combine(Path.GetTempPath(), "ovl-missing-model-runtime-" + Guid.NewGuid().ToString("N"));
                        temporaryVisualSmokeRoots.Add(missingRuntimeRoot);
                        string missingRuntimePython = Path.Combine(missingRuntimeRoot, ".venv", "Scripts", "python.exe");
                        Directory.CreateDirectory(Path.GetDirectoryName(missingRuntimePython) ?? missingRuntimeRoot);
                        Directory.CreateDirectory(Path.Combine(missingRuntimeRoot, ".venv", "Lib", "site-packages"));
                        File.WriteAllText(missingRuntimePython, "python");
                        CGlobal.Inst.Data.ProjectSettings ??= new LabelingProjectSettings();
                        CGlobal.Inst.Data.ProjectSettings.PythonModel = new PythonModelSettings
                        {
                            PythonExecutablePath = missingRuntimePython,
                            ModelEngine = PythonModelSettings.EngineYolo11,
                            ProjectRootPath = missingRuntimeRoot,
                            ClientScriptPath = Path.Combine(missingRuntimeRoot, "labelling_tcp_client.py"),
                            WeightsPath = Path.Combine(missingRuntimeRoot, "best.pt"),
                            ImageRootPath = Path.GetDirectoryName(imagePath) ?? string.Empty
                        };
                        window.YoloModelSettingsViewModel?.LoadFrom(CGlobal.Inst.Data.ProjectSettings.PythonModel);
                        InvokePrivateResult<object>(window, "RefreshYoloStatus");
                        InvokePrivateResult<object>(window, "UpdateYoloCommandButtons");
                        SelectVisualSmokeReviewTab(window, reviewTab);
                        EnsureVisualSmokeRightWorkflowExpanded(window, expandRightWorkflow);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }
                    else if (ultralyticsRuntimeReady)
                    {
                        ApplyVisualSmokeUltralyticsRuntimeReady(window, imagePath, temporaryVisualSmokeRoots);
                        SelectVisualSmokeReviewTab(window, reviewTab);
                        EnsureVisualSmokeRightWorkflowExpanded(window, expandRightWorkflow);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (expandModelRuntimeDetails
                        && window.FindName("YoloModelSettingsPanelControl") is WpfYoloModelSettingsPanel modelSettingsPanel)
                    {
                        modelSettingsPanel.SettingsExpander.IsExpanded = true;
                        modelSettingsPanel.AdvancedSettingsExpander.IsExpanded = true;
                        window.UpdateLayout();
                        modelSettingsPanel.AdvancedSettingsExpander.BringIntoView();
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (showBatchFailureResultCard)
                    {
                        InvokePrivateResult<object>(
                            window,
                            "ShowBatchDetectionFailureResult",
                            WpfImageQueueItem.CreateShell(imagePath),
                            new YoloWorkerSmokeTestResult
                            {
                                Succeeded = false,
                                ImagePath = imagePath,
                                Summary = "Detection request failed.",
                                Candidates = Array.Empty<YoloWorkerSmokeCandidate>()
                            });
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (labelsOnly)
                    {
                        InvokePrivateResult<object>(
                            window,
                            "ApplyCanvasDisplayMode",
                            WpfCanvasDisplayMode.LabelsOnly,
                            true,
                            false);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    if (showRoiLodStatus)
                    {
                        InvokePrivateResult<object>(
                            window.MainCanvasViewModel.ImageViewer,
                            "UpdateVisibleOverlayLodState",
                            10_001,
                            true);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                        AssertTrue(window.MainCanvasViewModel.IsOverlayDisplayLodActive, "ROI LOD visual fixture did not activate the display cap status");
                    }

                    if (leftPaneWidth > 0)
                    {
                        window.ShellViewModel.SetRightWorkflowExpandedPaneWidth(leftPaneWidth);
                    }
                    if (rightPaneWidth > 0
                        && window.FindName("ImageQueueColumn") is System.Windows.Controls.ColumnDefinition imageQueueColumn)
                    {
                        imageQueueColumn.Width = new System.Windows.GridLength(Math.Clamp(rightPaneWidth, 260, 640));
                    }

                    if (selectMergeSegments)
                    {
                        foreach (WpfObjectReviewListItem item in window.ObjectReviewViewModel.Objects
                            .Where(item => item.IsManualSegment)
                            .Take(2))
                        {
                            item.IsMergeSelected = true;
                            window.ObjectReviewViewModel.MergeSelectionChangedCommand.Execute(item);
                        }
                    }
                    if (!string.IsNullOrWhiteSpace(armSegmentationSplit))
                    {
                        SelectVisualSmokeMaskObject(window);
                        if (armSegmentationSplit.Equals("horizontal", StringComparison.OrdinalIgnoreCase))
                        {
                            window.ObjectReviewViewModel.BeginHorizontalSplitCommand.Execute(null);
                        }
                        else
                        {
                            window.ObjectReviewViewModel.BeginVerticalSplitCommand.Execute(null);
                        }
                    }
                    if (!string.IsNullOrWhiteSpace(armSegmentationHole))
                    {
                        SelectVisualSmokeMaskObject(window);
                        if (armSegmentationHole.Equals("remove", StringComparison.OrdinalIgnoreCase))
                        {
                            window.ObjectReviewViewModel.BeginRemoveHoleCommand.Execute(null);
                        }
                        else
                        {
                            window.ObjectReviewViewModel.BeginAddHoleCommand.Execute(null);
                        }
                    }
                    if (!string.IsNullOrWhiteSpace(armPolygonVertex))
                    {
                        SelectVisualSmokePolygonObject(window);
                        if (armPolygonVertex.Equals("delete", StringComparison.OrdinalIgnoreCase))
                        {
                            window.ObjectReviewViewModel.BeginDeleteVertexCommand.Execute(null);
                        }
                        else
                        {
                            window.ObjectReviewViewModel.BeginInsertVertexCommand.Execute(null);
                        }
                    }
                    if (previewIntelligentScissors)
                    {
                        SelectVisualSmokePolygonObject(window);
                        window.ObjectReviewViewModel.BeginIntelligentScissorsCommand.Execute(null);
                        List<LabelingSegmentationObject> segments =
                            GetPrivateField<List<LabelingSegmentationObject>>(window, "manualSegments");
                        LabelingSegmentationObject polygon = segments.FirstOrDefault(segment => segment?.IsRasterMask == false);
                        AssertTrue(polygon?.Points?.Count >= 3, "Intelligent-scissors visual smoke needs a manual polygon");
                        Point first = polygon.Points[0];
                        Point second = polygon.Points[1];
                        Point edgeMidpoint = new Point(
                            (first.X + second.X) / 2,
                            (first.Y + second.Y) / 2);
                        InvokePrivateResult<object>(
                            window,
                            "MainCanvasViewModel_ImagePointClicked",
                            window.MainCanvasViewModel,
                            new CanvasImagePointEventArgs(
                                CanvasPointerButton.Left,
                                1,
                                0,
                                0,
                                edgeMidpoint,
                                PointF.Empty));
                        AssertTrue(
                            window.ObjectReviewViewModel.HasIntelligentScissorsPreview,
                            "Intelligent-scissors visual smoke did not produce a preview");
                    }
                    if (!string.IsNullOrWhiteSpace(applySegmentationZOrder))
                    {
                        SelectVisualSmokeMaskObject(window);
                        switch (applySegmentationZOrder.Trim().ToLowerInvariant())
                        {
                            case "back":
                                window.ObjectReviewViewModel.SendToBackCommand.Execute(null);
                                break;
                            case "backward":
                                window.ObjectReviewViewModel.SendBackwardCommand.Execute(null);
                                break;
                            case "forward":
                                window.ObjectReviewViewModel.BringForwardCommand.Execute(null);
                                break;
                            default:
                                window.ObjectReviewViewModel.BringToFrontCommand.Execute(null);
                                break;
                        }
                    }
                    if (previewSegmentationRemoveUnderlying)
                    {
                        SeedVisualSmokeRemoveUnderlyingOverlap(window);
                        SelectVisualSmokeMaskObject(window);
                        window.ObjectReviewViewModel.PreviewRemoveUnderlyingCommand.Execute(null);
                    }
                    if (showObjectSessionState)
                    {
                        if (window.CanvasPanelViewModel.ResetAiOverlayCommand.CanExecute(null))
                        {
                            window.CanvasPanelViewModel.ResetAiOverlayCommand.Execute(null);
                        }

                        SelectVisualSmokePolygonObject(window);
                        window.ObjectReviewViewModel.ToggleObjectPinnedCommand.Execute(null);
                        window.ObjectReviewViewModel.ToggleObjectLockedCommand.Execute(null);
                        AssertTrue(
                            window.MainCanvasViewModel.PolygonOverlays.Any(overlay =>
                                overlay.Label.StartsWith("SEG", StringComparison.Ordinal)
                                && overlay.Color.ToArgb() != Color.Gold.ToArgb()),
                            "Object-session-state visual smoke should preserve the class-colored polygon under movement pin");
                    }
                    if (openDisplayAdjustment)
                    {
                        window.CanvasPanelViewModel.DisplayBrightness = displayBrightness;
                        window.CanvasPanelViewModel.DisplayContrastPercent = displayContrast;
                        window.CanvasPanelViewModel.DisplayGamma = displayGamma;
                        window.CanvasPanelViewModel.IsDisplayInverted = displayInvert;
                        window.CanvasPanelViewModel.IsDisplayHistogramEqualized = displayEqualize;
                        InvokePrivate(window, "ApplyDisplayAdjustmentNow");
                        window.CanvasPanelViewModel.IsDisplayAdjustmentOpen = true;
                        AssertTrue(
                            window.CanvasPanelViewModel.IsDisplayAdjustmentOpen,
                            "Display-adjustment visual smoke should open the compact popup");
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                    }

                    window.UpdateLayout();
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));

                    WpfModelBenchmarkWindow modelBenchmarkWindow = null;
                    WpfDatasetHealthWindow datasetHealthWindow = null;
                    WpfDatasetInterchangeWindow datasetInterchangeWindow = null;
                    WpfBatchDetectionPreflightWindow batchDetectionPreflightWindow = null;
                    if (openModelBenchmark)
                    {
                        window.ShellViewModel.OpenModelBenchmarkCommand.Execute(null);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                        modelBenchmarkWindow = System.Windows.Application.Current.Windows
                            .OfType<WpfModelBenchmarkWindow>()
                            .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                        AssertTrue(modelBenchmarkWindow != null, "WPF visual smoke did not open the model benchmark window");
                        if (includeAnomalyInModelBenchmark)
                        {
                            WpfModelBenchmarkRunItemViewModel anomalyRun = modelBenchmarkWindow.ViewModel.CatalogRuns
                                .FirstOrDefault(item => item.Run.TaskKey == "anomaly-classification");
                            AssertTrue(anomalyRun != null, "WPF visual smoke did not find an anomaly-classification benchmark run");
                            anomalyRun.IsSelected = true;
                        }
                        if (modelBenchmarkWindow.FindName("ModelBenchmarkTabs") is System.Windows.Controls.TabControl benchmarkTabs)
                        {
                            if (showModelBenchmarkClassErrors)
                            {
                                benchmarkTabs.SelectedIndex = 2;
                            }
                            else if (showModelBenchmarkConditions)
                            {
                                benchmarkTabs.SelectedIndex = 3;
                            }
                            else if (showModelBenchmarkThresholdReview)
                            {
                                benchmarkTabs.SelectedIndex = 4;
                            }
                        }
                        modelBenchmarkWindow.Width = Math.Max(1050, windowWidth);
                        modelBenchmarkWindow.Height = Math.Max(650, windowHeight);
                        modelBenchmarkWindow.Left = screenCapture ? 0 : 24;
                        modelBenchmarkWindow.Top = screenCapture ? 0 : 24;
                        modelBenchmarkWindow.WindowStartupLocation = System.Windows.WindowStartupLocation.Manual;
                        modelBenchmarkWindow.Topmost = true;
                        modelBenchmarkWindow.UpdateLayout();
                        modelBenchmarkWindow.Activate();
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    }

                    if (openDatasetHealth)
                    {
                        window.ShellViewModel.OpenDatasetHealthCommand.Execute(null);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                        datasetHealthWindow = System.Windows.Application.Current.Windows
                            .OfType<WpfDatasetHealthWindow>()
                            .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                        AssertTrue(datasetHealthWindow != null, "WPF visual smoke did not open the Dataset Health window");
                        datasetHealthWindow.Width = Math.Max(980, windowWidth);
                        datasetHealthWindow.Height = Math.Max(650, windowHeight);
                        datasetHealthWindow.Left = screenCapture ? 0 : 24;
                        datasetHealthWindow.Top = screenCapture ? 0 : 24;
                        datasetHealthWindow.WindowStartupLocation = System.Windows.WindowStartupLocation.Manual;
                        datasetHealthWindow.Topmost = true;
                        if (showDatasetHealthVisualQa
                            && datasetHealthWindow.FindName("DatasetHealthTabs") is System.Windows.Controls.TabControl healthTabs
                            && datasetHealthWindow.FindName("DatasetHealthVisualQaTab") is System.Windows.Controls.TabItem visualQaTab)
                        {
                            healthTabs.SelectedItem = visualQaTab;
                            if (!string.IsNullOrWhiteSpace(datasetHealthVisualQaSplit))
                            {
                                datasetHealthWindow.ViewModel.SelectedVisualQaSplitFilter =
                                    datasetHealthVisualQaSplit.Trim();
                            }

                            if (!string.IsNullOrWhiteSpace(datasetHealthVisualQaClass))
                            {
                                string requestedClass = datasetHealthVisualQaClass.Trim();
                                WpfDatasetVisualQaClassFilterItem classFilter =
                                    datasetHealthWindow.ViewModel.VisualQaClassFilters.FirstOrDefault(item =>
                                        string.Equals(item.ClassName, requestedClass, StringComparison.OrdinalIgnoreCase)
                                        || string.Equals(item.ClassIndex?.ToString(CultureInfo.InvariantCulture), requestedClass, StringComparison.OrdinalIgnoreCase)
                                        || string.Equals(item.Text, requestedClass, StringComparison.OrdinalIgnoreCase));
                                if (classFilter != null)
                                {
                                    datasetHealthWindow.ViewModel.SelectedVisualQaClassFilter = classFilter;
                                }
                            }
                        }
                        datasetHealthWindow.UpdateLayout();
                        datasetHealthWindow.Activate();
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    }

                    if (openDatasetInterchange)
                    {
                        window.ShellViewModel.OpenDatasetInterchangeCommand.Execute(null);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                        datasetInterchangeWindow = System.Windows.Application.Current.Windows
                            .OfType<WpfDatasetInterchangeWindow>()
                            .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                        AssertTrue(datasetInterchangeWindow != null, "WPF visual smoke did not open the Dataset Interchange window");
                        string interchangeOutputRoot = Path.Combine(
                            Path.GetTempPath(),
                            "ovl-interchange-visual-" + Guid.NewGuid().ToString("N"));
                        temporaryVisualSmokeRoots.Add(interchangeOutputRoot);
                        datasetInterchangeWindow.ViewModel.TargetPath = Path.Combine(
                            interchangeOutputRoot,
                            "coco-detection.json");
                        datasetInterchangeWindow.ViewModel.DryRunCommand.Execute(null);
                        datasetInterchangeWindow.Width = Math.Max(1040, windowWidth);
                        datasetInterchangeWindow.Height = Math.Max(680, windowHeight);
                        datasetInterchangeWindow.Left = screenCapture ? 0 : 24;
                        datasetInterchangeWindow.Top = screenCapture ? 0 : 24;
                        datasetInterchangeWindow.WindowStartupLocation = System.Windows.WindowStartupLocation.Manual;
                        datasetInterchangeWindow.Topmost = true;
                        datasetInterchangeWindow.UpdateLayout();
                        datasetInterchangeWindow.Activate();
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    }

                    if (openBatchDetectionPreflight)
                    {
                        string preflightModelRoot = Path.Combine(
                            Path.GetTempPath(),
                            "ovl-batch-preflight-visual-" + Guid.NewGuid().ToString("N"));
                        temporaryVisualSmokeRoots.Add(preflightModelRoot);
                        Directory.CreateDirectory(preflightModelRoot);
                        string clientPath = Path.Combine(preflightModelRoot, "worker.py");
                        string weightsPath = Path.Combine(preflightModelRoot, "best.pt");
                        File.WriteAllText(clientPath, "# visual smoke worker");
                        File.WriteAllText(weightsPath, "visual smoke weights");
                        CGlobal.Inst.Data.ProjectSettings.PythonModel = new PythonModelSettings
                        {
                            ModelEngine = PythonModelSettings.EngineYolo11,
                            ProjectRootPath = preflightModelRoot,
                            ClientScriptPath = clientPath,
                            WeightsPath = weightsPath,
                            MinimumDetectionConfidence = 0.35F
                        };
                        if (CGlobal.Inst.Data.ClassNamedList.Count == 0)
                        {
                            CGlobal.Inst.Data.ClassNamedList.Add(new CClassItem { Text = "OK" });
                            CGlobal.Inst.Data.ClassNamedList.Add(new CClassItem { Text = "NG" });
                            CGlobal.Inst.Data.ClassNamedList.Add(new CClassItem { Text = "Defect" });
                        }

                        var preflightItem = WpfImageQueueItem.CreateShell(imagePath);
                        var preflightViewModel = new WpfBatchDetectionPreflightViewModel(
                            CGlobal.Inst.Data,
                            new[] { preflightItem },
                            "\uD45C\uC2DC \uD589");
                        batchDetectionPreflightWindow = new WpfBatchDetectionPreflightWindow(preflightViewModel)
                        {
                            Owner = window,
                            Width = Math.Max(1040, windowWidth),
                            Height = Math.Max(620, windowHeight),
                            Left = screenCapture ? 0 : 24,
                            Top = screenCapture ? 0 : 24,
                            WindowStartupLocation = System.Windows.WindowStartupLocation.Manual,
                            Topmost = true
                        };
                        batchDetectionPreflightWindow.ApplyThemeFrom(window);
                        batchDetectionPreflightWindow.Show();
                        batchDetectionPreflightWindow.UpdateLayout();
                        batchDetectionPreflightWindow.Activate();
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    }

                    WpfEnvironmentSetupCenterWindow environmentSetupCenterWindow = null;
                    if (openEnvironmentSetupCenter)
                    {
                        window.RuntimeDiagnosticsViewModel.OpenSetupCenterCommand.Execute(null);
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                        environmentSetupCenterWindow = System.Windows.Application.Current.Windows
                            .OfType<WpfEnvironmentSetupCenterWindow>()
                            .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                        AssertTrue(environmentSetupCenterWindow != null, "WPF visual smoke did not open the Environment Setup Center window");
                        environmentSetupCenterWindow.Width = Math.Max(920, windowWidth);
                        environmentSetupCenterWindow.Height = Math.Max(620, windowHeight);
                        environmentSetupCenterWindow.Left = screenCapture ? 0 : 24;
                        environmentSetupCenterWindow.Top = screenCapture ? 0 : 24;
                        environmentSetupCenterWindow.WindowStartupLocation = System.Windows.WindowStartupLocation.Manual;
                        environmentSetupCenterWindow.Topmost = true;
                        environmentSetupCenterWindow.UpdateLayout();
                        environmentSetupCenterWindow.Activate();
                        PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    }

                    System.Windows.Window captureTarget = (System.Windows.Window)environmentSetupCenterWindow
                        ?? (System.Windows.Window)batchDetectionPreflightWindow
                        ?? (System.Windows.Window)datasetInterchangeWindow
                        ?? (System.Windows.Window)datasetHealthWindow
                        ?? (System.Windows.Window)modelBenchmarkWindow
                        ?? window;
                    if (showCrashRecoveryDialog)
                    {
                        bool dialogCaptured = false;
                        WpfCrashRecoveryDraft visualDraft = CrashRecoveryTests.CreateVisualDraft(
                            imagePath,
                            CGlobal.Inst.Data.OutputRootPath);
                        window.Dispatcher.BeginInvoke(new Action(() =>
                        {
                            WpfMessageDialogWindow recoveryDialog = System.Windows.Application.Current.Windows
                                .OfType<WpfMessageDialogWindow>()
                                .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                            AssertTrue(recoveryDialog != null, "crash-recovery dialog was not visible for capture");
                            recoveryDialog.UpdateLayout();
                            recoveryDialog.Activate();
                            PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                            CaptureWindowFromScreen(window, outputPath);
                            dialogCaptured = true;
                            recoveryDialog.Close();
                        }), System.Windows.Threading.DispatcherPriority.ApplicationIdle);

                        InvokePrivateResult<WpfMessageDialogResult>(
                            window,
                            "ShowCrashRecoveryPrompt",
                            visualDraft);
                        AssertTrue(dialogCaptured, "crash-recovery dialog capture did not complete");
                        Console.WriteLine($"WPF crash-recovery visual smoke captured: {outputPath}");
                        return 0;
                    }

                    if (showApplicationCloseDialog)
                    {
                        bool dialogCaptured = false;
                        window.Dispatcher.BeginInvoke(new Action(() =>
                        {
                            WpfMessageDialogWindow closeDialog = System.Windows.Application.Current.Windows
                                .OfType<WpfMessageDialogWindow>()
                                .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                            AssertTrue(closeDialog != null, "application-close dialog was not visible for capture");
                            closeDialog.UpdateLayout();
                            closeDialog.Activate();
                            PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                            CaptureWindowFromScreen(window, outputPath);
                            dialogCaptured = true;
                            closeDialog.Close();
                        }), System.Windows.Threading.DispatcherPriority.ApplicationIdle);

                        window.Close();
                        AssertTrue(dialogCaptured, "application-close dialog capture did not complete");
                        AssertTrue(window.IsVisible, "closing the application-close dialog should cancel the window close");
                        Console.WriteLine($"WPF application-close visual smoke captured: {outputPath}");
                        return 0;
                    }

                    if (showGraphicsCapabilityDialog)
                    {
                        window.RuntimeDiagnosticsViewModel.AttachGraphicsCapabilityProvider(
                            CreateVisualSmokeFailedGraphicsCapabilityCheck);
                        bool dialogCaptured = false;
                        window.Dispatcher.BeginInvoke(new Action(() =>
                        {
                            WpfMessageDialogWindow graphicsDialog = System.Windows.Application.Current.Windows
                                .OfType<WpfMessageDialogWindow>()
                                .FirstOrDefault(candidate => ReferenceEquals(candidate.Owner, window));
                            AssertTrue(graphicsDialog != null, "graphics-capability dialog was not visible for capture");
                            graphicsDialog.UpdateLayout();
                            graphicsDialog.Activate();
                            PumpWpfDispatcher(TimeSpan.FromMilliseconds(250));
                            CaptureWindowFromScreen(window, outputPath);
                            dialogCaptured = true;
                            graphicsDialog.Close();
                        }), System.Windows.Threading.DispatcherPriority.ApplicationIdle);

                        bool reloaded = window.TryLoadImage(
                            imagePath,
                            populateQueue: false,
                            refreshQueueDetails: false,
                            refreshActiveStatus: false,
                            appendLoadLog: false);
                        AssertTrue(!reloaded, "failed graphics capability should block the central image-load path");
                        AssertTrue(dialogCaptured, "graphics-capability dialog capture did not complete");
                        Console.WriteLine($"WPF graphics-capability dialog captured: {outputPath}");
                        return 0;
                    }

                    if (openPatchCoreHeatmap)
                    {
                        AssertTrue(patchCoreHeatmapCaptured, "PatchCore heatmap evidence window was not captured after opening");
                    }
                    else if (screenCapture)
                    {
                        CaptureWindowFromScreen(captureTarget, outputPath);
                    }
                    else
                    {
                        CaptureWindow(captureTarget, outputPath);
                    }
                    Console.WriteLine($"WPF visual smoke captured: {outputPath}");
                    return 0;
                }
                finally
                {
                    SetPrivateField(window, "isApplicationCloseApproved", true);
                    window.Close();
                }
            }
            finally
            {
                if (!string.IsNullOrWhiteSpace(root))
                {
                    DeleteTempRoot(root);
                }

                foreach (string temporaryRoot in temporaryVisualSmokeRoots)
                {
                    DeleteTempRoot(temporaryRoot);
                }

                ShutdownVisualSmokeApplication();
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"FAIL WPF visual smoke: {ex.Message}");
            Console.Error.WriteLine(ex.ToString());
            return 1;
        }
    }

    private static WpfRuntimeSelfTestCheck CreateVisualSmokeFailedGraphicsCapabilityCheck()
    {
        return new WpfRuntimeSelfTestCheck(
            WpfRuntimeDiagnosticsService.ViewerGraphicsCheckName,
            "fail",
            "이미지 뷰어 사용 불가 · Microsoft Hyper-V Video / OpenGL 1.1 · "
            + "지원되지 않는 필수 기능: glGenFramebuffersEXT · "
            + "지원되는 GPU 드라이버가 설치된 로컬 PC/VM 콘솔에서 다시 실행하세요.");
    }

    private static int RunWpfStartupOnboardingVisualSmoke(string[] args)
    {
        string outputPath = GetArgumentValue(
            args,
            "--output",
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "artifacts", "ui", "wpf-startup-onboarding.png"));
        outputPath = Path.GetFullPath(outputPath);
        int windowWidth = TryParseInt(
            GetArgumentValue(args, "--width", VisualSmokeDefaultWindowWidth.ToString(CultureInfo.InvariantCulture)),
            VisualSmokeDefaultWindowWidth);
        int windowHeight = TryParseInt(
            GetArgumentValue(args, "--height", VisualSmokeDefaultWindowHeight.ToString(CultureInfo.InvariantCulture)),
            VisualSmokeDefaultWindowHeight);
        string theme = GetArgumentValue(args, "--theme", "dark");

        try
        {
            if (System.Windows.Application.Current == null)
            {
                _ = new System.Windows.Application
                {
                    ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
                };
            }

            string recipeRootPath = WpfProjectRecipeService.GetRecipeRootDirectory();
            string lastOpenedPath = WpfProjectRecipeService.BuildLastOpenedRecipePath(recipeRootPath);
            bool hadLastOpened = File.Exists(lastOpenedPath);
            string previousLastOpenedText = hadLastOpened ? File.ReadAllText(lastOpenedPath) : string.Empty;
            CData previousData = CGlobal.Inst.Data;
            string previousRecipeName = CGlobal.Inst.Recipe.Name;

            try
            {
                if (File.Exists(lastOpenedPath))
                {
                    File.Delete(lastOpenedPath);
                }

                CGlobal.Inst.Data = new CData();
                SetPrivateField(CGlobal.Inst.Recipe, "m_strName", string.Empty);

                WpfLabelingShellWindow window = new WpfLabelingShellWindow
                {
                    Width = Math.Max(VisualSmokeMinimumWindowWidth, windowWidth),
                    Height = Math.Max(VisualSmokeMinimumWindowHeight, windowHeight),
                    Left = 24,
                    Top = 24,
                    WindowStartupLocation = System.Windows.WindowStartupLocation.Manual,
                    Topmost = true
                };

                try
                {
                    window.Show();
                    ApplyVisualSmokeTheme(window, theme);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(700));
                    SelectVisualSmokeReviewTab(window, "guide");
                    PrepareVisualSmokeGuidePanel(window, "guide", expandLearningConcepts: false);
                    CloseAuxiliaryVisualSmokeWindows(window);
                    BringVisualSmokeWindowToFront(window);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(500));
                    CaptureWindow(window, outputPath);
                    Console.WriteLine($"WPF startup onboarding visual smoke captured: {outputPath}");
                    return 0;
                }
                finally
                {
                    window.Close();
                }
            }
            finally
            {
                if (hadLastOpened)
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(lastOpenedPath) ?? recipeRootPath);
                    File.WriteAllText(lastOpenedPath, previousLastOpenedText);
                }
                else if (File.Exists(lastOpenedPath))
                {
                    File.Delete(lastOpenedPath);
                }

                CGlobal.Inst.Data = previousData;
                SetPrivateField(CGlobal.Inst.Recipe, "m_strName", previousRecipeName ?? string.Empty);
                ShutdownVisualSmokeApplication();
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"FAIL WPF startup onboarding visual smoke: {ex.Message}");
            Console.Error.WriteLine(ex.ToString());
            return 1;
        }
    }

    private static int RunWpfDatasetSetupWizardSmoke(string[] args)
    {
        string outputPath = GetArgumentValue(
            args,
            "--output",
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "artifacts", "ui", "wpf-dataset-setup-wizard.png"));
        outputPath = Path.GetFullPath(outputPath);

        try
        {
            if (System.Windows.Application.Current == null)
            {
                _ = new System.Windows.Application
                {
                    ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
                };
            }

            WpfDatasetSetupWizardViewModel viewModel = new WpfDatasetSetupWizardViewModel();
            viewModel.LoadFrom(
                LabelingDatasetPurpose.Segmentation,
                "WizardVisualDataset",
                Path.Combine(AppContext.BaseDirectory, "DATA", "WizardVisualDataset"),
                new[] { "Defect", "Scratch" });
            viewModel.ConfigureCommands(_ => { }, () => { }, () => { });

            WpfDatasetSetupWizardWindow window = new WpfDatasetSetupWizardWindow
            {
                DataContext = viewModel,
                Width = 900,
                Height = 820,
                Left = 80,
                Top = 80,
                WindowStartupLocation = System.Windows.WindowStartupLocation.Manual,
                Topmost = true
            };

            try
            {
                window.Show();
                PumpWpfDispatcher(TimeSpan.FromMilliseconds(600));
                CaptureWindow(window, outputPath);
                Console.WriteLine($"WPF dataset setup wizard smoke captured: {outputPath}");
                return 0;
            }
            finally
            {
                window.Close();
                ShutdownVisualSmokeApplication();
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"FAIL WPF dataset setup wizard smoke: {ex.Message}");
            Console.Error.WriteLine(ex.ToString());
            return 1;
        }
    }

    private static int RunWpfDatasetSelectionSmoke(string[] args)
    {
