        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"FAIL WPF dataset selection smoke: {ex.Message}");
            Console.Error.WriteLine(ex.ToString());
            return 1;
        }
        finally
        {
            DeleteTempRoot(root);
            DeleteTempRoot(imageRootContainer);
        }
