    }

    private static string ResolveExeSmokePythonExecutablePath()
    {
        string pyLauncher = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "py.exe");
        if (File.Exists(pyLauncher))
        {
            return pyLauncher;
        }

        string pathValue = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
        foreach (string directory in pathValue.Split(Path.PathSeparator))
        {
            if (string.IsNullOrWhiteSpace(directory))
            {
                continue;
            }

            string candidate = Path.Combine(directory.Trim(), "python.exe");
            if (File.Exists(candidate))
            {
                return candidate;
            }
        }

        return "python";
    }

    private static bool OpenExeSmokeDatasetRecipe(Process process, string recipeName)
    {
        bool selectorRequested = WaitUntil(
            () => TryInvokeAutomationButtonByAutomationId(
                RefreshAutomationRoot(process, bringToFront: false),
                "ChangeDatasetButton"),
            TimeSpan.FromSeconds(5));
        if (!selectorRequested)
        {
            BringNativeWindowToFront(process.MainWindowHandle);
            SendKeys.SendWait("{ESC}");
            Thread.Sleep(150);
            var root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "DatasetHomeStageButton");
            selectorRequested = WaitUntil(
                () => TryInvokeAutomationButtonByAutomationId(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "ChangeDatasetButton"),
                TimeSpan.FromSeconds(3));
        }

        if (!selectorRequested)
        {
            Console.Error.WriteLine("EXE_DATASET_SELECTOR_OPEN_BUTTON_NOT_INVOKED");
            return false;
        }

        System.Windows.Automation.AutomationElement selector = WaitForProcessWindowByName(
            process,
            "\uB370\uC774\uD130\uC14B \uC120\uD0DD",
            TimeSpan.FromSeconds(8));
        if (selector == null)
        {
            Console.Error.WriteLine("EXE_DATASET_SELECTOR_WINDOW_NOT_FOUND");
            return false;
        }

        System.Windows.Automation.AutomationElement item = FindListItemContainingText(selector, recipeName);
        if (item == null)
        {
            _ = TryInvokeAutomationButtonByAutomationId(selector, "RefreshDatasetSelectionButton");
            Thread.Sleep(250);
            selector = WaitForProcessWindowByName(
                process,
                "\uB370\uC774\uD130\uC14B \uC120\uD0DD",
                TimeSpan.FromSeconds(3));
            item = FindListItemContainingText(selector, recipeName);
        }

        if (item == null)
        {
            Console.Error.WriteLine(
                $"EXE_DATASET_SELECTOR_RECIPE_NOT_FOUND recipe={recipeName} sample=\"{BuildAutomationTextSample(selector, 100)}\"");
            return false;
        }

        if (item.TryGetCurrentPattern(System.Windows.Automation.SelectionItemPattern.Pattern, out object pattern)
            && pattern is System.Windows.Automation.SelectionItemPattern selectionPattern)
        {
            selectionPattern.Select();
        }
        else
        {
            NativeClick(GetAutomationCenter(item));
        }

        Thread.Sleep(150);
        selector = WaitForProcessWindowByName(
            process,
            "\uB370\uC774\uD130\uC14B \uC120\uD0DD",
            TimeSpan.FromSeconds(3));
        if (selector == null)
        {
            Console.Error.WriteLine("EXE_DATASET_SELECTOR_WINDOW_LOST_BEFORE_OPEN");
            return false;
        }

        bool openInvoked = TryInvokeAutomationButtonByAutomationId(selector, "OpenSelectedDatasetButton");
        bool selectorClosed = openInvoked
            && WaitUntil(
                () => FindProcessWindowByName(process, "\uB370\uC774\uD130\uC14B \uC120\uD0DD") == null,
                TimeSpan.FromSeconds(8));
        if (!openInvoked || !selectorClosed)
        {
            Console.Error.WriteLine(
                $"EXE_DATASET_SELECTOR_OPEN_FAILED invoked={openInvoked} closed={selectorClosed} sample=\"{BuildAutomationTextSample(selector, 100)}\"");
        }

        return openInvoked && selectorClosed;
    }

    internal static bool ApplyExeSmokeRecipe(Process process, string recipeName)
    {
        var root = RefreshAutomationRoot(process);
        _ = TryInvokeAutomationButtonByAutomationId(root, "TrainingModelStageButton");
        _ = WaitUntil(
            () => IsExeWorkflowStageActive(
                RefreshAutomationRoot(process, bringToFront: false),
                "training"),
            TimeSpan.FromSeconds(5));
        EnsureExeRightWorkflowExpanded(process);
        root = RefreshAutomationRoot(process);
        _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowTrainingModelButton");
        root = RefreshAutomationRoot(process);
        if (!SelectAutomationTabByAutomationId(root, "YoloSettingsReviewTab") && !SelectTabItemByName(root, "\uBAA8\uB378"))
        {
            return false;
        }

        root = RefreshAutomationRoot(process);
        if (!SelectAutomationTabByAutomationId(root, "YoloModelCenterDataTaskTab"))
        {
            return false;
        }

        root = RefreshAutomationRoot(process);
        _ = TryExpandAutomationElementByAutomationId(root, "ProjectConfigExpander");
        root = RefreshAutomationRoot(process);
        if (!TrySetAutomationValueByAutomationId(root, "ProjectRecipeNameBox", recipeName))
        {
            return false;
        }

        root = RefreshAutomationRoot(process);
        return TryInvokeAutomationButtonByAutomationId(root, "ApplyProjectRecipeButton")
            || TryInvokeAutomationButton(root, "Recipe 적용");
    }

    private static bool TryInvokeExeHeaderToolButton(
        Process process,
        string buttonAutomationId,
        string expandAutomationId = null)
    {
        var root = RefreshAutomationRoot(process);
        bool menuAlreadyOpen = FindVisibleProcessAutomationElementByAutomationId(
            process,
            "QuickLoadSampleButton") != null;
        if (!menuAlreadyOpen
            && !TryInvokeAutomationButtonByAutomationId(root, "HeaderToolsMenuButton"))
        {
            return false;
        }

        bool toolVisible = WaitUntil(
            () =>
            {
                var currentRoot = RefreshAutomationRoot(process, bringToFront: false);
                if (!string.IsNullOrWhiteSpace(expandAutomationId))
                {
                    _ = TryExpandAutomationElementByAutomationId(currentRoot, expandAutomationId);
                    foreach (var processRoot in GetVisibleProcessAutomationRoots(process))
                    {
                        _ = TryExpandAutomationElementByAutomationId(processRoot, expandAutomationId);
                    }
                }

                return IsAutomationElementVisibleByAutomationId(currentRoot, buttonAutomationId)
                    || FindVisibleProcessAutomationElementByAutomationId(process, buttonAutomationId) != null;
            },
            TimeSpan.FromSeconds(3));
        if (!toolVisible)
        {
            return false;
        }

        root = RefreshAutomationRoot(process, bringToFront: false);
        if (TryInvokeAutomationButtonByAutomationId(root, buttonAutomationId))
        {
            return true;
        }

        foreach (var processRoot in GetVisibleProcessAutomationRoots(process))
        {
            if (TryInvokeAutomationButtonByAutomationId(processRoot, buttonAutomationId))
            {
                return true;
            }
        }

        return false;
    }

    private static System.Windows.Automation.AutomationElement FindVisibleProcessAutomationElementByAutomationId(
        Process process,
        string automationId)
    {
        foreach (var processRoot in GetVisibleProcessAutomationRoots(process))
        {
            try
            {
                if (string.Equals(processRoot.Current.AutomationId, automationId, StringComparison.Ordinal)
                    && IsAutomationElementVisible(processRoot))
                {
                    return processRoot;
                }

                var element = FindAutomationElementByAutomationId(processRoot, automationId);
                if (IsAutomationElementVisible(element))
                {
                    return element;
                }
            }
            catch (System.Windows.Automation.ElementNotAvailableException)
            {
            }
        }

        return null;
    }

    private static IReadOnlyList<System.Windows.Automation.AutomationElement> GetVisibleProcessAutomationRoots(
        Process process)
    {
        var roots = new List<System.Windows.Automation.AutomationElement>();
        if (process == null || process.HasExited)
        {
            return roots;
        }

        uint targetProcessId = (uint)process.Id;
        EnumWindows((hWnd, _) =>
        {
            if (!IsWindowVisible(hWnd))
            {
                return true;
            }

            GetWindowThreadProcessId(hWnd, out uint processId);
            if (processId != targetProcessId)
            {
                return true;
            }

            try
            {
                var root = System.Windows.Automation.AutomationElement.FromHandle(hWnd);
                if (root != null)
                {
                    roots.Add(root);
                }
            }
            catch (System.Windows.Automation.ElementNotAvailableException)
            {
            }
            catch (System.Runtime.InteropServices.COMException)
            {
            }

            return true;
        }, IntPtr.Zero);
        return roots;
    }

    internal static bool TryReadDatasetManifest(string manifestPath, out LabelingDatasetManifest manifest)
    {
        manifest = null;
        if (string.IsNullOrWhiteSpace(manifestPath) || !File.Exists(manifestPath))
        {
            return false;
        }

        try
        {
            manifest = JsonConvert.DeserializeObject<LabelingDatasetManifest>(File.ReadAllText(manifestPath));
            return manifest != null;
        }
        catch
        {
            return false;
        }
    }

    private static ExeGuideWorkflowChipSmokeResult ExecuteExeGuideWorkflowChipSmoke(
        string exePath,
        string outputPath)
    {
        int[] chipOrders = { 2, 3, 4, 5, 6 };
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE guide workflow chip smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE guide workflow chip smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE guide workflow chip smoke automation root was not available");

            AssertTrue(
                SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                "guide/tools tab was not selectable before clicking the YOLO completion chips");

            int chipsFound = 0;
            int chipsVerified = 0;
            double totalMilliseconds = 0D;
            double maxMilliseconds = 0D;
            var statusItems = new List<string>();
            foreach (int chipOrder in chipOrders)
            {
                root = RefreshAutomationRoot(process);
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                    $"guide/tools tab was not selectable before clicking YOLO completion chip {chipOrder}");

                System.Windows.Automation.AutomationElement chip = null;
                bool chipFound = WaitUntil(
                    () =>
                    {
                        root = RefreshAutomationRoot(process, bringToFront: false);
                        chip = FindYoloTrainingProgressChipElement(root, chipOrder);
                        if (IsAutomationElementVisible(chip))
                        {
                            return true;
                        }

                        ScrollExeSmokeLearningWorkflowToProgressChips(root);
                        root = RefreshAutomationRoot(process, bringToFront: false);
                        chip = FindYoloTrainingProgressChipElement(root, chipOrder);
                        return IsAutomationElementVisible(chip);
                    },
                    TimeSpan.FromSeconds(6));
                if (!chipFound)
                {
                    TryCaptureExeSmokeFailure(root, outputPath, $"guide-chip-{chipOrder}-not-found");
                    Console.Error.WriteLine("EXE_GUIDE_CHIP_AUTOMATION_SAMPLE " + BuildAutomationTextSample(root, 120));
                }

                AssertTrue(chipFound, $"YOLO completion chip {chipOrder} was not visible in the real EXE guide");
                chipsFound++;

                Stopwatch stopwatch = Stopwatch.StartNew();
                NativeClick(GetAutomationCenter(chip));
                string chipSignal = string.Empty;
                bool chipVerified = WaitUntil(
                    () => TryVerifyYoloTrainingChipEffect(process, chipOrder, out chipSignal),
                    TimeSpan.FromSeconds(5));
                stopwatch.Stop();
                totalMilliseconds += stopwatch.Elapsed.TotalMilliseconds;
                maxMilliseconds = Math.Max(maxMilliseconds, stopwatch.Elapsed.TotalMilliseconds);
                statusItems.Add(FormattableString.Invariant($"{chipOrder}:{chipSignal}"));

                if (!chipVerified)
                {
                    root = RefreshAutomationRoot(process, bringToFront: false);
                    TryCaptureExeSmokeFailure(root, outputPath, $"guide-chip-{chipOrder}-not-verified");
                    string modelStatus = GetAutomationValueByAutomationId(root, "ModelStatusText");
                    Console.Error.WriteLine($"EXE_GUIDE_CHIP_STATUS_AFTER_CLICK order={chipOrder} signal=\"{chipSignal}\" status=\"{modelStatus}\"");
                }

                AssertTrue(chipVerified, $"clicking YOLO completion chip {chipOrder} did not reach its expected real-EXE target");
                chipsVerified++;
            }

            root = RefreshAutomationRoot(process, bringToFront: false);
            CaptureAutomationRoot(root, outputPath);
            return new ExeGuideWorkflowChipSmokeResult(
                string.Join(",", chipOrders),
                totalMilliseconds,
                maxMilliseconds,
                chipsFound,
                chipsVerified,
                string.Join(" | ", statusItems));
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    private static ExeTopSubNavigationSmokeResult ExecuteExeTopSubNavigationSmoke(
        string exePath,
        string outputPath)
    {
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE top subnavigation smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE top subnavigation smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE top subnavigation smoke automation root was not available");

            string[] allShortcutIds =
            {
                "RightWorkflowDatasetHomeButton",
                "RightWorkflowSavedLabelsButton",
                "RightWorkflowGuideToolsButton",
                "RightWorkflowClassCatalogButton",
                "RightWorkflowInferenceCandidatesButton",
                "RightWorkflowInferenceInspectButton",
                "RightWorkflowTrainingModelButton",
                "RightWorkflowTrainingReviewCandidateButton",
                "RightWorkflowTrainingInspectButton"
            };

            int stagesVerified = 0;
            int visibleShortcutsVerified = 0;
            int shortcutsClicked = 0;
            var statusItems = new List<string>();

            VerifyExeTopSubNavigationStage(
                process,
                outputPath,
                "DatasetHomeStageButton",
                "dataset",
                new[] { "RightWorkflowDatasetHomeButton", "RightWorkflowClassCatalogButton" },
                allShortcutIds,
                new[] { "RightWorkflowClassCatalogButton", "RightWorkflowDatasetHomeButton" },
                ref stagesVerified,
                ref visibleShortcutsVerified,
