                outputPath,
                "LabelingWorkbenchStageButton",
                "labeling",
                new[] { "RightWorkflowSavedLabelsButton", "RightWorkflowGuideToolsButton", "RightWorkflowClassCatalogButton" },
                allShortcutIds,
                new[] { "RightWorkflowGuideToolsButton", "RightWorkflowSavedLabelsButton", "RightWorkflowClassCatalogButton" },
                ref stagesVerified,
                ref visibleShortcutsVerified,
                ref shortcutsClicked,
                statusItems);

            VerifyExeTopSubNavigationStage(
                process,
                outputPath,
                "InferenceReviewStageButton",
                "inference",
                new[] { "RightWorkflowInferenceCandidatesButton", "RightWorkflowInferenceInspectButton" },
                allShortcutIds,
                new[] { "RightWorkflowInferenceCandidatesButton" },
                ref stagesVerified,
                ref visibleShortcutsVerified,
                ref shortcutsClicked,
                statusItems);

            VerifyExeTopSubNavigationStage(
                process,
                outputPath,
                "TrainingModelStageButton",
                "training",
                new[] { "RightWorkflowTrainingModelButton", "RightWorkflowTrainingReviewCandidateButton", "RightWorkflowTrainingInspectButton" },
                allShortcutIds,
                new[] { "RightWorkflowTrainingModelButton" },
                ref stagesVerified,
                ref visibleShortcutsVerified,
                ref shortcutsClicked,
                statusItems);

            root = RefreshAutomationRoot(process, handle, bringToFront: false);
            CaptureAutomationRoot(root, outputPath);
            return new ExeTopSubNavigationSmokeResult(
                stagesVerified,
                visibleShortcutsVerified,
                shortcutsClicked,
                string.Join(" | ", statusItems));
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    private static void VerifyExeTopSubNavigationStage(
        Process process,
        string outputPath,
        string stageButtonAutomationId,
        string stageName,
        IReadOnlyCollection<string> expectedVisibleShortcutIds,
        IReadOnlyCollection<string> allShortcutIds,
        IReadOnlyCollection<string> shortcutClickIds,
        ref int stagesVerified,
        ref int visibleShortcutsVerified,
        ref int shortcutsClicked,
        List<string> statusItems)
    {
        var root = RefreshAutomationRoot(process);
        bool humanClicked = TryHumanClickAutomationElementByAutomationId(root, stageButtonAutomationId);
        AssertTrue(humanClicked, $"workflow stage button was not clickable in real EXE: {stageButtonAutomationId}");
        bool stageActivatedByClick = WaitUntil(
            () => IsExeWorkflowStageActive(
                RefreshAutomationRoot(process, bringToFront: false),
                stageName),
            TimeSpan.FromSeconds(2));
        bool usedInvokeFallback = false;
        if (!stageActivatedByClick)
        {
            root = RefreshAutomationRoot(process);
            usedInvokeFallback = TryInvokeAutomationButtonByAutomationId(root, stageButtonAutomationId);
            AssertTrue(
                usedInvokeFallback
                    && WaitUntil(
                        () => IsExeWorkflowStageActive(
                            RefreshAutomationRoot(process, bringToFront: false),
                            stageName),
                        TimeSpan.FromSeconds(5)),
                $"workflow stage did not activate after click or invoke fallback: {stageButtonAutomationId}");
        }

        EnsureExeRightWorkflowExpanded(process);

        bool ready = WaitUntil(
            () =>
            {
                root = RefreshAutomationRoot(process, bringToFront: false);
                return expectedVisibleShortcutIds.All(id => IsAutomationElementVisibleByAutomationId(root, id))
                    && allShortcutIds
                        .Where(id => !expectedVisibleShortcutIds.Contains(id, StringComparer.Ordinal))
                        .All(id => !IsAutomationElementVisibleByAutomationId(root, id));
            },
            TimeSpan.FromSeconds(5));

        if (!ready)
        {
            root = RefreshAutomationRoot(process, bringToFront: false);
            TryCaptureExeSmokeFailure(root, outputPath, $"top-subnav-{stageName}-not-ready");
            Console.Error.WriteLine("EXE_TOP_SUBNAV_SAMPLE " + BuildAutomationTextSample(root, 140));
        }

        AssertTrue(ready, $"top subnavigation did not show the expected shortcuts for stage: {stageName}");
        stagesVerified++;
        visibleShortcutsVerified += expectedVisibleShortcutIds.Count;

        int clickedForStage = 0;
        foreach (string shortcutId in shortcutClickIds)
        {
            root = RefreshAutomationRoot(process, bringToFront: false);
            if (!IsAutomationButtonEnabledByAutomationId(root, shortcutId))
            {
                continue;
            }

            AssertTrue(TryHumanClickAutomationElementByAutomationId(root, shortcutId), $"top subnavigation shortcut was not invokable in real EXE: {shortcutId}");
            clickedForStage++;
            shortcutsClicked++;
            bool stillVisible = WaitUntil(
                () =>
                {
                    root = RefreshAutomationRoot(process, bringToFront: false);
                    return expectedVisibleShortcutIds.All(id => IsAutomationElementVisibleByAutomationId(root, id));
                },
                TimeSpan.FromSeconds(3));
            AssertTrue(stillVisible, $"top subnavigation shortcuts disappeared after clicking: {shortcutId}");
        }

        statusItems.Add(FormattableString.Invariant(
            $"{stageName}:{expectedVisibleShortcutIds.Count}/{clickedForStage}/invokeFallback={usedInvokeFallback}"));
    }

    private static bool IsExeWorkflowStageActive(
        System.Windows.Automation.AutomationElement root,
        string stageName)
    {
        string marker = stageName switch
        {
            "dataset" => "1/4 \uB370\uC774\uD130\uC14B",
            "labeling" => "2/4 \uB77C\uBCA8\uB9C1",
            "inference" => "3/4",
            "training" => "4/4 \uD559\uC2B5/\uBAA8\uB378",
            _ => string.Empty
        };
        return !string.IsNullOrWhiteSpace(marker) && ContainsAutomationText(root, marker);
    }

    private static void EnsureExeRightWorkflowExpanded(Process process)
    {
        var root = RefreshAutomationRoot(process, bringToFront: false);
        if (!IsAutomationElementVisibleByAutomationId(root, "RightWorkflowRailOpenButton"))
        {
            return;
        }

        bool clicked = TryHumanClickAutomationElementByAutomationId(root, "RightWorkflowRailOpenButton");
        bool expanded = clicked && WaitUntil(
            () => IsExeRightWorkflowExpanded(RefreshAutomationRoot(process, bringToFront: false)),
            TimeSpan.FromSeconds(1));
        if (!expanded)
        {
            root = RefreshAutomationRoot(process);
            clicked = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowRailOpenButton");
            expanded = clicked && WaitUntil(
                () => IsExeRightWorkflowExpanded(RefreshAutomationRoot(process, bringToFront: false)),
                TimeSpan.FromSeconds(5));
        }

        AssertTrue(
            expanded,
            "expanded work panel did not appear after clicking its rail");
    }

    private static bool IsExeRightWorkflowExpanded(System.Windows.Automation.AutomationElement root)
    {
        return !IsAutomationElementVisibleByAutomationId(root, "RightWorkflowRailOpenButton")
            && (IsAutomationElementVisibleByAutomationId(root, "RightWorkflowExpandedContent")
                || IsAutomationElementVisibleByAutomationId(root, "RightWorkflowDatasetHomeButton")
                || IsAutomationElementVisibleByAutomationId(root, "RightWorkflowSavedLabelsButton")
                || IsAutomationElementVisibleByAutomationId(root, "RightWorkflowInferenceCandidatesButton")
                || IsAutomationElementVisibleByAutomationId(root, "RightWorkflowTrainingModelButton"));
    }

    private static bool TryHumanClickAutomationElementByAutomationId(
        System.Windows.Automation.AutomationElement root,
        string automationId)
    {
        System.Windows.Automation.AutomationElement element = FindAutomationElementByAutomationId(root, automationId);
        if (element == null || !element.Current.IsEnabled || element.Current.IsOffscreen)
        {
            return false;
        }

        _ = HumanClickAutomationElement(element);
        return true;
    }

    private static ExeGuideDashboardCardSmokeResult ExecuteExeGuideDashboardCardSmoke(
        string exePath,
        string outputPath)
    {
        WpfDatasetDashboardActionKind[] cardActions =
        {
            WpfDatasetDashboardActionKind.OpenClassCatalog,
            WpfDatasetDashboardActionKind.OpenLabelingTool,
            WpfDatasetDashboardActionKind.OpenDatasetSettings
        };
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE guide dashboard card smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE guide dashboard card smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE guide dashboard card smoke automation root was not available");

            AssertTrue(
                SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                "guide/tools tab was not selectable before clicking the dataset dashboard cards");
            root = RefreshAutomationRoot(process);
            _ = SelectListItemByText(root, "\uAC1D\uCCB4 \uD0D0\uC9C0");

            int cardsFound = 0;
            int cardsVerified = 0;
            double totalMilliseconds = 0D;
            double maxMilliseconds = 0D;
            var statusItems = new List<string>();
            foreach (WpfDatasetDashboardActionKind cardAction in cardActions)
            {
                root = RefreshAutomationRoot(process);
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                    $"guide/tools tab was not selectable before clicking dataset dashboard card {cardAction}");

                System.Windows.Automation.AutomationElement card = null;
                bool cardFound = WaitUntil(
                    () =>
                    {
                        root = RefreshAutomationRoot(process, bringToFront: false);
                        card = FindDatasetDashboardMetricCardElement(root, cardAction);
                        if (IsAutomationElementVisible(card))
                        {
                            return true;
                        }

                        ScrollExeSmokeLearningWorkflowToDatasetDashboard(root);
                        root = RefreshAutomationRoot(process, bringToFront: false);
                        card = FindDatasetDashboardMetricCardElement(root, cardAction);
                        return IsAutomationElementVisible(card);
                    },
                    TimeSpan.FromSeconds(6));
                if (!cardFound)
                {
                    TryCaptureExeSmokeFailure(root, outputPath, $"guide-dashboard-card-{cardAction}-not-found");
                    Console.Error.WriteLine("EXE_GUIDE_DASHBOARD_CARD_AUTOMATION_SAMPLE " + BuildAutomationTextSample(root, 120));
                }

                AssertTrue(cardFound, $"dataset dashboard card {cardAction} was not visible in the real EXE guide");
                cardsFound++;
                bool cardClickable = TryBringDatasetDashboardMetricCardIntoClickableView(process, cardAction, out card);
                if (!cardClickable)
                {
                    root = RefreshAutomationRoot(process, bringToFront: false);
                    TryCaptureExeSmokeFailure(root, outputPath, $"guide-dashboard-card-{cardAction}-not-clickable");
                }

                AssertTrue(cardClickable, $"dataset dashboard card {cardAction} was not inside the visible guide viewport before click");

                Stopwatch stopwatch = Stopwatch.StartNew();
                Point cardCenter = GetAutomationCenter(card);
                System.Windows.Rect cardClickBounds = card.Current.BoundingRectangle;
                NativeClick(cardCenter);
                string cardSignal = string.Empty;
                bool cardVerified = WaitUntil(
                    () => TryVerifyDatasetDashboardMetricEffect(process, cardAction, out cardSignal),
                    TimeSpan.FromSeconds(5));
                stopwatch.Stop();
                totalMilliseconds += stopwatch.Elapsed.TotalMilliseconds;
                maxMilliseconds = Math.Max(maxMilliseconds, stopwatch.Elapsed.TotalMilliseconds);
                statusItems.Add(FormattableString.Invariant($"{cardAction}:{cardSignal}"));

                if (!cardVerified)
                {
                    root = RefreshAutomationRoot(process, bringToFront: false);
                    TryCaptureExeSmokeFailure(root, outputPath, $"guide-dashboard-card-{cardAction}-not-verified");
                    string modelStatus = GetAutomationValueByAutomationId(root, "ModelStatusText");
                    Console.Error.WriteLine(
                        FormattableString.Invariant(
                            $"EXE_GUIDE_DASHBOARD_CARD_STATUS_AFTER_CLICK action={cardAction} center=({cardCenter.X},{cardCenter.Y}) bounds={cardClickBounds} signal=\"{cardSignal}\" status=\"{modelStatus}\""));
                }

                AssertTrue(cardVerified, $"clicking dataset dashboard card {cardAction} did not reach its expected real-EXE target");
                cardsVerified++;
            }

            root = RefreshAutomationRoot(process, bringToFront: false);
            CaptureAutomationRoot(root, outputPath);
            return new ExeGuideDashboardCardSmokeResult(
                string.Join(",", cardActions.Select(action => action.ToString())),
                totalMilliseconds,
                maxMilliseconds,
                cardsFound,
                cardsVerified,
                string.Join(" | ", statusItems));
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    private static ExeRoiToolsSmokeResult ExecuteExeRoiToolsSmoke(
        string exePath,
        string outputPath,
        int seed,
        int boxCount)
    {
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE ROI-tools smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE ROI-tools smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE ROI-tools smoke automation root was not available");
            WaitForAutomationText(root, "\uCE94\uBC84\uC2A4", TimeSpan.FromSeconds(10));

            AssertTrue(
                TryInvokeExeHeaderToolButton(process, "QuickLoadSampleButton"),
                "EXE purpose-scope smoke sample-load button was not invokable");
            Thread.Sleep(800);
            root = RefreshAutomationRoot(process);
            WaitForAutomationText(root, "\uBE60\uB978 \uB3C4\uAD6C", TimeSpan.FromSeconds(10));
            System.Windows.Automation.AutomationElement canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "EXE ROI-tools smoke canvas was not found");
            System.Windows.Rect canvasRect = canvas.Current.BoundingRectangle;
            AssertTrue(canvasRect.Width > 100 && canvasRect.Height > 100, "EXE ROI-tools smoke canvas bounds were not usable");

            var random = new Random(seed);
            string smokeImagePath = ResolveVisualSmokeImagePath();
            bool hasSmokeImageBounds = !string.IsNullOrWhiteSpace(smokeImagePath) && File.Exists(smokeImagePath);
            System.Windows.Rect annotationRegion = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageRegion(canvasRect, smokeImagePath)
                : BuildExeSmokeAnnotationRegion(canvasRect);
            if (!ClickDatasetPurposeByText(root, "\uAC1D\uCCB4 \uD0D0\uC9C0"))
            {
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                    "guide/tools tab was not selectable before ROI-tools smoke");
                root = RefreshAutomationRoot(process);
                AssertTrue(
                    ClickDatasetPurposeByText(root, "\uAC1D\uCCB4 \uD0D0\uC9C0"),
                    "native click did not find the object-detection dataset purpose");
            }

            root = RefreshAutomationRoot(process);
            System.Windows.Automation.AutomationElement boxToolItem = FindAnnotationToolItem(root, "\uBC15\uC2A4");
            AssertTrue(boxToolItem != null, "native click did not find the box tool");
            NativeClick(GetAutomationCenter(boxToolItem));
            bool boxSelected = WaitUntil(
                () => IsAutomationSelectionItemSelected(boxToolItem)
                    || string.Equals(GetSelectedAnnotationToolText(RefreshAutomationRoot(process, bringToFront: false)), "\uBC15\uC2A4", StringComparison.Ordinal),
                TimeSpan.FromSeconds(2));
            AssertTrue(boxSelected, "real native click did not select the box tool");

            IReadOnlyList<ExeSmokeDragPath> boxDrags = BuildExeSmokeBoxDrags(random, annotationRegion, boxCount);
            ExeSmokeDragBatchMetrics boxInputMetrics = ExecuteExeSmokeDragBatch(boxDrags, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 10);

            root = RefreshAutomationRoot(process);
            if (!ContainsAutomationText(root, "/ \uBC15\uC2A4"))
            {
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "ObjectsReviewTab") || SelectTabItemByName(root, "\uC800\uC7A5 \uB77C\uBCA8"),
                    "saved-label tab was not selectable after ROI smoke box drawing");
                root = RefreshAutomationRoot(process);
            }

            bool objectRowVisible = WaitUntil(
                () => ContainsAutomationText(RefreshAutomationRoot(process, bringToFront: false), "/ \uBC15\uC2A4"),
                TimeSpan.FromSeconds(4));
            AssertTrue(objectRowVisible, "real EXE ROI smoke box draw did not create an object-review row");

            ExeSmokeDragPath selectedBox = boxDrags[random.Next(boxDrags.Count)];
            Stopwatch selectToDeleteEnabledStopwatch = Stopwatch.StartNew();
            NativeClick(selectedBox.Center);
            bool deleteButtonEnabledAfterRoiClick = WaitUntil(
                () => FindEnabledObjectDeleteButton(RefreshAutomationRoot(process, bringToFront: false)) != null,
                TimeSpan.FromSeconds(2));
            selectToDeleteEnabledStopwatch.Stop();
            AssertTrue(deleteButtonEnabledAfterRoiClick, "real EXE ROI click did not keep a selectable object/delete state");

            root = RefreshAutomationRoot(process, bringToFront: false);
            System.Windows.Automation.AutomationElement deleteButton = FindEnabledObjectDeleteButton(root);
            AssertTrue(deleteButton != null, "real EXE delete button was not enabled after selecting the ROI");
            System.Windows.Automation.AutomationElement statusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");

            // The regression this catches is a full overlay/list redraw on a single-object
            // delete. Wheel and UIAutomation reads should remain responsive immediately
            // after the delete button's MouseUp.
            double deleteThenWheelMilliseconds = MeasureExeSmokeClickReleaseThenWheelResponsiveness(
                process,
                GetAutomationCenter(deleteButton),
                RandomPointInRect(random, annotationRegion),
                statusElement);
            AssertTrue(deleteThenWheelMilliseconds < 2_000.0, "real EXE ROI delete should not block immediate wheel/UIAutomation response");

            bool remainingObjectVisible = WaitUntil(
                () =>
                {
                    var currentRoot = RefreshAutomationRoot(process, bringToFront: false);
                    return boxDrags.Count <= 1
                        ? ContainsAutomationText(currentRoot, "\uD604\uC7AC \uC774\uBBF8\uC9C0 \uAC1D\uCCB4 \uC5C6\uC74C")
                        : ContainsAutomationText(currentRoot, "/ \uBC15\uC2A4");
                },
                TimeSpan.FromSeconds(4));
            AssertTrue(remainingObjectVisible, "real EXE ROI delete did not leave the expected object-review state");

            root = RefreshAutomationRoot(process, bringToFront: false);
            CaptureAutomationRoot(root, outputPath);
            return new ExeRoiToolsSmokeResult(
                seed,
                boxDrags.Count,
                boxInputMetrics.TotalMilliseconds,
                boxInputMetrics.AverageMilliseconds,
                boxInputMetrics.MaxMilliseconds,
                selectToDeleteEnabledStopwatch.Elapsed.TotalMilliseconds,
                deleteThenWheelMilliseconds,
                boxSelected,
                objectRowVisible,
                deleteButtonEnabledAfterRoiClick,
                remainingObjectVisible);
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    private static ExeUndoRedoSmokeResult ExecuteExeUndoRedoSmoke(
        string exePath,
        string outputPath,
        string recipeName,
        string outputRoot,
        string recipeDirectory,
        string fakeYoloRoot)
    {
        Process process = null;
        bool completed = false;
        try
        {
            string imageRoot = Path.Combine(outputRoot, "data", "train", "images");
            string imagePath = Path.Combine(imageRoot, "undo-redo-target.jpg");
            Directory.CreateDirectory(imageRoot);
            CreateVisualSmokeImage(imagePath);
            PrepareExeCandidateFocusFakeYoloProject(fakeYoloRoot);
            WriteExeCandidateFocusRecipe(recipeName, outputRoot, recipeDirectory, fakeYoloRoot, imageRoot);

            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE undo/redo smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE undo/redo smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE undo/redo smoke automation root was not available");
            WaitForAutomationText(root, "\uCE94\uBC84\uC2A4", TimeSpan.FromSeconds(10));

            bool recipeApplied = ApplyExeSmokeRecipe(process, recipeName);
            bool imageLoaded;
            if (recipeApplied)
            {
                Thread.Sleep(500);
                AssertTrue(
                    SelectImageQueueItemBySearch(process, "undo-redo-target", TimeSpan.FromSeconds(6)),
                    "EXE undo/redo smoke target image was not selectable from the queue");
                imageLoaded = WaitUntil(
                    () => GetAutomationValueByAutomationId(RefreshAutomationRoot(process, bringToFront: false), "DatasetStatusText")
                        .Contains("undo-redo-target", StringComparison.OrdinalIgnoreCase),
                    TimeSpan.FromSeconds(5));
                AssertTrue(imageLoaded, "EXE undo/redo smoke target image was not loaded");
            }
            else
            {
                root = RefreshAutomationRoot(process, bringToFront: false);
                Console.WriteLine("EXE_UNDO_REDO_SMOKE_RECIPE_FALLBACK " + BuildAutomationTextSample(root, 120));
                imageLoaded = FindAutomationElementByClass(root, "RoiImageCanvasView") != null
                    && !string.IsNullOrWhiteSpace(GetAutomationValueByAutomationId(root, "DatasetStatusText"));
                AssertTrue(imageLoaded, "EXE undo/redo smoke could not find a loaded current image for fallback verification");
            }

            root = RefreshAutomationRoot(process, handle);
            int baselineLabelCount = GetExeCanvasLabelCount(root);
            using Bitmap beforeBitmap = CaptureAutomationRootBitmap(root);
            bool quickBoxCreated =
                TryInvokeAutomationButtonByAutomationId(root, "AddSampleRoiButton")
                    || TryInvokeAutomationButton(root, "\uBC15\uC2A4");
            System.Windows.Rect probeRegion = default;
            bool undoButtonEnabledAfterDraw = false;
            bool undoButtonWasCheckedInBrushMode = false;
            bool brushRoute = false;
            int randomBrushStrokeCount = 0;
            if (!quickBoxCreated)
            {
                bool brushCreated = TryCreateExeUndoRedoBrushTarget(
                    process,
                    outputPath,
                    baselineLabelCount,
                    out probeRegion,
                    out undoButtonEnabledAfterDraw,
                    out randomBrushStrokeCount);
                if (brushCreated)
                {
                    brushRoute = true;
                    undoButtonWasCheckedInBrushMode = true;
                    root = RefreshAutomationRoot(process, handle, bringToFront: false);
                }
                else
                {
                    root = RefreshAutomationRoot(process);
                    AssertTrue(
                        SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                        "guide/tools tab was not selectable before drawing the undo/redo smoke box");
                    root = RefreshAutomationRoot(process);
                    System.Windows.Automation.AutomationElement boxToolItem = FindAnnotationToolItem(root, "\uBC15\uC2A4");
                    if (boxToolItem == null)
                    {
                        TryCaptureExeSmokeFailure(root, outputPath, "undo-redo-no-create-tool");
                        Console.WriteLine("EXE_UNDO_REDO_SMOKE_NO_CREATE_TOOL " + BuildAutomationTextSample(root, 160));
                    }

                    AssertTrue(boxToolItem != null, "undo/redo smoke could not find a brush or box tool");
                    NativeClick(GetAutomationCenter(boxToolItem));
                    bool boxSelected = WaitUntil(
                        () => IsAutomationSelectionItemSelected(boxToolItem)
                            || IsExeSmokeBoxToolSelected(RefreshAutomationRoot(process, bringToFront: false)),
                        TimeSpan.FromSeconds(2));
                    AssertTrue(boxSelected, "undo/redo smoke box tool was not selected");
                    root = RefreshAutomationRoot(process);
                    System.Windows.Automation.AutomationElement drawCanvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
                    AssertTrue(drawCanvas != null, "undo/redo smoke canvas was not found before drawing a box");
                    System.Windows.Rect annotationRegion = File.Exists(imagePath)
                        ? BuildExeSmokeFittedImageRegion(drawCanvas.Current.BoundingRectangle, imagePath)
                        : BuildExeSmokeAnnotationRegion(drawCanvas.Current.BoundingRectangle);
                    ExeSmokeDragPath boxDrag = BuildExeSmokeCenterBoxDrag(annotationRegion);
                    probeRegion = BuildExeUndoRedoProbeRegion(boxDrag, padding: 20);
                    _ = ExecuteExeSmokeDragBatch(new[] { boxDrag }, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 40);
                    undoButtonEnabledAfterDraw = WaitUntil(
                        () => IsAutomationButtonEnabledByAutomationId(RefreshAutomationRoot(process, bringToFront: false), "CanvasUndoAnnotationButton"),
                        TimeSpan.FromSeconds(2));
                }
            }
            else
            {
                undoButtonEnabledAfterDraw = WaitUntil(
                    () => IsAutomationButtonEnabledByAutomationId(RefreshAutomationRoot(process, bringToFront: false), "CanvasUndoAnnotationButton"),
                    TimeSpan.FromSeconds(2));
            }

            bool roiCreated = WaitUntil(
                () => HasExeUndoRedoTargetAnnotation(RefreshAutomationRoot(process, bringToFront: false), baselineLabelCount),
                TimeSpan.FromSeconds(5));
            if (!roiCreated)
            {
                TryCaptureExeSmokeFailure(RefreshAutomationRoot(process, bringToFront: false), outputPath, "undo-redo-target-not-created");
                Console.WriteLine("EXE_UNDO_REDO_SMOKE_TARGET_NOT_CREATED " + BuildAutomationTextSample(RefreshAutomationRoot(process, bringToFront: false), 160));
            }

            AssertTrue(roiCreated, "EXE undo/redo smoke did not create an annotation target");
            root = RefreshAutomationRoot(process, handle);
            if (!undoButtonWasCheckedInBrushMode && !undoButtonEnabledAfterDraw)
            {
                undoButtonEnabledAfterDraw = IsAutomationButtonEnabledByAutomationId(root, "CanvasUndoAnnotationButton");
            }

            AssertTrue(
                undoButtonEnabledAfterDraw,
                undoButtonWasCheckedInBrushMode
                    ? "EXE brush stroke should enable the undo button before switching away from the brush tool"
                    : "EXE annotation creation should enable the undo button");
            if (probeRegion == default)
            {
                System.Windows.Automation.AutomationElement latestCanvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
                AssertTrue(latestCanvas != null, "EXE undo/redo smoke canvas was not found before building a fallback probe region");
                System.Windows.Rect bounds = latestCanvas.Current.BoundingRectangle;
                probeRegion = new System.Windows.Rect(
                    bounds.Left + (bounds.Width * 0.38D),
                    bounds.Top + (bounds.Height * 0.38D),
                    bounds.Width * 0.24D,
                    bounds.Height * 0.24D);
            }

            using Bitmap createdBitmap = CaptureAutomationRootBitmap(root);
            System.Windows.Automation.AutomationElement canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "EXE undo/redo smoke canvas was not found before sending shortcuts");
            BringNativeWindowToFront(handle);
            NativeClick(GetAutomationCenter(canvas));
            Thread.Sleep(120);

            Stopwatch ctrlZStopwatch = Stopwatch.StartNew();
            SendKeys.SendWait("^z");
            bool ctrlZRemovedObject = brushRoute
                ? WaitForExeUndoRedoPixelState(
                    process,
                    beforeBitmap,
                    createdBitmap,
                    root.Current.BoundingRectangle,
                    probeRegion,
                    expectChangedFromBefore: false,
                    TimeSpan.FromSeconds(4))
                : WaitUntil(
                    () => !HasExeUndoRedoTargetAnnotation(RefreshAutomationRoot(process, bringToFront: false), baselineLabelCount),
                    TimeSpan.FromSeconds(4));
            ctrlZStopwatch.Stop();
            if (!ctrlZRemovedObject)
            {
                TryCaptureExeSmokeFailure(RefreshAutomationRoot(process, bringToFront: false), outputPath, "undo-redo-ctrl-z-did-not-remove");
            }

            AssertTrue(
                ctrlZRemovedObject,
                brushRoute
                    ? "Ctrl+Z in the real EXE should remove the last random brush stroke from the canvas"
                    : "Ctrl+Z in the real EXE should undo the added annotation");
            root = RefreshAutomationRoot(process, bringToFront: false);
            using Bitmap undoneBitmap = CaptureAutomationRootBitmap(root);
            BringNativeWindowToFront(handle);
            NativeClick(GetAutomationCenter(canvas));
            Thread.Sleep(120);

            Stopwatch ctrlShiftZStopwatch = Stopwatch.StartNew();
            SendKeys.SendWait("^+z");
            bool ctrlShiftZRestoredObject = brushRoute
                ? WaitForExeUndoRedoPixelState(
                    process,
                    beforeBitmap,
                    createdBitmap,
                    root.Current.BoundingRectangle,
                    probeRegion,
                    expectChangedFromBefore: true,
                    TimeSpan.FromSeconds(4))
                : WaitUntil(
                    () => HasExeUndoRedoTargetAnnotation(RefreshAutomationRoot(process, bringToFront: false), baselineLabelCount),
                    TimeSpan.FromSeconds(4));
            ctrlShiftZStopwatch.Stop();
            if (!ctrlShiftZRestoredObject)
            {
                TryCaptureExeSmokeFailure(RefreshAutomationRoot(process, bringToFront: false), outputPath, "undo-redo-ctrl-shift-z-did-not-restore");
            }

            AssertTrue(
                ctrlShiftZRestoredObject,
                brushRoute
                    ? "Ctrl+Shift+Z in the real EXE should restore the last random brush stroke after Ctrl+Z"
                    : "Ctrl+Shift+Z in the real EXE should redo the annotation after Ctrl+Z");
            root = RefreshAutomationRoot(process, bringToFront: false);
            using Bitmap redoneBitmap = CaptureAutomationRootBitmap(root);
            ExeUndoRedoPixelMetrics pixelMetrics = VerifyExeUndoRedoPixelRegion(
                beforeBitmap,
                createdBitmap,
                undoneBitmap,
                redoneBitmap,
                root.Current.BoundingRectangle,
                probeRegion);
            SaveBitmap(beforeBitmap, BuildSiblingOutputPath(outputPath, "before"));
            SaveBitmap(createdBitmap, BuildSiblingOutputPath(outputPath, "created"));
            SaveBitmap(undoneBitmap, BuildSiblingOutputPath(outputPath, "undo"));
            SaveBitmap(redoneBitmap, outputPath);
            Console.WriteLine(
                FormattableString.Invariant(
                    $"EXE_UNDO_REDO_PIXEL_CHECK createdDiff={pixelMetrics.CreatedDiffPixels} undoResidual={pixelMetrics.UndoResidualPixels} redoDiff={pixelMetrics.RedoDiffPixels} redoOverlap={pixelMetrics.CreatedRedoOverlapPixels} createdRedoDelta={pixelMetrics.CreatedRedoDeltaPixels} probe={pixelMetrics.ProbeRectangle}"));
            completed = true;
            return new ExeUndoRedoSmokeResult(
                recipeApplied,
                ImageLoaded: true,
                RoiCreated: true,
                brushRoute,
                randomBrushStrokeCount,
                undoButtonEnabledAfterDraw,
                CtrlZRemovedObject: true,
                CtrlShiftZRestoredObject: true,
                pixelMetrics.CreatedDiffPixels,
                pixelMetrics.UndoResidualPixels,
                pixelMetrics.RedoDiffPixels,
                pixelMetrics.CreatedRedoOverlapPixels,
                pixelMetrics.CreatedRedoDeltaPixels,
                ctrlZStopwatch.Elapsed.TotalMilliseconds,
                ctrlShiftZStopwatch.Elapsed.TotalMilliseconds);
        }
        finally
        {
            CloseExeSmokeProcess(process);
            if (completed)
            {
                DeleteDirectoryIfExists(recipeDirectory);
                DeleteDirectoryIfExists(outputRoot);
                DeleteDirectoryIfExists(fakeYoloRoot);
            }
        }
    }

    private static bool TryCreateExeUndoRedoBrushTarget(
        Process process,
        string outputPath,
        int baselineLabelCount,
        out System.Windows.Rect probeRegion,
        out bool undoButtonEnabledBeforeToolSwitch,
        out int randomBrushStrokeCount)
    {
        probeRegion = default;
        undoButtonEnabledBeforeToolSwitch = false;
        randomBrushStrokeCount = 0;
        System.Windows.Automation.AutomationElement root = RefreshAutomationRoot(process);
        System.Windows.Automation.AutomationElement brushToolItem = FindAnnotationToolItem(root, "\uBE0C\uB7EC\uC2DC");
        if (brushToolItem == null)
        {
            return false;
        }

        NativeClick(GetAutomationCenter(brushToolItem));
        bool brushSelected = WaitUntil(
            () => IsAutomationSelectionItemSelected(brushToolItem)
                || string.Equals(GetSelectedAnnotationToolText(RefreshAutomationRoot(process, bringToFront: false)), "\uBE0C\uB7EC\uC2DC", StringComparison.Ordinal),
            TimeSpan.FromSeconds(2));
        if (!brushSelected)
        {
            TryCaptureExeSmokeFailure(root, outputPath, "undo-redo-brush-not-selected");
            return false;
        }

        root = RefreshAutomationRoot(process);
        System.Windows.Automation.AutomationElement canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
        if (canvas == null)
        {
            TryCaptureExeSmokeFailure(root, outputPath, "undo-redo-brush-no-canvas");
            return false;
        }

        var random = new Random(20260704);
        System.Windows.Rect annotationRegion = BuildExeSmokeAnnotationRegion(canvas.Current.BoundingRectangle);
        IReadOnlyList<ExeSmokeDragPath> brushDrags = BuildExeSmokeSeparatedStrokeDrags(random, annotationRegion, 4);
        randomBrushStrokeCount = brushDrags.Count;
        probeRegion = BuildExeUndoRedoProbeRegion(brushDrags[brushDrags.Count - 1], padding: 36);
        _ = ExecuteExeSmokeDragBatch(brushDrags, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 20);

        root = RefreshAutomationRoot(process, bringToFront: false);
        undoButtonEnabledBeforeToolSwitch = WaitUntil(
            () => IsAutomationButtonEnabledByAutomationId(RefreshAutomationRoot(process, bringToFront: false), "CanvasUndoAnnotationButton"),
            TimeSpan.FromSeconds(2));
        using Bitmap brushActiveBitmap = CaptureAutomationRootBitmap(root);
        SaveBitmap(brushActiveBitmap, BuildSiblingOutputPath(outputPath, "brush-active"));
        if (!undoButtonEnabledBeforeToolSwitch)
        {
            TryCaptureExeSmokeFailure(root, outputPath, "undo-redo-brush-undo-disabled");
        }

        System.Windows.Automation.AutomationElement selectToolItem = FindAnnotationToolItem(root, "\uC120\uD0DD");
        if (selectToolItem != null)
        {
            NativeClick(GetAutomationCenter(selectToolItem));
        }

        bool materialized = WaitUntil(
            () => HasExeUndoRedoTargetAnnotation(RefreshAutomationRoot(process, bringToFront: false), baselineLabelCount),
            TimeSpan.FromSeconds(4));
        if (!materialized)
        {
            TryCaptureExeSmokeFailure(RefreshAutomationRoot(process, bringToFront: false), outputPath, "undo-redo-brush-not-materialized");
        }

        return materialized;
    }

    private static bool HasExeUndoRedoTargetAnnotation(
        System.Windows.Automation.AutomationElement root,
        int baselineLabelCount)
    {
        if (ContainsExeUndoRedoBoxRow(root))
        {
            return true;
        }

        int currentLabelCount = GetExeCanvasLabelCount(root);
        return currentLabelCount > baselineLabelCount;
    }

    private static int GetExeCanvasLabelCount(System.Windows.Automation.AutomationElement root)
    {
        string value = GetAutomationValueByAutomationId(root, "CanvasLabelLayerText");
        if (string.IsNullOrWhiteSpace(value))
        {
            foreach (System.Windows.Automation.AutomationElement element in EnumerateAutomationDescendants(root))
            {
                string name;
                try
                {
                    name = element.Current.Name;
                }
                catch (System.Windows.Automation.ElementNotAvailableException)
                {
                    continue;
                }

                if (!string.IsNullOrWhiteSpace(name)
                    && name.Contains("\uB77C\uBCA8", StringComparison.Ordinal)
                    && name.Contains("\uAC1C \uD45C\uC2DC", StringComparison.Ordinal))
                {
                    value = name;
                    break;
                }
            }
        }

        if (string.IsNullOrWhiteSpace(value))
        {
            return 0;
        }

        int start = -1;
        for (int index = 0; index < value.Length; index++)
        {
            if (char.IsDigit(value[index]))
            {
                start = index;
                break;
            }
        }

        if (start < 0)
        {
            return 0;
        }

        int end = start;
        while (end < value.Length && char.IsDigit(value[end]))
        {
            end++;
        }

        return int.TryParse(value.Substring(start, end - start), NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsed)
            ? parsed
            : 0;
    }

    private static System.Windows.Rect BuildExeUndoRedoProbeRegion(ExeSmokeDragPath drag, int padding)
    {
        AssertTrue(drag.Points != null && drag.Points.Count > 0, "undo/redo pixel probe requires drag points");
        int left = drag.Points.Min(point => point.X) - padding;
        int top = drag.Points.Min(point => point.Y) - padding;
        int right = drag.Points.Max(point => point.X) + padding;
        int bottom = drag.Points.Max(point => point.Y) + padding;
        return new System.Windows.Rect(left, top, Math.Max(1, right - left), Math.Max(1, bottom - top));
    }

    private static bool WaitForExeUndoRedoPixelState(
        Process process,
        Bitmap beforeBitmap,
        Bitmap createdBitmap,
        System.Windows.Rect rootBounds,
        System.Windows.Rect probeRegion,
        bool expectChangedFromBefore,
        TimeSpan timeout)
    {
        DateTime deadline = DateTime.UtcNow.Add(timeout);
        int lastChangedPixels = 0;
        Rectangle probe = BuildBitmapProbeRectangle(rootBounds, probeRegion, beforeBitmap.Size);
        int createdDiffPixels = createdBitmap == null ? 0 : CountChangedPixels(beforeBitmap, createdBitmap, probe);
        int minimumDiff = Math.Min(25, Math.Max(8, probe.Width * probe.Height / 80));
        int undoResidualLimit = Math.Max(12, createdDiffPixels > 0 ? createdDiffPixels / 4 : minimumDiff / 2);
        while (DateTime.UtcNow < deadline)
        {
            using Bitmap currentBitmap = CaptureAutomationRootBitmap(RefreshAutomationRoot(process, bringToFront: false));
            lastChangedPixels = CountChangedPixels(beforeBitmap, currentBitmap, probe);
            if (expectChangedFromBefore ? lastChangedPixels >= minimumDiff : lastChangedPixels <= undoResidualLimit)
            {
                return true;
            }

            Thread.Sleep(120);
        }

        Console.WriteLine($"EXE_UNDO_REDO_PIXEL_WAIT changed={lastChangedPixels} expectChanged={expectChangedFromBefore}");
        return false;
    }

    private static int CountChangedPixels(Bitmap baselineBitmap, Bitmap currentBitmap, Rectangle probe)
    {
        int changed = 0;
        const int threshold = 28;
        for (int y = probe.Top; y < probe.Bottom; y++)
        {
            for (int x = probe.Left; x < probe.Right; x++)
            {
                if (ColorDistance(baselineBitmap.GetPixel(x, y), currentBitmap.GetPixel(x, y)) > threshold)
                {
                    changed++;
                }
            }
        }

        return changed;
    }

    private static ExeUndoRedoPixelMetrics VerifyExeUndoRedoPixelRegion(
        Bitmap beforeBitmap,
        Bitmap createdBitmap,
        Bitmap undoneBitmap,
        Bitmap redoneBitmap,
        System.Windows.Rect rootBounds,
        System.Windows.Rect probeRegion)
    {
        Rectangle probe = BuildBitmapProbeRectangle(rootBounds, probeRegion, beforeBitmap.Size);
        AssertTrue(probe.Width > 4 && probe.Height > 4, "undo/redo pixel probe region was empty");

        int createdDiff = 0;
        int undoResidual = 0;
        int redoDiff = 0;
        int createdRedoOverlap = 0;
        int createdRedoDelta = 0;
        const int threshold = 28;
        for (int y = probe.Top; y < probe.Bottom; y++)
        {
            for (int x = probe.Left; x < probe.Right; x++)
            {
                Color before = beforeBitmap.GetPixel(x, y);
                bool createdChanged = ColorDistance(before, createdBitmap.GetPixel(x, y)) > threshold;
                bool undoneChanged = ColorDistance(before, undoneBitmap.GetPixel(x, y)) > threshold;
                bool redoneChanged = ColorDistance(before, redoneBitmap.GetPixel(x, y)) > threshold;
                if (createdChanged)
                {
                    createdDiff++;
                }

                if (undoneChanged)
                {
                    undoResidual++;
                }

                if (redoneChanged)
                {
                    redoDiff++;
                }

                if (createdChanged && redoneChanged)
                {
                    createdRedoOverlap++;
                }

                if (ColorDistance(createdBitmap.GetPixel(x, y), redoneBitmap.GetPixel(x, y)) > threshold)
                {
                    createdRedoDelta++;
                }
            }
        }

        int minimumDiff = Math.Min(25, Math.Max(8, probe.Width * probe.Height / 80));
        AssertTrue(createdDiff >= minimumDiff, $"drawn annotation did not produce visible pixels in the probe region: {createdDiff}");
        AssertTrue(redoDiff >= minimumDiff, $"redo did not restore visible pixels in the probe region: {redoDiff}");
        AssertTrue(undoResidual <= Math.Max(12, createdDiff / 4), $"undo left too much of the drawn region visible: residual={undoResidual}, created={createdDiff}");
        AssertTrue(createdRedoOverlap >= Math.Max(12, Math.Min(createdDiff, redoDiff) / 8), $"redo did not restore enough of the same drawn probe area: overlap={createdRedoOverlap}, created={createdDiff}, redo={redoDiff}");

        return new ExeUndoRedoPixelMetrics(
            createdDiff,
            undoResidual,
            redoDiff,
            createdRedoOverlap,
            createdRedoDelta,
            $"{probe.Left},{probe.Top},{probe.Width},{probe.Height}");
    }

    private static Rectangle BuildBitmapProbeRectangle(
        System.Windows.Rect rootBounds,
        System.Windows.Rect probeRegion,
        Size bitmapSize)
    {
        var probe = new Rectangle(
            (int)Math.Floor(probeRegion.Left - rootBounds.Left),
            (int)Math.Floor(probeRegion.Top - rootBounds.Top),
            Math.Max(1, (int)Math.Ceiling(probeRegion.Width)),
            Math.Max(1, (int)Math.Ceiling(probeRegion.Height)));
        return Rectangle.Intersect(new Rectangle(0, 0, bitmapSize.Width, bitmapSize.Height), probe);
    }

    private static int ColorDistance(Color left, Color right)
        => Math.Abs(left.R - right.R) + Math.Abs(left.G - right.G) + Math.Abs(left.B - right.B);

    private static string BuildSiblingOutputPath(string outputPath, string suffix)
    {
        string directory = Path.GetDirectoryName(outputPath);
        string stem = Path.GetFileNameWithoutExtension(outputPath);
        string extension = Path.GetExtension(outputPath);
        return Path.Combine(
            string.IsNullOrWhiteSpace(directory) ? Environment.CurrentDirectory : directory,
            $"{stem}.{suffix}{(string.IsNullOrWhiteSpace(extension) ? ".png" : extension)}");
    }

    private static bool ContainsExeUndoRedoBoxRow(System.Windows.Automation.AutomationElement root)
        => ContainsAutomationText(root, "Defect / \uBC15\uC2A4");

    private static ExeMaskToolsSmokeResult ExecuteExeMaskToolsSmoke(
        string exePath,
        string outputPath,
        int seed,
        int brushStrokeCount,
        int eraserStrokeCount)
    {
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE mask-tools smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE mask-tools smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE mask-tools smoke automation root was not available");
            WaitForAutomationText(root, "캔버스", TimeSpan.FromSeconds(10));

            TryInvokeAutomationButton(root, "샘플");
            Thread.Sleep(800);
            root = RefreshAutomationRoot(process);
            WaitForAutomationText(root, "캔버스", TimeSpan.FromSeconds(10));
            System.Windows.Automation.AutomationElement canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "EXE mask-tools smoke canvas was not found");
            System.Windows.Rect canvasRect = canvas.Current.BoundingRectangle;
            AssertTrue(canvasRect.Width > 100 && canvasRect.Height > 100, "EXE mask-tools smoke canvas bounds were not usable");

            var random = new Random(seed);
            string smokeImagePath = ResolveVisualSmokeImagePath();
            bool hasSmokeImageBounds = !string.IsNullOrWhiteSpace(smokeImagePath) && File.Exists(smokeImagePath);
            System.Windows.Rect annotationRegion = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageRegion(canvasRect, smokeImagePath)
                : BuildExeSmokeAnnotationRegion(canvasRect);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "DatasetHomeStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "dataset"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowDatasetHomeButton");
            root = RefreshAutomationRoot(process);
            if (!ClickDatasetPurposeByText(root, "세그멘테이션"))
            {
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                    "guide/tools tab was not selectable before mask-tools smoke");
                root = RefreshAutomationRoot(process);
                AssertTrue(ClickDatasetPurposeByText(root, "세그멘테이션"), "native click did not find the segmentation dataset purpose");
            }

            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "LabelingWorkbenchStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "labeling"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowGuideToolsButton")
                || SelectAutomationTabByAutomationId(root, "LearningReviewTab");
            root = RefreshAutomationRoot(process);
            System.Windows.Automation.AutomationElement brushToolItem = FindAnnotationToolItem(root, "브러시");
            System.Windows.Automation.AutomationElement eraserToolItem = FindAnnotationToolItem(root, "지우개");
            System.Windows.Automation.AutomationElement selectToolItem = FindAnnotationToolItem(root, "선택");
            AssertTrue(brushToolItem != null, "native click did not find the brush tool");
            AssertTrue(eraserToolItem != null, "native click did not find the eraser tool before brush strokes");
            AssertTrue(selectToolItem != null, "native click did not find the select tool before mask materialization");
            System.Windows.Automation.AutomationElement statusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            Point brushToolCenter = GetAutomationCenter(brushToolItem);
            Point eraserToolCenter = GetAutomationCenter(eraserToolItem);
            Point selectToolCenter = GetAutomationCenter(selectToolItem);
            NativeClick(brushToolCenter);
            bool brushSelected = WaitUntil(
                () => IsAutomationSelectionItemSelected(brushToolItem),
                TimeSpan.FromSeconds(2));
            AssertTrue(brushSelected, "real native click did not select the brush tool");

            IReadOnlyList<ExeSmokeDragPath> brushDrags = BuildExeSmokeStrokeDrags(random, annotationRegion, brushStrokeCount);
            ExeSmokeDragBatchMetrics brushInputMetrics = ExecuteExeSmokeDragBatch(brushDrags, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 8);

            // Cache the tool centers before painting so this metric reflects a real
            // operator click after MouseUp, not helper sleep or a slow UIAutomation tree search.
            double brushSwitchMilliseconds = MeasureExeSmokeClickReleaseThenSelectionResponsiveness(
                eraserToolCenter,
                eraserToolItem,
                TimeSpan.FromSeconds(2),
                out bool eraserSelected);
            AssertTrue(eraserSelected, "real native click did not select the eraser tool after brush strokes");

            Stopwatch brushCommitWaitStopwatch = new Stopwatch();
            // Brush -> eraser must stay in the GPU-preview path. Waiting for CPU
            // materialization here would measure the stutter we are intentionally
            // removing from the active paint loop.

            IReadOnlyList<ExeSmokeDragPath> eraserDrags = BuildExeSmokeEraserDrags(random, brushDrags, annotationRegion, eraserStrokeCount);
            ExeSmokeDragBatchMetrics eraserInputMetrics = ExecuteExeSmokeDragBatch(eraserDrags, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 8);
            Stopwatch eraserCommitWaitStopwatch = new Stopwatch();

            ExeSmokeDragPath eraserWheelProbe = BuildExeSmokeEraserDrags(random, brushDrags, annotationRegion, 1)[0];
            root = RefreshAutomationRoot(process, bringToFront: false);
            System.Windows.Automation.AutomationElement eraserStatusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            double eraserImmediateWheelUiMilliseconds = MeasureExeSmokeStrokeReleaseThenWheelResponsiveness(
                process,
                eraserWheelProbe,
                moveDelayMilliseconds: 1,
                wheelPoint: RandomPointInRect(random, annotationRegion),
                statusElement: eraserStatusElement);
            AssertTrue(eraserImmediateWheelUiMilliseconds < 2_000.0, "real EXE eraser MouseUp should not block immediate wheel/UIAutomation response");

            root = RefreshAutomationRoot(process, bringToFront: false);
            selectToolItem = FindAnnotationToolItem(root, "선택") ?? selectToolItem;
            System.Windows.Automation.AutomationElement materializeStatusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            string materializePreviousCommitSignal = GetAutomationHelpText(materializeStatusElement);
            bool materializeAlreadyReported = IsChangedExeMaskCommitSignal(materializePreviousCommitSignal);
            eraserCommitWaitStopwatch.Start();
            double selectExitMilliseconds = MeasureExeSmokeClickReleaseThenSelectionResponsiveness(
                selectToolCenter,
                selectToolItem,
                TimeSpan.FromSeconds(2),
                out bool selectSelectedAfterPaint);
            string materializeCommitSignal;
            bool materializeReported = materializeAlreadyReported;
            if (materializeReported)
            {
                materializeCommitSignal = materializePreviousCommitSignal;
            }
            else
            {
                materializeReported = WaitForExeMaskCommitSignal(
                    process,
                    materializeStatusElement,
                    materializePreviousCommitSignal,
                    TimeSpan.FromSeconds(3),
                    out materializeCommitSignal);
            }
            eraserCommitWaitStopwatch.Stop();
            if (!materializeReported)
            {
                root = RefreshAutomationRoot(process, bringToFront: false);
                string statusText = GetAutomationValueByAutomationId(root, "ModelStatusText");
                string commitSignal = GetAutomationHelpText(FindAutomationElementByAutomationId(root, "ModelStatusText"));
                TryCaptureExeSmokeFailure(root, outputPath, "mask-materialize-timeout");
                Console.WriteLine($"EXE_MASK_TOOLS_SMOKE_MATERIALIZE_TIMEOUT status=\"{statusText}\" commitSignal=\"{commitSignal}\" selectedTool=\"{GetSelectedAnnotationToolText(root)}\"");
            }

            AssertTrue(selectSelectedAfterPaint, "real native click did not leave the mask paint tool after strokes");
            AssertTrue(materializeReported, "real EXE mask strokes did not materialize after leaving the paint tool");

            root = RefreshAutomationRoot(process, bringToFront: false);
            CaptureAutomationRoot(root, outputPath);
            return new ExeMaskToolsSmokeResult(
                seed,
                brushDrags.Count,
                eraserDrags.Count,
                brushInputMetrics.TotalMilliseconds,
                brushInputMetrics.AverageMilliseconds,
                brushInputMetrics.MaxMilliseconds,
                brushSwitchMilliseconds,
                brushCommitWaitStopwatch.Elapsed.TotalMilliseconds,
                eraserInputMetrics.TotalMilliseconds,
                eraserInputMetrics.AverageMilliseconds,
                eraserInputMetrics.MaxMilliseconds,
                eraserCommitWaitStopwatch.Elapsed.TotalMilliseconds,
                TryParseAutomationMetric(materializeCommitSignal, "waitMs"),
                TryParseAutomationMetric(materializeCommitSignal, "toolEndWaitMs"),
                TryParseAutomationMetric(materializeCommitSignal, "queueMs"),
                selectExitMilliseconds,
                eraserImmediateWheelUiMilliseconds,
                brushSelected,
                eraserSelected);
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    private static ExeMaskClassRecolorSmokeResult ExecuteExeMaskClassRecolorSmoke(
        string exePath,
        string outputPath,
        int seed,
        int brushStrokeCount)
    {
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE mask-class recolor smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE mask-class recolor smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE mask-class recolor smoke automation root was not available");
            WaitForAutomationText(root, "\uCE94\uBC84\uC2A4", TimeSpan.FromSeconds(10));

            _ = TryInvokeAutomationButtonByAutomationId(root, "LoadSampleButton")
                || TryInvokeAutomationButton(root, "\uC0D8\uD50C");
            Thread.Sleep(800);
            root = RefreshAutomationRoot(process);
            System.Windows.Automation.AutomationElement canvas = null;
            bool canvasFound = WaitUntil(
                () =>
                {
                    root = RefreshAutomationRoot(process, handle, bringToFront: false);
                    canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
                    return canvas != null;
                },
                TimeSpan.FromSeconds(5));
            if (!canvasFound)
            {
                TryCaptureExeSmokeFailure(root, outputPath, "canvas-missing");
                Console.WriteLine("EXE_MASK_CLASS_RECOLOR_CANVAS_MISSING " + BuildAutomationTextSample(root, 160));
            }

            AssertTrue(canvas != null, "EXE mask-class recolor smoke canvas was not found");
            System.Windows.Rect canvasRect = canvas.Current.BoundingRectangle;
            AssertTrue(canvasRect.Width > 100 && canvasRect.Height > 100, "EXE mask-class recolor smoke canvas bounds were not usable");

            var random = new Random(seed);
            string smokeImagePath = ResolveVisualSmokeImagePath();
            bool hasSmokeImageBounds = !string.IsNullOrWhiteSpace(smokeImagePath) && File.Exists(smokeImagePath);
            System.Windows.Rect annotationRegion = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageRegion(canvasRect, smokeImagePath)
                : BuildExeSmokeAnnotationRegion(canvasRect);
            if (!ClickDatasetPurposeByText(root, "\uC138\uADF8\uBA58\uD14C\uC774\uC158"))
            {
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                    "guide/tools tab was not selectable before mask-class recolor smoke");
                root = RefreshAutomationRoot(process, handle);
                AssertTrue(ClickDatasetPurposeByText(root, "\uC138\uADF8\uBA58\uD14C\uC774\uC158"), "native click did not find the segmentation dataset purpose");
            }

            root = RefreshAutomationRoot(process, handle);
            System.Windows.Automation.AutomationElement brushToolItem = FindAnnotationToolItem(root, "\uBE0C\uB7EC\uC2DC");
            System.Windows.Automation.AutomationElement selectToolItem = FindAnnotationToolItem(root, "\uC120\uD0DD");
            AssertTrue(brushToolItem != null, "native click did not find the brush tool");
            AssertTrue(selectToolItem != null, "native click did not find the select tool before mask class change");
            NativeClick(GetAutomationCenter(brushToolItem));
            AssertTrue(
                WaitUntil(() => IsAutomationSelectionItemSelected(brushToolItem), TimeSpan.FromSeconds(2)),
                "real native click did not select the brush tool");

            IReadOnlyList<ExeSmokeDragPath> brushDrags = BuildExeSmokeStrokeDrags(random, annotationRegion, brushStrokeCount);
            _ = ExecuteExeSmokeDragBatch(brushDrags, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 8);

            root = RefreshAutomationRoot(process, handle, bringToFront: false);
            System.Windows.Automation.AutomationElement materializeStatusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            string previousCommitSignal = GetAutomationHelpText(materializeStatusElement);
            NativeClick(GetAutomationCenter(selectToolItem));
            bool materialized =
                IsChangedExeMaskCommitSignal(previousCommitSignal)
                || WaitForExeMaskCommitSignal(process, materializeStatusElement, previousCommitSignal, TimeSpan.FromSeconds(3));
            AssertTrue(materialized, "real EXE mask strokes did not materialize before class recolor");

            root = RefreshAutomationRoot(process, handle, bringToFront: false);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "ObjectsReviewTab") || SelectTabItemByName(root, "\uAC1D\uCCB4"),
                "object tab was not selectable after mask materialization");
            bool maskRowVisible = WaitUntil(
                () => ContainsAutomationText(RefreshAutomationRoot(process, handle, bringToFront: false), " / \uB9C8\uC2A4\uD06C"),
                TimeSpan.FromSeconds(4));
            AssertTrue(maskRowVisible, "real EXE mask class smoke did not create a selected object-review mask row");

            root = RefreshAutomationRoot(process, handle, bringToFront: false);
            canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "EXE mask-class recolor smoke canvas was not found before class apply");
            string sourceClass = GetAutomationValueByAutomationId(root, "ObjectClassBox");
            if (string.IsNullOrWhiteSpace(sourceClass))
            {
                sourceClass = "(unknown)";
            }

            using Bitmap beforeClassBitmap = CaptureAutomationRootBitmap(root);
            SaveBitmap(beforeClassBitmap, BuildSiblingOutputPath(outputPath, "before"));
            System.Windows.Rect rootBounds = root.Current.BoundingRectangle;
            System.Windows.Rect canvasProbe = canvas.Current.BoundingRectangle;

            string[] preferredClasses = string.Equals(sourceClass, "OK", StringComparison.OrdinalIgnoreCase)
                ? new[] { "NG", "Defect", "OK" }
                : new[] { "OK", "NG", "Defect" };
            bool classSelected = TrySelectComboBoxItemByAutomationId(process, handle, "ObjectClassBox", preferredClasses, sourceClass, out string targetClass);
            if (!classSelected)
            {
                root = RefreshAutomationRoot(process, handle, bringToFront: false);
                TryCaptureExeSmokeFailure(root, outputPath, "class-combo-target-missing");
                Console.WriteLine($"EXE_MASK_CLASS_RECOLOR_CLASS_COMBO_MISSING sourceClass=\"{sourceClass}\" sample=\"{BuildAutomationTextSample(root, 180)}\"");
            }

            AssertTrue(classSelected, "real EXE object class combo did not expose a selectable target class");
            root = RefreshAutomationRoot(process, handle, bringToFront: false);
            bool applyEnabled = IsAutomationButtonEnabledByAutomationId(root, "ApplyObjectClassButton");
            AssertTrue(applyEnabled, "real EXE apply class button was not enabled after selecting a different class");
            AssertTrue(
                TryInvokeAutomationButtonByAutomationId(root, "ApplyObjectClassButton"),
                "real EXE apply class button was not invokable");

            bool rowUpdated = WaitUntil(
                () => ContainsAutomationText(RefreshAutomationRoot(process, handle, bringToFront: false), targetClass + " / \uB9C8\uC2A4\uD06C"),
                TimeSpan.FromSeconds(3));
            if (!rowUpdated)
            {
                root = RefreshAutomationRoot(process, handle, bringToFront: false);
                TryCaptureExeSmokeFailure(root, outputPath, "row-not-updated");
                Console.WriteLine("EXE_MASK_CLASS_RECOLOR_ROW_MISSING " + BuildAutomationTextSample(root, 160));
            }

            AssertTrue(rowUpdated, "real EXE object-review mask row did not update to the target class");
            root = RefreshAutomationRoot(process, handle, bringToFront: false);
            Thread.Sleep(160);
            using Bitmap afterClassBitmap = CaptureAutomationRootBitmap(root);
            Rectangle probe = BuildBitmapProbeRectangle(rootBounds, canvasProbe, beforeClassBitmap.Size);
            int canvasDiffPixels = CountChangedPixels(beforeClassBitmap, afterClassBitmap, probe);
            CaptureAutomationRoot(root, outputPath);
            return new ExeMaskClassRecolorSmokeResult(
                seed,
                brushDrags.Count,
                sourceClass,
                targetClass,
                canvasDiffPixels,
                rowUpdated,
                applyEnabled);
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    private static ExePurposeScopeSmokeResult ExecuteExePurposeScopeSmoke(
        string exePath,
        string outputPath,
        int seed,
        int brushStrokeCount)
    {
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE purpose-scope smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE purpose-scope smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE purpose-scope smoke automation root was not available");
            WaitForAutomationText(root, "\uCE94\uBC84\uC2A4", TimeSpan.FromSeconds(10));

            AssertTrue(
                TryInvokeExeHeaderToolButton(process, "QuickLoadSampleButton"),
                "purpose-scope smoke sample-load button was not invokable");
            Thread.Sleep(800);
            root = RefreshAutomationRoot(process);
            WaitForAutomationText(root, "\uCE94\uBC84\uC2A4", TimeSpan.FromSeconds(10));
            System.Windows.Automation.AutomationElement canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "EXE purpose-scope smoke canvas was not found");
            System.Windows.Rect canvasRect = canvas.Current.BoundingRectangle;
            AssertTrue(canvasRect.Width > 100 && canvasRect.Height > 100, "EXE purpose-scope smoke canvas bounds were not usable");

            var random = new Random(seed);
            string smokeImagePath = ResolveVisualSmokeImagePath();
            bool hasSmokeImageBounds = !string.IsNullOrWhiteSpace(smokeImagePath) && File.Exists(smokeImagePath);
            System.Windows.Rect fittedImageBounds = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageBounds(canvasRect, smokeImagePath)
                : canvasRect;
            System.Windows.Rect annotationRegion = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageRegion(canvasRect, smokeImagePath)
                : BuildExeSmokeAnnotationRegion(canvasRect);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "DatasetHomeStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "dataset"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowDatasetHomeButton");
            root = RefreshAutomationRoot(process);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                "guide/tools tab was not selectable before purpose-scope smoke");
            root = RefreshAutomationRoot(process);
            AssertTrue(SelectListItemByText(root, "\uC138\uADF8\uBA58\uD14C\uC774\uC158"), "segmentation dataset purpose was not selectable");
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "LabelingWorkbenchStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "labeling"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowGuideToolsButton")
                || SelectAutomationTabByAutomationId(root, "LearningReviewTab");
            root = RefreshAutomationRoot(process);

            canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "purpose-scope canvas was not available before brush input");
            canvasRect = canvas.Current.BoundingRectangle;
            fittedImageBounds = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageBounds(canvasRect, smokeImagePath)
                : canvasRect;
            annotationRegion = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageRegion(canvasRect, smokeImagePath)
                : BuildExeSmokeAnnotationRegion(canvasRect);

            System.Windows.Automation.AutomationElement brushToolItem = FindAnnotationToolItem(root, "\uBE0C\uB7EC\uC2DC");
            AssertTrue(brushToolItem != null, "native click did not find the brush tool");
            AssertTrue(IsForegroundWindowOwnedByProcess(process), "environment-contended before purpose-scope brush-tool click: " + DescribeForegroundWindowOwner());
            _ = HumanClickAutomationElement(brushToolItem);
            AssertTrue(
                WaitUntil(
                    () => IsAutomationSelectionItemSelected(brushToolItem)
                        || string.Equals(GetSelectedAnnotationToolText(RefreshAutomationRoot(process, bringToFront: false)), "\uBE0C\uB7EC\uC2DC", StringComparison.Ordinal),
                    TimeSpan.FromSeconds(2)),
                "real native click did not select the brush tool");
            IReadOnlyList<ExeSmokeDragPath> brushDrags = BuildExeSmokeStrokeDrags(random, annotationRegion, brushStrokeCount);
            ExeSmokeDragBatchMetrics brushMetrics = ExecuteExeSmokeDragBatch(brushDrags, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 8);

            root = RefreshAutomationRoot(process, bringToFront: false);
            System.Windows.Automation.AutomationElement statusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            string previousCommitSignal = GetAutomationHelpText(statusElement);
            System.Windows.Automation.AutomationElement selectToolItem = FindAnnotationToolItem(root, "\uC120\uD0DD");
            AssertTrue(selectToolItem != null, "select tool was not visible after brush strokes");
            AssertTrue(IsForegroundWindowOwnedByProcess(process), "environment-contended before purpose-scope select-tool click: " + DescribeForegroundWindowOwner());
            _ = HumanClickAutomationElement(selectToolItem);
            AssertTrue(
                IsChangedExeMaskCommitSignal(previousCommitSignal)
                || WaitForExeMaskCommitSignal(process, statusElement, previousCommitSignal, TimeSpan.FromSeconds(3)),
                "mask did not materialize before purpose switching");

            root = RefreshAutomationRoot(process, bringToFront: false);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "ObjectsReviewTab") || SelectTabItemByName(root, "\uC800\uC7A5 \uB77C\uBCA8"),
                "saved-label tab was not selectable after mask materialization");
            bool maskVisibleBeforeSwitch = WaitUntil(
                () => ContainsAutomationText(RefreshAutomationRoot(process, bringToFront: false), "Defect / \uB9C8\uC2A4\uD06C"),
                TimeSpan.FromSeconds(4));
            AssertTrue(maskVisibleBeforeSwitch, "segmentation purpose should show the mask object before switching purpose");

            root = RefreshAutomationRoot(process, bringToFront: false);
            _ = TryInvokeAutomationButtonByAutomationId(root, "DatasetHomeStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "dataset"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowDatasetHomeButton");
            root = RefreshAutomationRoot(process);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                "guide/tools tab was not selectable before object-detection switch");
            root = RefreshAutomationRoot(process);
            AssertTrue(SelectListItemByText(root, "\uAC1D\uCCB4 \uD0D0\uC9C0"), "object-detection dataset purpose was not selectable");
            string hiddenStatusSnapshot = string.Empty;
            bool hiddenStatusVisible = WaitUntil(
                () =>
                {
                    var currentRoot = RefreshAutomationRoot(process, bringToFront: false);
                    hiddenStatusSnapshot = GetAutomationValueByAutomationId(currentRoot, "ModelStatusText");
                    return hiddenStatusSnapshot.Contains("\uC138\uADF8 \uB77C\uBCA8", StringComparison.Ordinal)
                        && hiddenStatusSnapshot.Contains("\uC228\uAE40", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(3));
            if (!hiddenStatusVisible)
            {
                TryCaptureExeSmokeFailure(RefreshAutomationRoot(process, bringToFront: false), outputPath, "purpose-hidden-status");
                Console.WriteLine($"EXE_PURPOSE_SCOPE_HIDDEN_STATUS_MISSING status=\"{hiddenStatusSnapshot}\"");
            }

            AssertTrue(hiddenStatusVisible, "purpose switch should explain hidden segmentation labels in the model status");

            root = RefreshAutomationRoot(process, bringToFront: false);
            _ = TryInvokeAutomationButtonByAutomationId(root, "LabelingWorkbenchStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "labeling"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowSavedLabelsButton");
            root = RefreshAutomationRoot(process);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "ObjectsReviewTab") || SelectTabItemByName(root, "\uC800\uC7A5 \uB77C\uBCA8"),
                "saved-label tab was not selectable after object-detection switch");
            bool segmentationHidden = WaitUntil(
                () => !ContainsAutomationText(RefreshAutomationRoot(process, bringToFront: false), "Defect / \uB9C8\uC2A4\uD06C"),
                TimeSpan.FromSeconds(3));
            AssertTrue(segmentationHidden, "object-detection purpose should hide stale mask rows");

            root = RefreshAutomationRoot(process, bringToFront: false);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowGuideToolsButton");
            root = RefreshAutomationRoot(process);
            System.Windows.Automation.AutomationElement boxToolItem = FindAnnotationToolItem(root, "\uBC15\uC2A4");
            AssertTrue(boxToolItem != null, "box tool was not visible after object-detection switch");
            NativeClick(GetAutomationCenter(boxToolItem));
            AssertTrue(WaitUntil(() => IsAutomationSelectionItemSelected(boxToolItem), TimeSpan.FromSeconds(2)), "box tool was not selected for object-detection scope");

            root = RefreshAutomationRoot(process, bringToFront: false);
            canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "purpose-scope canvas was not available after the object-detection layout change");
            canvasRect = canvas.Current.BoundingRectangle;
            fittedImageBounds = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageBounds(canvasRect, smokeImagePath)
                : canvasRect;
            annotationRegion = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageRegion(canvasRect, smokeImagePath)
                : BuildExeSmokeAnnotationRegion(canvasRect);

            // Saved sample boxes can hydrate shortly after the purpose/tab switch.
            // Let the object list settle so the outside-drag check measures new rows only.
            Thread.Sleep(350);
            root = RefreshAutomationRoot(process, bringToFront: false);
            int boxCountBeforeOutsideDrag = CountAutomationTextOccurrences(root, "Defect / \uBC15\uC2A4");
            int boxBaselineBeforeOutsideDrag = InferExistingBoxTextCount(root, boxCountBeforeOutsideDrag);
            int canvasLabelCountBeforeOutsideDrag = GetExeCanvasLabelCount(root);
            ExeSmokeDragPath outsideDrag = BuildExeSmokeOutsideImageBoxDrag(random, canvasRect, fittedImageBounds);
            AssertTrue(
                IsForegroundWindowOwnedByProcess(process),
                "environment-contended before purpose-scope outside-image drag: " + DescribeForegroundWindowOwner());
            double outsideBoxMilliseconds = NativeHumanDrag(outsideDrag.Points, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 80);
            root = RefreshAutomationRoot(process, bringToFront: false);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "ObjectsReviewTab") || SelectTabItemByName(root, "\uC800\uC7A5 \uB77C\uBCA8"),
                "saved-label tab was not selectable after outside-image drag");
            root = RefreshAutomationRoot(process, bringToFront: false);
            int boxCountAfterOutsideDrag = CountAutomationTextOccurrences(root, "Defect / \uBC15\uC2A4");
            int canvasLabelCountAfterOutsideDrag = GetExeCanvasLabelCount(root);
            bool outsideBoxCreatedObject = boxCountAfterOutsideDrag > boxBaselineBeforeOutsideDrag
                || canvasLabelCountAfterOutsideDrag > canvasLabelCountBeforeOutsideDrag;
            if (outsideBoxCreatedObject)
            {
                TryCaptureExeSmokeFailure(root, outputPath, "purpose-outside-box-created");
                Console.WriteLine(
                    FormattableString.Invariant(
                        $"EXE_PURPOSE_SCOPE_OUTSIDE_DEBUG before={boxCountBeforeOutsideDrag} baseline={boxBaselineBeforeOutsideDrag} after={boxCountAfterOutsideDrag} canvas={FormatRectForLog(canvasRect)} imageBounds={FormatRectForLog(fittedImageBounds)} annotation={FormatRectForLog(annotationRegion)} dragStart={outsideDrag.Points.First()} dragEnd={outsideDrag.Points.Last()} image=\"{smokeImagePath}\""));
            }

            AssertTrue(!outsideBoxCreatedObject, "dragging a box fully outside the image should not create an object row");

            root = RefreshAutomationRoot(process, bringToFront: false);
            int boxCountBeforeInsideDrag = Math.Max(
                CountAutomationTextOccurrences(root, "Defect / \uBC15\uC2A4"),
                boxBaselineBeforeOutsideDrag);
            int canvasLabelCountBeforeInsideDrag = GetExeCanvasLabelCount(root);
            root = RefreshAutomationRoot(process);
            AssertTrue(
                TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowGuideToolsButton")
                    || SelectAutomationTabByAutomationId(root, "LearningReviewTab"),
                "guide/tools was not selectable before the inside-image box drag");
            root = RefreshAutomationRoot(process);
            boxToolItem = FindAnnotationToolItem(root, "\uBC15\uC2A4");
            AssertTrue(boxToolItem != null, "box tool was not visible before the inside-image drag");
            AssertTrue(
                IsForegroundWindowOwnedByProcess(process),
                "environment-contended before purpose-scope inside-image box-tool click: " + DescribeForegroundWindowOwner());
            _ = HumanClickAutomationElement(boxToolItem);
            AssertTrue(
                WaitUntil(
                    () => IsExeSmokeBoxToolSelected(RefreshAutomationRoot(process, bringToFront: false)),
                    TimeSpan.FromSeconds(2)),
                "box tool was not selected before the inside-image drag");

            root = RefreshAutomationRoot(process);
            canvas = FindAutomationElementByClass(root, "RoiImageCanvasView");
            AssertTrue(canvas != null, "purpose-scope canvas was not available before the inside-image drag");
            canvasRect = canvas.Current.BoundingRectangle;
            annotationRegion = hasSmokeImageBounds
                ? BuildExeSmokeFittedImageRegion(canvasRect, smokeImagePath)
                : BuildExeSmokeAnnotationRegion(canvasRect);
            ExeSmokeDragPath insideDrag = BuildExeSmokeBoxDrags(random, annotationRegion, 1)[0];
            AssertTrue(
                IsForegroundWindowOwnedByProcess(process),
                "environment-contended before purpose-scope inside-image drag: " + DescribeForegroundWindowOwner());
            double insideBoxMilliseconds = NativeHumanDrag(insideDrag.Points, moveDelayMilliseconds: 1, postMouseUpMilliseconds: 80);
            bool insideBoxCreatedObject = WaitUntil(
                () =>
                {
                    var currentRoot = RefreshAutomationRoot(process, bringToFront: false);
                    return CountAutomationTextOccurrences(currentRoot, "Defect / \uBC15\uC2A4") > boxCountBeforeInsideDrag
                        || GetExeCanvasLabelCount(currentRoot) > canvasLabelCountBeforeInsideDrag
                        || GetAutomationValueByAutomationId(currentRoot, "AnnotationSaveStatusText")
                            .Contains("\uD544\uC694", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(4));
            if (!insideBoxCreatedObject)
            {
                TryCaptureExeSmokeFailure(
                    RefreshAutomationRoot(process, bringToFront: false),
                    outputPath,
                    "purpose-inside-box-missing");
            }
            AssertTrue(insideBoxCreatedObject, "dragging a box inside the image should create a visible label or object row");

            root = RefreshAutomationRoot(process, bringToFront: false);
            _ = TryInvokeAutomationButtonByAutomationId(root, "DatasetHomeStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "dataset"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowDatasetHomeButton");
            root = RefreshAutomationRoot(process);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                "guide/tools tab was not selectable before segmentation restore");
            root = RefreshAutomationRoot(process);
            AssertTrue(SelectListItemByText(root, "\uC138\uADF8\uBA58\uD14C\uC774\uC158"), "segmentation dataset purpose was not selectable for restore");
            string restoredStatusSnapshot = string.Empty;
            bool restoredStatusVisible = WaitUntil(
                () =>
                {
                    var currentRoot = RefreshAutomationRoot(process, bringToFront: false);
                    restoredStatusSnapshot = GetAutomationValueByAutomationId(currentRoot, "ModelStatusText");
                    return restoredStatusSnapshot.Contains("\uC138\uADF8 \uB77C\uBCA8", StringComparison.Ordinal)
                        && restoredStatusSnapshot.Contains("\uD45C\uC2DC", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(3));
            if (!restoredStatusVisible)
            {
                TryCaptureExeSmokeFailure(RefreshAutomationRoot(process, bringToFront: false), outputPath, "purpose-restored-status");
                Console.WriteLine($"EXE_PURPOSE_SCOPE_RESTORED_STATUS_MISSING status=\"{restoredStatusSnapshot}\"");
            }

            AssertTrue(restoredStatusVisible, "purpose switch back should explain restored segmentation label visibility");
            root = RefreshAutomationRoot(process, bringToFront: false);
            _ = TryInvokeAutomationButtonByAutomationId(root, "LabelingWorkbenchStageButton");
            _ = WaitUntil(
                () => IsExeWorkflowStageActive(
                    RefreshAutomationRoot(process, bringToFront: false),
                    "labeling"),
                TimeSpan.FromSeconds(3));
            EnsureExeRightWorkflowExpanded(process);
            root = RefreshAutomationRoot(process);
            _ = TryInvokeAutomationButtonByAutomationId(root, "RightWorkflowSavedLabelsButton");
            root = RefreshAutomationRoot(process);
            AssertTrue(
                SelectAutomationTabByAutomationId(root, "ObjectsReviewTab") || SelectTabItemByName(root, "\uC800\uC7A5 \uB77C\uBCA8"),
                "saved-label tab was not selectable after segmentation restore");
            bool segmentationRestored = WaitUntil(
                () => ContainsAutomationText(RefreshAutomationRoot(process, bringToFront: false), "Defect / \uB9C8\uC2A4\uD06C"),
                TimeSpan.FromSeconds(4));
            AssertTrue(segmentationRestored, "segmentation purpose should restore the existing mask row");

            root = RefreshAutomationRoot(process, bringToFront: false);
            CaptureAutomationRoot(root, outputPath);
            string lastPurposeStatus = GetAutomationValueByAutomationId(root, "ModelStatusText");
            return new ExePurposeScopeSmokeResult(
                seed,
                brushDrags.Count,
                brushMetrics.TotalMilliseconds,
                outsideBoxMilliseconds,
                insideBoxMilliseconds,
                segmentationHidden,
                segmentationRestored,
                outsideBoxCreatedObject,
                insideBoxCreatedObject,
                lastPurposeStatus);
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    private static ExeRealLabelingSmokeResult ExecuteExeRealLabelingSmoke(
        string exePath,
        string outputPath,
        int seed,
        int boxCount,
        int brushStrokeCount,
        int eraserStrokeCount)
    {
        Process process = null;
        try
        {
            process = Process.Start(new ProcessStartInfo
            {
                FileName = exePath,
                WorkingDirectory = Path.GetDirectoryName(exePath),
                UseShellExecute = true
            });
            AssertTrue(process != null, "failed to start EXE smoke process");

            IntPtr handle = WaitForMainWindowHandle(process, TimeSpan.FromSeconds(25));
            AssertTrue(handle != IntPtr.Zero, "EXE smoke window did not appear");
            BringNativeWindowToFront(handle);
            var root = System.Windows.Automation.AutomationElement.FromHandle(handle);
            AssertTrue(root != null, "EXE smoke automation root was not available");
            WaitForAutomationText(root, "캔버스", TimeSpan.FromSeconds(10));

            TryInvokeAutomationButton(root, "샘플");
            Thread.Sleep(800);
            root = RefreshAutomationRoot(process);
            WaitForAutomationText(root, "빠른 도구", TimeSpan.FromSeconds(10));
            System.Windows.Rect canvasRect = FindAutomationElementByClass(root, "RoiImageCanvasView").Current.BoundingRectangle;
            AssertTrue(canvasRect.Width > 100 && canvasRect.Height > 100, "EXE smoke canvas bounds were not usable");
            var random = new Random(seed);
            System.Windows.Rect annotationRegion = BuildExeSmokeAnnotationRegion(canvasRect);

            System.Windows.Automation.AutomationElement boxToolItem = FindAnnotationToolItem(root, "\uBC15\uC2A4");
            AssertTrue(boxToolItem != null, "native click did not find the box tool");
            NativeClick(GetAutomationCenter(boxToolItem));
            bool boxSelected = WaitUntil(
                () => IsAutomationSelectionItemSelected(boxToolItem)
                    || string.Equals(GetSelectedAnnotationToolText(RefreshAutomationRoot(process, bringToFront: false)), "\uBC15\uC2A4", StringComparison.Ordinal),
                TimeSpan.FromSeconds(2));
            AssertTrue(boxSelected, "real native click did not select the box tool");
            root = RefreshAutomationRoot(process);

            IReadOnlyList<ExeSmokeDragPath> boxDrags = BuildExeSmokeBoxDrags(random, annotationRegion, boxCount);
            Point boxStart = boxDrags[0].Center;
            Point boxEnd = boxDrags[0].Center;
            Stopwatch boxDrawStopwatch = Stopwatch.StartNew();
            foreach (ExeSmokeDragPath boxDrag in boxDrags)
            {
                NativeHumanDrag(boxDrag.Points, moveDelayMilliseconds: 3, postMouseUpMilliseconds: 35);
            }

            boxDrawStopwatch.Stop();
            root = RefreshAutomationRoot(process);
            if (!ContainsAutomationText(root, "Defect / 박스"))
            {
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "ObjectsReviewTab") || SelectTabItemByName(root, "저장 라벨"),
                    "saved-label tab was not selectable after box drawing");
                root = RefreshAutomationRoot(process);
            }

            WaitForAutomationText(process, "Defect / \uBC15\uC2A4", TimeSpan.FromSeconds(4));
            AssertTrue(ContainsAutomationText(RefreshAutomationRoot(process, bringToFront: false), "Defect / \uBC15\uC2A4"), "real EXE box draw did not create an object-review row");

            NativeClick(new Point((int)((boxStart.X + boxEnd.X) / 2D), (int)((boxStart.Y + boxEnd.Y) / 2D)));
            Thread.Sleep(200);
            root = RefreshAutomationRoot(process);
            var deleteButton = FindEnabledAutomationButton(root, "삭제");
            AssertTrue(deleteButton != null, "real EXE delete button was not enabled after selecting the ROI");
            Stopwatch deleteThenWheelStopwatch = Stopwatch.StartNew();
            NativeClick(GetAutomationCenter(deleteButton));
            NativeMouseWheel(RandomPointInRect(random, annotationRegion), 120);
            deleteThenWheelStopwatch.Stop();
            root = RefreshAutomationRoot(process);
            if (boxDrags.Count <= 1)
            {
            WaitForAutomationText(process, "현재 이미지 객체 없음", TimeSpan.FromSeconds(4));
            }
            else
            {
                AssertTrue(ContainsAutomationText(root, "Defect /"), "real EXE delete unexpectedly removed every random object");
            }

            if (!ClickDatasetPurposeByText(root, "세그멘테이션"))
            {
                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                    "guide/tools tab was not selectable before mask tools");
                root = RefreshAutomationRoot(process);
                AssertTrue(ClickDatasetPurposeByText(root, "세그멘테이션"), "native click did not find the segmentation dataset purpose");
            }

            root = RefreshAutomationRoot(process);
            System.Windows.Automation.AutomationElement brushToolItem = FindAnnotationToolItem(root, "\uBE0C\uB7EC\uC2DC");
            System.Windows.Automation.AutomationElement eraserToolItem = FindAnnotationToolItem(root, "\uC9C0\uC6B0\uAC1C");
            AssertTrue(brushToolItem != null, "native click did not find the brush tool");
            AssertTrue(eraserToolItem != null, "native click did not find the eraser tool before brush strokes");
            Point brushToolCenter = GetAutomationCenter(brushToolItem);
            Point eraserToolCenter = GetAutomationCenter(eraserToolItem);
            NativeClick(brushToolCenter);
            bool brushSelected = WaitUntil(
                () => IsAutomationSelectionItemSelected(brushToolItem)
                    || string.Equals(GetSelectedAnnotationToolText(RefreshAutomationRoot(process, bringToFront: false)), "\uBE0C\uB7EC\uC2DC", StringComparison.Ordinal),
                TimeSpan.FromSeconds(2));
            AssertTrue(brushSelected, "real native click did not select the brush tool");
            root = RefreshAutomationRoot(process);

            IReadOnlyList<ExeSmokeDragPath> brushDrags = BuildExeSmokeStrokeDrags(random, annotationRegion, brushStrokeCount);
            Stopwatch brushReleaseStopwatch = Stopwatch.StartNew();
            ExeSmokeDragBatchMetrics brushInputMetrics = ExecuteExeSmokeDragBatch(brushDrags, moveDelayMilliseconds: 2, postMouseUpMilliseconds: 30);
            Stopwatch brushUiWaitStopwatch = new Stopwatch();
            brushUiWaitStopwatch.Stop();
            brushReleaseStopwatch.Stop();
            root = RefreshAutomationRoot(process);
            string brushStatusAfterCommit = GetAutomationValueByAutomationId(root, "ModelStatusText");
            System.Windows.Automation.AutomationElement brushStatusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            ExeSmokeDragPath brushWheelProbe = BuildExeSmokeStrokeDrags(random, annotationRegion, 1)[0];
            double brushImmediateWheelUiMilliseconds = MeasureExeSmokeStrokeReleaseThenWheelResponsiveness(
                process,
                brushWheelProbe,
                moveDelayMilliseconds: 2,
                wheelPoint: RandomPointInRect(random, annotationRegion),
                statusElement: brushStatusElement);
            AssertTrue(brushImmediateWheelUiMilliseconds < 2_000.0, "real EXE brush MouseUp should not block immediate wheel/UIAutomation response");
            if (!brushStatusAfterCommit.Contains("\uB9C8\uC2A4\uD06C", StringComparison.Ordinal))
            {
                Console.WriteLine($"EXE_REAL_LABELING_SMOKE_BRUSH_STATUS_OVERWRITTEN status=\"{brushStatusAfterCommit}\"");
            }

            NativeClick(eraserToolCenter);
            bool eraserSelected = WaitUntil(
                () =>
                {
                    if (IsAutomationSelectionItemSelected(eraserToolItem))
                    {
                        return true;
                    }

                    var latestRoot = RefreshAutomationRoot(process, bringToFront: false);
                    System.Windows.Automation.AutomationElement latestEraserToolItem = FindAnnotationToolItem(latestRoot, "\uC9C0\uC6B0\uAC1C");
                    return IsAutomationSelectionItemSelected(latestEraserToolItem)
                        || string.Equals(GetSelectedAnnotationToolText(latestRoot), "\uC9C0\uC6B0\uAC1C", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(2));
            AssertTrue(eraserSelected, "real native click did not select the eraser tool");
            IReadOnlyList<ExeSmokeDragPath> eraserDrags = BuildExeSmokeEraserDrags(random, brushDrags, annotationRegion, eraserStrokeCount);
            Stopwatch eraserReleaseStopwatch = Stopwatch.StartNew();
            ExeSmokeDragBatchMetrics eraserInputMetrics = ExecuteExeSmokeDragBatch(eraserDrags, moveDelayMilliseconds: 2, postMouseUpMilliseconds: 30);
            Stopwatch eraserUiWaitStopwatch = new Stopwatch();
            root = RefreshAutomationRoot(process, bringToFront: false);
            eraserUiWaitStopwatch.Stop();
            eraserReleaseStopwatch.Stop();
            string eraserStatusAfterCommit = GetAutomationValueByAutomationId(root, "ModelStatusText");
            System.Windows.Automation.AutomationElement eraserStatusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            if (!eraserStatusAfterCommit.Contains("\uB9C8\uC2A4\uD06C", StringComparison.Ordinal))
            {
                Console.WriteLine($"EXE_REAL_LABELING_SMOKE_ERASER_STATUS_OVERWRITTEN status=\"{eraserStatusAfterCommit}\"");
            }

            ExeSmokeDragPath eraserWheelProbe = BuildExeSmokeEraserDrags(random, brushDrags, annotationRegion, 1)[0];
            double eraserImmediateWheelUiMilliseconds = MeasureExeSmokeStrokeReleaseThenWheelResponsiveness(
                process,
                eraserWheelProbe,
                moveDelayMilliseconds: 2,
                wheelPoint: RandomPointInRect(random, annotationRegion),
                statusElement: eraserStatusElement);
            AssertTrue(eraserImmediateWheelUiMilliseconds < 2_000.0, "real EXE eraser MouseUp should not block immediate wheel/UIAutomation response");

            root = RefreshAutomationRoot(process, bringToFront: false);
            System.Windows.Automation.AutomationElement materializeStatusElement = FindAutomationElementByAutomationId(root, "ModelStatusText");
            string materializePreviousCommitSignal = GetAutomationHelpText(materializeStatusElement);
            AssertTrue(ClickAnnotationToolByText(root, "선택"), "native click did not find the select tool before saving mask data");
            bool selectSelectedAfterPaint = WaitUntil(() => string.Equals(GetSelectedAnnotationToolText(RefreshAutomationRoot(process)), "선택", StringComparison.Ordinal), TimeSpan.FromSeconds(2));
            AssertTrue(selectSelectedAfterPaint, "real native click did not leave the mask paint tool before save");
            bool maskMaterializedBeforeSave =
                IsChangedExeMaskCommitSignal(materializePreviousCommitSignal)
                || WaitForExeMaskCommitSignal(process, materializeStatusElement, materializePreviousCommitSignal, TimeSpan.FromSeconds(3));
            if (!maskMaterializedBeforeSave)
            {
                root = RefreshAutomationRoot(process, bringToFront: false);
                string statusText = GetAutomationValueByAutomationId(root, "ModelStatusText");
                TryCaptureExeSmokeFailure(root, outputPath, "mask-materialize-before-save-timeout");
                Console.WriteLine($"EXE_REAL_LABELING_SMOKE_MASK_MATERIALIZE_TIMEOUT status=\"{statusText}\" selectedTool=\"{GetSelectedAnnotationToolText(root)}\"");
            }

            AssertTrue(maskMaterializedBeforeSave, "real EXE mask strokes did not materialize after leaving the paint tool before save");
            root = RefreshAutomationRoot(process, bringToFront: false);

            string activeImagePath = ResolveExeSmokeActiveImagePath(root);
            IReadOnlyList<string> outputRoots = ResolveExeSmokeOutputRoots(activeImagePath, exePath);
            string fileStem = Path.GetFileNameWithoutExtension(activeImagePath);
            var saveSnapshot = CaptureExeSmokeSaveSnapshot(outputRoots, fileStem);
            double saveMilliseconds;
            int savedArtifactCount;
            ExeSmokeSavedArtifactDiagnostics saveDiagnostics;
            ExeSmokeDatasetReadinessDiagnostics datasetDiagnostics;
            try
            {
                // The real-EXE smoke must click Save, but it snapshots/restores the bundled sample
                // artifacts so verification does not permanently rewrite the developer dataset.
                DeleteExeSmokeAnnotationArtifacts(saveSnapshot);
                var saveButton = FindEnabledAutomationButton(root, "저장");
                AssertTrue(saveButton != null, "real EXE save button was not enabled after drawing a mask");
                Stopwatch saveStopwatch = Stopwatch.StartNew();
                NativeClick(GetAutomationCenter(saveButton));
                root = RefreshAutomationRoot(process);
                WaitForAutomationText(process, "라벨 저장됨", TimeSpan.FromSeconds(4));
                saveStopwatch.Stop();
                saveMilliseconds = saveStopwatch.Elapsed.TotalMilliseconds;

                List<string> savedArtifacts = GetExeSmokeExistingSaveArtifacts(saveSnapshot)
                    .Where(IsExeSmokeAnnotationArtifactPath)
                    .ToList();
                savedArtifactCount = savedArtifacts.Count;
                AssertTrue(
                    savedArtifacts.Any(IsExeSmokeSegmentationArtifactPath),
                    "real EXE save did not create a mask/segment artifact after brush drawing");
                saveDiagnostics = ValidateExeSmokeSavedArtifactContents(savedArtifacts);

                AssertTrue(
                    SelectAutomationTabByAutomationId(root, "LearningReviewTab") || SelectTabItemByName(root, "\uAC00\uC774\uB4DC/\uB3C4\uAD6C"),
                    "guide/tools tab was not selectable");
                root = RefreshAutomationRoot(process);
                WaitForAutomationText(process, "다음 작업", TimeSpan.FromSeconds(4));
                AssertTrue(ContainsAutomationText(root, "데이터셋 점검"), "guide next-action dataset check was not visible in the real EXE");
                datasetDiagnostics = ExecuteExeSmokeDatasetCheckFromGuide(process, root);
                root = RefreshAutomationRoot(process);
                CaptureAutomationRoot(root, outputPath);
            }
            finally
            {
                RestoreExeSmokeSaveSnapshot(saveSnapshot);
            }

            return new ExeRealLabelingSmokeResult(
                boxDrawStopwatch.Elapsed.TotalMilliseconds,
                deleteThenWheelStopwatch.Elapsed.TotalMilliseconds,
                brushReleaseStopwatch.Elapsed.TotalMilliseconds,
                eraserReleaseStopwatch.Elapsed.TotalMilliseconds,
                saveMilliseconds,
                datasetDiagnostics.CheckMilliseconds,
                savedArtifactCount,
                saveDiagnostics.MaskPixels,
                saveDiagnostics.SegmentPolygons,
                saveDiagnostics.SegmentPoints,
                datasetDiagnostics.State,
                brushSelected,
                eraserSelected,
                SaveVerified: true,
                DatasetCheckVerified: true,
                GuideActionVisible: true,
                MaskObjectVisible: true,
                Seed: seed,
                BoxCount: boxDrags.Count,
                BrushStrokeCount: brushDrags.Count,
                EraserStrokeCount: eraserDrags.Count,
                BrushInputMilliseconds: brushInputMetrics.TotalMilliseconds,
                BrushUiWaitMilliseconds: brushUiWaitStopwatch.Elapsed.TotalMilliseconds,
                BrushImmediateWheelUiMilliseconds: brushImmediateWheelUiMilliseconds,
                BrushStrokeAverageMilliseconds: brushInputMetrics.AverageMilliseconds,
                BrushStrokeMaxMilliseconds: brushInputMetrics.MaxMilliseconds,
                EraserInputMilliseconds: eraserInputMetrics.TotalMilliseconds,
                EraserUiWaitMilliseconds: eraserUiWaitStopwatch.Elapsed.TotalMilliseconds,
                EraserImmediateWheelUiMilliseconds: eraserImmediateWheelUiMilliseconds,
                EraserStrokeAverageMilliseconds: eraserInputMetrics.AverageMilliseconds,
                EraserStrokeMaxMilliseconds: eraserInputMetrics.MaxMilliseconds);
        }
        finally
        {
            CloseExeSmokeProcess(process);
        }
    }

    internal static Screen PlaceExeSmokeWindowOnLeftmostMonitor(
        IntPtr handle,
        int requestedWidth = VisualSmokeDefaultWindowWidth,
        int requestedHeight = VisualSmokeDefaultWindowHeight)
    {
        AssertTrue(handle != IntPtr.Zero, "EXE smoke window handle was not available for monitor placement");
        Screen expectedScreen = Screen.AllScreens
            .OrderBy(screen => screen.Bounds.Left)
            .ThenBy(screen => screen.Bounds.Top)
            .First();
        Rectangle monitorBounds = expectedScreen.Bounds;
        int width = Math.Min(Math.Max(1, requestedWidth), monitorBounds.Width);
        int height = Math.Min(Math.Max(1, requestedHeight), monitorBounds.Height);
        int left = monitorBounds.Left + ((monitorBounds.Width - width) / 2);
        int top = monitorBounds.Top + ((monitorBounds.Height - height) / 2);

        AssertTrue(
            SetWindowPos(handle, HwndTopMost, left, top, width, height, SwpShowWindow),
            $"failed to place EXE smoke window on leftmost monitor {expectedScreen.DeviceName}");
        Thread.Sleep(100);

        Screen actualScreen = Screen.FromHandle(handle);
        AssertEqual(expectedScreen.DeviceName, actualScreen.DeviceName);
        AssertTrue(GetWindowRect(handle, out NativeRect windowRect), "failed to read EXE smoke window bounds after placement");
        var actualBounds = new Rectangle(
            windowRect.Left,
            windowRect.Top,
            windowRect.Right - windowRect.Left,
            windowRect.Bottom - windowRect.Top);
        AssertTrue(
            monitorBounds.IntersectsWith(actualBounds),
            $"EXE smoke window does not intersect leftmost monitor {expectedScreen.DeviceName}: {actualBounds}");

        string evidencePath = Environment.GetEnvironmentVariable(ExeSmokeMonitorEvidenceEnvironmentVariable);
        if (!string.IsNullOrWhiteSpace(evidencePath))
        {
            string fullEvidencePath = Path.GetFullPath(evidencePath);
            Directory.CreateDirectory(Path.GetDirectoryName(fullEvidencePath)!);
            File.WriteAllText(
                fullEvidencePath,
                System.Text.Json.JsonSerializer.Serialize(
                    new
                    {
                        schemaVersion = 1,
                        capturedAt = DateTimeOffset.Now,
                        expectedScreen = new
                        {
                            expectedScreen.DeviceName,
                            expectedScreen.Primary,
                            left = monitorBounds.Left,
                            top = monitorBounds.Top,
                            width = monitorBounds.Width,
                            height = monitorBounds.Height,
                        },
                        actualScreen = new
                        {
                            actualScreen.DeviceName,
                            actualScreen.Primary,
                        },
                        window = new
                        {
                            left = actualBounds.Left,
                            top = actualBounds.Top,
                            width = actualBounds.Width,
                            height = actualBounds.Height,
                        },
                    },
                    new System.Text.Json.JsonSerializerOptions { WriteIndented = true }));
        }

        string screenshotPath = Environment.GetEnvironmentVariable(ExeSmokeDesktopScreenshotEnvironmentVariable);
        if (!string.IsNullOrWhiteSpace(screenshotPath))
        {
            string fullScreenshotPath = Path.GetFullPath(screenshotPath);
            Directory.CreateDirectory(Path.GetDirectoryName(fullScreenshotPath)!);
            Rectangle virtualBounds = SystemInformation.VirtualScreen;
            using var bitmap = new Bitmap(virtualBounds.Width, virtualBounds.Height);
            using (Graphics graphics = Graphics.FromImage(bitmap))
            {
                graphics.CopyFromScreen(
                    virtualBounds.Left,
                    virtualBounds.Top,
                    0,
                    0,
                    bitmap.Size);
            }

            bitmap.Save(fullScreenshotPath, System.Drawing.Imaging.ImageFormat.Png);
        }

        Console.WriteLine(
            $"EXE_SMOKE_MONITOR={expectedScreen.DeviceName} " +
            $"LEFT={monitorBounds.Left} TOP={monitorBounds.Top} " +
            $"WINDOW={actualBounds.Left},{actualBounds.Top},{actualBounds.Width},{actualBounds.Height}");
        return expectedScreen;
    }

    internal static IntPtr WaitForMainWindowHandle(Process process, TimeSpan timeout)
    {
        Stopwatch stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < timeout)
        {
            if (process == null || process.HasExited)
            {
                return IntPtr.Zero;
            }

            process.Refresh();
            if (process.MainWindowHandle != IntPtr.Zero)
            {
                IntPtr handle = process.MainWindowHandle;
                PlaceExeSmokeWindowOnLeftmostMonitor(handle);
                return handle;
            }

            Thread.Sleep(100);
        }

        return IntPtr.Zero;
    }

    internal static void BringNativeWindowToFront(IntPtr handle)
    {
        if (handle == IntPtr.Zero)
        {
            return;
        }

        if (IsIconic(handle))
        {
            ShowWindow(handle, SwRestore);
        }

        IntPtr foreground = GetForegroundWindow();
        uint currentThreadId = GetCurrentThreadId();
        uint foregroundThreadId = foreground == IntPtr.Zero
            ? 0
            : GetWindowThreadProcessId(foreground, out _);
        uint targetThreadId = GetWindowThreadProcessId(handle, out _);
        bool attachedForeground = foregroundThreadId != 0
            && foregroundThreadId != currentThreadId
            && AttachThreadInput(currentThreadId, foregroundThreadId, true);
        bool attachedTarget = targetThreadId != 0
            && targetThreadId != currentThreadId
            && AttachThreadInput(currentThreadId, targetThreadId, true);
        try
        {
            SetWindowPos(handle, HwndTopMost, 0, 0, 0, 0, SwpNoMove | SwpNoSize | SwpShowWindow);
            BringWindowToTop(handle);
            SetForegroundWindow(handle);
        }
        finally
        {
            if (attachedTarget)
            {
                AttachThreadInput(currentThreadId, targetThreadId, false);
            }

            if (attachedForeground)
            {
                AttachThreadInput(currentThreadId, foregroundThreadId, false);
            }
        }

        Thread.Sleep(250);
    }

    internal static System.Windows.Automation.AutomationElement RefreshAutomationRoot(Process process, bool bringToFront = true)
    {
        AssertTrue(process != null && !process.HasExited, "EXE smoke process exited unexpectedly");
        process.Refresh();
        PlaceExeSmokeWindowOnLeftmostMonitor(process.MainWindowHandle);
        if (bringToFront)
        {
            AssertTrue(
                TryActivateProcessWindowWithoutStealingFromPeer(
                    process,
                    process.MainWindowHandle,
                    TimeSpan.FromSeconds(45)),
                "environment-contended: " + DescribeForegroundWindowOwner());
        }

        var root = System.Windows.Automation.AutomationElement.FromHandle(process.MainWindowHandle);
        AssertTrue(root != null, "EXE smoke automation root was not available after refresh");
        return root;
    }

    internal static System.Windows.Automation.AutomationElement RefreshAutomationRoot(Process process, IntPtr stableHandle, bool bringToFront = true)
    {
        AssertTrue(process != null && !process.HasExited, "EXE smoke process exited unexpectedly");
        AssertTrue(stableHandle != IntPtr.Zero, "EXE smoke stable window handle was not available");
        PlaceExeSmokeWindowOnLeftmostMonitor(stableHandle);
        if (bringToFront)
        {
            AssertTrue(
                TryActivateProcessWindowWithoutStealingFromPeer(
                    process,
                    stableHandle,
                    TimeSpan.FromSeconds(45)),
                "environment-contended: " + DescribeForegroundWindowOwner());
        }

        var root = System.Windows.Automation.AutomationElement.FromHandle(stableHandle);
        AssertTrue(root != null, "EXE smoke automation root was not available after stable refresh");
        return root;
    }

    private static bool TryActivateProcessWindowWithoutStealingFromPeer(
        Process process,
        IntPtr handle,
        TimeSpan timeout)
    {
        Stopwatch stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < timeout)
        {
            if (process == null || process.HasExited)
            {
                return false;
            }

            if (IsForegroundWindowOwnedByProcess(process))
            {
                return true;
            }

            if (IsForegroundOwnedByAnotherOpenVisionLabProcess(process))
            {
                Thread.Sleep(250);
                continue;
            }

            BringNativeWindowToFront(handle);
            if (IsForegroundWindowOwnedByProcess(process))
            {
                return true;
            }

            Thread.Sleep(250);
        }

        return IsForegroundWindowOwnedByProcess(process);
    }

    private static bool IsForegroundOwnedByAnotherOpenVisionLabProcess(Process target)
    {
        IntPtr foreground = GetForegroundWindow();
        if (foreground == IntPtr.Zero)
        {
            return false;
        }

        GetWindowThreadProcessId(foreground, out uint processId);
        if (processId == (uint)target.Id)
        {
            return false;
        }

        try
        {
            using Process owner = Process.GetProcessById((int)processId);
            return owner.ProcessName.StartsWith("OpenVisionLab", StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return false;
        }
    }

    private static bool IsForegroundWindowOwnedByProcess(Process process)
    {
        if (process == null || process.HasExited)
        {
            return false;
        }

        IntPtr foreground = GetForegroundWindow();
        if (foreground == IntPtr.Zero)
        {
            return false;
        }

        GetWindowThreadProcessId(foreground, out uint processId);
        return processId == (uint)process.Id;
    }

    private static string DescribeForegroundWindowOwner()
    {
        IntPtr foreground = GetForegroundWindow();
        if (foreground == IntPtr.Zero)
        {
            return "foreground window is unavailable";
        }

        GetWindowThreadProcessId(foreground, out uint processId);
        try
        {
            using Process owner = Process.GetProcessById((int)processId);
            string path;
            try
            {
                path = owner.MainModule?.FileName ?? string.Empty;
            }
            catch
            {
                path = string.Empty;
            }

            return $"foreground belongs to PID {processId} ({owner.ProcessName})"
                + (string.IsNullOrWhiteSpace(path) ? string.Empty : $" at {path}");
        }
        catch
        {
            return $"foreground belongs to PID {processId}";
        }
    }

    internal static bool TryInvokeAutomationButton(System.Windows.Automation.AutomationElement root, string name)
    {
        var button = FindAutomationButton(root, name, requireEnabled: true);
        if (button == null)
        {
            return false;
        }

        if (button.TryGetCurrentPattern(System.Windows.Automation.InvokePattern.Pattern, out object pattern)
            && pattern is System.Windows.Automation.InvokePattern invokePattern)
        {
            invokePattern.Invoke();
            return true;
        }

        if (!IsForegroundOwnedByAutomationElement(button))
        {
            return false;
        }

        NativeClick(GetAutomationCenter(button));
        return true;
    }

    private static System.Windows.Automation.AutomationElement FindAutomationButton(
        System.Windows.Automation.AutomationElement root,
        string name,
        bool requireEnabled)
    {
        foreach (System.Windows.Automation.AutomationElement element in EnumerateAutomationDescendants(root))
        {
            try
            {
                if (element.Current.ControlType == System.Windows.Automation.ControlType.Button
                    && string.Equals(element.Current.Name, name, StringComparison.Ordinal)
                    && (!requireEnabled || element.Current.IsEnabled))
                {
                    return element;
                }
            }
            catch (System.Windows.Automation.ElementNotAvailableException)
            {
                continue;
            }
        }

        return null;
    }

    internal static System.Windows.Automation.AutomationElement FindEnabledAutomationButton(
        System.Windows.Automation.AutomationElement root,
        string name)
        => FindAutomationButton(root, name, requireEnabled: true);

    private static System.Windows.Automation.AutomationElement FindEnabledObjectDeleteButton(
        System.Windows.Automation.AutomationElement root)
    {
        System.Windows.Automation.AutomationElement button = FindAutomationElementByAutomationId(root, "DeleteObjectButton");
        try
        {
            if (button != null
                && button.Current.ControlType == System.Windows.Automation.ControlType.Button
                && button.Current.IsEnabled)
            {
                return button;
            }
        }
        catch (System.Windows.Automation.ElementNotAvailableException)
        {
        }

        return FindEnabledAutomationButton(root, "\uC0AD\uC81C");
    }

    internal static System.Windows.Automation.AutomationElement FindAutomationElementByClass(
        System.Windows.Automation.AutomationElement root,
        string className)
    {
        foreach (System.Windows.Automation.AutomationElement element in EnumerateAutomationDescendants(root))
        {
            string currentClassName;
            try
            {
                currentClassName = element.Current.ClassName;
            }
            catch (System.Windows.Automation.ElementNotAvailableException)
            {
                continue;
            }

            if (string.Equals(currentClassName, className, StringComparison.Ordinal))
            {
                return element;
            }
        }

        return null;
    }

    internal static System.Windows.Automation.AutomationElement FindVisibleAutomationElementByName(
        System.Windows.Automation.AutomationElement root,
        string name,
        double maximumWidth,
        double maximumHeight)
    {
        foreach (System.Windows.Automation.AutomationElement element in EnumerateAutomationDescendants(root))
        {
            try
            {
                System.Windows.Rect bounds = element.Current.BoundingRectangle;
                if (!element.Current.IsOffscreen
                    && string.Equals(element.Current.Name, name, StringComparison.Ordinal)
                    && bounds.Width > 0D
                    && bounds.Height > 0D
                    && bounds.Width <= maximumWidth
                    && bounds.Height <= maximumHeight)
                {
                    return element;
                }
            }
            catch (System.Windows.Automation.ElementNotAvailableException)
            {
            }
        }

        return null;
    }

    internal static System.Windows.Automation.AutomationElement FindCanvasAnnotationToolByIndex(
        System.Windows.Automation.AutomationElement root,
        int index)
    {
        System.Windows.Automation.AutomationElement toolList =
            FindAutomationElementByAutomationId(root, "CanvasAnnotationToolListBox");
        if (toolList == null)
        {
            return null;
        }

        System.Windows.Automation.AutomationElement[] items = EnumerateAutomationDescendants(toolList)
            .Where(element =>
            {
                try
                {
                    return element.Current.ControlType == System.Windows.Automation.ControlType.ListItem
                        && !element.Current.IsOffscreen
                        && element.Current.IsEnabled;
                }
                catch (System.Windows.Automation.ElementNotAvailableException)
                {
                    return false;
                }
            })
            .OrderBy(element => element.Current.BoundingRectangle.Top)
            .ToArray();
        return index >= 0 && index < items.Length ? items[index] : null;
    }

    internal static System.Windows.Automation.AutomationElement FindAutomationElementByAutomationId(
        System.Windows.Automation.AutomationElement root,
        string automationId)
    {
        foreach (System.Windows.Automation.AutomationElement element in EnumerateAutomationDescendants(root))
        {
            string currentAutomationId;
            try
            {
                currentAutomationId = element.Current.AutomationId;
            }
            catch (System.Windows.Automation.ElementNotAvailableException)
            {
                continue;
            }

            if (string.Equals(currentAutomationId, automationId, StringComparison.Ordinal))
            {
                return element;
            }
        }

        return null;
    }

    internal static bool SelectAutomationTabByAutomationId(
        System.Windows.Automation.AutomationElement root,
        string automationId)
    {
        System.Windows.Automation.AutomationElement element = FindAutomationElementByAutomationId(root, automationId);
        if (element == null || element.Current.ControlType != System.Windows.Automation.ControlType.TabItem)
        {
            return false;
        }

        if (element.TryGetCurrentPattern(System.Windows.Automation.SelectionItemPattern.Pattern, out object pattern)
            && pattern is System.Windows.Automation.SelectionItemPattern selectionPattern)
        {
            selectionPattern.Select();
            Thread.Sleep(300);
            return true;
        }

        NativeClick(GetAutomationCenter(element));
        Thread.Sleep(300);
        return true;
    }

    internal static bool TrySetAutomationValueByAutomationId(
        System.Windows.Automation.AutomationElement root,
        string automationId,
        string value)
    {
        System.Windows.Automation.AutomationElement element = FindAutomationElementByAutomationId(root, automationId);
        if (element == null || !element.Current.IsEnabled)
        {
            return false;
        }

        if (element.TryGetCurrentPattern(System.Windows.Automation.ValuePattern.Pattern, out object pattern)
            && pattern is System.Windows.Automation.ValuePattern valuePattern
            && !valuePattern.Current.IsReadOnly)
        {
            valuePattern.SetValue(value ?? string.Empty);
            return WaitUntil(() => string.Equals(GetAutomationValueByAutomationId(root, automationId), value ?? string.Empty, StringComparison.Ordinal), TimeSpan.FromSeconds(1));
        }

        NativeClick(GetAutomationCenter(element));
        SendKeys.SendWait("^a");
        SendKeys.SendWait(value ?? string.Empty);
        return WaitUntil(() => string.Equals(GetAutomationValueByAutomationId(root, automationId), value ?? string.Empty, StringComparison.Ordinal), TimeSpan.FromSeconds(1));
    }

    private static bool TryPasteAutomationValueByAutomationId(
        System.Windows.Automation.AutomationElement root,
        string automationId,
        string value)
    {
        System.Windows.Automation.AutomationElement element = FindAutomationElementByAutomationId(root, automationId);
        if (element == null || !element.Current.IsEnabled)
        {
            return false;
        }

        // The real-EXE smoke intentionally uses the keyboard/clipboard path so
        // WPF TextChanged and binding updates follow the same route as a user.
        string text = value ?? string.Empty;
        NativeClick(GetAutomationCenter(element));
        Thread.Sleep(60);
        SendKeys.SendWait("^a");
        Thread.Sleep(30);
        Clipboard.SetText(text);
        SendKeys.SendWait("^v");
        return WaitUntil(
            () => string.Equals(GetAutomationValueByAutomationId(root, automationId), text, StringComparison.Ordinal),
            TimeSpan.FromSeconds(2));
    }

    private static bool TryPasteAutomationValueByName(
        System.Windows.Automation.AutomationElement root,
        string name,
        string value)
    {
        System.Windows.Automation.AutomationElement element = EnumerateAutomationDescendants(root)
            .FirstOrDefault(candidate =>
            {
                try
                {
                    return candidate.Current.IsEnabled
                        && string.Equals(candidate.Current.Name, name, StringComparison.Ordinal)
                        && candidate.TryGetCurrentPattern(
                            System.Windows.Automation.ValuePattern.Pattern,
                            out object pattern)
                        && pattern is System.Windows.Automation.ValuePattern valuePattern
                        && !valuePattern.Current.IsReadOnly;
                }
                catch (System.Windows.Automation.ElementNotAvailableException)
                {
                    return false;
                }
            });
        if (element == null)
        {
            return false;
        }

        string text = value ?? string.Empty;
        NativeClick(GetAutomationCenter(element));
        Thread.Sleep(60);
        SendKeys.SendWait("^a");
        Thread.Sleep(30);
        Clipboard.SetText(text);
        SendKeys.SendWait("^v");
        return WaitUntil(
            () =>
            {
                try
                {
                    return element.TryGetCurrentPattern(
                            System.Windows.Automation.ValuePattern.Pattern,
                            out object pattern)
                        && pattern is System.Windows.Automation.ValuePattern valuePattern
                        && string.Equals(
                            valuePattern.Current.Value ?? string.Empty,
                            text,
                            StringComparison.Ordinal);
                }
                catch (System.Windows.Automation.ElementNotAvailableException)
                {
                    return false;
                }
            },
            TimeSpan.FromSeconds(2));
    }

    internal static string GetAutomationValueByAutomationId(
        System.Windows.Automation.AutomationElement root,
        string automationId)
    {
        System.Windows.Automation.AutomationElement element = FindAutomationElementByAutomationId(root, automationId);
        if (element == null)
        {
            return string.Empty;
        }

        if (element.TryGetCurrentPattern(System.Windows.Automation.ValuePattern.Pattern, out object pattern)
            && pattern is System.Windows.Automation.ValuePattern valuePattern)
        {
            return valuePattern.Current.Value ?? string.Empty;
        }

        return element.Current.Name ?? string.Empty;
    }

    private static int GetObjectReviewSummaryCount(System.Windows.Automation.AutomationElement root)
    {
        string summary = GetAutomationValueByAutomationId(root, "ObjectReviewSummaryText");
        if (summary.Contains("\uAC1D\uCCB4 \uC5C6\uC74C", StringComparison.Ordinal))
        {
            return 0;
        }

        int countSuffixIndex = summary.IndexOf("\uAC1C \uAC1D\uCCB4", StringComparison.Ordinal);
        return countSuffixIndex > 0
            && int.TryParse(summary.Substring(0, countSuffixIndex), NumberStyles.Integer, CultureInfo.InvariantCulture, out int count)
                ? count
                : -1;
    }

    private static string GetAutomationElementValue(System.Windows.Automation.AutomationElement element)
    {
        if (element == null)
        {
            return string.Empty;
        }

        try
        {
            if (element.TryGetCurrentPattern(System.Windows.Automation.ValuePattern.Pattern, out object pattern)
                && pattern is System.Windows.Automation.ValuePattern valuePattern)
            {
                return valuePattern.Current.Value ?? string.Empty;
            }

            return element.Current.Name ?? string.Empty;
        }
        catch (System.Windows.Automation.ElementNotAvailableException)
        {
            return string.Empty;
        }
    }

