    private static bool WaitForAutomationValueByAutomationId(
        Process process,
        string automationId,
        string expectedText,
        TimeSpan timeout)
    {
        return WaitUntil(
            () =>
            {
                var root = RefreshAutomationRoot(process, bringToFront: false);
