        InvokePrivate(window, "RefreshPolygonOverlays");
    }

    private static void SeedVisualSmokeRemoveUnderlyingOverlap(WpfLabelingShellWindow window)
    {
        List<LabelingSegmentationObject> segments =
            GetPrivateField<List<LabelingSegmentationObject>>(window, "manualSegments");
        LabelingSegmentationObject selectedMask = segments.FirstOrDefault(segment => segment?.IsRasterMask == true);
        int polygonIndex = segments.FindIndex(segment => segment?.IsRasterMask != true);
        if (selectedMask == null || polygonIndex < 0 || selectedMask.Bounds.IsEmpty)
        {
            return;
        }

        Rectangle bounds = selectedMask.Bounds;
        Size imageSize = selectedMask.MaskSize;
        int left = Math.Max(0, bounds.Left - 8);
        int top = Math.Max(0, bounds.Top - 8);
        int right = Math.Min(imageSize.Width - 1, bounds.Right + 8);
        int bottom = Math.Min(imageSize.Height - 1, bounds.Bottom + 8);
        var previewClass = new CClassItem { Text = "Defect", DrawColor = Color.DeepSkyBlue };
        segments[polygonIndex] = new LabelingSegmentationObject(
            new[]
            {
                new Point(left, top),
                new Point(right, top),
                new Point(right, bottom),
                new Point(left, bottom)
            },
            previewClass)
        {
            ClassName = previewClass.Text,
            ObjectId = "visual-remove-underlying",
            ZOrder = selectedMask.ZOrder - 1,
            LastStructuralOperation = "Original"
        };
        selectedMask.ZOrder = Math.Max(selectedMask.ZOrder, segments[polygonIndex].ZOrder + 1);
        InvokePrivate(window, "RefreshObjectList");
    }

    private static void SelectVisualSmokeActiveRoi(WpfLabelingShellWindow window)
    {
        if (window?.MainCanvasViewModel == null)
        {
            return;
        }

        CanvasRect<float> selectedRect = GetPrivateField<CanvasRect<float>>(window.MainCanvasViewModel, "_selectedRect");
        if (selectedRect == null || selectedRect.IsEmpty())
        {
            return;
        }

        selectedRect.IsEditing = true;
        selectedRect.IsChanged = true;
        window.MainCanvasViewModel.ImageViewer.RefreshGL();
    }

    private static void ApplyVisualSmokeZoom(WpfLabelingShellWindow window, int zoomSteps)
    {
        if (window == null || zoomSteps == 0)
        {
            return;
        }

        Size canvasSize = window.MainCanvasViewModel.ImageViewer.GetSize();
        var center = new Point(Math.Max(1, canvasSize.Width / 2), Math.Max(1, canvasSize.Height / 2));
        int delta = zoomSteps > 0 ? 120 : -120;
        for (int i = 0; i < Math.Abs(zoomSteps); i++)
        {
            window.MainCanvasViewModel.ImageViewer.ZoomAt(center, delta);
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(120));
        }
    }

    private static void SelectVisualSmokeReviewTab(WpfLabelingShellWindow window, string reviewTab)
    {
        if (window == null || string.IsNullOrWhiteSpace(reviewTab))
        {
            return;
        }

        string tabKey = reviewTab.Trim().ToLowerInvariant();
        bool isLabelingGuideTab = tabKey is "labeling-guide" or "guide-labeling";
        WpfShellWorkflowStage stage = isLabelingGuideTab
            ? WpfShellWorkflowStage.Labeling
            : tabKey switch
            {
                "objects" or "object" => WpfShellWorkflowStage.Labeling,
                "candidates" or "candidate" => WpfShellWorkflowStage.Inference,
                "guide" or "learning" or "learn" => WpfShellWorkflowStage.Dataset,
                "classes" or "class" => WpfShellWorkflowStage.Labeling,
                "data" or "dataset-data" or "yolo" or "model" or "yolo-model" or "yolo-model-anomaly" or "training" => WpfShellWorkflowStage.TrainingModel,
                _ => WpfShellWorkflowStage.Dataset
            };
        window.ShellViewModel?.SetWorkflowStage(stage);
        window.ShellViewModel?.SetRightWorkflowShortcut(stage == WpfShellWorkflowStage.Labeling
            ? isLabelingGuideTab
                ? WpfRightWorkflowShortcut.LabelingGuide
                : tabKey switch
                {
                    "objects" or "object" => WpfRightWorkflowShortcut.SavedLabels,
                    "guide" or "learning" or "learn" => WpfRightWorkflowShortcut.LabelingGuide,
                    "classes" or "class" => WpfRightWorkflowShortcut.ClassCatalog,
                    _ => WpfRightWorkflowShortcut.None
                }
            : WpfRightWorkflowShortcut.None);
        window.UpdateLayout();

        string controlName = isLabelingGuideTab
            ? "LearningReviewTab"
            : tabKey switch
            {
                "objects" or "object" => "ObjectsReviewTab",
                "candidates" or "candidate" => "CandidatesReviewTab",
                "guide" or "learning" or "learn" => "LearningReviewTab",
                "classes" or "class" => "ClassesReviewTab",
                "data" or "dataset-data" or "yolo" or "model" or "yolo-model" or "yolo-model-anomaly" or "training" => "YoloSettingsReviewTab",
                _ => string.Empty
            };

        if (!string.IsNullOrWhiteSpace(controlName)
            && window.FindName(controlName) is System.Windows.Controls.TabItem tab)
        {
            if (window.FindName("ReviewTabControl") is System.Windows.Controls.TabControl reviewTabs)
            {
                reviewTabs.SelectedItem = tab;
            }

            tab.IsSelected = true;
            tab.Focus();
            window.UpdateLayout();
        }

        if (window.FindName("YoloModelCenterTaskTabs") is System.Windows.Controls.TabControl modelCenterTaskTabs)
        {
            string taskTabName = tabKey == "training"
                ? "YoloModelCenterTrainingTaskTab"
                : tabKey is "data" or "dataset-data"
                    ? "YoloModelCenterDataTaskTab"
                    : tabKey is "model" or "yolo-model" or "yolo-model-anomaly"
                        ? "YoloModelCenterRuntimeTaskTab"
                        : "YoloModelCenterOverviewTaskTab";
            if (window.FindName(taskTabName) is System.Windows.Controls.TabItem taskTab)
            {
                modelCenterTaskTabs.SelectedItem = taskTab;
                taskTab.IsSelected = true;
                window.UpdateLayout();
            }
        }

        if (tabKey is "model" or "yolo-model" or "yolo-model-anomaly"
            && window.FindName("YoloModelSettingsPanelControl") is WpfYoloModelSettingsPanel modelSettingsPanel)
        {
            modelSettingsPanel.SettingsExpander.IsExpanded = true;
            window.UpdateLayout();
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(120));
            if (window.FindName("YoloSettingsScrollViewer") is System.Windows.Controls.ScrollViewer yoloScrollViewer)
            {
                yoloScrollViewer.UpdateLayout();
                yoloScrollViewer.ScrollToTop();
            }

            if (tabKey == "yolo-model-anomaly"
                && modelSettingsPanel.FindName("YoloAnomalyMappingPanel") is System.Windows.FrameworkElement anomalyPanel)
            {
                anomalyPanel.BringIntoView();
            }
            else
            {
                modelSettingsPanel.BringIntoView();
            }

            window.UpdateLayout();
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(120));
        }

        if (tabKey == "training"
            && window.FindName("TrainingSettingsPanelControl") is WpfTrainingSettingsPanel trainingPanel)
        {
            System.Windows.Controls.Expander trainingExpander = trainingPanel.SettingsExpander;
            trainingExpander.IsExpanded = true;
            window.UpdateLayout();
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(120));
            if (window.FindName("YoloSettingsScrollViewer") is System.Windows.Controls.ScrollViewer yoloScrollViewer)
            {
                yoloScrollViewer.UpdateLayout();
                yoloScrollViewer.ScrollToVerticalOffset(yoloScrollViewer.ScrollableHeight);
            }

            if (window.FindName("PostTrainingModelActionPanel") is System.Windows.FrameworkElement postTrainingActions)
            {
                postTrainingActions.BringIntoView();
            }
            else
            {
                trainingExpander.BringIntoView();
            }
            window.UpdateLayout();
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(120));
        }

        if (tabKey is "data" or "dataset-data"
            && window.FindName("YoloSettingsScrollViewer") is System.Windows.Controls.ScrollViewer dataScrollViewer)
        {
            dataScrollViewer.UpdateLayout();
            dataScrollViewer.ScrollToTop();
            window.UpdateLayout();
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(120));
        }
    }

