    private static void AssertWpfMainLayoutKeepsReviewPanelVisible(WpfLabelingShellWindow window, string reviewTab)
    {
        AssertTrue(window != null, "responsive layout window was not created");
        window.UpdateLayout();

        if (window.FindName("ReviewTabControl") is not System.Windows.Controls.TabControl reviewTabs)
        {
            throw new InvalidOperationException("ReviewTabControl was not found for responsive layout verification");
        }

        if (window.FindName("CanvasPanelControl") is not System.Windows.FrameworkElement canvasPanel)
        {
            throw new InvalidOperationException("CanvasPanelControl was not found for responsive layout verification");
        }

        if (window.FindName("ImageQueuePanelControl") is not System.Windows.FrameworkElement imageQueuePanel)
        {
            throw new InvalidOperationException("ImageQueuePanelControl was not found for responsive layout verification");
        }

        if (window.ShellViewModel?.IsModelWorkspaceActive == true)
        {
            if (window.FindName("RightWorkflowDockPanel") is not System.Windows.FrameworkElement modelWorkspacePanel)
            {
                throw new InvalidOperationException("RightWorkflowDockPanel was not found for model workspace verification");
            }

            AssertEqual(System.Windows.Visibility.Collapsed, canvasPanel.Visibility);
            AssertEqual(System.Windows.Visibility.Collapsed, imageQueuePanel.Visibility);
            AssertTrue(modelWorkspacePanel.ActualWidth >= 640D,
                FormattableString.Invariant($"model workspace did not use the available width on {reviewTab}: width={modelWorkspacePanel.ActualWidth:0.0}"));
            return;
        }

        bool isRightWorkflowExpanded = window.ShellViewModel?.IsRightWorkflowDockExpanded == true;
        System.Windows.FrameworkElement reviewTarget = reviewTabs;
        string reviewTargetName = "left workflow panel";
        double minimumTargetWidth = 280D;

        if (!isRightWorkflowExpanded)
        {
            if (window.FindName("RightWorkflowCollapsedRail") is not System.Windows.FrameworkElement collapsedRail)
            {
                throw new InvalidOperationException("RightWorkflowCollapsedRail was not found for responsive layout verification");
            }

            reviewTarget = collapsedRail;
            reviewTargetName = "left workflow rail";
            minimumTargetWidth = 60D;
        }

        System.Windows.Point reviewOrigin = reviewTarget.TranslatePoint(new System.Windows.Point(0, 0), window);
        System.Windows.Point canvasOrigin = canvasPanel.TranslatePoint(new System.Windows.Point(0, 0), window);
        System.Windows.Point imageQueueOrigin = imageQueuePanel.TranslatePoint(new System.Windows.Point(0, 0), window);
        double reviewRight = reviewOrigin.X + reviewTarget.ActualWidth;
        double canvasRight = canvasOrigin.X + canvasPanel.ActualWidth;
        double imageQueueRight = imageQueueOrigin.X + imageQueuePanel.ActualWidth;
        double windowRight = window.ActualWidth;

        AssertTrue(
            reviewTarget.ActualWidth >= minimumTargetWidth,
            FormattableString.Invariant($"responsive layout {reviewTargetName} became too narrow on {reviewTab}: width={reviewTarget.ActualWidth:0.0}"));
        AssertTrue(
            reviewOrigin.X >= 0D && reviewRight <= windowRight - 4D,
            FormattableString.Invariant($"responsive layout pushed {reviewTargetName} out of window on {reviewTab}: left={reviewOrigin.X:0.0}, right={reviewRight:0.0}, window={windowRight:0.0}"));
        AssertTrue(
            imageQueuePanel.ActualWidth >= 260D && imageQueueOrigin.X >= 0D && imageQueueRight <= windowRight - 4D,
            FormattableString.Invariant($"responsive layout image queue became hidden or too narrow on {reviewTab}: queueWidth={imageQueuePanel.ActualWidth:0.0}, left={imageQueueOrigin.X:0.0}, right={imageQueueRight:0.0}, window={windowRight:0.0}"));
        AssertTrue(
            reviewRight <= canvasOrigin.X - 6D,
            FormattableString.Invariant($"responsive layout left workflow overlapped canvas on {reviewTab}: workflowRight={reviewRight:0.0}, canvasLeft={canvasOrigin.X:0.0}"));
        AssertTrue(
            canvasPanel.ActualWidth >= 360D && canvasRight <= imageQueueOrigin.X - 6D,
            FormattableString.Invariant($"responsive layout left insufficient canvas space or overlap on {reviewTab}: canvasWidth={canvasPanel.ActualWidth:0.0}, canvasRight={canvasRight:0.0}, queueLeft={imageQueueOrigin.X:0.0}"));
    }

    private static void PrepareVisualSmokeGuidePanel(
        WpfLabelingShellWindow window,
        string reviewTab,
        bool expandLearningConcepts,
        bool focusTemplateWorkflow = false,
        bool expandLabelingDetails = false,
        bool focusYoloValidationReport = false,
        bool focusDatasetDashboard = false)
    {
        if (window == null
            || (!expandLearningConcepts && !focusTemplateWorkflow && !expandLabelingDetails && !focusYoloValidationReport && !focusDatasetDashboard)
            || string.IsNullOrWhiteSpace(reviewTab))
        {
            return;
        }

        string tabKey = reviewTab.Trim().ToLowerInvariant();
        if (tabKey is not ("guide" or "learning" or "learn" or "labeling-guide" or "guide-labeling"))
        {
            return;
        }

        WpfLearningWorkflowPanel workflowPanel = window.FindName("LearningWorkflowPanelControl") as WpfLearningWorkflowPanel;
        object FindGuideElement(string name) => workflowPanel?.FindName(name) ?? window.FindName(name);

        if (focusDatasetDashboard)
        {
            window.LearningWorkflowViewModel?.ShowLabelingTask();
            if (FindGuideElement("LabelingGuideDetailsExpander") is System.Windows.Controls.Expander detailsExpander)
            {
                detailsExpander.IsExpanded = true;
            }
            if (FindGuideElement("LabelingGuideTrainingFlowExpander") is System.Windows.Controls.Expander trainingFlowExpander)
            {
                trainingFlowExpander.IsExpanded = true;
            }
        }

        if (expandLearningConcepts
            && FindGuideElement("LearningConceptsExpander") is System.Windows.Controls.Expander expander)
        {
            expander.IsExpanded = true;
        }

        if (expandLabelingDetails || focusTemplateWorkflow || focusYoloValidationReport)
        {
            if (FindGuideElement("LabelingGuideDetailsExpander") is System.Windows.Controls.Expander detailsExpander)
            {
                detailsExpander.IsExpanded = true;
            }

            if (expandLabelingDetails
                && FindGuideElement("LabelingGuideTrainingFlowExpander") is System.Windows.Controls.Expander trainingFlowExpander)
            {
                trainingFlowExpander.IsExpanded = true;
            }
        }

        if (focusTemplateWorkflow)
        {
            if (FindGuideElement("LabelingGuideWorkflowGuideExpander") is System.Windows.Controls.Expander guideExpander)
            {
                guideExpander.IsExpanded = true;
            }

            if (FindGuideElement("LabelingGuideWorkflowTabs") is System.Windows.Controls.TabControl workflowTabs)
            {
                workflowTabs.SelectedIndex = 1;
            }

            if (FindGuideElement("LabelingGuideTemplateTutorialSubTabs") is System.Windows.Controls.TabControl templateTabs)
            {
                templateTabs.SelectedIndex = 0;
            }
        }

        if (focusYoloValidationReport)
        {
            if (FindGuideElement("LabelingGuideReferenceExpander") is System.Windows.Controls.Expander referenceExpander)
            {
                referenceExpander.IsExpanded = true;
            }
            if (FindGuideElement("LabelingGuideYoloValidationExpander") is System.Windows.Controls.Expander validationExpander)
            {
                validationExpander.IsExpanded = true;
            }
        }

        window.UpdateLayout();
        PumpWpfDispatcher(TimeSpan.FromMilliseconds(150));

        if (focusDatasetDashboard && FindGuideElement("DatasetStatusDashboardPanel") is System.Windows.FrameworkElement datasetDashboard)
        {
            datasetDashboard.BringIntoView();
        }
        else if (FindGuideElement("AnnotationToolListBox") is System.Windows.FrameworkElement toolList)
        {
            toolList.BringIntoView();
        }

        if (focusYoloValidationReport && FindGuideElement("YoloTrainingResultComparisonPanel") is System.Windows.FrameworkElement trainingReport)
        {
            trainingReport.BringIntoView();
        }
        else if (focusTemplateWorkflow && FindGuideElement("TemplateWorkflowPanel") is System.Windows.FrameworkElement templateWorkflow)
        {
            templateWorkflow.BringIntoView();
        }
        else if (expandLabelingDetails && FindGuideElement("YoloCurrentTrainingActionPanel") is System.Windows.FrameworkElement trainingDetails)
        {
            trainingDetails.BringIntoView();
        }

        window.UpdateLayout();
        PumpWpfDispatcher(TimeSpan.FromMilliseconds(150));
    }

