    private static List<YoloWorkerSmokeCandidate> CreateVisualSmokeCandidates(Size imageSize, bool segmentationCandidates = false)
    {
        int width = Math.Max(80, imageSize.Width);
        int height = Math.Max(80, imageSize.Height);
        double outerWidth = Math.Max(42, width * 0.44);
        double outerHeight = Math.Max(42, height * 0.40);
        double outerX = Math.Max(0, (width - outerWidth) / 2);
        double outerY = Math.Max(0, (height - outerHeight) / 2);
        double innerWidth = Math.Max(18, width * 0.14);
        double innerHeight = Math.Max(24, height * 0.22);
        double innerX = Math.Max(0, (width - innerWidth) / 2);
        double innerY = Math.Max(0, (height - innerHeight) / 2);

        return new List<YoloWorkerSmokeCandidate>
        {
            new YoloWorkerSmokeCandidate
            {
                Index = 1,
                ClassName = "OK",
                Confidence = 0.959,
                X = outerX,
                Y = outerY,
                Width = outerWidth,
                Height = outerHeight,
                SegmentationType = segmentationCandidates ? "polygon" : string.Empty,
                PolygonPoints = segmentationCandidates
                    ? new[]
                    {
                        new DetectionPolygonPoint { X = (float)(outerX + outerWidth * 0.50), Y = (float)outerY },
                        new DetectionPolygonPoint { X = (float)(outerX + outerWidth * 0.90), Y = (float)(outerY + outerHeight * 0.22) },
                        new DetectionPolygonPoint { X = (float)(outerX + outerWidth), Y = (float)(outerY + outerHeight * 0.62) },
                        new DetectionPolygonPoint { X = (float)(outerX + outerWidth * 0.58), Y = (float)(outerY + outerHeight) },
                        new DetectionPolygonPoint { X = (float)(outerX + outerWidth * 0.12), Y = (float)(outerY + outerHeight * 0.82) },
                        new DetectionPolygonPoint { X = (float)outerX, Y = (float)(outerY + outerHeight * 0.35) }
                    }
                    : Array.Empty<DetectionPolygonPoint>()
            },
            new YoloWorkerSmokeCandidate
            {
                Index = 2,
                ClassName = "NG",
                Confidence = 0.954,
                X = innerX,
                Y = innerY,
                Width = innerWidth,
                Height = innerHeight,
                SegmentationType = segmentationCandidates ? "polygon" : string.Empty,
                PolygonPoints = segmentationCandidates
                    ? new[]
                    {
                        new DetectionPolygonPoint { X = (float)(innerX + innerWidth * 0.50), Y = (float)innerY },
                        new DetectionPolygonPoint { X = (float)(innerX + innerWidth), Y = (float)(innerY + innerHeight * 0.42) },
                        new DetectionPolygonPoint { X = (float)(innerX + innerWidth * 0.72), Y = (float)(innerY + innerHeight) },
                        new DetectionPolygonPoint { X = (float)(innerX + innerWidth * 0.18), Y = (float)(innerY + innerHeight * 0.84) },
                        new DetectionPolygonPoint { X = (float)innerX, Y = (float)(innerY + innerHeight * 0.30) }
                    }
                    : Array.Empty<DetectionPolygonPoint>()
            }
        };
    }

    private static List<YoloWorkerSmokeCandidate> CreateVisualSmokePatchCoreCandidate(Size imageSize, string heatmapPath)
    {
        int width = Math.Max(80, imageSize.Width);
        int height = Math.Max(80, imageSize.Height);
        double candidateWidth = Math.Max(28, width * 0.28);
        double candidateHeight = Math.Max(28, height * 0.24);
        return new List<YoloWorkerSmokeCandidate>
        {
            new YoloWorkerSmokeCandidate
            {
                Index = 1,
                ClassName = "Defect",
                Confidence = 0.584,
                X = Math.Max(0, width * 0.50 - candidateWidth / 2),
                Y = Math.Max(0, height * 0.46 - candidateHeight / 2),
                Width = candidateWidth,
                Height = candidateHeight,
                CandidateType = "anomaly",
                PredictionType = "patchcore",
                ImageLevel = true,
                AnomalyScore = 0.5839282274,
                AnomalyThreshold = 0.4214764774,
                HeatmapPath = Path.GetFullPath(heatmapPath)
            }
        };
    }

    private static void CloseAuxiliaryVisualSmokeWindows(System.Windows.Window mainWindow)
    {
        IntPtr mainHandle = new System.Windows.Interop.WindowInteropHelper(mainWindow).Handle;
        foreach (System.Windows.Window window in System.Windows.Application.Current.Windows.Cast<System.Windows.Window>().ToArray())
        {
            if (!ReferenceEquals(window, mainWindow))
            {
                window.Close();
            }
        }

        foreach (Form form in System.Windows.Forms.Application.OpenForms.Cast<Form>().ToArray())
        {
            form.Close();
        }

        uint currentProcessId = (uint)Process.GetCurrentProcess().Id;
        EnumWindows((hWnd, _) =>
        {
            GetWindowThreadProcessId(hWnd, out uint processId);
            if (processId == currentProcessId && hWnd != mainHandle && IsWindowVisible(hWnd))
            {
                SendMessage(hWnd, WmClose, IntPtr.Zero, IntPtr.Zero);
            }

            return true;
        }, IntPtr.Zero);
    }

    private static void BringVisualSmokeWindowToFront(System.Windows.Window window)
    {
        if (window == null)
        {
            return;
        }

        IntPtr handle = new System.Windows.Interop.WindowInteropHelper(window).Handle;
        if (handle == IntPtr.Zero)
        {
            return;
        }

        window.Topmost = true;
        window.Activate();
        window.Focus();
        SetWindowPos(handle, HwndTopMost, 0, 0, 0, 0, SwpNoMove | SwpNoSize | SwpShowWindow);
        SetForegroundWindow(handle);
    }

    internal static void CreateVisualSmokeImage(string imagePath, int marker = 0)
    {
        using (Bitmap image = new Bitmap(260, 220))
        using (Graphics graphics = Graphics.FromImage(image))
        using (Brush background = new SolidBrush(Color.FromArgb(18, 18, 18)))
        using (Brush frame = new SolidBrush(Color.FromArgb(176, 176, 176)))
        using (Brush inner = new SolidBrush(Color.FromArgb(82, 82, 82)))
        using (Brush part = new SolidBrush(Color.FromArgb(138, 138, 138)))
        using (Brush defect = new SolidBrush(Color.FromArgb(38, 38, 38)))
        {
            graphics.Clear(Color.Black);
            graphics.FillRectangle(background, 0, 0, image.Width, image.Height);
            graphics.FillRectangle(frame, 30, 20, 200, 180);
            graphics.FillRectangle(inner, 43, 34, 174, 153);
            graphics.FillEllipse(part, 70, 58, 116, 116);
            graphics.FillRectangle(defect, 116, 86, 34, 58);
            if (marker > 0)
            {
                using Brush markerBrush = new SolidBrush(Color.FromArgb(40 + (marker * 37 % 180), 72 + (marker * 53 % 160), 96 + (marker * 29 % 140)));
                graphics.FillRectangle(markerBrush, 8, 8, 12, 12);
            }

            graphics.Save();
            Directory.CreateDirectory(Path.GetDirectoryName(imagePath));
            image.Save(imagePath, System.Drawing.Imaging.ImageFormat.Jpeg);
        }
    }

