    internal static void CaptureWindow(System.Windows.Window window, string outputPath)
    {
        window.UpdateLayout();
        int width = Math.Max(1, (int)Math.Ceiling(window.ActualWidth));
        int height = Math.Max(1, (int)Math.Ceiling(window.ActualHeight));
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));

        var renderBitmap = new System.Windows.Media.Imaging.RenderTargetBitmap(
            width,
            height,
            96,
            96,
            System.Windows.Media.PixelFormats.Pbgra32);
        renderBitmap.Render(window);

        var encoder = new System.Windows.Media.Imaging.PngBitmapEncoder();
        encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(renderBitmap));
        using (FileStream stream = File.Create(outputPath))
        {
            encoder.Save(stream);
        }
    }

    private static void CaptureWindowFromScreen(System.Windows.Window window, string outputPath)
    {
        window.UpdateLayout();
        System.Windows.Point origin = window.PointToScreen(new System.Windows.Point(0, 0));
        int width = Math.Max(1, (int)Math.Ceiling(window.ActualWidth));
        int height = Math.Max(1, (int)Math.Ceiling(window.ActualHeight));
        using var bitmap = new Bitmap(width, height);
        using (Graphics graphics = Graphics.FromImage(bitmap))
        {
            graphics.CopyFromScreen(
                (int)Math.Round(origin.X),
                (int)Math.Round(origin.Y),
                0,
                0,
                bitmap.Size);
        }

        SaveBitmap(bitmap, outputPath);
    }

