                string.Create(
                    CultureInfo.InvariantCulture,
                    $"WPF_MASK_BRUSH_DRAG_1000_MOVE_MS={stopwatch.Elapsed.TotalMilliseconds:F3} WPF_MASK_BRUSH_RELEASE_MS={releaseStopwatch.Elapsed.TotalMilliseconds:F3} WPF_MASK_BRUSH_EXISTING_DRAG_1000_MOVE_MS={secondMoveStopwatch.Elapsed.TotalMilliseconds:F3} WPF_MASK_BRUSH_EXISTING_RELEASE_MS={secondReleaseStopwatch.Elapsed.TotalMilliseconds:F3} WPF_MASK_TOOL_END_CALL_MS={toolEndStopwatch.Elapsed.TotalMilliseconds:F3} SEGMENTS={manualSegments.Count} UNDO_DURING={undoCountDuringDrag} UNDO_AFTER={undoCountAfterRelease} UNDO_BUTTON_IMMEDIATE={undoButtonEnabledImmediatelyAfterRelease} UNDO_BUTTON_AFTER={undoButtonEnabledAfterRelease} UNDO_AFTER_SECOND={undoCountAfterSecondRelease} SECOND_UNDO_BUTTON_IMMEDIATE={secondUndoButtonEnabledImmediatelyAfterRelease} SECOND_UNDO_BUTTON_AFTER={secondUndoButtonEnabledAfterRelease} UNDO_AFTER_TOOL_END={undoCountAfterToolEnd} OBJECT_ROWS_BEFORE={objectRowsBeforeDrag} OBJECT_ROWS_DURING={objectRowsDuringDrag} OBJECT_ROWS_AFTER={objectRowsAfterRelease} OBJECT_ROWS_AFTER_TOOL_END={objectRowsAfterToolEnd} SELECTED_AFTER={selectedObjectAfterRelease} SELECTED_AFTER_SECOND={selectedObjectAfterSecondRelease} COLLECTION_CHANGED_DURING={collectionChangesBeforeRelease} COLLECTION_CHANGED_AFTER={collectionChangesAfterRelease} SECOND_COLLECTION_CHANGED_DURING={secondCollectionChangesBeforeRelease} SECOND_COLLECTION_CHANGED_AFTER={secondCollectionChangesAfterRelease} COLLECTION_CHANGED_AFTER_TOOL_END={collectionChangesAfterToolEnd} QUEUE_CHANGED_AFTER={queueChangesAfterRelease - queueChangesBeforeRelease} SECOND_QUEUE_CHANGED_AFTER={secondQueueChangesAfterRelease - secondQueueChangesBeforeRelease} QUEUE_CHANGED_AFTER_TOOL_END={queueChangesAfterToolEnd - queueChangesBeforeToolEnd} PREVIEW_DURING={previewVisibleDuringDrag} PREVIEW_IMMEDIATE_AFTER={previewVisibleImmediatelyAfterRelease} PREVIEW_AFTER={previewVisibleAfterRelease} SECOND_PREVIEW_DURING={secondPreviewVisibleDuringDrag} SECOND_PREVIEW_IMMEDIATE_AFTER={secondPreviewVisibleImmediatelyAfterRelease} SECOND_PREVIEW_AFTER={secondPreviewVisibleAfterRelease} PREVIEW_AFTER_TOOL_END={previewVisibleAfterToolEnd} TAB_AFTER_RELEASE={learningTabSelectedAfterRelease} TAB_AFTER_SECOND_RELEASE={learningTabSelectedAfterSecondRelease} MODEL_STATUS_CHANGED={modelStatusPropertyChanged} RELEASE_ACTIONS={string.Join("|", releaseActions)} SECOND_RELEASE_ACTIONS={string.Join("|", secondReleaseActions)} TOOL_END_ACTIONS={string.Join("|", toolEndActions)}"));

            AssertEqual(1, manualSegments.Count);
            AssertEqual(0, undoCountDuringDrag);
            AssertEqual(1, undoCountAfterRelease);
            AssertTrue(undoButtonEnabledImmediatelyAfterRelease, "mask brush MouseUp should enable the undo button while CPU history materialization is still deferred");
            AssertTrue(undoButtonEnabledAfterRelease, "mask brush queued edit should keep undo enabled while the brush tool remains active");
            AssertEqual(0, collectionChangesBeforeRelease);
            AssertTrue(collectionChangesAfterRelease > collectionChangesBeforeRelease, "mask brush should materialize an object-review row after the quiet idle window");
            AssertTrue(queueChangesAfterRelease > queueChangesBeforeRelease, "mask brush should refresh image-queue save state after the quiet idle window");
            AssertEqual(objectRowsBeforeDrag, objectRowsAfterRelease);
            AssertTrue(selectedObjectAfterRelease, "mask brush should select the materialized row for immediate class edits");
            AssertTrue(releaseActions.Count <= 1, "mask brush quiet-idle materialization should collapse the row update");
            AssertTrue(window.MainCanvasViewModel.MaskOverlays.Count == 1, "mask brush drag should keep one live raster mask overlay");
            AssertTrue(previewVisibleDuringDrag, "mask brush MouseMove should render through the FBO stroke preview while dragging");
            AssertTrue(previewVisibleImmediatelyAfterRelease, "mask brush MouseUp should keep the FBO preview for the first fast post-release paint");
            AssertTrue(dirtyImmediatelyAfterRelease, "mask brush MouseUp should immediately mark pending FBO edits as needing save");
            AssertTrue(saveStatusNeedsSaveImmediatelyAfterRelease, "mask brush MouseUp should show save-needed state before delayed CPU materialization");
            AssertTrue(previewVisibleAfterRelease, "mask brush MouseUp should keep the FBO stroke preview while the brush/eraser tool remains active");
            AssertTrue(learningTabSelectedAfterRelease, "mask brush MouseUp should keep the active guide/tool tab selected during rapid painting");
            AssertEqual(2, undoCountAfterSecondRelease);
            AssertTrue(secondUndoButtonEnabledImmediatelyAfterRelease, "existing mask brush MouseUp should enable undo while CPU history materialization is still deferred");
            AssertTrue(secondUndoButtonEnabledAfterRelease, "existing mask brush queued edit should keep undo enabled while the brush tool remains active");
            AssertEqual(2, undoCountAfterToolEnd);
            AssertEqual(1, manualSegments.Count);
            AssertEqual(0, secondCollectionChangesBeforeRelease - collectionChangesAfterRelease);
            AssertTrue(secondCollectionChangesAfterRelease > secondCollectionChangesBeforeRelease, "existing mask brush should refresh the materialized row after the quiet idle window");
            AssertTrue(secondQueueChangesAfterRelease > secondQueueChangesBeforeRelease, "existing mask brush should refresh image-queue save state after the quiet idle window");
            AssertTrue(selectedObjectAfterSecondRelease, "existing mask brush should keep the materialized row selected for class edits");
            AssertTrue(secondReleaseActions.Count <= 1, "existing mask brush quiet-idle materialization should collapse the row update");
            AssertEqual(secondCollectionChangesAfterRelease, collectionChangesAfterToolEnd);
            AssertEqual(secondQueueChangesAfterRelease, queueChangesAfterToolEnd);
            AssertEqual(0, toolEndActions.Count);
            AssertTrue(!toolEndActions.Contains(NotifyCollectionChangedAction.Reset), "mask brush tool-end materialization should keep object-review incremental");
            AssertTrue(objectRowsAfterToolEnd > 0, "mask brush should refresh object review when leaving the paint tool");
            AssertTrue(secondPreviewVisibleDuringDrag, "existing mask brush MouseMove should render through the FBO stroke preview while dragging");
            AssertTrue(secondPreviewVisibleImmediatelyAfterRelease, "existing mask brush MouseUp should keep the FBO preview for the first fast post-release paint");
            AssertTrue(secondPreviewVisibleAfterRelease, "existing mask brush MouseUp should keep the FBO stroke preview while the brush/eraser tool remains active");
            AssertTrue(!previewVisibleAfterToolEnd, "mask stroke preview should clear when leaving mask annotation mode");
            AssertTrue(learningTabSelectedAfterSecondRelease, "existing mask brush MouseUp should not force a right-panel tab switch");
            AssertTrue(modelStatusPropertyChanged <= 40, "mask brush MouseMove should throttle status-bar text updates");
            AssertTrue(stopwatch.Elapsed.TotalMilliseconds < 1_000.0, "mask brush MouseMove should not capture history or rebuild side lists per event");
            AssertTrue(secondMoveStopwatch.Elapsed.TotalMilliseconds < 1_000.0, "existing mask brush MouseMove should stay on the FBO preview path");
            AssertTrue(releaseStopwatch.Elapsed.TotalMilliseconds < 16.0, "mask brush MouseUp should stay under one 60Hz frame");
            AssertTrue(secondReleaseStopwatch.Elapsed.TotalMilliseconds < 16.0, "existing mask brush MouseUp should stay under one 60Hz frame");
            AssertTrue(toolEndStopwatch.Elapsed.TotalMilliseconds < 50.0, "leaving the mask tool should schedule materialization instead of blocking the selection event");
        }
        finally
        {
            SetPrivateField(window, "activeImageBitmap", null);
            window.Close();
            bitmap.Dispose();
            CGlobal.Inst.Data = previousData;
        }
    }

    private static void AssertMaskStrokePreviewOpacitySourceContract()
    {
        string root = FindRepositoryRoot();
        string canvasSource = File.ReadAllText(Path.Combine(
            root,
            "OpenVisionLab",
            "Library",
            "OpenVisionLab.ImageCanvas",
            "ViewModel",
            "RoiImageCanvasViewModel.cs"));
        string strokePresentationSource = File.ReadAllText(Path.Combine(
            root,
            "0. UI",
            "9) WPF",
            "Views",
            "WpfLabelingShellWindow.AnnotationMaskStrokePresentation.cs"));
        string strokeInputSource = File.ReadAllText(Path.Combine(
            root,
            "0. UI",
            "9) WPF",
            "Views",
            "WpfLabelingShellWindow.AnnotationMaskStrokeInput.cs"));

        AssertTrue(
            canvasSource.Contains("gl.Disable(OpenGL.GL_BLEND);", StringComparison.Ordinal)
                && canvasSource.Contains("The whole preview layer is alpha-blended once when drawn to screen.", StringComparison.Ordinal),
            "mask stroke preview base should copy committed masks into the FBO without double-applying alpha");
        AssertTrue(
            canvasSource.Contains("Math.Min(255, (int)baseColor.A)", StringComparison.Ordinal),
            "mask stroke preview brush stamps should preserve the opacity supplied by the shell");
        AssertTrue(
            strokePresentationSource.Contains("GetMaskStrokePreviewColor", StringComparison.Ordinal)
                && strokePresentationSource.Contains("LearningWorkflowViewModel?.MaskOpacity", StringComparison.Ordinal),
            "mask stroke preview fill color should use the same opacity as committed mask overlays");
        AssertTrue(
            strokeInputSource.Contains("GetMaskStrokePreviewColor(activeAnnotationTool == WpfAnnotationTool.Eraser)", StringComparison.Ordinal),
            "mask stroke input should use fill preview opacity, not cursor-only color, for brush stamps");
    }

    private static void TestWpfSegmentationObjectManipulationVerificationMatrix()
    {
        string shellSource = ReadWpfLabelingShellWindowSources();
        string moveSegmentEditSource = FindMethodSourceBlock(shellSource, "private bool TryMoveSelectedSegmentEdit");
        string completeSegmentEditSource = FindMethodSourceBlock(shellSource, "private void CompleteSelectedSegmentEdit");
        AssertTrue(!string.IsNullOrWhiteSpace(moveSegmentEditSource), "selected segment MouseMove source should be inspectable");
        AssertTrue(!moveSegmentEditSource.Contains("RefreshObjectList()", StringComparison.Ordinal), "selected polygon/mask MouseMove should not rebuild the object-review list per pointer event");
        AssertTrue(!moveSegmentEditSource.Contains("RefreshActiveImageQueueStatus", StringComparison.Ordinal), "selected polygon/mask MouseMove should not recount queue status per pointer event");
        AssertTrue(completeSegmentEditSource.Contains("RefreshObjectList()", StringComparison.Ordinal), "selected polygon/mask MouseUp should refresh object review once after a changed drag");
        AssertTrue(completeSegmentEditSource.Contains("RefreshActiveImageQueueStatus", StringComparison.Ordinal), "selected polygon/mask MouseUp should refresh queue status once after a changed drag");

        Size imageSize = new Size(40, 40);
        var defectClass = new CClassItem { Text = "Defect", DrawColor = Color.DeepSkyBlue };

        var polygon = new LabelingSegmentationObject(
            new[]
            {
                new Point(5, 5),
                new Point(20, 5),
                new Point(20, 20),
                new Point(5, 20)
            },
            defectClass)
        {
            ClassName = "Defect"
        };

        AssertTrue(WpfPolygonAnnotationService.IsPointInsidePolygon(polygon, new Point(10, 10)), "polygon interior hit-test should accept points inside the polygon body");
        AssertTrue(WpfPolygonAnnotationService.TryMovePolygon(polygon, 7, -3, imageSize, out Rectangle polygonMoveBounds), "polygon body drag should move the entire polygon");
        AssertEqual(new Rectangle(12, 2, 16, 16), polygon.Bounds);
        AssertEqual(new Point(12, 2), polygon.Points[0]);
        AssertTrue(polygonMoveBounds.Contains(new Point(5, 5)), "polygon move dirty bounds should include old geometry");
        AssertTrue(polygonMoveBounds.Contains(new Point(27, 17)), "polygon move dirty bounds should include new geometry");

        AssertTrue(WpfPolygonAnnotationService.TryMovePolygon(polygon, -100, -100, imageSize, out _), "polygon body drag should clamp at image bounds");
        AssertEqual(new Rectangle(0, 0, 16, 16), polygon.Bounds);
        AssertEqual(new Point(0, 0), polygon.Points[0]);

        AssertTrue(WpfPolygonAnnotationService.TryMovePoint(polygon, 2, new Point(39, 39), imageSize, out Rectangle pointMoveBounds), "polygon point resize/edit should move one vertex");
        AssertEqual(new Point(39, 39), polygon.Points[2]);
        AssertTrue(pointMoveBounds.Contains(new Point(39, 39)), "polygon point move dirty bounds should include the moved vertex");

        var maskService = new WpfMaskAnnotationService();
        var segments = new List<LabelingSegmentationObject>();
        AssertTrue(maskService.Paint(
            segments,
            new[] { new Point(10, 10), new Point(16, 10) },
            3,
            imageSize,
            defectClass,
            out LabelingSegmentationObject mask,
            out Rectangle paintBounds), "mask matrix should create a raster mask");
        AssertEqual(1, segments.Count);
        AssertTrue(mask.IsRasterMask, "mask matrix should create a raster segment");
        AssertTrue(paintBounds.Contains(new Point(10, 10)), "mask paint dirty bounds should include brush center");

        Rectangle maskBoundsBeforeMove = mask.Bounds;
        AssertTrue(maskService.TryMoveRasterMask(mask, 4, 5, imageSize, out Rectangle maskMoveBounds), "mask matrix should move a selected raster mask");
        AssertEqual(new Rectangle(maskBoundsBeforeMove.X + 4, maskBoundsBeforeMove.Y + 5, maskBoundsBeforeMove.Width, maskBoundsBeforeMove.Height), mask.Bounds);
        AssertTrue(maskMoveBounds.Contains(maskBoundsBeforeMove.Location), "mask move dirty bounds should include the old mask area");

        AssertTrue(maskService.TryMoveRasterMask(mask, -100, -100, imageSize, out _), "mask matrix should clamp movement at image bounds");
        AssertEqual(0, mask.Bounds.Left);
        AssertEqual(0, mask.Bounds.Top);
        AssertEqual(maskBoundsBeforeMove.Width, mask.Bounds.Width);
        AssertEqual(maskBoundsBeforeMove.Height, mask.Bounds.Height);

        Point maskCenter = new Point(mask.Bounds.Left + (mask.Bounds.Width / 2), mask.Bounds.Top + (mask.Bounds.Height / 2));
        AssertTrue(maskService.Erase(segments, new[] { maskCenter }, 40, imageSize, out _), "mask matrix should erase raster mask pixels");
        AssertEqual(0, segments.Count);
    }

    private static void TestWpfSegmentationObjectManipulationUpdatesShellState()
    {
        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        CData previousData = CGlobal.Inst.Data;
        var data = new CData();
        data.LastSelectImageName = "wpf-segmentation-object-shell";
        data.ProjectSettings.DatasetPurpose = LabelingDatasetPurpose.Segmentation;
        data.ClassNamedList.Add(new CClassItem { Text = "Defect", DrawColor = Color.DeepSkyBlue });
        CGlobal.Inst.Data = data;

        WpfLabelingShellWindow window = new WpfLabelingShellWindow();
        Bitmap bitmap = new Bitmap(50, 50);
        try
        {
            SetPrivateField(window, "activeImageSize", new Size(50, 50));
            SetPrivateField(window, "activeImageBitmap", bitmap);
            SetPrivateField(window.MainCanvasViewModel, "_imageSize", new Size(50, 50));

            var manualSegments = GetPrivateField<List<LabelingSegmentationObject>>(window, "manualSegments");
            var polygon = new LabelingSegmentationObject(
                new[]
                {
                    new Point(10, 10),
                    new Point(25, 10),
                    new Point(25, 25),
                    new Point(10, 25)
                },
                data.ClassNamedList[0])
            {
                ClassName = "Defect"
            };
            manualSegments.Add(polygon);
            InvokePrivateResult<object>(window, "RefreshObjectList");
            InvokePrivateResult<object>(window, "RefreshPolygonOverlays");

            var objectReviewPanel = (WpfObjectReviewPanel)window.FindName("ObjectReviewPanelControl");
            objectReviewPanel.ViewModel.SelectedObject = objectReviewPanel.ViewModel.Objects.First(item => item.DisplayText.Contains("\uD3F4\uB9AC\uACE4", StringComparison.Ordinal));
            SetPrivateField(window, "activeAnnotationTool", WpfAnnotationTool.Select);
            window.MainCanvasViewModel.IsImagePointInputMode = true;
            var polygonObjectReviewActions = new List<NotifyCollectionChangedAction>();
            NotifyCollectionChangedEventHandler polygonObjectReviewChanged = (_, args) => polygonObjectReviewActions.Add(args.Action);
            ((INotifyCollectionChanged)objectReviewPanel.ViewModel.Objects).CollectionChanged += polygonObjectReviewChanged;
            try
            {
                InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointClicked", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(16, 16), PointF.Empty));
                InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointMoved", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(18, 17), PointF.Empty));
                InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointMoved", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(20, 19), PointF.Empty));
                InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointMoved", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(21, 21), PointF.Empty));
                AssertEqual(0, polygonObjectReviewActions.Count);
                InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointReleased", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(21, 21), PointF.Empty));
            }
            finally
            {
                ((INotifyCollectionChanged)objectReviewPanel.ViewModel.Objects).CollectionChanged -= polygonObjectReviewChanged;
            }

            AssertEqual(1, polygonObjectReviewActions.Count);
            AssertEqual(NotifyCollectionChangedAction.Reset, polygonObjectReviewActions[0]);
            AssertEqual(new Rectangle(15, 15, 16, 16), polygon.Bounds);
            AssertEqual(new Point(15, 15), polygon.Points[0]);
            Dictionary<string, List<LabelingSegmentationObject>> afterPolygonMove = InvokePrivateResult<Dictionary<string, List<LabelingSegmentationObject>>>(window, "BuildAnnotationSegments");
            AssertEqual(new Rectangle(15, 15, 16, 16), afterPolygonMove["Defect"].First(segment => !segment.IsRasterMask).Bounds);

            InvokePrivateResult<object>(window, "BeginMaskAnnotationMode", WpfAnnotationTool.Brush);
            InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointClicked", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(30, 30), PointF.Empty));
            InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointMoved", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(34, 30), PointF.Empty));
            InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointReleased", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(34, 30), PointF.Empty));
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(430));
            System.Windows.Threading.Dispatcher.CurrentDispatcher.Invoke(
                new Action(() => { }),
                System.Windows.Threading.DispatcherPriority.ApplicationIdle);
            AssertTrue(manualSegments.Any(segment => segment.IsRasterMask), "mask stroke should materialize after the quiet idle window while the brush tool stays active");
            AssertTrue(objectReviewPanel.ViewModel.Objects.Any(item => item.DisplayText.Contains("\uB9C8\uC2A4\uD06C", StringComparison.Ordinal)), "object review should show the materialized mask row before leaving the brush tool");
            InvokePrivateResult<object>(window, "EndMaskAnnotationMode");
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(260));
            System.Windows.Threading.Dispatcher.CurrentDispatcher.Invoke(
                new Action(() => { }),
                System.Windows.Threading.DispatcherPriority.ApplicationIdle);
            LabelingSegmentationObject mask = manualSegments.First(segment => segment.IsRasterMask);
            Rectangle maskBoundsBeforeMove = mask.Bounds;

            objectReviewPanel.ViewModel.SelectedObject = objectReviewPanel.ViewModel.Objects.First(item => item.DisplayText.Contains("\uB9C8\uC2A4\uD06C", StringComparison.Ordinal));
            SetPrivateField(window, "activeAnnotationTool", WpfAnnotationTool.Select);
            window.MainCanvasViewModel.IsImagePointInputMode = true;
            InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointClicked", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(32, 30), PointF.Empty));
            InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointMoved", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(35, 32), PointF.Empty));
            InvokePrivateResult<object>(window, "MainCanvasViewModel_ImagePointReleased", window.MainCanvasViewModel, new CanvasImagePointEventArgs(CanvasPointerButton.Left, 1, 0, 0, new Point(35, 32), PointF.Empty));
            AssertEqual(new Rectangle(maskBoundsBeforeMove.X + 3, maskBoundsBeforeMove.Y + 2, maskBoundsBeforeMove.Width, maskBoundsBeforeMove.Height), mask.Bounds);
            Dictionary<string, List<LabelingSegmentationObject>> afterMaskMove = InvokePrivateResult<Dictionary<string, List<LabelingSegmentationObject>>>(window, "BuildAnnotationSegments");
            AssertTrue(afterMaskMove["Defect"].Any(segment => segment.IsRasterMask && segment.Bounds == mask.Bounds), "moved mask should be exported with the edited geometry");
            AssertTrue(window.MainCanvasViewModel.MaskOverlays.Any(overlay => overlay.IsSelected && overlay.Bounds == mask.Bounds), "moved mask should remain selected on the OpenGL overlay");
        }
        finally
        {
            SetPrivateField(window, "activeImageBitmap", null);
            window.Close();
            bitmap.Dispose();
            CGlobal.Inst.Data = previousData;
        }
    }

    private static void TestWpfAnnotationHistoryService()
    {
        var rois = new List<Rectangle> { new Rectangle(1, 2, 3, 4) };
        var classNames = new List<string> { "OK" };
        var shapeKinds = new List<CanvasRoiShapeKind> { CanvasRoiShapeKind.Ellipse };
        var segment = new LabelingSegmentationObject(new[] { new Point(1, 1), new Point(5, 1), new Point(5, 5) }, new CClassItem { Text = "Defect", DrawColor = Color.Red })
        {
            MaskData = new byte[16],
            MaskSize = new Size(4, 4),
            MaskBounds = new Rectangle(1, 1, 2, 2)
        };
        segment.MaskData[5] = 1;
        var pending = new List<YoloWorkerSmokeCandidate>
        {
            new YoloWorkerSmokeCandidate { Index = 1, ClassName = "NG", Confidence = 0.9, X = 7, Y = 8, Width = 9, Height = 10 }
        };
        var confirmed = new List<YoloWorkerSmokeCandidate>
        {
            new YoloWorkerSmokeCandidate { Index = 2, ClassName = "OK", Confidence = 0.8, X = 11, Y = 12, Width = 13, Height = 14 }
        };

        WpfAnnotationHistorySnapshot snapshot = WpfAnnotationHistoryService.Capture(
            "test",
            rois,
            classNames,
            shapeKinds,
            new[] { segment },
            pending,
            confirmed);

        rois.Clear();
        classNames[0] = "Changed";
        shapeKinds[0] = CanvasRoiShapeKind.Rectangle;
        segment.MaskData[5] = 0;
        pending[0].ClassName = "Changed";

        var restoredRois = new List<Rectangle>();
        var restoredClassNames = new List<string>();
        var restoredShapeKinds = new List<CanvasRoiShapeKind>();
        var restoredOverlayIds = new List<string> { "old" };
        var restoredSegments = new List<LabelingSegmentationObject>();
        var restoredPending = new List<YoloWorkerSmokeCandidate>();
        var restoredConfirmed = new List<YoloWorkerSmokeCandidate>();

        WpfAnnotationHistoryService.Restore(
            snapshot,
            restoredRois,
            restoredClassNames,
            restoredShapeKinds,
            restoredOverlayIds,
            restoredSegments,
            restoredPending,
            restoredConfirmed);

        AssertEqual(new Rectangle(1, 2, 3, 4), restoredRois[0]);
        AssertEqual("OK", restoredClassNames[0]);
        AssertEqual(CanvasRoiShapeKind.Ellipse, restoredShapeKinds[0]);
        AssertEqual(0, restoredOverlayIds.Count);
        AssertTrue(restoredSegments[0].IsRasterMask, "history should restore raster mask metadata");
        AssertEqual((byte)1, restoredSegments[0].MaskData[5]);
        AssertTrue(!ReferenceEquals(segment, restoredSegments[0]), "segment snapshot should be a deep copy");
        AssertEqual("NG", restoredPending[0].ClassName);
        AssertEqual("OK", restoredConfirmed[0].ClassName);
        AssertTrue(!ReferenceEquals(pending[0], restoredPending[0]), "candidate snapshot should be a deep copy");

        var roiOnlySourceRois = new List<Rectangle> { new Rectangle(9, 8, 7, 6) };
        var roiOnlySourceClassNames = new List<string> { "ROI" };
        var roiOnlySourceShapeKinds = new List<CanvasRoiShapeKind> { CanvasRoiShapeKind.Rectangle };
        WpfAnnotationHistorySnapshot roiOnlySnapshot = WpfAnnotationHistoryService.CaptureManualRoiList(
            "delete roi",
            roiOnlySourceRois,
            roiOnlySourceClassNames,
            roiOnlySourceShapeKinds);
        var preservedSegment = new LabelingSegmentationObject
        {
            ClassName = "KeepMask",
            MaskData = new byte[] { 7 },
            MaskSize = new Size(1, 1),
            MaskBounds = new Rectangle(0, 0, 1, 1)
        };
        var preservedPending = new YoloWorkerSmokeCandidate { ClassName = "KeepPending" };
        var preservedConfirmed = new YoloWorkerSmokeCandidate { ClassName = "KeepConfirmed" };
        var roiOnlyRois = new List<Rectangle>();
        var roiOnlyClassNames = new List<string>();
        var roiOnlyShapeKinds = new List<CanvasRoiShapeKind>();
        var roiOnlyOverlayIds = new List<string> { "old-overlay" };
        var roiOnlySegments = new List<LabelingSegmentationObject> { preservedSegment };
        var roiOnlyPending = new List<YoloWorkerSmokeCandidate> { preservedPending };
        var roiOnlyConfirmed = new List<YoloWorkerSmokeCandidate> { preservedConfirmed };

        WpfAnnotationHistoryService.Restore(
            roiOnlySnapshot,
            roiOnlyRois,
            roiOnlyClassNames,
            roiOnlyShapeKinds,
            roiOnlyOverlayIds,
            roiOnlySegments,
            roiOnlyPending,
            roiOnlyConfirmed);

        AssertEqual(new Rectangle(9, 8, 7, 6), roiOnlyRois[0]);
        AssertEqual("ROI", roiOnlyClassNames[0]);
        AssertEqual(CanvasRoiShapeKind.Rectangle, roiOnlyShapeKinds[0]);
        AssertEqual(0, roiOnlyOverlayIds.Count);
        AssertTrue(ReferenceEquals(preservedSegment, roiOnlySegments[0]), "ROI-only history should not replace unrelated mask segments");
        AssertEqual((byte)7, roiOnlySegments[0].MaskData[0]);
        AssertTrue(ReferenceEquals(preservedPending, roiOnlyPending[0]), "ROI-only history should not replace unrelated pending candidates");
        AssertTrue(ReferenceEquals(preservedConfirmed, roiOnlyConfirmed[0]), "ROI-only history should not replace unrelated confirmed candidates");
    }

    private static void TestWpfShellUndoRedoRestoresAnnotationState()
    {
        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        CData previousData = CGlobal.Inst.Data;
        string root = CreateTempRoot();
        var data = new CData();
        data.LastSelectImageName = "wpf-undo-redo";
        data.ClassNamedList.Add(new CClassItem { Text = "Defect", DrawColor = Color.LimeGreen });
        data.ConfigureOutputRoot(root);
        data.ProjectSettings.DatasetPurpose = LabelingDatasetPurpose.ObjectDetection;
        data.ProjectSettings.YoloDataset.ValidationPercent = 0;
        CGlobal.Inst.Data = data;

        WpfLabelingShellWindow window = new WpfLabelingShellWindow();
        Bitmap bitmap = new Bitmap(40, 40);
        try
        {
            var learningPanel = (WpfLearningWorkflowPanel)window.FindName("LearningWorkflowPanelControl");
            WpfAnnotationToolItem undoTool = learningPanel.ViewModel.AnnotationTools.First(item => item.Tool == WpfAnnotationTool.Undo);
            WpfAnnotationToolItem redoTool = learningPanel.ViewModel.AnnotationTools.First(item => item.Tool == WpfAnnotationTool.Redo);
            var statusPanel = (WpfStatusBarPanel)window.FindName("StatusBarPanelControl");
            var saveStatusText = (System.Windows.Controls.TextBlock)window.FindName("AnnotationSaveStatusText");
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(20));
            AssertTrue(!statusPanel.ViewModel.IsAnnotationDirty, "annotation save state should start clean before any WPF edit");
            AssertTrue(!undoTool.IsActionEnabled, "undo should start disabled before any WPF edit");
            AssertTrue(!redoTool.IsActionEnabled, "redo should start disabled before an undo action");
            AssertEqual("\uC5C6\uC74C", undoTool.DisplayCapabilityText);
