        AssertTrue(tcpSmokeScript.Contains("[int]$ImgSize = 320", StringComparison.Ordinal), "YOLO TCP smoke should use the fast default inference image size");
        AssertTrue(verifyScript.Contains("Expand-PathTokens", StringComparison.Ordinal), "first-run verifier should resolve runtime config path tokens");
    }

    private static void TestPythonModelSettingsValidator()
    {
        string root = CreateTempRoot();
        try
        {
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            File.WriteAllText(scriptPath, "print('ready')");

            var missingRuntimeSettings = new PythonModelSettings
            {
                ProjectRootPath = Path.Combine(root, "missing-yolo"),
                ClientScriptPath = Path.Combine(root, "missing-yolo", "labelling_tcp_client.py"),
                WeightsPath = Path.Combine(root, "missing-yolo", "best.pt")
            };
            PythonModelRuntimeState missingRuntimeState = PythonModelSettingsValidator.GetRuntimeState(missingRuntimeSettings);
            AssertEqual(PythonModelRuntimeStateKind.NotInstalled, missingRuntimeState.State);
            AssertTrue(!missingRuntimeState.CanRunTraining, "missing model runtime should block training commands");
            AssertTrue(!missingRuntimeState.CanRunInference, "missing model runtime should block current inspection commands");
            AssertTrue(missingRuntimeState.SummaryText.Contains("\uB77C\uBCA8\uB9C1 \uAC00\uB2A5", StringComparison.Ordinal), "missing model runtime should still present labeling as available");

            var settings = new PythonModelSettings
            {
                ProjectRootPath = root,
                ClientScriptPath = scriptPath,
                WeightsPath = Path.Combine(root, "missing.pt")
            };

            PythonModelValidationResult trainingValidation = PythonModelSettingsValidator.Validate(settings, requireWeights: false);
            AssertTrue(trainingValidation.IsValid, trainingValidation.Summary);
            AssertTrue(trainingValidation.Warnings.Any(line => line.Contains("YOLO \uAC00\uC911\uCE58 \uD30C\uC77C", StringComparison.Ordinal)), "missing weights should be a training warning");

            PythonModelValidationResult detectionValidation = PythonModelSettingsValidator.Validate(settings, requireWeights: true);
            AssertTrue(!detectionValidation.IsValid, "missing weights should block detection");
            AssertTrue(detectionValidation.Errors.Any(line => line.Contains("YOLO \uAC00\uC911\uCE58 \uD30C\uC77C", StringComparison.Ordinal)), "missing weights error was not reported");

            settings.MinimumDetectionConfidence = 1.2F;
            PythonModelValidationResult confidenceValidation = PythonModelSettingsValidator.Validate(settings, requireWeights: false);
            AssertTrue(!confidenceValidation.IsValid, "out-of-range confidence should be invalid");
            AssertTrue(confidenceValidation.Errors.Any(line => line.Contains("\uC2E0\uB8B0\uB3C4", StringComparison.Ordinal)), "confidence error was not reported");

            settings.MinimumDetectionConfidence = 0.25F;
            settings.DetectionTimeoutSeconds = 0;
            PythonModelValidationResult timeoutValidation = PythonModelSettingsValidator.Validate(settings, requireWeights: false);
            AssertTrue(!timeoutValidation.IsValid, "out-of-range detection timeout should be invalid");
            AssertTrue(timeoutValidation.Errors.Any(line => line.Contains("\uAC80\uC0AC \uC2DC\uAC04 \uC81C\uD55C", StringComparison.Ordinal)), "detection timeout error was not reported");

            settings.DetectionTimeoutSeconds = 30;
            settings.MaximumDetectionCandidates = 0;
            PythonModelValidationResult maximumCandidatesValidation = PythonModelSettingsValidator.Validate(settings, requireWeights: false);
            AssertTrue(!maximumCandidatesValidation.IsValid, "out-of-range maximum candidates should be invalid");
            AssertTrue(maximumCandidatesValidation.Errors.Any(line => line.Contains("\uCD5C\uB300 \uD6C4\uBCF4 \uC218", StringComparison.Ordinal)), "maximum candidates error was not reported");

            settings.MaximumDetectionCandidates = 20;
            settings.InferenceImageSize = 32;
            PythonModelValidationResult imageSizeValidation = PythonModelSettingsValidator.Validate(settings, requireWeights: false);
            AssertTrue(!imageSizeValidation.IsValid, "out-of-range inference image size should be invalid");
            AssertTrue(imageSizeValidation.Errors.Any(line => line.Contains("\uCD94\uB860 \uC774\uBBF8\uC9C0 \uD06C\uAE30", StringComparison.Ordinal)), "inference image size error was not reported");

            string cGlobalSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "1. Core", "ApplicationState", "CGlobal.cs"));
            int ensureStartIndex = cGlobalSource.IndexOf("if (autoStartClient && !EnsurePythonModelClientStarted())", StringComparison.Ordinal);
            int connectedReturnIndex = cGlobalSource.IndexOf("if (status.IsClientConnected && connectedAfterClientStart)", StringComparison.Ordinal);
            AssertTrue(ensureStartIndex >= 0, "client readiness should validate the current Python process settings before using an existing connection");
            AssertTrue(connectedReturnIndex > ensureStartIndex, "client readiness should not return an existing TCP connection before checking the current weights start signature");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestPythonModelRuntimeProfiles()
    {
        string root = CreateTempRoot();
        try
        {
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            File.WriteAllText(scriptPath, "print('ready')");
            string weightsPath = Path.Combine(root, "best.pt");
            File.WriteAllText(weightsPath, "weights");

            var settings = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYoloV5,
                ProjectRootPath = root,
                ClientScriptPath = scriptPath,
                WeightsPath = weightsPath,
                ImageRootPath = root
            };

            IReadOnlyList<PythonModelRuntimeProfile> profiles = PythonModelRuntimeProfileService.BuildProfiles(settings);
            AssertEqual(
                string.Join("|", PythonModelSettings.GetSupportedModelEngines()),
                string.Join("|", profiles.Select(profile => profile.Engine)));
            PythonModelRuntimeProfile selectedYoloV5 = profiles.First(item => item.Engine == PythonModelSettings.EngineYoloV5);
            AssertTrue(selectedYoloV5.IsSelected, "YOLOv5 runtime profile should be selected when the settings engine is YOLOv5");
            AssertTrue(selectedYoloV5.IsRuntimeConnected, "selected YOLOv5 runtime profile should report a connected runtime when paths exist");
            AssertTrue(selectedYoloV5.CanTrain, "connected YOLOv5 runtime profile should allow training");
            AssertTrue(selectedYoloV5.CanInspect, "connected YOLOv5 runtime profile should allow current inspection when weights exist");
            AssertTrue(selectedYoloV5.CapabilityText.Contains("\uD559\uC2B5", StringComparison.Ordinal)
                && selectedYoloV5.CapabilityText.Contains("\uD604\uC7AC \uAC80\uC0AC", StringComparison.Ordinal),
                "YOLOv5 runtime profile should show its training/current-inspection support scope");
            AssertTrue(!string.IsNullOrWhiteSpace(selectedYoloV5.PrimaryActionText), "selected YOLOv5 runtime profile should expose a primary action label");

            PythonModelRuntimeProfile yolo11 = profiles.First(item => item.Engine == PythonModelSettings.EngineYolo11);
            AssertTrue(!yolo11.IsSelected, "YOLO11 runtime profile should not be selected while YOLOv5 is active");
            AssertTrue(yolo11.RuntimeFamilyText.Contains("Ultralytics", StringComparison.Ordinal), "YOLO11 runtime profile should identify the Ultralytics runtime family");
            AssertTrue(yolo11.CapabilityText.Contains("\uD604\uC7AC \uAC80\uC0AC", StringComparison.Ordinal)
                && yolo11.CapabilityText.Contains("worker", StringComparison.Ordinal),
                "YOLO11 runtime profile should explain inspection-first support and training worker requirements");
            AssertTrue(yolo11.NextActionText.Contains("Ultralytics", StringComparison.Ordinal), "YOLO11 runtime profile should direct the operator to install or connect Ultralytics");
            AssertTrue(yolo11.PrimaryActionText.Contains("\uC5F0\uACB0", StringComparison.Ordinal), "unselected Ultralytics runtime profiles should expose a connect action");

            settings.ModelEngine = PythonModelSettings.EngineYolo11;
            profiles = PythonModelRuntimeProfileService.BuildProfiles(settings);
            PythonModelRuntimeProfile selectedYolo11 = profiles.First(item => item.Engine == PythonModelSettings.EngineYolo11);
            AssertTrue(selectedYolo11.IsSelected, "YOLO11 runtime profile should become selected when the settings engine changes");
            AssertTrue(!selectedYolo11.CanTrain, "YOLO11 profile should not claim training is executable until the Ultralytics worker adapter is connected");
            AssertTrue(!selectedYolo11.CanInspect, "YOLO11 profile should not claim inspection is executable until the Ultralytics worker adapter is connected");
            AssertTrue(selectedYolo11.CapabilityText.Contains("\uC5F0\uACB0 \uD6C4 \uD655\uC778", StringComparison.Ordinal), "selected disconnected YOLO11 profile should not claim model execution support before connection");
            AssertTrue(selectedYolo11.NextActionText.Contains("YOLO11", StringComparison.Ordinal), "selected YOLO11 profile should explain the required execution connection");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestPythonModelRuntimeSelfTest()
    {
        string root = CreateTempRoot();
        try
        {
            string modelRoot = Path.Combine(root, "yolov5Master");
            Directory.CreateDirectory(modelRoot);
            string venvScripts = Path.Combine(root, ".venv", "Scripts");
            Directory.CreateDirectory(venvScripts);
            string pythonPath = Path.Combine(venvScripts, "python.exe");
            File.WriteAllText(pythonPath, "python");
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            File.WriteAllText(scriptPath, "print('ready')");
            string weightsPath = Path.Combine(root, "best.pt");
            File.WriteAllText(weightsPath, "weights");
            string imageRoot = Path.Combine(root, "images");
            Directory.CreateDirectory(imageRoot);

            var settings = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYoloV5,
                ProjectRootPath = root,
                ClientScriptPath = scriptPath,
                WeightsPath = weightsPath,
                ImageRootPath = imageRoot
            };

            PythonModelRuntimeSelfTestReport readyReport = PythonModelRuntimeSelfTestService.BuildReport(settings);
            AssertTrue(readyReport.CanTrain, "self-test should report training available when project, python, and client script exist");
            AssertTrue(readyReport.CanInspect, "self-test should report inspection available when weights exist");
            AssertTrue(readyReport.Items.Any(item => item.LabelText.Contains("Python", StringComparison.Ordinal) && item.IsPassed), "self-test should include the resolved Python executable check");
            AssertTrue(readyReport.Items.Any(item => item.LabelText.Contains("\uBAA8\uB378 \uB8E8\uD2B8", StringComparison.Ordinal) && item.IsPassed), "YOLOv5 self-test should include the model-root folder check");
            AssertReadableRuntimeSelfTestReport(readyReport);

            File.Delete(weightsPath);
            PythonModelRuntimeSelfTestReport missingWeightsReport = PythonModelRuntimeSelfTestService.BuildReport(settings);
            AssertTrue(missingWeightsReport.CanTrain, "missing weights should not block training");
            AssertTrue(!missingWeightsReport.CanInspect, "missing weights should block current inspection");
            PythonModelRuntimeSelfTestItem missingWeightsItem = missingWeightsReport.Items.FirstOrDefault(item => item.LabelText.Contains("\uAC80\uC0AC \uBAA8\uB378", StringComparison.Ordinal));
            AssertTrue(missingWeightsItem != null && missingWeightsItem.IsWarning, "missing weights should be shown as a warning check");
            AssertTrue(missingWeightsItem.DetailText.Contains("\uD559\uC2B5 \uC644\uB8CC", StringComparison.Ordinal)
                && missingWeightsItem.DetailText.Contains(".pt", StringComparison.Ordinal),
                "missing weights self-test detail should explain that the operator can train first or choose a .pt file");
            AssertReadableRuntimeSelfTestReport(missingWeightsReport);

            string sitePackagesPath = Path.Combine(root, ".venv", "Lib", "site-packages");
            string ultralyticsPath = Path.Combine(sitePackagesPath, "ultralytics");
            Directory.CreateDirectory(ultralyticsPath);
            settings.ModelEngine = PythonModelSettings.EngineYolo11;
            PythonModelRuntimeSelfTestReport ultralyticsReport = PythonModelRuntimeSelfTestService.BuildReport(settings);
            AssertTrue(ultralyticsReport.Items.Any(item => item.LabelText.Contains("Ultralytics", StringComparison.Ordinal) && item.IsPassed), "Ultralytics runtime self-test should pass when the package folder exists in venv site-packages");
            AssertTrue(!ultralyticsReport.CanTrain, "Ultralytics package presence alone should not enable YOLO11 training until the worker adapter is connected");
            AssertTrue(!ultralyticsReport.CanInspect, "Ultralytics package presence alone should not enable YOLO11 inspection until the worker adapter is connected");
            AssertTrue(ultralyticsReport.Items.Any(item => item.LabelText.Contains("\uC2E4\uD589 \uC5F0\uACB0", StringComparison.Ordinal) && !item.IsPassed), "YOLO11 self-test should show execution connection as a blocking check");
            AssertReadableRuntimeSelfTestReport(ultralyticsReport);
            PythonModelRuntimeState connectedYolo11TrainingState = PythonModelSettingsValidator.GetRuntimeState(
                settings,
                new[] { "yolo11" },
                new[] { "yolo11" },
                new[] { "yolo11" });
            AssertTrue(connectedYolo11TrainingState.CanRunTraining, "YOLO11 worker capability should enable training when package and runtime paths are present");
            AssertTrue(!connectedYolo11TrainingState.CanRunInference, "YOLO11 inspection should still require an existing weights file");
            File.WriteAllText(weightsPath, "weights");
            PythonModelRuntimeState connectedYolo11ReadyState = PythonModelSettingsValidator.GetRuntimeState(
                settings,
                new[] { "yolo11" },
                new[] { "yolo11" },
                new[] { "yolo11" });
            AssertTrue(connectedYolo11ReadyState.CanRunTraining && connectedYolo11ReadyState.CanRunInference, "YOLO11 worker capability should enable execution only after runtime paths, package, and weights are present");
            PythonModelRuntimeExecutionSummary executionSummary = PythonModelRuntimeExecutionSummaryService.Build(settings);
            AssertTrue(executionSummary.SummaryText.Contains("YOLO11", StringComparison.Ordinal)
                && executionSummary.SummaryText.Contains("adapter=yolo11", StringComparison.Ordinal),
                "runtime execution summary should show the selected YOLO11 adapter key");
            AssertTrue(executionSummary.WorkerText.Contains("python.exe", StringComparison.Ordinal)
                && executionSummary.WorkerText.Contains("labelling_tcp_client.py", StringComparison.Ordinal),
                "runtime execution summary should show the Python worker launch route");
            AssertTrue(executionSummary.TrainingText.Contains("StartTraining(model=yolo11)", StringComparison.Ordinal)
                && executionSummary.TrainingText.Contains("\uC2E4\uD589 \uCC28\uB2E8", StringComparison.Ordinal),
                "runtime execution summary should show the training adapter key but block execution until YOLO11 worker routing exists");
            AssertTrue(executionSummary.InspectionText.Contains("DetectImage(model=yolo11)", StringComparison.Ordinal)
                && executionSummary.InspectionText.Contains("\uC2E4\uD589 \uCC28\uB2E8", StringComparison.Ordinal),
                "runtime execution summary should show the inspection adapter key but block execution until YOLO11 worker routing exists");

            Directory.Delete(ultralyticsPath, recursive: true);
            PythonModelRuntimeSelfTestReport missingUltralyticsReport = PythonModelRuntimeSelfTestService.BuildReport(settings);
            PythonModelRuntimeSelfTestItem missingUltralyticsItem = missingUltralyticsReport.Items.FirstOrDefault(item => item.LabelText.Contains("Ultralytics", StringComparison.Ordinal));
            AssertTrue(missingUltralyticsItem != null && !missingUltralyticsItem.IsPassed && !missingUltralyticsItem.IsWarning, "Ultralytics runtime self-test should require installation when the package folder is missing");
            AssertTrue(missingUltralyticsItem.DetailText.Contains("\uC124\uCE58 \uC2E4\uD589", StringComparison.Ordinal), "missing Ultralytics self-test detail should point to the install action");
            AssertReadableRuntimeSelfTestReport(missingUltralyticsReport);
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void AssertReadableRuntimeSelfTestReport(PythonModelRuntimeSelfTestReport report)
    {
        string combinedText = string.Join(
            " ",
            new[] { report.TitleText, report.SummaryText, report.DetailText }
                .Concat(report.Items.SelectMany(item => new[] { item.LabelText, item.StatusText, item.DetailText })));
        AssertTrue(!ContainsVisibleMojibakeArtifact(combinedText), "runtime self-test report should not expose mojibake artifacts");
    }

    private static void TestPythonModelRuntimeConnection()
    {
        string root = CreateTempRoot();
        try
        {
            string modelRoot = Path.Combine(root, "yolov5Master");
            Directory.CreateDirectory(modelRoot);
            string venvScripts = Path.Combine(root, ".venv", "Scripts");
            Directory.CreateDirectory(venvScripts);
            string pythonPath = Path.Combine(venvScripts, "python.exe");
            File.WriteAllText(pythonPath, "python");
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            File.WriteAllText(scriptPath, "print('ready')");
            string weightsPath = Path.Combine(root, "best.pt");
            File.WriteAllText(weightsPath, "weights");
            string imageRoot = Path.Combine(root, "data", "train", "images");
            Directory.CreateDirectory(imageRoot);
            string selectedWeightsPath = Path.Combine(root, "inspection", "selected-best.pt");
            Directory.CreateDirectory(Path.GetDirectoryName(selectedWeightsPath)!);
            File.WriteAllText(selectedWeightsPath, "selected inspection weights");
            string selectedImageRoot = Path.Combine(root, "recipe-images");
            Directory.CreateDirectory(selectedImageRoot);

            var current = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYolo11,
                ProjectRootPath = Path.Combine(root, "missing"),
                ClientScriptPath = string.Empty,
                WeightsPath = selectedWeightsPath,
                ImageRootPath = selectedImageRoot
            };

            PythonModelRuntimeConnectionResult result = PythonModelRuntimeConnectionService.BuildYoloV5FolderConnection(current, modelRoot);
            AssertEqual(PythonModelSettings.EngineYoloV5, result.Settings.ModelEngine);
            AssertEqual(root, result.Settings.ProjectRootPath);
            AssertEqual(scriptPath, result.Settings.ClientScriptPath);
            AssertEqual(pythonPath, result.Settings.PythonExecutablePath);
            AssertEqual(selectedWeightsPath, result.Settings.WeightsPath);
            AssertEqual(selectedImageRoot, result.Settings.ImageRootPath);
            AssertTrue(!string.Equals(weightsPath, result.Settings.WeightsPath, StringComparison.OrdinalIgnoreCase), "runtime connection must not auto-adopt a model-root best.pt");
            AssertTrue(!string.Equals(imageRoot, result.Settings.ImageRootPath, StringComparison.OrdinalIgnoreCase), "runtime connection must not replace the recipe image root");
            AssertTrue(result.SelfTestReport.CanTrain, "connected YOLOv5 folder should be train-ready");
            AssertTrue(result.SelfTestReport.CanInspect, "connected YOLOv5 folder with best.pt should be inspection-ready");

            string invalidYolo5Root = Path.Combine(root, "invalid-yolov5");
            Directory.CreateDirectory(invalidYolo5Root);
            PythonModelRuntimeConnectionResult invalidYolo5Result = PythonModelRuntimeConnectionService.BuildYoloV5FolderConnection(
                new PythonModelSettings
                {
                    PythonExecutablePath = @"C:\old-yolov8\.venv\Scripts\python.exe",
                    ClientScriptPath = @"C:\old-yolov8\labeling_tcp_client.py",
                    WeightsPath = selectedWeightsPath,
                    ImageRootPath = selectedImageRoot
                },
                invalidYolo5Root);
            AssertEqual(string.Empty, invalidYolo5Result.Settings.PythonExecutablePath);
            AssertEqual(Path.Combine(invalidYolo5Root, "labelling_tcp_client.py"), invalidYolo5Result.Settings.ClientScriptPath);
            AssertTrue(!invalidYolo5Result.SelfTestReport.CanTrain, "an invalid target runtime must fail instead of reusing the previous engine's Python and worker paths");

            string yolo8Root = Path.Combine(root, "yolov8");
            Directory.CreateDirectory(yolo8Root);
            string yolo8VenvScripts = Path.Combine(yolo8Root, ".venv", "Scripts");
            Directory.CreateDirectory(yolo8VenvScripts);
            string yolo8PythonPath = Path.Combine(yolo8VenvScripts, "python.exe");
            File.WriteAllText(yolo8PythonPath, "python");
            Directory.CreateDirectory(Path.Combine(yolo8Root, ".venv", "Lib", "site-packages", "ultralytics"));
            string yolo8ClientPath = Path.Combine(yolo8Root, "labeling_tcp_client.py");
            File.WriteAllText(yolo8ClientPath, "# YOLOv8 DetectImage local worker" + Environment.NewLine + "def handle_train_yolo(): return 'TrainYoloResult'");
            string unrelatedTrainedWeightsPath = Path.Combine(yolo8Root, "runs", "segment", "unrelated-dataset", "weights", "best.pt");
            Directory.CreateDirectory(Path.GetDirectoryName(unrelatedTrainedWeightsPath)!);
            File.WriteAllText(unrelatedTrainedWeightsPath, "unrelated trained weights");
            string yolo8ImageRoot = Path.Combine(yolo8Root, "data", "train", "images");
            Directory.CreateDirectory(yolo8ImageRoot);

            PythonModelRuntimeConnectionResult yolo8Result = PythonModelRuntimeConnectionService.BuildYoloV8FolderConnection(current, yolo8Root);
            AssertEqual(PythonModelSettings.EngineYoloV8, yolo8Result.Settings.ModelEngine);
            AssertEqual(yolo8Root, yolo8Result.Settings.ProjectRootPath);
            AssertEqual(yolo8ClientPath, yolo8Result.Settings.ClientScriptPath);
            AssertEqual(yolo8PythonPath, yolo8Result.Settings.PythonExecutablePath);
            AssertEqual(selectedWeightsPath, yolo8Result.Settings.WeightsPath);
            AssertEqual(selectedImageRoot, yolo8Result.Settings.ImageRootPath);
            AssertTrue(!string.Equals(unrelatedTrainedWeightsPath, yolo8Result.Settings.WeightsPath, StringComparison.OrdinalIgnoreCase), "local YOLOv8 folder connection must not auto-adopt the newest unrelated best.pt");
            AssertTrue(!string.Equals(yolo8ImageRoot, yolo8Result.Settings.ImageRootPath, StringComparison.OrdinalIgnoreCase), "local YOLOv8 folder connection must preserve the recipe image root");
            AssertTrue(yolo8Result.SelfTestReport.CanTrain, "local YOLOv8 folder connection should enable training when the worker implements TrainYolo");
            AssertTrue(yolo8Result.SelfTestReport.CanInspect, "local YOLOv8 folder connection should keep inspection available when the explicitly selected model exists");
            AssertTrue(yolo8Result.DetailText.Contains("\uD604\uC7AC \uC774\uBBF8\uC9C0\uC640 \uAC80\uC0AC \uBAA8\uB378\uC740 \uC720\uC9C0", StringComparison.Ordinal), "YOLOv8 folder connection should explain its image/model preservation boundary");
            AssertTrue(PythonModelRuntimeInstallPlanService.BuildPlan(yolo8Result.Settings).IsAlreadyInstalled, "local YOLOv8 folder connection should check the selected venv for ultralytics");
            string knownYolo8Root = PythonModelRuntimeConnectionService.ResolveKnownLocalRuntimeFolder(Path.Combine(root, "yolov5"), "yolov8");
            AssertEqual(yolo8Root, knownYolo8Root);
            AssertEqual(string.Empty, PythonModelRuntimeConnectionService.ResolveKnownLocalRuntimeFolder(Path.Combine(root, "yolov5"), "missing-runtime"));
            var legacyAnomalySettings = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYoloV5,
                ProjectRootPath = Path.Combine(root, "yolov5"),
                WeightsPath = selectedWeightsPath,
                ImageRootPath = selectedImageRoot
            };
            AssertTrue(
                PythonModelRuntimeConnectionService.TryBuildAnomalyTrainingConnection(
                    legacyAnomalySettings,
                    out PythonModelRuntimeConnectionResult automaticAnomalyConnection),
                "anomaly training should automatically resolve a train-ready sibling YOLOv8 runtime");
            AssertEqual(PythonModelSettings.EngineYoloV8, automaticAnomalyConnection.Settings.ModelEngine);
            AssertEqual(yolo8Root, automaticAnomalyConnection.Settings.ProjectRootPath);
            AssertEqual(selectedWeightsPath, automaticAnomalyConnection.Settings.WeightsPath);
            AssertEqual(selectedImageRoot, automaticAnomalyConnection.Settings.ImageRootPath);
            AssertTrue(
                !PythonModelRuntimeConnectionService.TryBuildAnomalyTrainingConnection(
                    automaticAnomalyConnection.Settings,
                    out _),
                "already compatible anomaly runtimes should not be replaced again");

            PythonModelRuntimeConnectionResult yolo8DetectResult = PythonModelRuntimeConnectionService.BuildYoloV8FolderConnection(
                current,
                yolo8Root,
                LabelingDatasetPurpose.ObjectDetection);
            AssertEqual(selectedWeightsPath, yolo8DetectResult.Settings.WeightsPath);
            AssertEqual(selectedImageRoot, yolo8DetectResult.Settings.ImageRootPath);
            AssertTrue(yolo8DetectResult.DetailText.Contains("object-detection", StringComparison.Ordinal), "object-detection folder connection should describe the selected training task");

            PythonModelRuntimeConnectionResult yolo11FolderResult = PythonModelRuntimeConnectionService.BuildYolo11FolderConnection(
                current,
                yolo8Root,
                LabelingDatasetPurpose.ObjectDetection);
            AssertEqual(PythonModelSettings.EngineYolo11, yolo11FolderResult.Settings.ModelEngine);
            AssertEqual(yolo8Root, yolo11FolderResult.Settings.ProjectRootPath);
            AssertEqual(yolo8PythonPath, yolo11FolderResult.Settings.PythonExecutablePath);
            AssertEqual(PythonModelRuntimeBundledWorkerService.ResolveUltralyticsWorkerScriptPath(), yolo11FolderResult.Settings.ClientScriptPath);
            AssertEqual(selectedWeightsPath, yolo11FolderResult.Settings.WeightsPath);
            AssertEqual(selectedImageRoot, yolo11FolderResult.Settings.ImageRootPath);
            AssertTrue(!yolo11FolderResult.Settings.ClientScriptPath.EndsWith("labeling_tcp_client.py", StringComparison.OrdinalIgnoreCase), "YOLO11 folder connection should use the bundled worker instead of the YOLOv8-only client");
            AssertTrue(yolo11FolderResult.DetailText.Contains("yolo11n.pt", StringComparison.Ordinal), "YOLO11 folder connection should disclose its object-detection start weight without replacing the current inspection model");

            string ultralyticsPath = Path.Combine(root, ".venv", "Lib", "site-packages", "ultralytics");
            Directory.CreateDirectory(ultralyticsPath);
            var ultralyticsCurrent = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYolo11,
                WeightsPath = string.Empty,
                ImageRootPath = selectedImageRoot
            };
            PythonModelRuntimeConnectionResult ultralyticsResult = PythonModelRuntimeConnectionService.BuildUltralyticsPythonConnection(
                ultralyticsCurrent,
                PythonModelSettings.EngineYoloV8,
                pythonPath);
            AssertEqual(PythonModelSettings.EngineYoloV8, ultralyticsResult.Settings.ModelEngine);
            AssertEqual(pythonPath, ultralyticsResult.Settings.PythonExecutablePath);
            string bundledWorkerPath = PythonModelRuntimeBundledWorkerService.ResolveUltralyticsWorkerScriptPath();
            string bundledWorkerRootPath = PythonModelRuntimeBundledWorkerService.ResolveUltralyticsWorkerRootPath();
            AssertTrue(File.Exists(bundledWorkerPath), "Ultralytics runtime connection requires the bundled worker script to exist");
            AssertEqual(bundledWorkerRootPath, ultralyticsResult.Settings.ProjectRootPath);
            AssertEqual(bundledWorkerPath, ultralyticsResult.Settings.ClientScriptPath);
            AssertTrue(!ultralyticsResult.Settings.ClientScriptPath.EndsWith("labelling_tcp_client.py", StringComparison.OrdinalIgnoreCase), "Ultralytics runtime connection should not keep the YOLOv5 TCP client script");
            AssertTrue(ultralyticsResult.SelfTestReport.Items.Any(item => item.LabelText.Contains("Ultralytics", StringComparison.Ordinal) && item.IsPassed), "Ultralytics connection should report installed package when it exists in site-packages");
            AssertTrue(ultralyticsResult.SelfTestReport.Items.Any(item => item.LabelText.Contains("\uC2E4\uD589 \uC2A4\uD06C\uB9BD\uD2B8", StringComparison.Ordinal) && item.IsPassed), "Ultralytics connection should verify the bundled worker script in self-test");
            AssertTrue(!ultralyticsResult.SelfTestReport.CanTrain && !ultralyticsResult.SelfTestReport.CanInspect, "Ultralytics package and worker path should still wait for worker capability before execution is enabled");

            var ultralyticsDetectionReadySettings = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYolo11,
                PythonExecutablePath = pythonPath,
                ProjectRootPath = bundledWorkerRootPath,
                ClientScriptPath = bundledWorkerPath,
                WeightsPath = weightsPath,
                ImageRootPath = imageRoot
            };
            PythonModelRuntimeState ultralyticsDetectionReadyState = PythonModelSettingsValidator.GetRuntimeState(ultralyticsDetectionReadySettings);
            AssertTrue(!ultralyticsDetectionReadyState.CanRunTraining, "bundled Ultralytics worker should not enable training before training support is implemented");
            AssertTrue(ultralyticsDetectionReadyState.CanRunInference, "bundled Ultralytics worker with installed package and weights should enable current inspection before a manual restart is required");
            AssertTrue(ultralyticsDetectionReadyState.SummaryText.Contains("\uD604\uC7AC \uAC80\uC0AC \uAC00\uB2A5", StringComparison.Ordinal), "Ultralytics detection-ready state should tell the operator current inspection is available");
            IReadOnlyList<PythonModelRuntimeProfile> ultralyticsDetectionReadyProfiles = PythonModelRuntimeProfileService.BuildProfiles(ultralyticsDetectionReadySettings);
            PythonModelRuntimeProfile ultralyticsDetectionReadyProfile = ultralyticsDetectionReadyProfiles.First(item => item.Engine == PythonModelSettings.EngineYolo11);
            AssertTrue(ultralyticsDetectionReadyProfile.StatusText.Contains("\uD604\uC7AC \uAC80\uC0AC \uAC00\uB2A5", StringComparison.Ordinal), "Ultralytics profile should show current inspection available when only detection is connected");
            AssertTrue(ultralyticsDetectionReadyProfile.StatusText.Contains("\uD559\uC2B5 \uBBF8\uC9C0\uC6D0", StringComparison.Ordinal), "Ultralytics profile should show training unsupported when the bundled worker is detection-only");
            AssertEqual("\uD655\uC778", ultralyticsDetectionReadyProfile.PrimaryActionText);
            PythonModelRuntimeExecutionSummary ultralyticsDetectionReadyExecution = PythonModelRuntimeExecutionSummaryService.Build(ultralyticsDetectionReadySettings);
            AssertTrue(ultralyticsDetectionReadyExecution.SummaryText.Contains("\uD604\uC7AC \uAC80\uC0AC \uAC00\uB2A5", StringComparison.Ordinal), "Ultralytics execution summary should not collapse detection-ready state into generic settings-check text");
            AssertTrue(ultralyticsDetectionReadyExecution.TrainingText.Contains("\uD559\uC2B5: \uBBF8\uC9C0\uC6D0", StringComparison.Ordinal), "Ultralytics execution route should say training is unsupported when current inspection is available");
            AssertTrue(ultralyticsDetectionReadyExecution.InspectionText.Contains("DetectImage(model=yolo11)", StringComparison.Ordinal), "Ultralytics execution route should still show the selected inspection adapter key");
            PythonModelRuntimeState ultralyticsTrainingReadyState = PythonModelSettingsValidator.GetRuntimeState(
                ultralyticsDetectionReadySettings,
                new[] { "yolo11" },
                new[] { "yolo11" },
                new[] { "yolo11" });
            AssertTrue(ultralyticsTrainingReadyState.CanRunTraining && ultralyticsTrainingReadyState.CanRunInference, "connected Ultralytics training capability should enable YOLO11 training and inspection");
            PythonModelRuntimeExecutionSummary ultralyticsTrainingReadyExecution = PythonModelRuntimeExecutionSummaryService.Build(
                ultralyticsDetectionReadySettings,
                new[] { "yolo11" },
                new[] { "yolo11" },
                new[] { "yolo11" });
            AssertTrue(ultralyticsTrainingReadyExecution.SummaryText.Contains("\uD559\uC2B5/\uAC80\uC0AC \uAC00\uB2A5", StringComparison.Ordinal), "Ultralytics execution summary should use connected worker training capabilities");
            AssertTrue(ultralyticsTrainingReadyExecution.TrainingText.Contains("StartTraining(model=yolo11)", StringComparison.Ordinal), "Ultralytics execution route should keep the selected YOLO11 training adapter key");
            AssertTrue(!ultralyticsTrainingReadyExecution.TrainingText.Contains("\uBBF8\uC9C0\uC6D0", StringComparison.Ordinal)
                && !ultralyticsTrainingReadyExecution.TrainingText.Contains("\uC2E4\uD589 \uCC28\uB2E8", StringComparison.Ordinal),
                "Ultralytics execution route should not show training as unsupported when worker training capability is connected");
            PythonModelRuntimeState excludedYolo11State = PythonModelSettingsValidator.GetRuntimeState(
                ultralyticsDetectionReadySettings,
                new[] { "yolov8" },
                new[] { "yolov8" },
                new[] { "yolov8" });
            AssertTrue(!excludedYolo11State.CanRunTraining && !excludedYolo11State.CanRunInference, "YOLO11 execution should stay blocked when the connected worker reports only YOLOv8 capabilities");
            AssertTrue(excludedYolo11State.DetailText.Contains("did not report adapter capability for yolo11", StringComparison.Ordinal), "YOLO11 blocked state should explain that live worker capabilities exclude the selected adapter");
            PythonModelRuntimeExecutionSummary excludedYolo11Execution = PythonModelRuntimeExecutionSummaryService.Build(
                ultralyticsDetectionReadySettings,
                new[] { "yolov8" },
                new[] { "yolov8" },
                new[] { "yolov8" });
            AssertTrue(excludedYolo11Execution.TrainingText.Contains("\uC2E4\uD589 \uCC28\uB2E8", StringComparison.Ordinal)
                && excludedYolo11Execution.InspectionText.Contains("\uC2E4\uD589 \uCC28\uB2E8", StringComparison.Ordinal),
                "YOLO11 execution summary should stay blocked when live worker capabilities exclude YOLO11");
            IReadOnlyList<PythonModelRuntimeProfile> ultralyticsTrainingReadyProfiles = PythonModelRuntimeProfileService.BuildProfiles(
                ultralyticsDetectionReadySettings,
                new[] { "yolo11" },
                new[] { "yolo11" },
                new[] { "yolo11" });
            PythonModelRuntimeProfile ultralyticsTrainingReadyProfile = ultralyticsTrainingReadyProfiles.First(item => item.Engine == PythonModelSettings.EngineYolo11);
            AssertTrue(ultralyticsTrainingReadyProfile.CanTrain && ultralyticsTrainingReadyProfile.CanInspect, "Ultralytics profile should use connected worker training and inspection capabilities");

            Directory.Delete(ultralyticsPath, recursive: true);
            PythonModelRuntimeConnectionResult missingUltralyticsResult = PythonModelRuntimeConnectionService.BuildUltralyticsPythonConnection(
                ultralyticsCurrent,
                PythonModelSettings.EngineYolo11,
                pythonPath);
            AssertEqual(PythonModelSettings.EngineYolo11, missingUltralyticsResult.Settings.ModelEngine);
            AssertEqual(bundledWorkerRootPath, missingUltralyticsResult.Settings.ProjectRootPath);
            AssertEqual(bundledWorkerPath, missingUltralyticsResult.Settings.ClientScriptPath);
            AssertTrue(missingUltralyticsResult.SummaryText.Contains("\uC124\uCE58", StringComparison.Ordinal), "missing Ultralytics connection should report installation required");
            PythonModelRuntimeInstallPlan missingUltralyticsInstallPlan = PythonModelRuntimeInstallPlanService.BuildPlan(missingUltralyticsResult.Settings);
            AssertTrue(missingUltralyticsInstallPlan.IsVisible, "Ultralytics install plan should be visible for YOLOv8/YOLO11 profiles");
            AssertTrue(missingUltralyticsInstallPlan.RequiresInstallation, "missing Ultralytics install plan should require installation");
            AssertTrue(missingUltralyticsInstallPlan.CommandText.Contains("pip install --upgrade ultralytics", StringComparison.Ordinal), "missing Ultralytics install plan should preview the pip install command without executing it");
            AssertTrue(missingUltralyticsInstallPlan.InstallCommandText.Contains("pip install --upgrade ultralytics", StringComparison.Ordinal), "missing Ultralytics install plan should expose a runnable install command");
            AssertTrue(missingUltralyticsInstallPlan.UninstallCommandText.Contains("pip uninstall -y ultralytics", StringComparison.Ordinal), "Ultralytics install plan should expose a separate uninstall command for test reset");
            AssertTrue(missingUltralyticsInstallPlan.CanRunInstall, "Ultralytics install plan should enable the install action when a venv is connected");
            AssertTrue(missingUltralyticsInstallPlan.CanRunUninstall, "Ultralytics install plan should keep uninstall as a separate test-reset action");
            AssertTrue(missingUltralyticsInstallPlan.TargetEnvironmentText.Contains(".venv", StringComparison.Ordinal), "Ultralytics install plan should identify the target venv");

            Directory.CreateDirectory(ultralyticsPath);
            PythonModelRuntimeInstallPlan installedUltralyticsInstallPlan = PythonModelRuntimeInstallPlanService.BuildPlan(missingUltralyticsResult.Settings);
            AssertTrue(installedUltralyticsInstallPlan.IsAlreadyInstalled, "installed Ultralytics plan should report an existing package");
            AssertTrue(installedUltralyticsInstallPlan.CommandText.Contains("pip show ultralytics", StringComparison.Ordinal), "installed Ultralytics plan should preview a version-check command");
            AssertTrue(installedUltralyticsInstallPlan.UninstallCommandText.Contains("pip uninstall -y ultralytics", StringComparison.Ordinal), "installed Ultralytics plan should still expose uninstall for repeatable setup tests");

            File.Delete(weightsPath);
            var missingInspectionModel = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYoloV5,
                WeightsPath = Path.Combine(root, "missing-inspection-model.pt"),
                ImageRootPath = selectedImageRoot
            };
            PythonModelRuntimeConnectionResult missingWeightsResult = PythonModelRuntimeConnectionService.BuildYoloV5FolderConnection(missingInspectionModel, root);
            AssertTrue(!PythonModelRuntimeInstallPlanService.BuildPlan(missingWeightsResult.Settings).IsVisible, "YOLOv5 folder connection should not show the Ultralytics install plan");
            AssertTrue(missingWeightsResult.SelfTestReport.CanTrain, "missing weights should still allow training after YOLOv5 folder connection");
            AssertTrue(!missingWeightsResult.SelfTestReport.CanInspect, "missing weights should still block current inspection after YOLOv5 folder connection");
            AssertTrue(missingWeightsResult.DetailText.Contains("\uAC80\uC0AC \uBAA8\uB378", StringComparison.Ordinal), "connection result should explain that inspection model selection is still needed");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestPythonUltralyticsBundledWorker()
    {
        string scriptPath = PythonModelRuntimeBundledWorkerService.ResolveUltralyticsWorkerScriptPath();
        AssertTrue(File.Exists(scriptPath), "bundled Ultralytics worker script should exist in the repository or build output");
        AssertTrue(scriptPath.EndsWith(PythonModelRuntimeBundledWorkerService.UltralyticsWorkerRelativePath, StringComparison.OrdinalIgnoreCase), "bundled Ultralytics worker should resolve to the expected relative path");
        AssertTrue(PythonModelRuntimeBundledWorkerService.IsUltralyticsWorkerScriptPath(scriptPath), "bundled Ultralytics worker should be recognized as an Ultralytics worker script");
        AssertTrue(!PythonModelRuntimeBundledWorkerService.IsUltralyticsWorkerScriptPath(Path.Combine(Path.GetDirectoryName(scriptPath) ?? string.Empty, "labelling_tcp_client.py")), "YOLOv5 TCP client script should not be recognized as the Ultralytics worker");

        string rootPath = PythonModelRuntimeBundledWorkerService.ResolveUltralyticsWorkerRootPath();
        AssertEqual(Path.GetDirectoryName(scriptPath) ?? string.Empty, rootPath);
        AssertTrue(Directory.Exists(rootPath), "bundled Ultralytics worker root should exist");

        string source = File.ReadAllText(scriptPath);
        AssertTrue(source.Contains("BASE_SUPPORTED_MODELS = (\"yolov8\",)", StringComparison.Ordinal), "Ultralytics worker should keep YOLOv8 as the baseline adapter");
        AssertTrue(source.Contains("def yolo11_runtime_available()", StringComparison.Ordinal)
            && source.Contains("C3k2", StringComparison.Ordinal),
            "Ultralytics worker should advertise YOLO11 only when the local package supports YOLO11 modules");
        AssertTrue(source.Contains("def ultralytics_version()", StringComparison.Ordinal)
            && source.Contains("\"ultralyticsVersion\"", StringComparison.Ordinal),
            "Ultralytics worker should report the installed package version in health-check environment data");
        AssertTrue(source.Contains("\"runtimeWarnings\"", StringComparison.Ordinal)
            && source.Contains("YOLO11 disabled", StringComparison.Ordinal),
            "Ultralytics worker should report a capability warning when YOLO11 is disabled by the selected runtime");
        AssertTrue(source.Contains("def runtime_training_models()", StringComparison.Ordinal), "Ultralytics worker should compute training adapters from runtime capabilities");
        AssertTrue(source.Contains("def runtime_detection_models()", StringComparison.Ordinal), "Ultralytics worker should compute detection adapters from runtime capabilities");
        AssertTrue(source.Contains("def runtime_segmentation_models()", StringComparison.Ordinal), "Ultralytics worker should compute segmentation adapters from runtime capabilities");
        AssertTrue(source.Contains("def runtime_classification_models()", StringComparison.Ordinal), "Ultralytics worker should compute classification adapters from runtime capabilities");
        AssertTrue(source.Contains("\"HealthCheckResult\"", StringComparison.Ordinal), "Ultralytics worker should return health-check status messages");
        AssertTrue(source.Contains("\"ModelStatusResult\"", StringComparison.Ordinal), "Ultralytics worker should return model status messages");
        AssertTrue(source.Contains("\"DetectImageResult\"", StringComparison.Ordinal), "Ultralytics worker should return detection results");
        AssertTrue(source.Contains("\"polygonPoints\"", StringComparison.Ordinal), "Ultralytics worker should preserve segmentation polygons from mask results");
        AssertTrue(source.Contains("\"imageClassification\"", StringComparison.Ordinal), "Ultralytics worker should preserve image-level classification results for anomaly workflows");
        AssertTrue(source.Contains("parser.add_argument(\"--model\"", StringComparison.Ordinal)
            && source.Contains("\"UnsupportedModel\"", StringComparison.Ordinal)
            && source.Contains("unsupported_model_message(\"detection\"", StringComparison.Ordinal),
            "Ultralytics smoke-test mode should accept the selected adapter and report runtime capability blockers before model load");
        AssertTrue(source.Contains("\"TrainingStatus\"", StringComparison.Ordinal), "Ultralytics worker should emit training status messages for WPF progress");
        AssertTrue(source.Contains("\"trainingWeights\"", StringComparison.Ordinal), "Ultralytics worker should report resolved training weights in status messages");
        AssertTrue(source.Contains("\"cachedTrainingWeights\"", StringComparison.Ordinal)
            && source.Contains("\"missingTrainingWeights\"", StringComparison.Ordinal),
            "Ultralytics worker should report task-weight cache inventory in status capabilities");
        AssertTrue(source.Contains("\"runtimeReadyTrainingWeights\"", StringComparison.Ordinal)
            && source.Contains("\"runtimeBlockedTrainingWeights\"", StringComparison.Ordinal),
            "Ultralytics worker should distinguish cached weights usable by the current runtime");
        AssertTrue(source.Contains("\"downloadRequiredTrainingWeights\"", StringComparison.Ordinal)
            && source.Contains("\"runtimeBlockedMissingTrainingWeights\"", StringComparison.Ordinal),
            "Ultralytics worker should distinguish missing weights that require download from missing weights blocked by runtime");
        AssertTrue(source.Contains("TrainingWeightDownloadRequired", StringComparison.Ordinal)
            && source.Contains("allowModelDownload", StringComparison.Ordinal),
            "Ultralytics worker should block implicit model downloads unless explicitly allowed");
        AssertTrue(source.Contains("model.train(", StringComparison.Ordinal), "Ultralytics worker should route training through the Ultralytics API");
        AssertTrue(source.Contains("plots=False", StringComparison.Ordinal), "Ultralytics worker should skip optional training plots so completion status is not delayed by plot generation");
        AssertTrue(source.Contains("_resolve_cached_training_weight", StringComparison.Ordinal), "Ultralytics worker should prefer cached task-specific training weights from the model root when present");
        AssertTrue(source.Contains("yolov8n-seg.pt", StringComparison.Ordinal)
            && source.Contains("yolov8n-cls.pt", StringComparison.Ordinal)
            && source.Contains("yolo11n-seg.pt", StringComparison.Ordinal)
            && source.Contains("yolo11n-cls.pt", StringComparison.Ordinal),
            "Ultralytics worker self-test should cover YOLOv8/YOLO11 task-specific training defaults");
        AssertTrue(source.Contains("TrainingAlreadyRunning", StringComparison.Ordinal), "Ultralytics worker should guard duplicate training requests");

        var settings = new PythonModelSettings
        {
            ModelEngine = PythonModelSettings.EngineYolo11
        };
        PythonModelRuntimeAdapterSupport detectionOnly = PythonModelRuntimeAdapterSupportService.Build(
            settings,
            new[] { "yolo11" },
            Array.Empty<string>(),
            new[] { "yolo11" });
        AssertTrue(!detectionOnly.CanTrain, "detection-only Ultralytics capability should not enable training");
        AssertTrue(detectionOnly.CanInspect, "detection-only Ultralytics capability should enable inspection");

        PythonModelRuntimeAdapterSupport trainingAndDetection = PythonModelRuntimeAdapterSupportService.Build(
            settings,
            new[] { "yolo11" },
            new[] { "yolo11" },
            new[] { "yolo11" });
        AssertTrue(trainingAndDetection.CanTrain, "Ultralytics training capability should enable YOLO11 training");
        AssertTrue(trainingAndDetection.CanInspect, "Ultralytics detection capability should keep YOLO11 inspection enabled");

        PythonModelRuntimeAdapterSupport legacySupportedOnly = PythonModelRuntimeAdapterSupportService.Build(
            settings,
            new[] { "yolo11" });
        AssertTrue(legacySupportedOnly.CanTrain && legacySupportedOnly.CanInspect, "legacy supportedModels-only capability should remain backward-compatible");
    }

    private static void TestPythonEnvironmentRequirementsParser()
    {
        string root = CreateTempRoot();
        try
        {
            string nestedRequirementsPath = Path.Combine(root, "extras.txt");
            File.WriteAllLines(nestedRequirementsPath, new[]
            {
                "opencv-python>=4.8",
                "git+https://example.invalid/repo.git#egg=custom_pkg"
            });

            string requirementsPath = Path.Combine(root, "requirements.txt");
            File.WriteAllLines(requirementsPath, new[]
            {
                "# YOLOv5 runtime dependencies",
                "numpy>=1.21.0",
                "PyYAML==6.0",
                "ultralytics[export]>=8.0; python_version >= '3.8'",
                "-r extras.txt",
                "--find-links https://example.invalid/packages"
            });

            IReadOnlyList<string> packageNames = PythonEnvironmentService.ReadRequirementPackageNames(requirementsPath);

            AssertTrue(packageNames.Contains("numpy"), "numpy requirement was not parsed");
            AssertTrue(packageNames.Contains("PyYAML"), "PyYAML requirement was not parsed");
            AssertTrue(packageNames.Contains("ultralytics"), "ultralytics extra requirement was not parsed");
            AssertTrue(packageNames.Contains("opencv-python"), "included opencv-python requirement was not parsed");
            AssertTrue(packageNames.Contains("custom_pkg"), "git egg requirement was not parsed");
            AssertTrue(!packageNames.Contains("--find-links"), "pip option should not be parsed as a package");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestPythonEnvironmentResultSummaries()
    {
        var missingPackages = new PythonEnvironmentCheckResult
        {
            MissingPackages = new[] { "torch", "ultralytics" }
        };
        AssertTrue(
            missingPackages.Summary.StartsWith("누락 패키지:", StringComparison.Ordinal)
                && missingPackages.Summary.Contains("torch", StringComparison.Ordinal)
                && missingPackages.Summary.Contains("ultralytics", StringComparison.Ordinal),
            "missing-package summary should name the missing packages in Korean");
        AssertTrue(
            !missingPackages.Summary.Contains("Missing Python packages", StringComparison.OrdinalIgnoreCase),
            "missing-package summary should not expose raw English status text");

        var ready = new PythonEnvironmentCheckResult();
        AssertEqual("Python 실행 환경 준비 완료.", ready.Summary);

        var warning = new PythonEnvironmentCheckResult
        {
            Warnings = new[] { "requirements.txt에서 설치할 패키지 이름을 찾지 못했습니다: sample" }
        };
        AssertTrue(warning.Summary.Contains("설치할 패키지", StringComparison.Ordinal), "warning summary should stay operator-readable");

        var installSucceeded = new PythonPackageInstallResult
        {
            Succeeded = true,
            ExitCode = 0
        };
        AssertEqual("Python requirements 설치 완료.", installSucceeded.Summary);

        var installFailed = new PythonPackageInstallResult
        {
            Succeeded = false,
            ExitCode = 1,
            Output = "pip output"
        };
        AssertEqual("pip output", installFailed.Summary);

        string serviceSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "1. Core", "Runtime", "PythonEnvironmentService.cs"));
        AssertTrue(serviceSource.Contains("requirements.txt 파일을 찾을 수 없습니다", StringComparison.Ordinal), "missing requirements message should be localized");
        AssertTrue(serviceSource.Contains("Python 패키지 목록이 비어 있거나 읽을 수 없습니다", StringComparison.Ordinal), "empty pip-list message should be localized");
        AssertTrue(serviceSource.Contains("Python 명령 시간이 초과되었습니다", StringComparison.Ordinal), "timeout message should be localized");
        AssertTrue(!serviceSource.Contains("Python environment is ready.", StringComparison.Ordinal), "ready summary should not use raw English");
        AssertTrue(!serviceSource.Contains("Python requirements installed successfully.", StringComparison.Ordinal), "install success summary should not use raw English");
        AssertTrue(!serviceSource.Contains("Could not inspect installed Python packages.", StringComparison.Ordinal), "pip inspection fallback should not use raw English");
        AssertTrue(!ContainsVisibleMojibakeArtifact(serviceSource), "Python environment service source should not expose mojibake artifacts");
    }

    private static void TestYoloWorkerSmokeTestServiceValidation()
    {
        string root = CreateTempRoot();
        try
        {
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            string weightsPath = Path.Combine(root, "best.pt");
            Directory.CreateDirectory(Path.Combine(root, "yolov5Master"));
            File.WriteAllText(scriptPath, "print('ready')");
            File.WriteAllText(weightsPath, "");
            File.WriteAllText(Path.Combine(root, "requirements.txt"), "torch");
            string explicitImagePath = Path.Combine(root, "explicit.png");
            using (var image = new Bitmap(4, 3))
            {
                image.Save(explicitImagePath, System.Drawing.Imaging.ImageFormat.Png);
            }

            var settings = new PythonModelSettings
            {
                ProjectRootPath = root,
                ClientScriptPath = Path.Combine(root, "missing-client.py"),
                WeightsPath = weightsPath,
                ImageRootPath = root,
                PythonExecutablePath = Path.Combine(root, "python.exe")
            };

            YoloWorkerSmokeTestResult result = YoloWorkerSmokeTestService
                .RunAsync(settings)
                .GetAwaiter()
                .GetResult();

            AssertTrue(!result.Succeeded, "smoke test should fail before starting Python when inputs are invalid");
            AssertTrue(
                result.Errors.Any(error => error.Contains("client script", StringComparison.OrdinalIgnoreCase)),
                "missing client script should be reported");

            YoloWorkerSmokeTestResult explicitImageResult = YoloWorkerSmokeTestService
                .RunAsync(settings, explicitImagePath)
                .GetAwaiter()
                .GetResult();

            AssertEqual(explicitImagePath, explicitImageResult.ImagePath);
            AssertTrue(
                !explicitImageResult.Errors.Any(error => error.Contains("Smoke test image", StringComparison.OrdinalIgnoreCase)),
                "explicit smoke image should be accepted during input validation");

            using Process smokeProcess = InvokePrivateStaticResult<Process>(
                typeof(YoloWorkerSmokeTestService),
                "CreateSmokeProcess",
                "python",
                root,
                scriptPath,
                Path.Combine(root, "yolov5Master"),
                weightsPath,
                explicitImagePath,
                320,
                0.25F,
                "yolo11");
            List<string> smokeArgs = smokeProcess.StartInfo.ArgumentList.ToList();
            int modelArgIndex = smokeArgs.IndexOf("--model");
            AssertTrue(modelArgIndex >= 0, "worker smoke process should pass the selected YOLO adapter to --smoke-test");
            AssertEqual("yolo11", smokeArgs[modelArgIndex + 1]);

            using Process yolo8SmokeProcess = InvokePrivateStaticResult<Process>(
                typeof(YoloWorkerSmokeTestService),
                "CreateSmokeProcess",
                "python",
                root,
                scriptPath,
                Path.Combine(root, "yolov8"),
                weightsPath,
                explicitImagePath,
                64,
                0.01F,
                "yolov8");
            List<string> yolo8SmokeArgs = yolo8SmokeProcess.StartInfo.ArgumentList.ToList();
            AssertArgumentValue(yolo8SmokeArgs, "--model", "yolov8");
            AssertArgumentValue(yolo8SmokeArgs, "--conf", "0.01");
            AssertArgumentValue(yolo8SmokeArgs, "--img-size", "64");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestYoloWorkerSmokeCandidateBounds()
    {
        var candidate = new YoloWorkerSmokeCandidate
        {
            ClassName = "OK",
            Confidence = 0.976,
            X = 24.1588,
            Y = 22.9412,
            Width = 55.9874,
            Height = 55.9470
        };

        AssertEqual(new Rectangle(24, 23, 56, 56), candidate.ToRectangle());

        candidate.Width = 0;
        candidate.CandidateType = "imageClassification";
        candidate.PredictionType = "classification";
        candidate.ImageLevel = true;
        AssertEqual(Rectangle.Empty, candidate.ToRectangle());
        AssertTrue(candidate.ImageLevel, "image-level smoke candidates should preserve classification scope");

        string output = "{\"ok\":true,\"candidates\":[{\"className\":\"Part\",\"confidence\":0.77,\"x\":7,\"y\":8,\"width\":9,\"height\":10,\"segmentationType\":\"polygon\",\"polygonPoints\":[{\"x\":7,\"y\":8},{\"x\":16,\"y\":8},{\"x\":16,\"y\":18}],\"normalizedPolygonPoints\":[{\"x\":0.07,\"y\":0.08},{\"x\":0.16,\"y\":0.08},{\"x\":0.16,\"y\":0.18}]}]}";
        YoloWorkerSmokeTestResult parsed = InvokePrivateStaticResult<YoloWorkerSmokeTestResult>(
            typeof(YoloWorkerSmokeTestService),
            "ParseSmokeOutput",
            0,
            output,
            string.Empty,
            "python",
            "project",
            "client",
            "models",
            "weights",
            "image");
        AssertTrue(parsed.Succeeded, "smoke parser should accept a successful segmentation result");
        AssertEqual(1, parsed.Candidates.Count);
        YoloWorkerSmokeCandidate parsedCandidate = parsed.Candidates[0];
        AssertEqual("polygon", parsedCandidate.SegmentationType);
        AssertEqual(3, parsedCandidate.PolygonPoints.Count);
        AssertEqual(16F, parsedCandidate.PolygonPoints[1].X);
        AssertEqual(0.18F, parsedCandidate.NormalizedPolygonPoints[2].Y);

        string failedOutput = "{\"ok\":false,\"error\":{\"code\":\"UnsupportedModel\",\"message\":\"installed ultralytics 8.0.132 does not expose C3k2.\"}}";
        YoloWorkerSmokeTestResult failed = InvokePrivateStaticResult<YoloWorkerSmokeTestResult>(
            typeof(YoloWorkerSmokeTestService),
            "ParseSmokeOutput",
            1,
            failedOutput,
            string.Empty,
            "python",
            "project",
            "client",
            "models",
            "weights",
            "image");
        AssertTrue(!failed.Succeeded, "smoke parser should keep unsupported-runtime results failed");
        AssertEqual("UnsupportedModel", failed.ErrorCode);
        AssertTrue(failed.Summary.Contains("C3k2", StringComparison.Ordinal), "smoke parser should preserve the runtime blocker detail");
    }

    private static void TestWpfDetectionWorkerCompletionWaiter()
    {
        string root = CreateTempRoot();
        try
        {
            string targetImagePath = Path.Combine(root, "target.bmp");
            string otherImagePath = Path.Combine(root, "other.bmp");
            var service = new DetectionResultApplicationService();
            using var waiter = new WpfDetectionWorkerCompletionWaiter(
                service,
                targetImagePath,
                CancellationToken.None);

            var otherData = new CData
            {
                LastSelectImageName = Path.GetFileNameWithoutExtension(otherImagePath),
                LastSelectImagePath = otherImagePath
            };
            service.RegisterPendingDetectionImage(otherData, new Size(10, 10));
            service.ApplyToDetectLayer(Array.Empty<DefectInfo>());
            AssertTrue(!waiter.Completion.IsCompleted, "worker waiter should ignore completed events for another image");

            var targetData = new CData
            {
                LastSelectImageName = Path.GetFileNameWithoutExtension(targetImagePath),
                LastSelectImagePath = targetImagePath
            };
            service.RegisterPendingDetectionImage(targetData, new Size(10, 10));
            AssertTrue(!waiter.Completion.IsCompleted, "worker waiter should ignore RequestStarted events for the target image");
            service.ApplyToDetectLayer(Array.Empty<DefectInfo>());

            AssertTrue(WaitUntil(() => waiter.Completion.IsCompleted, TimeSpan.FromSeconds(1)), "worker waiter did not complete for the target image");
            AssertEqual(DetectionCandidateUpdateReason.ResultCompleted, waiter.Completion.Result.Reason);
            AssertTrue(
                WpfDetectionWorkerCompletionWaiter.IsCompletionForImage(
                    new DetectionCandidatesUpdatedEventArgs(
                        Path.GetFileNameWithoutExtension(targetImagePath),
                        string.Empty,
                        0,
                        DetectionCandidateUpdateReason.ResultCompleted),
                    targetImagePath),
                "worker waiter should match path-only requests by image name when the event path is empty");
            AssertTrue(
                !WpfDetectionWorkerCompletionWaiter.IsCompletionForImage(
                    new DetectionCandidatesUpdatedEventArgs(
                        Path.GetFileNameWithoutExtension(targetImagePath),
                        targetImagePath,
                        0,
                        DetectionCandidateUpdateReason.RequestStarted),
                    targetImagePath),
                "worker waiter should not complete on request-start events");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestYoloPythonClientStartInfo()
    {
        string root = CreateTempRoot();
        try
        {
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            string weightsPath = Path.Combine(root, "best.pt");
            string modelRootPath = Path.Combine(root, "yolov5Master");
            File.WriteAllText(scriptPath, "print('ready')");
            Directory.CreateDirectory(modelRootPath);

            var settings = new PythonModelSettings
            {
                ProjectRootPath = root,
                ClientScriptPath = scriptPath,
                WeightsPath = weightsPath,
                ImageRootPath = root,
                InferenceImageSize = 320,
                MinimumDetectionConfidence = 0.15F
            };

            AssertTrue(YoloPythonClientProcessService.TryCreateStartInfo(settings, out var startInfo, out string error), error);
            AssertEqual(root, startInfo.WorkingDirectory);
            AssertTrue(startInfo.CreateNoWindow, "Python client should start without opening a console window");
            AssertTrue(startInfo.ArgumentList.Contains(scriptPath), "client script was not passed to Python");
            AssertTrue(startInfo.ArgumentList.Contains("--retry"), "retry flag was not passed to Python");
            AssertTrue(startInfo.ArgumentList.Contains("--preload"), "preload flag should move model load into worker startup instead of the first image request");
            AssertTrue(startInfo.ArgumentList.Contains(weightsPath), "weights path was not passed to Python");
            AssertArgumentValue(startInfo.ArgumentList, "--model-root", modelRootPath);
            AssertArgumentValue(startInfo.ArgumentList, "--image-root", root);
            AssertArgumentValue(startInfo.ArgumentList, "--conf", "0.15");
            AssertArgumentValue(startInfo.ArgumentList, "--img-size", "320");

            AssertTrue(YoloPythonClientProcessService.TryCreateStartSignature(settings, out string firstSignature, out error), error);
            settings.MinimumDetectionConfidence = 0.2F;
            AssertTrue(YoloPythonClientProcessService.TryCreateStartSignature(settings, out string changedConfidenceSignature, out error), error);
            AssertTrue(
                !string.Equals(firstSignature, changedConfidenceSignature, StringComparison.Ordinal),
                "confidence changes should change Python client start signature");

            settings.MinimumDetectionConfidence = 0.15F;
            settings.InferenceImageSize = 416;
            AssertTrue(YoloPythonClientProcessService.TryCreateStartSignature(settings, out string changedImageSizeSignature, out error), error);
            AssertTrue(
                !string.Equals(firstSignature, changedImageSizeSignature, StringComparison.Ordinal),
                "inference image size changes should change Python client start signature");

            settings.InferenceImageSize = 320;
            settings.WeightsPath = Path.Combine(root, "other.pt");
            AssertTrue(YoloPythonClientProcessService.TryCreateStartSignature(settings, out string changedWeightsSignature, out error), error);
            AssertTrue(
                !string.Equals(firstSignature, changedWeightsSignature, StringComparison.Ordinal),
                "weight path changes should change Python client start signature");

            settings.ClientScriptPath = Path.Combine(root, "missing.py");
            AssertTrue(!YoloPythonClientProcessService.TryCreateStartInfo(settings, out _, out error), "missing client script was accepted");
            AssertTrue(
                error.Contains("\uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", StringComparison.Ordinal)
                && error.Contains("missing.py", StringComparison.Ordinal),
                "missing client script error was not descriptive");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestYoloDetectionWorkflowValidation()
    {
        string root = CreateTempRoot();
        try
        {
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            string weightsPath = Path.Combine(root, "best.pt");
            File.WriteAllText(scriptPath, "print('ready')");

            var data = new CData();
            data.ProjectSettings.PythonModel.ProjectRootPath = root;
            data.ProjectSettings.PythonModel.ClientScriptPath = scriptPath;
            data.ProjectSettings.PythonModel.WeightsPath = Path.Combine(root, "missing.pt");
            data.ProjectSettings.PythonModel.ImageRootPath = root;

            using var communication = new CCommunicationLearning(startListen: false);
            var workflow = new YoloDetectionWorkflowService();
            bool ensureCalled = false;
            bool invalidStarted = workflow.TryStartCurrentImageDetection(
                data,
                communication,
                new DetectionResultApplicationService(),
                () =>
                {
                    ensureCalled = true;
                    return true;
                });

            AssertTrue(!invalidStarted, "detection workflow should reject missing weights");
            AssertTrue(!ensureCalled, "Python client should not be prepared when detection settings are invalid");

            File.WriteAllText(weightsPath, "");
            data.ProjectSettings.PythonModel.WeightsPath = weightsPath;
            bool readyFailureStarted = workflow.TryStartCurrentImageDetection(
                data,
                communication,
                new DetectionResultApplicationService(),
                () =>
                {
                    ensureCalled = true;
                    return false;
                });

            AssertTrue(!readyFailureStarted, "detection workflow should stop when the Python client is not ready");
            AssertTrue(ensureCalled, "Python client readiness was not checked for valid settings");

            string imagePath = Path.Combine(root, "detect-yolo11.jpg");
            using (var image = new Bitmap(8, 8))
            {
                image.Save(imagePath, System.Drawing.Imaging.ImageFormat.Jpeg);
            }

            data.ProjectSettings.PythonModel.ModelEngine = PythonModelSettings.EngineYolo11;
            int detectPort = GetAvailableTcpPort();
            using var detectCommunication = new CCommunicationLearning(startListen: false, port: detectPort);
            using var receivedDetectRequest = new ManualResetEventSlim(false);
            AssertTrue(detectCommunication.Start(), "test TCP listener for DetectImage did not start");
            Task mockDetectClient = Task.Run(() => RunMockDetectImageClient(detectPort, receivedDetectRequest, "yolo11"));
            AssertTrue(WaitUntil(() => detectCommunication.GetStatusSnapshot().IsClientConnected, TimeSpan.FromSeconds(5)), "mock DetectImage client did not connect");

            var detectionService = new DetectionResultApplicationService();
            bool detectStarted = workflow.TryStartImagePathDetection(
                data,
                detectCommunication,
                detectionService,
                imagePath,
                new Size(8, 8),
                () => true);

            AssertTrue(detectStarted, "detection workflow should send DetectImage when settings and image path are valid");
            AssertTrue(receivedDetectRequest.Wait(TimeSpan.FromSeconds(5)), "mock DetectImage client did not receive the request");
            AssertTrue(mockDetectClient.Wait(TimeSpan.FromSeconds(5)), "mock DetectImage client did not finish");
            if (mockDetectClient.IsFaulted)
            {
                if (mockDetectClient.Exception != null)
                {
                    throw mockDetectClient.Exception;
                }

                throw new InvalidOperationException("mock DetectImage client failed");
            }
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestRuntimeCommandFailureMessages()
    {
        string repositoryRoot = FindRepositoryRoot();
        string detectionResultSource = File.ReadAllText(Path.Combine(repositoryRoot, "1. Core", "Detection", "DetectionResultApplicationService.cs"));
        string detectionWorkflowSource = File.ReadAllText(Path.Combine(repositoryRoot, "1. Core", "Detection", "YoloDetectionWorkflowService.cs"));
        string trainingWorkflowSource = File.ReadAllText(Path.Combine(repositoryRoot, "1. Core", "Model", "YoloTrainingWorkflowService.cs"));
        string combinedSource = string.Concat(detectionResultSource, detectionWorkflowSource, trainingWorkflowSource);

        string[] previousEnglishMessages =
        {
            "YOLO detection communication is not initialized.",
            "YOLO detection result service is not initialized.",
            "YOLO detection data is not initialized.",
            "StartDefect skipped because source image is empty.",
            "DetectImage skipped because image path is missing",
            "DetectImage skipped because image size is empty",
            "DetectImage was not sent because the Python model client is not connected.",
            "Selected detection candidate cannot be skipped because the active image changed.",
            "YOLO detection timed out after",
            "YOLO training communication is not initialized.",
            "StartTraining was not sent because the Python model client is not connected.",
            "StopTraining was not sent because the Python model client is not connected.",
            "YOLO training validation failed:"
        };

        foreach (string previousMessage in previousEnglishMessages)
        {
            AssertTrue(!combinedSource.Contains(previousMessage, StringComparison.Ordinal), $"old English runtime failure message remains: {previousMessage}");
        }

        AssertTrue(combinedSource.Contains("Python 모델 클라이언트가 연결되지 않아 현재 검사 요청을 보내지 못했습니다.", StringComparison.Ordinal), "current-inspection disconnect message should be Korean");
        AssertTrue(combinedSource.Contains("Python 모델 클라이언트가 연결되지 않아 학습 시작 명령을 보내지 못했습니다.", StringComparison.Ordinal), "training disconnect message should be Korean");
        AssertTrue(combinedSource.Contains("YOLO 검사 시간이 초과되었습니다.", StringComparison.Ordinal), "detection timeout message should be Korean");
        AssertTrue(!ContainsVisibleMojibakeArtifact(combinedSource), "runtime command failure sources should not expose mojibake artifacts");

        string root = CreateTempRoot();
        try
        {
            string scriptPath = Path.Combine(root, "labelling_tcp_client.py");
            string weightsPath = Path.Combine(root, "best.pt");
            string pythonPath = Path.Combine(root, "python.exe");
            File.WriteAllText(scriptPath, "print('ready')");
            File.WriteAllText(weightsPath, "");
            File.WriteAllText(pythonPath, "");

            var data = new CData();
            data.ProjectSettings.PythonModel.ProjectRootPath = root;
            data.ProjectSettings.PythonModel.ClientScriptPath = scriptPath;
            data.ProjectSettings.PythonModel.PythonExecutablePath = pythonPath;
            data.ProjectSettings.PythonModel.WeightsPath = weightsPath;
            data.ProjectSettings.PythonModel.ImageRootPath = root;

            using var communication = new CCommunicationLearning(startListen: false);
            var workflow = new YoloDetectionWorkflowService();

            bool missingImageStarted = workflow.TryStartImagePathDetection(
                data,
                communication,
                new DetectionResultApplicationService(),
                Path.Combine(root, "missing.jpg"),
                new Size(10, 10),
                () => true);

            AssertTrue(!missingImageStarted, "detection workflow should reject a missing image path");
            AssertTrue(communication.GetStatusSnapshot().LastError.Contains("검사 이미지 파일", StringComparison.Ordinal), "missing-image LastError should be operator-readable Korean");

            string imagePath = Path.Combine(root, "image.jpg");
            using (var image = new Bitmap(4, 4))
            {
                image.Save(imagePath, System.Drawing.Imaging.ImageFormat.Jpeg);
            }

            bool emptySizeStarted = workflow.TryStartImagePathDetection(
                data,
                communication,
                new DetectionResultApplicationService(),
                imagePath,
                Size.Empty,
                () => true);

            AssertTrue(!emptySizeStarted, "detection workflow should reject an empty image size");
            AssertTrue(communication.GetStatusSnapshot().LastError.Contains("이미지 크기", StringComparison.Ordinal), "empty-size LastError should be operator-readable Korean");

            bool nullDataStarted = workflow.TryStartCurrentImageDetection(
                null,
                communication,
                new DetectionResultApplicationService(),
                () => true);

            AssertTrue(!nullDataStarted, "detection workflow should reject null data");
            AssertTrue(communication.GetStatusSnapshot().LastError.Contains("검사 데이터", StringComparison.Ordinal), "null-data LastError should be operator-readable Korean");
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestPythonMessageFramer()
    {
        var framer = new PythonMessageFramer();

        IReadOnlyList<string> first = framer.Append("ResultDefect [{\"ClassName\":\"NG\",");
        AssertEqual(0, first.Count);

        IReadOnlyList<string> second = framer.Append("\"Confidence\":0.9,\"X\":1,\"Y\":2,\"Width\":3,\"Height\":4}]");
        AssertEqual(1, second.Count);
        AssertTrue(second[0].StartsWith("ResultDefect ", StringComparison.Ordinal), "split ResultDefect was not rebuilt");

        DetectionResultParseResult result = PythonDetectionResultProtocol.Parse(second[0]);
        AssertEqual(DetectionResultParseStatus.Parsed, result.Status);
        AssertEqual("NG", result.Defects[0].ClassName);

        var separatedFramer = new PythonMessageFramer();
        IReadOnlyList<string> separated = separatedFramer.Append("ResultDefect\n\n[{\"ClassName\":\"OK\",\"Confidence\":0.8,\"X\":1,\"Y\":2,\"Width\":3,\"Height\":4}]");
        AssertEqual(1, separated.Count);
        AssertEqual(DetectionResultParseStatus.Parsed, PythonDetectionResultProtocol.Parse(separated[0]).Status);

        IReadOnlyList<string> commands = framer.Append("StartTraining\nStopTraining\n");
        AssertEqual(2, commands.Count);
        AssertEqual("StartTraining", commands[0]);
        AssertEqual("StopTraining", commands[1]);

        var envelopeFramer = new PythonMessageFramer();
        IReadOnlyList<string> envelopeFirst = envelopeFramer.Append("{\"type\":\"ResultDefect\",\"items\":[");
        AssertEqual(0, envelopeFirst.Count);

        IReadOnlyList<string> envelopeSecond = envelopeFramer.Append("{\"className\":\"OK\",\"confidence\":0.7,\"x\":1,\"y\":2,\"width\":3,\"height\":4}]}");
        AssertEqual(1, envelopeSecond.Count);
        AssertEqual(DetectionResultParseStatus.Parsed, PythonDetectionResultProtocol.Parse(envelopeSecond[0]).Status);
    }

    private static void TestPythonModelStatusProtocol()
    {
        string statusJson = "{\"type\":\"TrainingStatus\",\"version\":1,\"state\":\"running\",\"message\":\"epoch\",\"progressPercent\":42,\"epoch\":2,\"totalEpochs\":5,\"trainingWeights\":\"C:/models/yolov8n-seg.pt\"}";

        PythonModelStatusParseResult result = PythonModelStatusProtocol.Parse(statusJson);

        AssertEqual(PythonModelStatusParseStatus.Parsed, result.Status);
        AssertEqual("running", result.Message.State);
        AssertEqual(42, result.Message.ProgressPercent.Value);
        AssertEqual(2, result.Message.Epoch.Value);
        AssertEqual(5, result.Message.TotalEpochs.Value);
        AssertEqual("C:/models/yolov8n-seg.pt", result.Message.TrainingWeights);
        AssertTrue(!result.Message.IsError, "running status should not be an error");

        string trainResultJson = "{\"type\":\"TrainYoloResult\",\"version\":1,\"ok\":true,\"taskId\":\"task-1\",\"state\":\"started\",\"trainingWeights\":\"C:/models/yolov8n-cls.pt\"}";
        PythonModelStatusParseResult trainResult = PythonModelStatusProtocol.Parse(trainResultJson);
        AssertEqual(PythonModelStatusParseStatus.Parsed, trainResult.Status);
        AssertEqual(PythonModelStatusProtocol.TrainingStatusType, trainResult.Message.Type);
        AssertEqual("started", trainResult.Message.State);
        AssertEqual("C:/models/yolov8n-cls.pt", trainResult.Message.TrainingWeights);

        string failedTrainResultJson = "{\"type\":\"TrainYoloResult\",\"version\":1,\"ok\":false,\"state\":\"failed\",\"trainingWeights\":\"yolov8n-seg.pt\",\"error\":{\"code\":\"TrainingWeightDownloadRequired\",\"message\":\"cache the file first\"}}";
        PythonModelStatusParseResult failedTrainResult = PythonModelStatusProtocol.Parse(failedTrainResultJson);
        AssertEqual(PythonModelStatusParseStatus.Parsed, failedTrainResult.Status);
        AssertEqual(PythonModelStatusProtocol.TrainingStatusType, failedTrainResult.Message.Type);
        AssertEqual("failed", failedTrainResult.Message.State);
        AssertEqual("yolov8n-seg.pt", failedTrainResult.Message.TrainingWeights);
        AssertTrue(failedTrainResult.Message.IsError, "failed training result should be treated as an error");
        AssertTrue(failedTrainResult.Message.Error.Contains("TrainingWeightDownloadRequired", StringComparison.Ordinal), "failed training result should preserve download guard error code");
        using (var communication = new CCommunicationLearning(startListen: false))
        {
            AssertTrue(InvokePrivateResult<bool>(communication, "TryHandleModelStatus", failedTrainResultJson), "communication should handle failed training result status");
            PythonCommunicationStatus snapshot = communication.GetStatusSnapshot();
            AssertEqual("failed", snapshot.LastTrainingState);
            AssertEqual("yolov8n-seg.pt", snapshot.LastTrainingWeightsPath);
            AssertTrue(snapshot.LastError.Contains("TrainingWeightDownloadRequired", StringComparison.Ordinal), "communication snapshot should retain download guard failure code");
        }

        string taskStatusJson = "{\"type\":\"TaskStatus\",\"version\":1,\"taskType\":\"TrainYolo\",\"taskId\":\"task-1\",\"state\":\"completed\",\"message\":\"YOLOv5 training completed.\",\"progressPercent\":100}";
        PythonModelStatusParseResult taskStatus = PythonModelStatusProtocol.Parse(taskStatusJson);
        AssertEqual(PythonModelStatusParseStatus.Parsed, taskStatus.Status);
        AssertEqual(PythonModelStatusProtocol.TrainingStatusType, taskStatus.Message.Type);
        AssertEqual("completed", taskStatus.Message.State);
        AssertEqual(100, taskStatus.Message.ProgressPercent.Value);

        string failedTaskStatusJson = "{\"type\":\"TaskStatus\",\"version\":1,\"taskType\":\"TrainYolo\",\"taskId\":\"task-2\",\"state\":\"failed\",\"message\":\"YOLOv5 training failed.\",\"exitCode\":1,\"logTail\":[\"Starting training for 1 epochs...\",\"Epoch GPU_mem box_loss obj_loss cls_loss Instances Size\",\"0%| | 0/7 [00:00<?, ?it/s]\"]}";
        PythonModelStatusParseResult failedTaskStatus = PythonModelStatusProtocol.Parse(failedTaskStatusJson);
        AssertEqual(PythonModelStatusParseStatus.Parsed, failedTaskStatus.Status);
        AssertTrue(failedTaskStatus.Message.Message.Contains("first training batch", StringComparison.OrdinalIgnoreCase), "failed training status should infer a user-actionable first-batch failure reason");

        string healthJson = "{\"type\":\"HealthCheckResult\",\"version\":1,\"requestId\":\"req-health\",\"ok\":true,\"worker\":{\"pid\":123,\"capabilities\":{\"models\":[\"yolov5\",\"yolo11\"],\"training\":[\"yolo11\"],\"inspection\":[\"yolo11\"],\"segmentationModels\":[\"yolo11\"],\"classificationModels\":[\"yolo11\"],\"runtimeWarnings\":[\"YOLO11 disabled: installed ultralytics runtime does not expose C3k2.\"],\"cachedTrainingWeights\":[\"yolo11n.pt\"],\"missingTrainingWeights\":[\"yolov8n-seg.pt\",\"yolo11n-cls.pt\"],\"runtimeReadyTrainingWeights\":[],\"runtimeBlockedTrainingWeights\":[\"yolo11n.pt\"],\"downloadRequiredTrainingWeights\":[\"yolov8n-seg.pt\"],\"runtimeBlockedMissingTrainingWeights\":[\"yolo11n-cls.pt\"]}}}";
        PythonModelStatusParseResult health = PythonModelStatusProtocol.Parse(healthJson);
        AssertEqual(PythonModelStatusParseStatus.Parsed, health.Status);
        AssertEqual(PythonModelStatusProtocol.HealthCheckResultType, health.Message.Type);
        AssertEqual("ready", health.Message.State);
        AssertTrue(health.Message.Ok == true, "health check ok state was not parsed");
        AssertTrue(health.Message.SupportedModels.Contains("yolo11"), "health check should parse worker supported model capabilities");
        AssertTrue(health.Message.TrainingModels.Contains("yolo11"), "health check should parse worker training capabilities");
        AssertTrue(health.Message.DetectionModels.Contains("yolo11"), "health check should parse worker detection capabilities");
        AssertTrue(health.Message.SegmentationModels.Contains("yolo11"), "health check should parse worker segmentation capabilities");
        AssertTrue(health.Message.ClassificationModels.Contains("yolo11"), "health check should parse worker classification capabilities");
        AssertTrue(health.Message.RuntimeWarnings.Any(item => item.Contains("C3k2", StringComparison.Ordinal)), "health check should parse worker runtime warnings without splitting the sentence");
        AssertTrue(health.Message.CachedTrainingWeights.Contains("yolo11n.pt"), "health check should parse cached training weight inventory");
        AssertTrue(health.Message.MissingTrainingWeights.Contains("yolov8n-seg.pt"), "health check should parse missing training weight inventory");
        AssertTrue(health.Message.RuntimeBlockedTrainingWeights.Contains("yolo11n.pt"), "health check should parse runtime-blocked cached weights");
        AssertTrue(health.Message.DownloadRequiredTrainingWeights.Contains("yolov8n-seg.pt"), "health check should parse download-required missing weights");
        AssertTrue(health.Message.RuntimeBlockedMissingTrainingWeights.Contains("yolo11n-cls.pt"), "health check should parse runtime-blocked missing weights");

        string modelJson = "{\"type\":\"ModelStatusResult\",\"version\":1,\"requestId\":\"req-model\",\"ok\":true,\"capabilities\":{\"supportedModels\":\"yolov5,yolov8\",\"trainingModels\":[\"yolov8\"],\"detectionModels\":[\"yolov8\"],\"segmentationModels\":[\"yolov8\"],\"classificationModels\":[\"yolov8\"],\"runtimeWarnings\":\"runtime warning\",\"cachedTrainingWeights\":\"yolov8n.pt, yolov8n-cls.pt\",\"missingTrainingWeights\":[\"yolov8n-seg.pt\"],\"runtimeReadyTrainingWeights\":[\"yolov8n.pt\",\"yolov8n-cls.pt\"],\"runtimeBlockedTrainingWeights\":\"yolo11n.pt\",\"downloadRequiredTrainingWeights\":[\"yolov8n-seg.pt\"],\"runtimeBlockedMissingTrainingWeights\":\"yolo11n-cls.pt\"},\"model\":{\"state\":\"ready\",\"loaded\":true,\"engine\":\"YOLOv8\",\"weightsPath\":\"C:/Git/yolov8/best.pt\"}}";
        PythonModelStatusParseResult model = PythonModelStatusProtocol.Parse(modelJson);
        AssertEqual(PythonModelStatusParseStatus.Parsed, model.Status);
        AssertEqual(PythonModelStatusProtocol.ModelStatusResultType, model.Message.Type);
        AssertEqual("req-model", model.Message.RequestId);
        AssertEqual("ready", model.Message.State);
        AssertTrue(model.Message.Loaded == true, "model loaded state was not parsed");
        AssertEqual(PythonModelSettings.EngineYoloV8, model.Message.ModelEngine);
        AssertEqual("C:/Git/yolov8/best.pt", model.Message.ModelWeightsPath);
        var expectedModel = new PythonModelSettings
        {
            ModelEngine = PythonModelSettings.EngineYoloV8,
            WeightsPath = "C:/Git/yolov8/best.pt"
        };
        AssertTrue(PythonModelIdentity.Matches(expectedModel, model.Message.ModelEngine, model.Message.ModelWeightsPath), "worker identity should match the configured engine and normalized weights path");
        AssertTrue(!PythonModelIdentity.Matches(expectedModel, model.Message.ModelEngine, "C:/Git/yolov8/runs/old/best.pt"), "worker identity should reject stale weights");
        AssertTrue(!PythonModelIdentity.Matches(expectedModel, PythonModelSettings.EngineYolo11, model.Message.ModelWeightsPath), "worker identity should reject the wrong engine");
        var artifactsDirectory = new DirectoryInfo(Path.Combine(FindRepositoryRoot(), "artifacts"));
        FileSystemInfo artifactsTarget = artifactsDirectory.ResolveLinkTarget(returnFinalTarget: true);
        if (artifactsTarget != null)
        {
            string logicalWeightsPath = Path.Combine(artifactsDirectory.FullName, "tests", "python-model-identity", "best.pt");
            string physicalWeightsPath = Path.Combine(artifactsTarget.FullName, "tests", "python-model-identity", "best.pt");
            var junctionModel = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYoloV8,
                WeightsPath = logicalWeightsPath
            };
            AssertTrue(PythonModelIdentity.Matches(junctionModel, PythonModelSettings.EngineYoloV8, physicalWeightsPath), "worker identity should treat logical junction and physical target paths as the same weights file");
            AssertTrue(!PythonModelIdentity.Matches(junctionModel, PythonModelSettings.EngineYoloV8, Path.Combine(artifactsTarget.FullName, "tests", "python-model-identity", "stale.pt")), "worker identity should still reject a different physical weights path through the same junction");
        }
        using (var communication = new CCommunicationLearning(startListen: false))
        {
            AssertTrue(InvokePrivateResult<bool>(communication, "TryHandleModelStatus", modelJson), "communication should handle model identity status");
            PythonCommunicationStatus snapshot = communication.GetStatusSnapshot();
            AssertEqual("req-model", snapshot.LastModelStatusRequestId);
            AssertEqual(PythonModelSettings.EngineYoloV8, snapshot.LastModelEngine);
            AssertEqual("C:/Git/yolov8/best.pt", snapshot.LastModelWeightsPath);
        }
        AssertTrue(model.Message.SupportedModels.Contains("yolov8"), "model status should parse supported model capabilities");
        AssertTrue(model.Message.SegmentationModels.Contains("yolov8"), "model status should parse segmentation model capabilities");
        AssertTrue(model.Message.ClassificationModels.Contains("yolov8"), "model status should parse classification model capabilities");
        AssertTrue(model.Message.RuntimeWarnings.Contains("runtime warning"), "model status should parse capability runtime warnings");
        AssertTrue(model.Message.CachedTrainingWeights.Contains("yolov8n-cls.pt"), "model status should parse cached training weight inventory");
        AssertTrue(model.Message.MissingTrainingWeights.Contains("yolov8n-seg.pt"), "model status should parse missing training weight inventory");
        AssertTrue(model.Message.RuntimeReadyTrainingWeights.Contains("yolov8n-cls.pt"), "model status should parse runtime-ready cached weights");
        AssertTrue(model.Message.RuntimeBlockedTrainingWeights.Contains("yolo11n.pt"), "model status should parse runtime-blocked cached weights");
        AssertTrue(model.Message.DownloadRequiredTrainingWeights.Contains("yolov8n-seg.pt"), "model status should parse download-required missing weights");
        AssertTrue(model.Message.RuntimeBlockedMissingTrainingWeights.Contains("yolo11n-cls.pt"), "model status should parse runtime-blocked missing weights");

        string modelTrainingJson = "{\"type\":\"ModelStatusResult\",\"version\":1,\"requestId\":\"req-model-training\",\"ok\":true,\"model\":{\"state\":\"ready\",\"loaded\":true,\"weightsPath\":\"C:/Git/yolov8/yolov8n-seg.pt\"},\"training\":{\"type\":\"TrainingStatus\",\"state\":\"completed\",\"message\":\"YOLOv8 segment training completed.\",\"progressPercent\":100,\"epoch\":1,\"totalEpochs\":1,\"trainingWeights\":\"C:/Git/yolov8/yolov8n-seg.pt\"}}";
        PythonModelStatusParseResult modelTraining = PythonModelStatusProtocol.Parse(modelTrainingJson);
        AssertEqual(PythonModelStatusParseStatus.Parsed, modelTraining.Status);
        AssertEqual(PythonModelStatusProtocol.ModelStatusResultType, modelTraining.Message.Type);
        AssertTrue(modelTraining.Message.HasEmbeddedTrainingStatus, "model status should expose embedded training status for polling recovery");
        AssertEqual("completed", modelTraining.Message.EmbeddedTrainingState);
        AssertEqual("YOLOv8 segment training completed.", modelTraining.Message.EmbeddedTrainingMessage);
        AssertEqual(100, modelTraining.Message.EmbeddedTrainingProgressPercent);
        AssertEqual(1, modelTraining.Message.EmbeddedTrainingEpoch);
        AssertEqual(1, modelTraining.Message.EmbeddedTrainingTotalEpochs);
        AssertEqual("C:/Git/yolov8/yolov8n-seg.pt", modelTraining.Message.TrainingWeights);

        string communicationSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "3. Communication", "TCP", "CCommunicationLearning.cs"));
        AssertTrue(communicationSource.Contains("WorkerSupportedModels = new List<string>(statusMessage.SupportedModels", StringComparison.Ordinal), "worker capability status should replace stale supported-model lists when the worker reports an empty list");
        AssertTrue(!communicationSource.Contains("statusMessage.SupportedModels?.Count > 0", StringComparison.Ordinal), "worker capability status should not preserve stale supported-model lists after an empty capability update");
        AssertTrue(communicationSource.Contains("LastTrainingWeightsPath = statusMessage.TrainingWeights", StringComparison.Ordinal), "worker training status should preserve resolved training weights");
        AssertTrue(communicationSource.Contains("WorkerCachedTrainingWeights = new List<string>(statusMessage.CachedTrainingWeights", StringComparison.Ordinal), "worker capability status should preserve cached training weight inventory");
        AssertTrue(communicationSource.Contains("WorkerRuntimeBlockedTrainingWeights = new List<string>(statusMessage.RuntimeBlockedTrainingWeights", StringComparison.Ordinal), "worker capability status should preserve runtime-blocked weight inventory");
        AssertTrue(communicationSource.Contains("WorkerDownloadRequiredTrainingWeights = new List<string>(statusMessage.DownloadRequiredTrainingWeights", StringComparison.Ordinal), "worker capability status should preserve download-required missing weight inventory");
        string globalSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "1. Core", "ApplicationState", "CGlobal.cs"));
        AssertTrue(globalSource.Contains("SendModelStatus(pendingStatusRequestId", StringComparison.Ordinal), "worker readiness should request fresh model identity before accepting a connection");
        AssertTrue(globalSource.Contains("PythonModelIdentity.Matches", StringComparison.Ordinal), "worker readiness should reject stale engine or weight settings");
        string tcpSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "3. Communication", "TCP", "CTCPAsync.cs"));
        AssertTrue(tcpSource.Contains("active worker is already connected", StringComparison.Ordinal), "TCP listener should keep one active worker instead of replacing the socket behind an in-flight request");
        string lifecycleSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "0. UI", "9) WPF", "Views", "WpfLabelingShellWindow.ShellLifecycle.cs"));
        AssertTrue(lifecycleSource.Contains("global.StopPythonModelClientConnection();", StringComparison.Ordinal), "WPF shell close should stop the managed Python worker");
        string programSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "Program.cs"));
        AssertTrue(programSource.Contains("finally", StringComparison.Ordinal) && programSource.Contains("CGlobal.Inst.StopPythonModelClientConnection();", StringComparison.Ordinal), "application shutdown should retain a process-level worker cleanup backstop");

        PythonModelStatusParseResult ignored = PythonModelStatusProtocol.Parse("{\"type\":\"Other\"}");
        AssertEqual(PythonModelStatusParseStatus.NotStatus, ignored.Status);
    }

    private static void TestTcpReceiveQueueEncoding()
    {
        var tcp = new CTCPAsync
        {
            TextEncoding = Encoding.UTF8
        };

        tcp.listRcvData.Add(Encoding.UTF8.GetBytes("class-\uB370\uC774\uD130"));

        AssertTrue(tcp.GetStringData(out string message), "queued string data was not returned");
        AssertEqual("class-\uB370\uC774\uD130", message);
        AssertTrue(!tcp.GetStringData(out string _), "queue should be empty after dequeue");
    }

    private static void TestPythonDetectionResultProtocol()
    {
        string message = "ResultDefect [{\"ClassName\":\"NG\",\"Confidence\":0.91,\"X\":12.5,\"Y\":20,\"Width\":30,\"Height\":40}]";

        DetectionResultParseResult result = PythonDetectionResultProtocol.Parse(message);

        AssertTrue(result.IsDetectionResult, "ResultDefect message was not recognized");
        AssertEqual(DetectionResultParseStatus.Parsed, result.Status);
        AssertEqual(1, result.Defects.Count);
        AssertEqual("NG", result.Defects[0].ClassName);
        AssertEqual(12.5F, result.Defects[0].X);
        AssertEqual(40F, result.Defects[0].Height);

        string envelope = "{\"type\":\"ResultDefect\",\"version\":1,\"imageId\":\"sample-001\",\"items\":[{\"className\":\"OK\",\"confidence\":0.82,\"x\":3,\"y\":4,\"width\":5,\"height\":6}]}";
        DetectionResultParseResult envelopeResult = PythonDetectionResultProtocol.Parse(envelope);

        AssertEqual(DetectionResultParseStatus.Parsed, envelopeResult.Status);
        AssertEqual(1, envelopeResult.Defects.Count);
        AssertEqual("OK", envelopeResult.Defects[0].ClassName);
        AssertEqual(5F, envelopeResult.Defects[0].Width);
        AssertEqual("sample-001", envelopeResult.ImageId);

        string detectResult = "{\"type\":\"DetectImageResult\",\"version\":1,\"requestId\":\"req-123\",\"imageId\":\"sample-002\",\"ok\":true,\"candidates\":[{\"className\":\"NG\",\"confidence\":0.72,\"x\":7,\"y\":8,\"width\":9,\"height\":10,\"segmentationType\":\"polygon\",\"polygonPoints\":[{\"x\":7,\"y\":8},{\"x\":16,\"y\":8},{\"x\":16,\"y\":18},{\"x\":7,\"y\":18}],\"normalizedPolygonPoints\":[{\"x\":0.07,\"y\":0.08},{\"x\":0.16,\"y\":0.08},{\"x\":0.16,\"y\":0.18},{\"x\":0.07,\"y\":0.18}]}]}";
        DetectionResultParseResult detectParse = PythonDetectionResultProtocol.Parse(detectResult);
        AssertEqual(DetectionResultParseStatus.Parsed, detectParse.Status);
        AssertEqual("req-123", detectParse.RequestId);
        AssertEqual("sample-002", detectParse.ImageId);
        AssertEqual("NG", detectParse.Defects[0].ClassName);
        AssertEqual(9F, detectParse.Defects[0].Width);
        AssertEqual("polygon", detectParse.Defects[0].SegmentationType);
        AssertEqual(4, detectParse.Defects[0].PolygonPoints.Count);
        AssertEqual(16F, detectParse.Defects[0].PolygonPoints[2].X);
        AssertEqual(0.18F, detectParse.Defects[0].NormalizedPolygonPoints[2].Y);

        string classificationResult = "{\"type\":\"DetectImageResult\",\"version\":1,\"requestId\":\"req-cls\",\"imageId\":\"sample-003\",\"ok\":true,\"candidates\":[{\"candidateType\":\"imageClassification\",\"predictionType\":\"classification\",\"imageLevel\":true,\"className\":\"Normal\",\"confidence\":0.88,\"x\":0,\"y\":0,\"width\":0,\"height\":0}]}";
        DetectionResultParseResult classificationParse = PythonDetectionResultProtocol.Parse(classificationResult);
        AssertEqual(DetectionResultParseStatus.Parsed, classificationParse.Status);
        AssertEqual("Normal", classificationParse.Defects[0].ClassName);
        AssertEqual("imageClassification", classificationParse.Defects[0].CandidateType);
        AssertEqual("classification", classificationParse.Defects[0].PredictionType);
        AssertTrue(classificationParse.Defects[0].ImageLevel, "image-level classification result was not preserved");
    }

    private static void TestPythonDetectionResultProtocolFailures()
    {
        DetectionResultParseResult ignored = PythonDetectionResultProtocol.Parse("StartTraining");
        AssertEqual(DetectionResultParseStatus.NotDetectionResult, ignored.Status);
        AssertTrue(!ignored.IsDetectionResult, "non-detection command was recognized as detection");

        DetectionResultParseResult empty = PythonDetectionResultProtocol.Parse("ResultDefect ");
        AssertEqual(DetectionResultParseStatus.EmptyPayload, empty.Status);
        AssertTrue(empty.IsDetectionResult, "empty ResultDefect command should still be handled");

        DetectionResultParseResult invalid = PythonDetectionResultProtocol.Parse("ResultDefect { bad json");
        AssertEqual(DetectionResultParseStatus.InvalidPayload, invalid.Status);
        AssertTrue(!string.IsNullOrWhiteSpace(invalid.ErrorMessage), "invalid payload did not include an error message");

        DetectionResultParseResult envelopeError = PythonDetectionResultProtocol.Parse("{\"type\":\"ResultDefect\",\"version\":1,\"error\":\"weights missing\",\"items\":[]}");
        AssertEqual(DetectionResultParseStatus.InvalidPayload, envelopeError.Status);
        AssertTrue(envelopeError.ErrorMessage.Contains("weights missing"), "detection envelope error was not surfaced");

        DetectionResultParseResult structuredError = PythonDetectionResultProtocol.Parse("{\"type\":\"DetectImageResult\",\"version\":1,\"requestId\":\"req-bad\",\"imageId\":\"img-bad\",\"ok\":false,\"error\":{\"code\":\"DetectImageFailed\",\"message\":\"file missing\"},\"candidates\":[]}");
        AssertEqual(DetectionResultParseStatus.InvalidPayload, structuredError.Status);
        AssertEqual("req-bad", structuredError.RequestId);
        AssertTrue(structuredError.ErrorMessage.Contains("file missing"), "structured detection error was not surfaced");
    }

    private static void TestLabelingImageWorkspace()
    {
        var workspace = new LabelingImageWorkspace();
        using Bitmap image = new Bitmap(32, 24);

        workspace.SetActiveImage("part-001", @"C:\images\part-001.png", image);

        AssertEqual("part-001", workspace.ActiveImageName);
        AssertEqual(@"C:\images\part-001.png", workspace.ActiveImagePath);
        AssertTrue(ReferenceEquals(image, workspace.ActiveImage), "active image was not stored in ImageSpace");
        AssertTrue(ReferenceEquals(image, workspace.GetMainImage()), "main image was not stored in ImageSpace");
        AssertTrue(workspace.MainImageChanged, "main image changed flag was not set");

        workspace.AcceptMainImageChange();
        AssertTrue(!workspace.MainImageChanged, "main image changed flag was not accepted");
    }

