        AssertTrue(shellSource.Contains("PythonModelRuntimeConnectionService.BuildYoloV8FolderConnection", StringComparison.Ordinal), "runtime-profile action adapter should delegate YOLOv8 local folder mapping to the core connection service");
        AssertTrue(shellSource.Contains("PythonModelRuntimeConnectionService.BuildUltralyticsPythonConnection", StringComparison.Ordinal), "runtime-profile action adapter should still delegate YOLO11 Python mapping to the core connection service");
        AssertTrue(shellSource.Contains("ExecuteInstallUltralyticsPackageCommand", StringComparison.Ordinal), "WPF shell should inject a separate Ultralytics install adapter into the settings ViewModel");
        AssertTrue(shellSource.Contains("ExecuteUninstallUltralyticsPackageCommand", StringComparison.Ordinal), "WPF shell should inject a separate Ultralytics uninstall adapter into the settings ViewModel");
        AssertTrue(shellSource.Contains("ConfirmUltralyticsPackageOperation", StringComparison.Ordinal), "WPF shell should confirm Ultralytics package changes before running pip");
        AssertTrue(shellSource.Contains("WpfMessageDialog.Confirm", StringComparison.Ordinal), "Ultralytics package confirmation should use the reusable WPF message dialog");
        AssertTrue(shellSource.Contains("WpfMessageDialogResult.Yes", StringComparison.Ordinal), "Ultralytics package confirmation should only continue after the explicit primary response");
        AssertTrue(!shellSource.Contains("MessageBox.Show", StringComparison.Ordinal), "WPF shell should not use stock MessageBox for model-runtime package changes");
        AssertTrue(shellSource.Contains("SetUltralyticsPackageOperationResult", StringComparison.Ordinal), "WPF shell should push recent Ultralytics package results into the settings ViewModel");
        AssertTrue(shellSource.Contains("YoloModelSettingsViewModel?.LoadFrom(global.Data.ProjectSettings.PythonModel, global.Data.ProjectSettings.AnomalyClassification)", StringComparison.Ordinal), "WPF shell should load anomaly mapping settings through the YOLO model settings ViewModel");
        AssertTrue(shellSource.Contains("YoloModelSettingsViewModel?.ApplyTo(global.Data.ProjectSettings.AnomalyClassification)", StringComparison.Ordinal), "WPF shell should save anomaly mapping settings through the YOLO model settings ViewModel");
        AssertTrue(yoloEnvironmentCommandPresentationSource.Contains("BuildUltralyticsConfirmation", StringComparison.Ordinal), "YOLO environment command presentation service should own Ultralytics confirmation dialog text");
        AssertTrue(yoloEnvironmentCommandPresentationSource.Contains("BuildUltralyticsPackageOperationDetail", StringComparison.Ordinal), "YOLO environment command presentation service should build visible package-result detail text");
        AssertTrue(yoloEnvironmentCommandPresentationSource.Contains("BuildUltralyticsPackageOperationLogLines", StringComparison.Ordinal), "YOLO environment command presentation service should build package-operation log rows");
        AssertTrue(yoloEnvironmentRuntimeCommandsSource.Contains("WpfYoloEnvironmentCommandPresentationService.BuildUltralyticsPackageOperationDetail", StringComparison.Ordinal), "WPF shell should delegate package-result detail text to the presentation service");
        AssertTrue(yoloEnvironmentRuntimeCommandsSource.Contains("WpfYoloEnvironmentCommandPresentationService.BuildUltralyticsPackageOperationLogLines", StringComparison.Ordinal), "WPF shell should delegate package-operation log rows to the presentation service");
        AssertTrue(!yoloEnvironmentRuntimeCommandsSource.Contains("SplitPackageCommandLogTail", StringComparison.Ordinal), "WPF shell should not own package-operation log splitting");
        AssertTrue(!yoloEnvironmentRuntimeCommandsSource.Contains("테스트를 반복하기 위해", StringComparison.Ordinal), "WPF shell should not inline Ultralytics uninstall confirmation wording");
        AssertTrue(!yoloEnvironmentRuntimeCommandsSource.Contains("결과:", StringComparison.Ordinal), "WPF shell should not inline Ultralytics package-result detail labels");
        AssertTrue(shellSource.Contains("PythonEnvironmentService.InstallPackageAsync", StringComparison.Ordinal), "WPF shell install adapter should delegate package installation to the core Python environment service");
        AssertTrue(shellSource.Contains("PythonEnvironmentService.UninstallPackageAsync", StringComparison.Ordinal), "WPF shell uninstall adapter should delegate package removal to the core Python environment service");
        AssertTrue(yoloEnvironmentCommandPresentationSource.Contains("설치 건너뜀", StringComparison.Ordinal), "legacy requirements install status should use readable Korean skip wording");
        AssertTrue(yoloEnvironmentCommandPresentationSource.Contains("설치 실패", StringComparison.Ordinal), "legacy requirements install status should use readable Korean failure wording");
        AssertTrue(!ContainsVisibleMojibakeArtifact(yoloEnvironmentRuntimeCommandsSource), "YOLO environment runtime command source should not expose mojibake artifacts");
        AssertTrue(!ContainsVisibleMojibakeArtifact(yoloEnvironmentCommandPresentationSource), "YOLO environment command presentation source should not expose mojibake artifacts");
        var packagePlan = new PythonModelRuntimeInstallPlan(
            PythonModelSettings.EngineYolo11,
            "title",
            "summary",
            "detail",
            "target venv",
            "preview command",
            "install command",
            "uninstall command",
            isVisible: true,
            canPreviewCommand: true,
            canRunInstall: true,
            canRunUninstall: true,
            requiresInstallation: true,
            isAlreadyInstalled: false);
        var packageResult = new PythonPackageInstallResult
        {
            Succeeded = false,
            ExitCode = 1,
            CommandLine = "python -m pip install ultralytics",
            Error = "package error"
        };
        WpfUltralyticsPackageConfirmationPresentation installConfirmation = WpfYoloEnvironmentCommandPresentationService.BuildUltralyticsConfirmation(false, packagePlan);
        WpfUltralyticsPackageConfirmationPresentation uninstallConfirmation = WpfYoloEnvironmentCommandPresentationService.BuildUltralyticsConfirmation(true, packagePlan);
        AssertTrue(installConfirmation.Title.Contains("설치 확인", StringComparison.Ordinal), "Ultralytics install confirmation should name the install action");
        AssertTrue(uninstallConfirmation.Detail.Contains("패키지만 제거", StringComparison.Ordinal), "Ultralytics uninstall confirmation should explain only the package is removed");
        string packageResultDetail = WpfYoloEnvironmentCommandPresentationService.BuildUltralyticsPackageOperationDetail(
            packagePlan,
            false,
            packageResult,
            "\uC124\uCE58 \uC2E4\uD328: package error");
        AssertTrue(packageResultDetail.StartsWith("\uACB0\uACFC:", StringComparison.Ordinal), "package result detail should start with an operator result summary");
        AssertTrue(packageResultDetail.Contains("\uC885\uB8CC \uCF54\uB4DC:", StringComparison.Ordinal), "package result detail should label exit code in Korean");
        AssertTrue(packageResultDetail.Contains("\uB85C\uADF8 \uC694\uC57D:", StringComparison.Ordinal), "package result detail should label command output as a log summary");
        AssertTrue(!packageResultDetail.Contains("ExitCode:", StringComparison.Ordinal), "package result detail should not expose the raw ExitCode label");
        AssertTrue(!ContainsVisibleMojibakeArtifact(packageResultDetail), "package result detail should not expose mojibake artifacts");
        string[] packageLogLines = WpfYoloEnvironmentCommandPresentationService.BuildUltralyticsPackageOperationLogLines("Ultralytics 설치", new PythonPackageInstallResult
        {
            CommandLine = "python -m pip install ultralytics",
            Output = "first output\r\nsecond output",
            Error = "first error\r\nsecond error"
        });
        AssertTrue(packageLogLines.SequenceEqual(new[]
        {
            "Ultralytics 설치 명령: python -m pip install ultralytics",
            "[stdout] first output",
            "[stdout] second output",
            "[stderr] first error",
            "[stderr] second error"
        }), "package-operation log rows should retain the command, stdout, then stderr order");
        var statusDetailSettings = new PythonModelSettings
        {
            PythonExecutablePath = @"C:\Python\python.exe",
            ProjectRootPath = @"C:\Models\yolov5",
            ClientScriptPath = @"C:\Models\yolov5\detect.py",
            WeightsPath = @"C:\models\best.pt",
            ImageRootPath = @"D:\Images",
            MinimumDetectionConfidence = 0.31F,
            DetectionTimeoutSeconds = 45
        };
        var statusDetailValidation = new PythonModelValidationResult(new[] { "weights missing" }, new[] { "low confidence" });
        var statusDetailCommunication = new PythonCommunicationStatus
        {
            IsListening = true,
            IsClientConnected = false,
            ListenerPort = 5055,
            LastWorkerState = "listening",
            LastWorkerMessage = "Python TCP listener is waiting for a client.",
            WorkerSupportedModels = new List<string> { "yolov8" },
            WorkerTrainingModels = new List<string> { "yolov8" },
            WorkerDetectionModels = new List<string> { "yolov8" },
            WorkerSegmentationModels = new List<string> { "yolov8" },
            WorkerClassificationModels = new List<string> { "yolov8" },
            WorkerCachedTrainingWeights = new List<string> { "yolov8n-cls.pt" },
            WorkerMissingTrainingWeights = new List<string> { "yolov8n-seg.pt", "yolo11n-cls.pt" },
            WorkerRuntimeReadyTrainingWeights = new List<string> { "yolov8n-cls.pt" },
            WorkerRuntimeBlockedTrainingWeights = new List<string> { "yolo11n.pt" },
            WorkerDownloadRequiredTrainingWeights = new List<string> { "yolov8n-seg.pt" },
            WorkerRuntimeBlockedMissingTrainingWeights = new List<string> { "yolo11n-cls.pt" },
            LastModelState = "loaded",
            LastModelLoaded = true,
            LastModelMessage = "best.pt",
            LastTrainingState = "running",
            LastTrainingProgressPercent = 42,
            LastTrainingEpoch = 2,
            LastTrainingTotalEpochs = 5,
            LastTrainingMessage = "epoch",
            LastTrainingWeightsPath = @"C:\models\yolov8n-seg.pt",
            WorkerRuntimeWarnings = new List<string> { "YOLO11 disabled: installed ultralytics runtime does not expose C3k2." },
            LastError = "TrainingWeightDownloadRequired: cache the file first"
        };
        var statusDetailEnvironment = new PythonEnvironmentCheckResult
        {
            RequiredPackages = new[] { "torch", "ultralytics" },
            MissingPackages = new[] { "ultralytics" }
        };
        string settingsPanelDetail = WpfYoloSettingsPanelStatusPresentationService.BuildDetail(
            statusDetailSettings,
            statusDetailValidation,
            new PythonModelRuntimeState(PythonModelRuntimeStateKind.Ready, true, true, "ready", "detail", "next"),
            statusDetailCommunication,
            pythonClientProcessRunning: true,
            statusDetailEnvironment,
            string.Empty);
        AssertTrue(settingsPanelDetail.Contains("\uC2E4\uD589 \uD30C\uC77C:", StringComparison.Ordinal), "settings status detail should label the Python executable in readable Korean");
        AssertTrue(settingsPanelDetail.Contains("\uD504\uB85C\uC81D\uD2B8:", StringComparison.Ordinal), "settings status detail should label the project path in readable Korean");
        AssertTrue(settingsPanelDetail.Contains("\uC774\uBBF8\uC9C0:", StringComparison.Ordinal), "settings status detail should label the image path in readable Korean");
        AssertTrue(settingsPanelDetail.Contains("\uC2E0\uB8B0\uB3C4: 0.31", StringComparison.Ordinal), "settings status detail should show confidence with a readable label");
        AssertTrue(settingsPanelDetail.Contains("\uCD94\uB860 \uC2E4\uD589\uAE30:", StringComparison.Ordinal), "settings status detail should summarize worker connection state");
        AssertTrue(settingsPanelDetail.Contains("\uC218\uC2E0 \uB300\uAE30", StringComparison.Ordinal), "settings status detail should translate worker listening state");
        AssertTrue(settingsPanelDetail.Contains("\uCD94\uB860 \uC2E4\uD589\uAE30 \uC5F0\uACB0 \uB300\uAE30 \uC911\uC785\uB2C8\uB2E4.", StringComparison.Ordinal), "settings status detail should translate worker listener messages");
        AssertTrue(settingsPanelDetail.Contains("segmentation=yolov8", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("classification=yolov8", StringComparison.Ordinal),
            "settings status detail should show worker segmentation/classification capabilities");
        AssertTrue(settingsPanelDetail.Contains("\uD559\uC2B5 weight \uCE90\uC2DC:", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("yolov8n-cls.pt", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("yolov8n-seg.pt", StringComparison.Ordinal),
            "settings status detail should show task-weight cache inventory");
        AssertTrue(settingsPanelDetail.Contains("\uD559\uC2B5 weight \uB7F0\uD0C0\uC784:", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("\uC2E4\uD589 \uAC00\uB2A5=yolov8n-cls.pt", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("\uB7F0\uD0C0\uC784 \uCC28\uB2E8=yolo11n.pt", StringComparison.Ordinal),
            "settings status detail should show runtime-ready and runtime-blocked cached weights");
        AssertTrue(settingsPanelDetail.Contains("\uD559\uC2B5 weight \uC900\uBE44:", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("\uB2E4\uC6B4\uB85C\uB4DC/\uCE90\uC2DC \uD544\uC694=yolov8n-seg.pt", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("\uB7F0\uD0C0\uC784 \uC9C0\uC6D0 \uD544\uC694=yolo11n-cls.pt", StringComparison.Ordinal),
            "settings status detail should show missing weights that require download or runtime support");
        AssertTrue(!settingsPanelDetail.Contains("runtime-blocked-missing", StringComparison.Ordinal)
            && !settingsPanelDetail.Contains("downloadRequiredTrainingWeights", StringComparison.Ordinal),
            "settings status detail should not expose raw worker weight inventory keys");
        AssertTrue(settingsPanelDetail.Contains("\uBAA8\uB378 \uC0C1\uD0DC:", StringComparison.Ordinal), "settings status detail should label model state");
        AssertTrue(settingsPanelDetail.Contains("\uB85C\uB4DC:\uC608", StringComparison.Ordinal), "settings status detail should show loaded state in readable Korean");
        AssertTrue(settingsPanelDetail.Contains("\uD559\uC2B5:", StringComparison.Ordinal) && settingsPanelDetail.Contains("42%", StringComparison.Ordinal), "settings status detail should include training progress");
        AssertTrue(settingsPanelDetail.Contains("\uC5D0\uD3ED 2/5", StringComparison.Ordinal), "settings status detail should include epoch progress");
        AssertTrue(settingsPanelDetail.Contains("\uD559\uC2B5 weight \uC120\uD0DD:", StringComparison.Ordinal)
            && settingsPanelDetail.Contains(@"C:\models\yolov8n-seg.pt", StringComparison.Ordinal),
            "settings status detail should include resolved training weights");
        AssertTrue(settingsPanelDetail.Contains("\uC2E4\uD589 \uC624\uB958:", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("\uD559\uC2B5 weight \uB2E4\uC6B4\uB85C\uB4DC \uC2B9\uC778 \uD544\uC694", StringComparison.Ordinal),
            "settings status detail should translate download-guard failures into operator-readable text");
        AssertTrue(!settingsPanelDetail.Contains("TrainingWeightDownloadRequired", StringComparison.Ordinal),
            "settings status detail should not expose the raw download guard failure code");
        AssertTrue(settingsPanelDetail.Contains("\uCD94\uB860 \uACBD\uACE0:", StringComparison.Ordinal)
            && settingsPanelDetail.Contains("C3k2", StringComparison.Ordinal),
            "settings status detail should show worker runtime warnings");
        AssertTrue(settingsPanelDetail.Contains("\uB204\uB77D: ultralytics", StringComparison.Ordinal), "settings status detail should show missing packages in readable Korean");
        AssertTrue(settingsPanelDetail.Contains("\uC624\uB958: weights missing", StringComparison.Ordinal), "settings status detail should show validation errors in readable Korean");
        AssertTrue(settingsPanelDetail.Contains("\uC8FC\uC758: low confidence", StringComparison.Ordinal), "settings status detail should show validation warnings in readable Korean");
        AssertTrue(!ContainsVisibleMojibakeArtifact(settingsPanelDetail), "settings status detail should not expose mojibake artifacts");
        string unavailableRuntimeDetail = WpfYoloSettingsPanelStatusPresentationService.BuildDetail(
            statusDetailSettings,
            null,
            new PythonModelRuntimeState(PythonModelRuntimeStateKind.NotInstalled, false, false, "missing runtime", "\uC2E4\uD589\uAE30 \uACBD\uB85C\uB97C \uC5F0\uACB0\uD558\uC138\uC694.", "connect"),
            new PythonCommunicationStatus(),
            pythonClientProcessRunning: false,
            null,
            string.Empty);
        AssertTrue(unavailableRuntimeDetail.Contains("\uD328\uD0A4\uC9C0: \uBAA8\uB378 \uC2E4\uD589\uAE30 \uC124\uCE58 \uD6C4 \uD655\uC778", StringComparison.Ordinal), "settings status detail should explain package checks wait for runtime installation");
        AssertTrue(unavailableRuntimeDetail.Contains("\uC2E4\uD589\uAE30 \uACBD\uB85C\uB97C \uC5F0\uACB0\uD558\uC138\uC694.", StringComparison.Ordinal), "settings status detail should keep runtime-unavailable guidance");
        AssertTrue(yoloSettingsPanelStatusSource.Contains("WpfYoloSettingsPanelStatusPresentationService.BuildDetail", StringComparison.Ordinal), "YOLO settings panel status shell should delegate detail text to the presentation service");
        AssertTrue(!yoloSettingsPanelStatusSource.Contains("detail.AppendLine", StringComparison.Ordinal), "YOLO settings panel status shell should not assemble operator-facing detail lines inline");
        AssertTrue(!yoloSettingsPanelStatusSource.Contains("AppendPythonWorkerStatus", StringComparison.Ordinal), "YOLO settings panel status shell should not own Python worker status wording");
        AssertTrue(yoloSettingsPanelStatusPresentationSource.Contains("BuildDetail", StringComparison.Ordinal), "YOLO settings status presentation service should own detail text building");
        AssertTrue(yoloSettingsPanelStatusPresentationSource.Contains("\uCD94\uB860 \uC2E4\uD589\uAE30:", StringComparison.Ordinal), "YOLO settings status presentation service should own worker status labels");
        AssertTrue(!ContainsVisibleMojibakeArtifact(yoloSettingsPanelStatusPresentationSource), "YOLO settings status presentation service should not contain visible mojibake artifacts");
        AssertTrue(shellSource.Contains("ApplyRuntimeConnectionResult", StringComparison.Ordinal), "runtime-profile action adapter should apply connection results through the ViewModel");
        AssertTrue(!shellSource.Contains("SaveYoloSettingsButton.IsEnabled", StringComparison.Ordinal), "WPF shell should not directly enable the YOLO model settings save button on the normal path");
        AssertTrue(!shellSource.Contains("ResetYoloSettingsButton.IsEnabled", StringComparison.Ordinal), "WPF shell should not directly enable the YOLO model settings reset button on the normal path");

        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        WpfLabelingShellWindow window = new WpfLabelingShellWindow();
        try
        {
            AssertTrue(window.FindName("YoloModelSettingsPanelControl") is WpfYoloModelSettingsPanel, "WPF YOLO model settings user control was not registered");
            var yoloPanel = (WpfYoloModelSettingsPanel)window.FindName("YoloModelSettingsPanelControl");
            AssertTrue(yoloPanel.ViewModel != null, "WPF YOLO model settings view model was not created");
            AssertTrue(yoloPanel.SummaryPanel != null, "WPF YOLO model settings summary panel should be exposed by the UserControl adapter");
            AssertTrue(yoloPanel.AdvancedSettingsExpander != null, "WPF YOLO advanced settings expander should be exposed by the UserControl adapter");
            AssertTrue(!yoloPanel.AdvancedSettingsExpander.IsExpanded, "WPF YOLO advanced settings should stay collapsed by default");
            AssertTrue(window.FindName("YoloInspectionModelQuickPanel") is System.Windows.Controls.Border, "WPF YOLO inspection-model picker should be registered outside advanced settings");
            AssertTrue(window.FindName("YoloWeightsPathBox") is System.Windows.Controls.TextBox, "WPF YOLO weights path proxy was not registered");
            AssertTrue(window.FindName("YoloModelEngineBox") is System.Windows.Controls.ComboBox, "WPF YOLO model engine selector was not registered");
            AssertTrue(window.FindName("YoloProjectRootBox") is System.Windows.Controls.TextBox, "WPF YOLO project path proxy was not registered");
            AssertTrue(window.FindName("YoloInferenceImageSizeBox") is System.Windows.Controls.TextBox, "WPF YOLO inference image-size proxy was not registered");
            AssertTrue(window.FindName("YoloMaxCandidatesBox") is System.Windows.Controls.TextBox, "WPF YOLO max-candidates proxy was not registered");
            AssertTrue(window.FindName("YoloAutoStartCheckBox") is System.Windows.Controls.CheckBox, "WPF YOLO auto-start proxy was not registered");
            AssertTrue(window.FindName("SaveYoloSettingsButton").GetType().FullName == "Wpf.Ui.Controls.Button", "WPF YOLO settings save button should use WPF-UI button");
            AssertTrue(window.FindName("ResetYoloSettingsButton").GetType().FullName == "Wpf.Ui.Controls.Button", "WPF YOLO settings reset button should use WPF-UI button");
            AssertTrue(window.FindName("YoloRuntimeInstallPackageButton").GetType().FullName == "Wpf.Ui.Controls.Button", "WPF YOLO runtime install button should be registered");
            AssertTrue(window.FindName("YoloRuntimeUninstallPackageButton").GetType().FullName == "Wpf.Ui.Controls.Button", "WPF YOLO runtime uninstall button should be registered separately");
        }
        finally
        {
            window.Close();
        }

        int runtimeProfileSelectionCount = 0;
        string selectedRuntimeProfile = string.Empty;
        var directSelectionViewModel = new WpfYoloModelSettingsPanelViewModel();
        directSelectionViewModel.ConfigureCommands(
            null,
            null,
            null,
            null,
            null,
            null,
            null,
            engine =>
            {
                runtimeProfileSelectionCount++;
                selectedRuntimeProfile = engine;
            });
        var directSelectionPanel = new WpfYoloModelSettingsPanel
        {
            DataContext = directSelectionViewModel
        };
        var directSelectionHost = new System.Windows.Window
        {
            Content = directSelectionPanel,
            Width = 900,
            Height = 700,
            ShowInTaskbar = false
        };
        try
        {
            directSelectionHost.Show();
            PumpWpfDispatcher(TimeSpan.FromMilliseconds(120));
            directSelectionPanel.SettingsExpander.IsExpanded = true;
            directSelectionPanel.AdvancedSettingsExpander.IsExpanded = true;
            directSelectionHost.UpdateLayout();
            InvokePrivateResult<object>(
                directSelectionPanel,
                "YoloModelEngineBox_DropDownOpened",
                directSelectionPanel.ModelEngineBox,
                EventArgs.Empty);
            directSelectionPanel.ModelEngineBox.SelectedItem = PythonModelSettings.EngineYoloV8;
            InvokePrivateResult<object>(
                directSelectionPanel,
                "YoloModelEngineBox_DropDownClosed",
                directSelectionPanel.ModelEngineBox,
                EventArgs.Empty);
            AssertEqual(1, runtimeProfileSelectionCount);
            AssertEqual(PythonModelSettings.EngineYoloV8, selectedRuntimeProfile);
        }
        finally
        {
            directSelectionHost.Close();
        }
    }

    private static void TestWpfTrainingSettingsPanelDeclaresControls()
    {
        string xamlPath = Path.Combine(FindRepositoryRoot(), "0. UI", "9) WPF", "Views", "WpfTrainingSettingsPanel.xaml");
        XDocument xaml = XDocument.Load(xamlPath);
        XName xName = XName.Get("Name", "http://schemas.microsoft.com/winfx/2006/xaml");

        AssertNamedXamlBinding(xaml, xName, "RefreshTrainingReadinessButton", "Command", "RefreshReadinessCommand");
        AssertNamedXamlBinding(xaml, xName, "StartTrainingButton", "Command", "StartTrainingCommand");
        AssertNamedXamlBinding(xaml, xName, "StopTrainingButton", "Command", "StopTrainingCommand");
        AssertNamedXamlBinding(xaml, xName, "ApplyFastTrainingPresetButton", "Command", "ApplyFastRecommendationCommand");
        AssertNamedXamlBinding(xaml, xName, "ApplyFastTrainingPresetButton", "IsEnabled", "IsApplyFastRecommendationEnabled");
        AssertNamedXamlBinding(xaml, xName, "ApplyFinalVerificationPresetButton", "Command", "ApplyFinalVerificationPresetCommand");
        AssertNamedXamlBinding(xaml, xName, "ApplyFinalVerificationPresetButton", "IsEnabled", "IsApplyFinalVerificationPresetEnabled");
        AssertNamedXamlBinding(xaml, xName, "ApplyFinalVerificationPresetButton", "Content", "FinalVerificationPresetActionText");
        AssertNamedXamlBinding(xaml, xName, "ApplyFinalVerificationPresetButton", "ToolTip", "FinalVerificationPresetToolTipText");
        AssertNamedXamlBinding(xaml, xName, "RefreshTrainingReadinessButton", "IsEnabled", "IsRefreshReadinessEnabled");
        AssertNamedXamlBinding(xaml, xName, "StartTrainingButton", "IsEnabled", "IsStartTrainingEnabled");
        AssertNamedXamlBinding(xaml, xName, "StopTrainingButton", "IsEnabled", "IsStopTrainingEnabled");
        string trainingXamlSource = File.ReadAllText(xamlPath);
        AssertTrue(trainingXamlSource.Contains("AutomationProperties.AutomationId=\"StartTrainingButton\"", StringComparison.Ordinal), "WPF training start button should expose a stable AutomationId for real-EXE guide chip testing");
        AssertTrue(trainingXamlSource.Contains("AutomationProperties.AutomationId=\"ApplyFastTrainingPresetButton\"", StringComparison.Ordinal), "WPF training fast recommendation button should expose a stable AutomationId for real-EXE testing");
        AssertTrue(trainingXamlSource.Contains("AutomationProperties.AutomationId=\"ApplyFinalVerificationPresetButton\"", StringComparison.Ordinal), "WPF final-verification preset should expose a stable AutomationId for real-EXE testing");
        AssertNamedXamlBinding(xaml, xName, "TrainingSettingsSummaryTitleText", "Text", "TrainingSettingsSummaryTitleText");
        AssertNamedXamlBinding(xaml, xName, "TrainingSettingsSummaryModelText", "Text", "TrainingSettingsSummaryModelText");
        AssertNamedXamlBinding(xaml, xName, "TrainingSettingsSummaryRuntimeText", "Text", "TrainingSettingsSummaryRuntimeText");
        AssertNamedXamlBinding(xaml, xName, "TrainingSettingsSummarySplitText", "Text", "TrainingSettingsSummarySplitText");
        AssertNamedXamlBinding(xaml, xName, "TrainingSettingsSummaryActionText", "Text", "TrainingSettingsSummaryActionText");
        AssertTrue(trainingXamlSource.Contains("AutomationProperties.AutomationId=\"PostTrainingModelActionPanel\"", StringComparison.Ordinal), "WPF training settings should expose post-training actions as a stable AutomationId for visual smoke checks");
        AssertNamedXamlBinding(xaml, xName, "PostTrainingModelActionTitleText", "Text", "PostTrainingModelActionTitleText");
        AssertNamedXamlBinding(xaml, xName, "PostTrainingModelStatusText", "Text", "PostTrainingModelStatusText");
        AssertNamedXamlBinding(xaml, xName, "PostTrainingModelDetailText", "Text", "PostTrainingModelDetailText");
        AssertNamedXamlBinding(xaml, xName, "ReviewTrainedModelButton", "Command", "ReviewTrainedModelCommand");
        AssertNamedXamlBinding(xaml, xName, "ReviewTrainedModelButton", "IsEnabled", "IsReviewTrainedModelEnabled");
        AssertNamedXamlBinding(xaml, xName, "ReviewTrainedModelButton", "ToolTip", "ReviewTrainedModelToolTip");
        AssertNamedXamlBinding(xaml, xName, "ReviewTrainedModelButtonText", "Text", "ReviewTrainedModelActionText");
        AssertNamedXamlBinding(xaml, xName, "ConfirmTrainedModelButton", "Command", "ConfirmTrainedModelCommand");
        AssertNamedXamlBinding(xaml, xName, "ConfirmTrainedModelButton", "IsEnabled", "IsConfirmTrainedModelEnabled");
        AssertNamedXamlBinding(xaml, xName, "ConfirmTrainedModelButton", "ToolTip", "ConfirmTrainedModelToolTip");
        AssertNamedXamlBinding(xaml, xName, "ConfirmTrainedModelButtonText", "Text", "ConfirmTrainedModelActionText");
        AssertNamedXamlBinding(xaml, xName, "RunYoloEngineComparisonButton", "Command", "RunYoloEngineComparisonCommand");
        AssertNamedXamlBinding(xaml, xName, "RunYoloEngineComparisonButton", "IsEnabled", "IsRunYoloEngineComparisonEnabled");
        AssertNamedXamlBinding(xaml, xName, "RunYoloEngineComparisonButton", "ToolTip", "RunYoloEngineComparisonToolTipText");
        AssertNamedXamlBinding(xaml, xName, "RunYoloEngineComparisonButtonText", "Text", "RunYoloEngineComparisonActionText");
        AssertNamedXamlBinding(xaml, xName, "TrainingAdvancedSettingsExpander", "Header", "AdvancedTrainingSettingsHeaderText");
        AssertTrue(trainingXamlSource.IndexOf("TrainingSettingsSummaryPanel", StringComparison.Ordinal) < trainingXamlSource.IndexOf("TrainingAdvancedSettingsExpander", StringComparison.Ordinal), "WPF training settings summary should appear before advanced parameter editors");
        AssertTrue(trainingXamlSource.IndexOf("TrainingProgressText", StringComparison.Ordinal) < trainingXamlSource.IndexOf("PostTrainingModelActionPanel", StringComparison.Ordinal), "WPF post-training actions should stay near the training progress result");
