            {
                DataYamlFilePath = @"D:\external\segment\data.yaml",
                DatasetPurpose = LabelingDatasetPurpose.Segmentation,
                UseForTraining = true
            });
        AssertEqual("YOLOv8 SEG", externalSegmentationTrainingViewModel.SelectedTrainingModel);
        AssertTrue(externalSegmentationTrainingViewModel.TrainingSettingsSummarySplitText.Contains("외부 data.yaml", StringComparison.Ordinal), "external native data.yaml should replace internal split wording in training summary");
        AssertTrue(externalSegmentationTrainingViewModel.TrainingSettingsSummaryActionText.Contains("외부 data.yaml", StringComparison.Ordinal), "external native data.yaml should state that its split stays selected until explicitly cleared");
        var yolo8DetectionTrainingViewModel = new WpfTrainingSettingsPanelViewModel();
        yolo8DetectionTrainingViewModel.LoadFrom(
            new TrainingSettings { Cfg = "yolov5s", Weight = "yolov5s" },
            new YoloDatasetSettings(),
            new PythonModelSettings { ModelEngine = PythonModelSettings.EngineYoloV8 },
            LabelingDatasetPurpose.ObjectDetection);
            AssertEqual("YOLOv8 Detect", yolo8DetectionTrainingViewModel.SelectedTrainingModel);
            AssertEqual("yolov8n.pt", yolo8DetectionTrainingViewModel.SelectedTrainingWeight);
            AssertTrue(!yolo8DetectionTrainingViewModel.IsTrainingModelSelectionEnabled, "YOLOv8 detection training should derive its model and starting weight from the selected runtime");
            AssertTrue(yolo8DetectionTrainingViewModel.RunYoloEngineComparisonActionText.Contains("v5 vs v8", StringComparison.Ordinal), "YOLOv8 selection should retain the existing v5/v8 comparison action");
            yolo8DetectionTrainingViewModel.ApplyModelEngineSelection(PythonModelSettings.EngineYolo11);
            AssertEqual("YOLO11 Detect", yolo8DetectionTrainingViewModel.SelectedTrainingModel);
            AssertEqual("yolo11n.pt", yolo8DetectionTrainingViewModel.SelectedTrainingWeight);
            AssertTrue(yolo8DetectionTrainingViewModel.RunYoloEngineComparisonActionText.Contains("v8 vs v11", StringComparison.Ordinal), "YOLO11 selection should expose the v8/v11 comparison action without adding a second control");
            AssertTrue(yolo8DetectionTrainingViewModel.RunYoloEngineComparisonToolTipText.Contains("YOLO11", StringComparison.Ordinal), "YOLO11 comparison action should explain the selected engine pair");
        var anomalyTrainingViewModel = new WpfTrainingSettingsPanelViewModel();
        anomalyTrainingViewModel.LoadFrom(
            new TrainingSettings { Cfg = "yolov5s", Weight = "yolov5s" },
            new YoloDatasetSettings(),
            new PythonModelSettings { ModelEngine = PythonModelSettings.EngineYoloV5 },
            LabelingDatasetPurpose.AnomalyDetection);
        anomalyTrainingViewModel.ApplyModelEngineSelection(PythonModelSettings.EngineYoloV8);
        AssertEqual("YOLOv8 Classify", anomalyTrainingViewModel.SelectedTrainingModel);
        AssertEqual("yolov8n-cls.pt", anomalyTrainingViewModel.SelectedTrainingWeight);
        AssertTrue(anomalyTrainingViewModel.TrainingSettingsSummaryModelText.Contains("YOLOv8 Classify", StringComparison.Ordinal), "anomaly training summary should identify the classification task immediately after a runtime selection");
        AssertTrue(anomalyTrainingViewModel.TrainingSettingsSummaryModelText.Contains("yolov8n-cls.pt", StringComparison.Ordinal), "anomaly training summary should identify the classification seed immediately after a runtime selection");
        bool reviewTrainedModelRequested = false;
        bool confirmTrainedModelRequested = false;
        bool engineComparisonRequested = false;
        trainingSummaryViewModel.ConfigureCommands(
            null,
            null,
            null,
