    private static void TestWpfCanvasDetectionOverlayUsesThemeResources()
    {
        string root = FindRepositoryRoot();
        string canvasXamlPath = Path.Combine(root, "0. UI", "9) WPF", "Views", "WpfCanvasPanel.xaml");
        XDocument canvasXaml = XDocument.Load(canvasXamlPath);
        XName xName = XName.Get("Name", "http://schemas.microsoft.com/winfx/2006/xaml");

        XElement FindElement(string localName, string controlName)
        {
            return canvasXaml.Descendants()
                .FirstOrDefault(element => string.Equals(element.Name.LocalName, localName, StringComparison.Ordinal)
                    && string.Equals((string)element.Attribute(xName), controlName, StringComparison.Ordinal));
        }

        XElement overlay = FindElement("Border", "DetectionResultOverlay");
        XElement selectedBorder = FindElement("Border", "DetectionOverlaySelectedBorder");
        XElement titleText = FindElement("TextBlock", "DetectionOverlayTitleText");
        XElement summaryText = FindElement("TextBlock", "DetectionOverlaySummaryText");
        XElement selectedText = FindElement("TextBlock", "DetectionOverlaySelectedText");
        XElement detailText = FindElement("TextBlock", "DetectionOverlayDetailText");
        XElement mainCanvas = FindElement("RoiImageCanvasView", "MainCanvasView");
        XElement smartMaskPromptBar = FindElement("Border", "CanvasSmartMaskPromptBar");
        XElement smartMaskOverlayLayer = FindElement("Canvas", "CanvasSmartMaskOverlayLayer");
        XElement annotationToolBarItems = FindElement("WrapPanel", "CanvasAnnotationToolBarItems");

        AssertNamedXamlBinding(canvasXaml, xName, "DetectionResultOverlay", "Visibility", "DetectionOverlayVisibility");
        AssertNamedXamlBinding(canvasXaml, xName, "DetectionOverlaySummaryText", "Text", "DetectionOverlaySummaryText");
        AssertNamedXamlBinding(canvasXaml, xName, "DetectionOverlaySelectedText", "Text", "DetectionOverlaySelectedText");
        AssertNamedXamlBinding(canvasXaml, xName, "DetectionOverlayDetailText", "Text", "DetectionOverlayDetailText");
        AssertNamedXamlBinding(canvasXaml, xName, "DetectionOverlayActionPanel", "Visibility", "DetectionOverlayActionsVisibility");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayPreviousCandidateButton", "Command", "PreviousCandidateCommand");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayPreviousCandidateButton", "IsEnabled", "IsPreviousCandidateEnabled");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayFocusCandidateButton", "Command", "FocusCandidateCommand");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayFocusCurrentLabelButton", "Command", "FocusCurrentLabelCommand");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayFocusCurrentLabelButton", "IsEnabled", "IsFocusCurrentLabelEnabled");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayNextCandidateButton", "Command", "NextCandidateCommand");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayNextCandidateButton", "IsEnabled", "IsNextCandidateEnabled");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayConfirmSelectedCandidateButton", "Command", "ConfirmSelectedCommand");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlayConfirmSelectedCandidateButton", "IsEnabled", "IsConfirmSelectedEnabled");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlaySkipSelectedCandidateButton", "Command", "SkipSelectedCommand");
        AssertNamedXamlBinding(canvasXaml, xName, "CanvasOverlaySkipSelectedCandidateButton", "IsEnabled", "IsSkipSelectedEnabled");
        AssertEqual("{StaticResource DetectionOverlayPanelStyle}", (string)overlay.Attribute("Style"));
        AssertEqual("{StaticResource DetectionOverlaySelectedBorderStyle}", (string)selectedBorder.Attribute("Style"));
        AssertEqual("Collapsed", (string)selectedBorder.Attribute("Visibility"));
        AssertEqual("{DynamicResource DetectionOverlayTitleTextBrush}", (string)titleText.Attribute("Foreground"));
        AssertEqual("{StaticResource DetectionOverlaySummaryTextStyle}", (string)summaryText.Attribute("Style"));
        AssertEqual("{DynamicResource DetectionOverlaySelectedTextBrush}", (string)selectedText.Attribute("Foreground"));
        AssertEqual("{DynamicResource DetectionOverlayDetailTextBrush}", (string)detailText.Attribute("Foreground"));
        string canvasSource = File.ReadAllText(canvasXamlPath);
        string canvasCodeBehind = File.ReadAllText(Path.Combine(root, "0. UI", "9) WPF", "Views", "WpfCanvasPanel.xaml.cs"));
        AssertTrue(canvasSource.Contains("DetectionOverlayStatusKey", StringComparison.Ordinal), "WPF detection result overlay should style itself from the canvas ViewModel state");
        AssertTrue(canvasSource.Contains("DetectionOverlayDuplicateAccentBrush", StringComparison.Ordinal), "WPF detection result overlay should expose duplicate candidate styling");
        AssertTrue(canvasSource.Contains("DetectionOverlayReviewAccentBrush", StringComparison.Ordinal), "WPF detection result overlay should expose review-needed candidate styling");
        AssertTrue(canvasSource.Contains("DetectionOverlayActionButtonStyle", StringComparison.Ordinal), "WPF detection result overlay should expose candidate action buttons on the canvas card");
        AssertTrue(canvasSource.Contains("x:Name=\"DetectionOverlayActionButtonChrome\"", StringComparison.Ordinal)
            && canvasSource.Contains("Value=\"{DynamicResource ToolbarButtonHoverBrush}\"", StringComparison.Ordinal)
            && canvasSource.Contains("<Trigger Property=\"IsPressed\" Value=\"True\">", StringComparison.Ordinal)
            && canvasSource.Contains("<Trigger Property=\"IsKeyboardFocusWithin\" Value=\"True\">", StringComparison.Ordinal)
            && canvasSource.Contains("Value=\"{DynamicResource PrimaryTextBrush}\"", StringComparison.Ordinal)
            && canvasSource.Contains("Value=\"{DynamicResource DisabledTextBrush}\"", StringComparison.Ordinal),
            "WPF detection result actions should keep dark themed hover, pressed, focus, and disabled states");
        AssertTrue(canvasSource.Contains("<Border x:Name=\"DetectionResultOverlay\"", StringComparison.Ordinal)
            && canvasSource.Contains("Grid.Row=\"2\"", StringComparison.Ordinal)
            && canvasSource.Contains("Height=\"27\"", StringComparison.Ordinal)
            && canvasSource.Contains("HorizontalAlignment=\"Center\"", StringComparison.Ordinal),
            "WPF detection result summary should share the existing fixed-height layer strip instead of resizing the WindowsFormsHost canvas");
        AssertTrue(canvasSource.Contains("<Grid Grid.Row=\"7\">", StringComparison.Ordinal), "WPF main canvas should stay in the star-sized viewer row and remain independent of detection result visibility");
        AssertEqual("1", (string)mainCanvas.Attribute("Grid.Column"));
        AssertEqual("2", (string)overlay.Attribute("Grid.Row"));
        AssertEqual("27", (string)overlay.Attribute("Height"));
        AssertTrue(!canvasSource.Contains("Grid.Row=\"5\"", StringComparison.Ordinal), "WPF detection result visibility should not consume a separate auto row above the viewer");
        AssertEqual("1", (string)smartMaskOverlayLayer.Attribute("Grid.Row"));
        AssertEqual("3", (string)smartMaskOverlayLayer.Attribute("Grid.RowSpan"));
        AssertTrue(ReferenceEquals(smartMaskPromptBar.Parent, smartMaskOverlayLayer),
            "WPF Smart Mask session guidance should be measured by a non-sizing overlay layer");
        AssertEqual("{Binding ActualWidth, ElementName=CanvasSmartMaskOverlayLayer}", (string)smartMaskPromptBar.Attribute("Width"));
        AssertEqual("102", (string)smartMaskPromptBar.Attribute("MaxHeight"));
        AssertEqual("8,1", (string)smartMaskPromptBar.Attribute("Padding"));
        AssertEqual("{DynamicResource PanelBrush}", (string)smartMaskPromptBar.Attribute("Background"));
        AssertEqual("{DynamicResource AccentBrush}", (string)smartMaskPromptBar.Attribute("BorderBrush"));
        AssertEqual("29", (string)annotationToolBarItems.Attribute("ItemHeight"));
        AssertTrue(!canvasSource.Contains("<Border x:Name=\"CanvasSmartMaskPromptBar\"\r\n                    Grid.Row=", StringComparison.Ordinal),
            "WPF Smart Mask session guidance should not participate directly in grid row measurement");
        AssertTrue(canvasCodeBehind.Contains("DetectionOverlayTitleText.SetBinding", StringComparison.Ordinal)
            && canvasCodeBehind.Contains(nameof(WpfCanvasPanelViewModel.DetectionOverlayTitleText), StringComparison.Ordinal),
            "WPF detection result title should bind to the canvas ViewModel even though the legacy XAML title text is mojibake");
        AssertTrue(canvasSource.Contains("MaxWidth=\"420\"", StringComparison.Ordinal), "WPF detection result summary should cap width inside the existing layer strip");
        AssertTrue(canvasSource.Contains("MaxHeight=\"27\"", StringComparison.Ordinal), "WPF detection result summary should not increase the layer-strip height");
        AssertTrue(canvasSource.Contains("ToolTip=\"{Binding DetectionOverlayDetailText}\"", StringComparison.Ordinal), "WPF detection result overlay should keep the long candidate list available without drawing it over the image");
        AssertTrue(canvasSource.Contains("ClipToBounds=\"True\"", StringComparison.Ordinal), "WPF detection result overlay should not spill over the canvas when details are long");
        AssertTrue(canvasSource.Contains("x:Name=\"DetectionOverlaySelectedBorder\"", StringComparison.Ordinal)
            && canvasSource.Contains("Visibility=\"Collapsed\"", StringComparison.Ordinal),
            "WPF detection result details and decisions should remain in the candidate review panel instead of expanding the canvas strip");
        AssertTrue(!canvasSource.Contains("HorizontalAlignment=\"Stretch\"", StringComparison.Ordinal), "WPF detection result overlay should not stretch across the image inspection area");

        string candidateReviewSource = File.ReadAllText(Path.Combine(root, "0. UI", "9) WPF", "Views", "WpfCandidateReviewPanel.xaml"));
        AssertTrue(candidateReviewSource.Contains("AutomationProperties.AutomationId=\"ConfirmSelectedCandidateButton\"", StringComparison.Ordinal)
            && candidateReviewSource.Contains("x:Name=\"SkipSelectedCandidateButton\"", StringComparison.Ordinal),
            "WPF candidate review panel should remain the visible owner of candidate decisions after the canvas summary is compacted");

        string shellXaml = File.ReadAllText(Path.Combine(root, "0. UI", "9) WPF", "Views", "WpfLabelingShellWindow.xaml"));
        string shellSource = ReadWpfLabelingShellWindowSources();
        AssertTrue(shellSource.Contains("CanvasPanelViewModel.SetDetectionOverlay", StringComparison.Ordinal), "WPF shell should push detection overlay presentation through the canvas ViewModel");
        AssertTrue(shellSource.Contains("CanvasPanelViewModel.ClearDetectionOverlay", StringComparison.Ordinal), "WPF shell should clear detection overlay presentation through the canvas ViewModel");
        AssertTrue(shellSource.Contains("CanvasPanelViewModel.ConfigureCandidateReviewCommands", StringComparison.Ordinal), "WPF shell should reuse candidate review commands from the canvas result card");
        AssertTrue(shellSource.Contains("CanvasPanelViewModel.SetCandidateReviewState", StringComparison.Ordinal), "WPF shell should sync candidate review enabled state to the canvas result card");
        AssertTrue(!shellSource.Contains("DetectionResultOverlay.Visibility =", StringComparison.Ordinal), "WPF shell should not directly show or hide the detection result overlay");
        AssertTrue(!shellSource.Contains("DetectionOverlaySummaryText.Text =", StringComparison.Ordinal), "WPF shell should not directly write detection overlay summary text");
        AssertTrue(!shellSource.Contains("DetectionOverlaySelectedText.Text =", StringComparison.Ordinal), "WPF shell should not directly write detection overlay selected text");
        AssertTrue(!shellSource.Contains("DetectionOverlayDetailText.Text =", StringComparison.Ordinal), "WPF shell should not directly write detection overlay detail text");
        AssertTrue(!shellSource.Contains("ApplyDetectionOverlayStatusStyle", StringComparison.Ordinal), "WPF shell should not directly paint detection overlay status");
        foreach (string key in new[]
        {
            "DetectionOverlayBackgroundBrush",
            "DetectionOverlayBorderBrush",
            "DetectionOverlayTitleTextBrush",
            "DetectionOverlaySummaryTextBrush",
            "DetectionOverlaySelectedBackgroundBrush",
            "DetectionOverlaySelectedTextBrush",
            "DetectionOverlayDetailTextBrush"
        })
        {
            AssertTrue(shellXaml.Contains($"x:Key=\"{key}\"", StringComparison.Ordinal), $"WPF shell should declare theme resource: {key}");
            AssertTrue(shellSource.Contains($"SetThemeBrush(\"{key}\"", StringComparison.Ordinal), $"WPF shell should update theme resource: {key}");
        }
    }

    private static void TestWpfTrainingStatusSummaries()
    {
        var running = new PythonCommunicationStatus
        {
            LastTrainingState = "running",
            LastTrainingMessage = "epoch",
            LastTrainingProgressPercent = 42,
            LastTrainingEpoch = 2,
            LastTrainingTotalEpochs = 5
        };

        AssertTrue(InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingProgressSummary", running).Contains("42%", StringComparison.Ordinal), "running training progress should include percent");
        AssertEqual("\uC5D0\uD3ED 2/5", InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingEpochSummary", running));

        var accepted = new PythonCommunicationStatus
        {
            LastTrainingState = "started",
            LastTrainingMessage = "YOLO training accepted by worker."
        };

        string acceptedSummary = InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingProgressSummary", accepted);
        AssertTrue(acceptedSummary.Contains("\uBA85\uB839 \uC218\uB77D\uB428", StringComparison.Ordinal), "accepted training status should not look completed");
        AssertTrue(acceptedSummary.Contains("\uC5D0\uD3ED \uC2DC\uC791 \uC804", StringComparison.Ordinal), "accepted training status should explain that epoch has not started yet");
        AssertEqual("\uC5D0\uD3ED \uC2DC\uC791 \uC804", InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingEpochSummary", accepted));

        var failed = new PythonCommunicationStatus
        {
            LastTrainingState = "failed",
            LastTrainingMessage = "Training failed: process exited at the first training batch. On CPU the selected training size may be too large (model=yolov5x, weights=best.pt, image=640, batch=16). Try yolov5s, image 320, batch 4."
        };

        string failedSummary = InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingProgressSummary", failed);
        AssertTrue(failedSummary.Contains("yolov5s", StringComparison.OrdinalIgnoreCase), "failed training summary should include the safe model recommendation");
        AssertTrue(failedSummary.Contains("320", StringComparison.Ordinal), "failed training summary should include the safe image-size recommendation");
        AssertTrue(failedSummary.Contains("4", StringComparison.Ordinal), "failed training summary should include the safe batch recommendation");
        AssertTrue(WpfTrainingProgressPresentationService.BuildProgressSummary(failed).Contains("yolov5s", StringComparison.OrdinalIgnoreCase), "training progress presentation service should own the failed first-batch recommendation");
        AssertTrue(WpfTrainingProgressPresentationService.BuildStatusNoResponseRecovery("timeout").Action.Contains("\uC7AC\uC2DC\uC791", StringComparison.Ordinal), "training progress presentation service should own no-response recovery guidance");
        AssertTrue(WpfTrainingProgressPresentationService.BuildFailedRecovery("failed").Action.Contains("320", StringComparison.Ordinal), "training progress presentation service should own failed-training recovery guidance");

        var downloadGuardFailed = new PythonCommunicationStatus
        {
            LastTrainingState = "failed",
            LastTrainingMessage = "YOLO training could not start.",
            LastTrainingWeightsPath = "yolov8n-seg.pt",
            LastError = "TrainingWeightDownloadRequired: cache the file first"
        };

        string downloadGuardSummary = InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingProgressSummary", downloadGuardFailed);
        AssertTrue(downloadGuardSummary.Contains("\uD559\uC2B5 weight \uC900\uBE44 \uD544\uC694", StringComparison.Ordinal), "download guard training summary should explain that the training weight must be prepared");
        AssertTrue(downloadGuardSummary.Contains("yolov8n-seg.pt", StringComparison.Ordinal), "download guard training summary should show the blocked task weight filename");
        AssertTrue(!downloadGuardSummary.Contains("TrainingWeightDownloadRequired", StringComparison.Ordinal), "download guard training summary should not expose the raw worker error code");
        string downloadGuardDetail = WpfTrainingProgressPresentationService.BuildFailureDetail(downloadGuardFailed);
        AssertTrue(downloadGuardDetail.Contains("\uB2E4\uC6B4\uB85C\uB4DC", StringComparison.Ordinal), "download guard recovery detail should mention explicit download approval as an option");
        AssertTrue(!downloadGuardDetail.Contains("TrainingWeightDownloadRequired", StringComparison.Ordinal), "download guard recovery detail should not expose the raw worker error code");

        var clamped = new PythonCommunicationStatus
        {
            LastTrainingState = "completed",
            LastTrainingProgressPercent = 140,
            LastTrainingEpoch = 5
        };

        AssertTrue(InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingProgressSummary", clamped).Contains("100%", StringComparison.Ordinal), "completed training progress should clamp at 100 percent");
        AssertEqual("\uC5D0\uD3ED 5", InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingEpochSummary", clamped));
        AssertTrue(!string.IsNullOrWhiteSpace(InvokePrivateStaticResult<string>(typeof(WpfLabelingShellWindow), "BuildTrainingProgressSummary", new PythonCommunicationStatus())), "idle training progress should remain readable");
        AssertTrue(InvokePrivateStaticResult<bool>(typeof(WpfLabelingShellWindow), "IsTrainingStopAvailable", running), "running training status should allow stop");
        AssertTrue(InvokePrivateStaticResult<bool>(typeof(WpfLabelingShellWindow), "IsTrainingStopAvailable", accepted), "accepted training status should allow stop");
        AssertTrue(!InvokePrivateStaticResult<bool>(typeof(WpfLabelingShellWindow), "IsTrainingStopAvailable", clamped), "completed training status should not allow stop");
        AssertTrue(!InvokePrivateStaticResult<bool>(typeof(WpfLabelingShellWindow), "IsTrainingStopAvailable", new PythonCommunicationStatus()), "idle training status should not allow stop");

        string root = FindRepositoryRoot();
        string trainingProgressShellSource = File.ReadAllText(Path.Combine(root, "0. UI", "9) WPF", "Views", "WpfLabelingShellWindow.TrainingProgressStatus.cs"));
        string trainingProgressPresentationSource = File.ReadAllText(Path.Combine(root, "0. UI", "9) WPF", "Services", "Training", "WpfTrainingProgressPresentationService.cs"));
        AssertTrue(trainingProgressShellSource.Contains("WpfTrainingProgressPresentationService.BuildStatusNoResponseText", StringComparison.Ordinal), "training progress shell should delegate no-response wording to the presentation service");
        AssertTrue(trainingProgressShellSource.Contains("WpfTrainingProgressPresentationService.BuildFailedRecovery", StringComparison.Ordinal), "training progress shell should delegate failed-training recovery wording to the presentation service");
        AssertTrue(trainingProgressShellSource.Contains("BuildFailureDetail(status)", StringComparison.Ordinal), "training progress shell should pass the full training status into failure-detail presentation");
        AssertTrue(trainingProgressPresentationSource.Contains("BuildProgressSummary", StringComparison.Ordinal), "training progress presentation service should own progress summary wording");
        AssertTrue(!trainingProgressShellSource.Contains("\\uD559\\uC2B5 \\uC0C1\\uD0DC \\uC751\\uB2F5 \\uC5C6\\uC74C:", StringComparison.Ordinal), "training progress shell should not inline no-response status text");
        AssertTrue(!trainingProgressShellSource.Contains("\\uD559\\uC2B5 \\uC2E4\\uD328 - \\uC870\\uCE58 \\uD544\\uC694", StringComparison.Ordinal), "training progress shell should not inline failed-training recovery title");
        AssertTrue(!ContainsVisibleMojibakeArtifact(trainingProgressPresentationSource), "training progress presentation service should not contain visible mojibake artifacts");
    }

    private static void TestWpfTrainingReadinessPresentationService()
    {
        var data = new CData();
        data.ClassNamedList.Clear();
        data.ClassNamedList.Add(new CClassItem { Text = "Defect", DrawColor = Color.Red });

        var classMismatchReport = new YoloDatasetReadinessReport(
            new YoloDatasetValidationResult(Array.Empty<string>()),
            new YoloDatasetValidationResult(new[]
            {
                "data.yaml class count does not match project classes. yaml nc:0, project classes:1."
            }),
            new YoloDatasetStatistics());

        string mismatchText = WpfTrainingReadinessPresentationService.BuildStatusText(data, classMismatchReport);
        AssertTrue(mismatchText.Contains("학습 데이터 확인 필요", StringComparison.Ordinal), "training readiness should keep the blocking state visible");
        AssertTrue(mismatchText.Contains("클래스 목록과 data.yaml", StringComparison.Ordinal), "training readiness should translate class-count mismatch into an operator issue");
        AssertTrue(mismatchText.Contains("데이터셋 점검", StringComparison.Ordinal), "training readiness should include the next action");
        AssertTrue(mismatchText.Contains("클래스 1", StringComparison.Ordinal), "training readiness should keep the dataset scale visible");
        AssertTrue(!mismatchText.Contains("class count does not match", StringComparison.OrdinalIgnoreCase), "training readiness should not expose raw validator wording as the main UI message");

        var readyReport = new YoloDatasetReadinessReport(
            new YoloDatasetValidationResult(Array.Empty<string>()),
            new YoloDatasetValidationResult(Array.Empty<string>()),
            new YoloDatasetStatistics());
        string readyText = WpfTrainingReadinessPresentationService.BuildStatusText(data, readyReport);
        AssertTrue(readyText.Contains("학습 준비 완료", StringComparison.Ordinal), "training readiness should keep the ready state readable");
        AssertTrue(readyText.Contains("학습 0", StringComparison.Ordinal), "training readiness should keep count context even when statistics are empty");
        var anomalyReport = new AnomalyClassificationTrainingReadinessReport(
            Array.Empty<string>(),
            normalImageCount: 1,
            abnormalImageCount: 0,
            unreviewedImageCount: 2,
            new[] { AnomalyClassificationTrainingReadinessService.NeedsReviewedNormalAndAbnormalError });
        string anomalyText = WpfTrainingReadinessPresentationService.BuildAnomalyClassificationStatusText(anomalyReport);
        AssertTrue(anomalyText.Contains("\uD559\uC2B5 \uB370\uC774\uD130 \uD655\uC778 \uD544\uC694", StringComparison.Ordinal), "anomaly readiness should keep the blocking state visible");
        AssertTrue(anomalyText.Contains("\uC815\uC0C1", StringComparison.Ordinal)
            && anomalyText.Contains("\uC774\uC0C1", StringComparison.Ordinal),
            "anomaly readiness should explain reviewed normal and abnormal image requirements");
        AssertTrue(anomalyText.Contains("normal 1", StringComparison.Ordinal)
            && anomalyText.Contains("abnormal 0", StringComparison.Ordinal)
            && anomalyText.Contains("unreviewed 2", StringComparison.Ordinal),
            "anomaly readiness should include current review counts");
        AssertTrue(!anomalyText.Contains(AnomalyClassificationTrainingReadinessService.NeedsReviewedNormalAndAbnormalError, StringComparison.Ordinal),
            "anomaly readiness should not expose raw readiness keys");

        var anomalyTrainSplitReport = new AnomalyClassificationTrainingReadinessReport(
            Array.Empty<string>(),
            normalImageCount: 1,
            abnormalImageCount: 1,
            unreviewedImageCount: 0,
            new[] { AnomalyClassificationTrainingReadinessService.NeedsTrainNormalAndAbnormalError },
            trainNormalImageCount: 1,
            trainAbnormalImageCount: 0);
        string anomalyTrainSplitText = WpfTrainingReadinessPresentationService.BuildAnomalyClassificationStatusText(anomalyTrainSplitReport);
        AssertTrue(anomalyTrainSplitText.Contains("train", StringComparison.OrdinalIgnoreCase)
            && anomalyTrainSplitText.Contains("\uC815\uC0C1", StringComparison.Ordinal)
            && anomalyTrainSplitText.Contains("\uC774\uC0C1", StringComparison.Ordinal),
            "anomaly readiness should explain train split normal and abnormal image requirements");
        AssertTrue(anomalyTrainSplitText.Contains("train normal 1", StringComparison.Ordinal)
            && anomalyTrainSplitText.Contains("train abnormal 0", StringComparison.Ordinal),
            "anomaly readiness should include train split class counts");
        AssertTrue(!anomalyTrainSplitText.Contains(AnomalyClassificationTrainingReadinessService.NeedsTrainNormalAndAbnormalError, StringComparison.Ordinal),
            "anomaly train split readiness should not expose raw readiness keys");

        var segmentationSplitReport = new YoloDatasetReadinessReport(
            new YoloDatasetValidationResult(Array.Empty<string>()),
            new YoloDatasetValidationResult(new[] { "train image directory has no supported images." }),
            new YoloDatasetStatistics(),
            LabelingDatasetPurpose.Segmentation);
        data.ProjectSettings.DatasetPurpose = LabelingDatasetPurpose.Segmentation;
        string segmentationSplitText = WpfTrainingReadinessPresentationService.BuildStatusText(data, segmentationSplitReport);
        AssertTrue(segmentationSplitText.Contains("\uC138\uADF8\uBA58\uD14C\uC774\uC158", StringComparison.Ordinal), "segmentation readiness should identify segmentation training");
        AssertTrue(segmentationSplitText.Contains("train", StringComparison.Ordinal)
            && segmentationSplitText.Contains("valid", StringComparison.Ordinal),
            "segmentation readiness should explain that both train and valid splits need saved labels");
        AssertTrue(segmentationSplitText.Contains("\uB9C8\uC2A4\uD06C", StringComparison.Ordinal), "segmentation readiness should mention saved mask labels");
        AssertTrue(!segmentationSplitText.Contains("train image directory has no supported images", StringComparison.OrdinalIgnoreCase),
            "segmentation readiness should not expose raw validator wording");

        string segmentJsonFailureText = WpfTrainingReadinessPresentationService.BuildFriendlyIssueSummary(
            "YOLOv8 segmentation training needs polygon segment JSON files that can be converted to labels/*.txt.");
        AssertTrue(segmentJsonFailureText.Contains("polygon segment JSON", StringComparison.Ordinal), "YOLOv8 segment-label export failure should keep the required artifact type visible");
        AssertTrue(segmentJsonFailureText.Contains("\uBE0C\uB7EC\uC2DC", StringComparison.Ordinal)
            || segmentJsonFailureText.Contains("\uD3F4\uB9AC\uACE4", StringComparison.Ordinal),
            "YOLOv8 segment-label export failure should guide the operator back to brush/polygon labels");
        AssertTrue(!segmentJsonFailureText.Contains("needs polygon segment JSON files", StringComparison.OrdinalIgnoreCase),
            "YOLOv8 segment-label export failure should not expose raw service wording");
    }

    private static void TestWpfInferenceStatusPresentationServiceReadable()
    {
        string root = CreateTempRoot();
        try
        {
            string weightsPath = Path.Combine(root, "runs", "train", "exp7", "weights", "best.pt");
            Directory.CreateDirectory(Path.GetDirectoryName(weightsPath));
            File.WriteAllText(weightsPath, "weights");

            var settings = new PythonModelSettings
            {
                ModelEngine = PythonModelSettings.EngineYoloV5,
                WeightsPath = weightsPath
            };
            string idleText = WpfInferenceStatusPresentationService.BuildStatusText("\uB300\uAE30", settings, hasPendingModelCandidate: false);
            AssertTrue(idleText.Contains("\uB300\uAE30", StringComparison.Ordinal), "inference status should keep the base state");
            AssertTrue(idleText.Contains("\uAC80\uC0AC \uBAA8\uB378", StringComparison.Ordinal), "inference status should show the current inspection model in readable Korean");
            AssertTrue(idleText.Contains("YOLOv5", StringComparison.Ordinal), "inference status should show the active runtime family beside the inspection model");
            AssertTrue(idleText.Contains("best.pt", StringComparison.Ordinal), "inference status should show the weights file name");

            string candidateText = WpfInferenceStatusPresentationService.BuildStatusText("\uAC80\uD1A0 \uB300\uAE30", settings, hasPendingModelCandidate: true);
            AssertTrue(candidateText.Contains("\uBAA8\uB378 \uD6C4\uBCF4", StringComparison.Ordinal), "inference status should distinguish an unsaved trained model candidate in readable Korean");
            AssertTrue(candidateText.Contains("YOLOv5", StringComparison.Ordinal), "pending model candidate status should keep the selected runtime family visible");

            string missingText = WpfInferenceStatusPresentationService.BuildStatusText("\uB300\uAE30", new PythonModelSettings { WeightsPath = Path.Combine(root, "missing.pt") }, hasPendingModelCandidate: false);
            AssertTrue(missingText.Contains("\uAC80\uC0AC \uBAA8\uB378 \uC5C6\uC74C", StringComparison.Ordinal), "inference status should tell the user when no inspection model is available in readable Korean");

            string readyRuntimeStatus = WpfInferenceStatusPresentationService.BuildRuntimePythonStatus(
                new PythonModelValidationResult(Array.Empty<string>(), Array.Empty<string>()),
                new PythonModelRuntimeState(PythonModelRuntimeStateKind.Ready, true, true, "fallback", "detail", "next"));
            AssertEqual("\uCD94\uB860: \uC900\uBE44 \uC644\uB8CC", readyRuntimeStatus);
            string fallbackRuntimeStatus = WpfInferenceStatusPresentationService.BuildRuntimePythonStatus(
                new PythonModelValidationResult(new[] { "missing weights" }, Array.Empty<string>()),
                new PythonModelRuntimeState(PythonModelRuntimeStateKind.Incomplete, false, false, "\uB77C\uBCA8\uB9C1 \uAC00\uB2A5", "detail", "next"));
            AssertEqual("\uB77C\uBCA8\uB9C1 \uAC00\uB2A5", fallbackRuntimeStatus);

            string toolTip = WpfInferenceStatusPresentationService.BuildToolTip("\uB300\uAE30", settings, hasPendingModelCandidate: false);
            AssertTrue(toolTip.Contains("\uCD94\uB860 \uC0C1\uD0DC", StringComparison.Ordinal), "inference status tooltip should keep a readable status label");
            AssertTrue(toolTip.Contains("\uC2E4\uD589\uAE30: YOLOv5", StringComparison.Ordinal), "inference status tooltip should show the active runtime family");
            AssertTrue(toolTip.Contains(weightsPath, StringComparison.Ordinal), "inference status tooltip should keep the full model path");

            string statusChipText = WpfInferenceStatusPresentationService.BuildInspectionModelStatusText(settings, hasPendingModelCandidate: false);
            AssertTrue(statusChipText.Contains("\uAC80\uC0AC \uBAA8\uB378:", StringComparison.Ordinal), "inspection-model status chip should keep the explicit role label");
            AssertTrue(statusChipText.Contains("YOLOv5", StringComparison.Ordinal), "inspection-model status chip should include the runtime family");
            AssertTrue(statusChipText.Contains("best.pt", StringComparison.Ordinal), "inspection-model status chip should include the weights file");
            AssertEqual("YOLOv5 / exp7" + Path.DirectorySeparatorChar + "best.pt", WpfInferenceStatusPresentationService.BuildRuntimeModelLabel(settings));
            string exportedWeightsPath = Path.Combine(root, "circular-disk-yolov8n-e30", "best.pt");
            Directory.CreateDirectory(Path.GetDirectoryName(exportedWeightsPath));
            File.WriteAllText(exportedWeightsPath, "weights");
            settings.WeightsPath = exportedWeightsPath;
            AssertEqual(
                "YOLOv5 / circular-disk-yolov8n-e30" + Path.DirectorySeparatorChar + "best.pt",
                WpfInferenceStatusPresentationService.BuildRuntimeModelLabel(settings));
            settings.WeightsPath = weightsPath;
            string comparisonSourceText = WpfInferenceStatusPresentationService.BuildModelComparisonSourceText(
                settings,
                weightsPath,
                Path.Combine(root, "runs", "train", "candidate", "weights", "best.pt"));
            AssertTrue(comparisonSourceText.Contains("\uBE44\uAD50 \uB300\uC0C1", StringComparison.Ordinal), "model comparison source text should label the compared models");
            AssertTrue(comparisonSourceText.Contains("\uD604\uC7AC \uAC80\uC0AC YOLOv5", StringComparison.Ordinal), "model comparison source text should show the current inspection runtime");
            AssertTrue(comparisonSourceText.Contains("\uD559\uC2B5 \uD6C4\uBCF4 YOLOv5", StringComparison.Ordinal), "model comparison source text should show the trained candidate runtime");

            string candidateStatusChipText = WpfInferenceStatusPresentationService.BuildInspectionModelStatusText(settings, hasPendingModelCandidate: true);
            AssertTrue(candidateStatusChipText.Contains("\uAC80\uC0AC \uD6C4\uBCF4:", StringComparison.Ordinal), "inspection-model status chip should distinguish a pending model candidate");
            AssertTrue(candidateStatusChipText.Contains("YOLOv5", StringComparison.Ordinal), "pending inspection-model chip should include the runtime family");

            settings.ModelEngine = PythonModelSettings.EngineYolo11;
            settings.WeightsPath = Path.Combine(root, "yolo11n.pt");
            File.WriteAllText(settings.WeightsPath, "weights");
            AssertEqual("YOLO11 / yolo11n.pt", WpfInferenceStatusPresentationService.BuildRuntimeModelLabel(settings));

            AssertEqual("\uCD94\uB860 \uC900\uBE44 \uC911...", WpfInferenceStatusPresentationService.BuildInteractivePreparingCommandStatus());
            AssertEqual("\uD604\uC7AC \uC774\uBBF8\uC9C0 \uCD94\uB860 \uC900\uBE44 \uC911", WpfInferenceStatusPresentationService.BuildInteractivePreparingInferenceStatus());
            var successResult = new YoloWorkerSmokeTestResult
            {
                Succeeded = true,
                CandidateCount = 2
            };
            AssertEqual(
                "\uCD94\uB860 \uC644\uB8CC: \uD6C4\uBCF4 2\uAC1C / 1.2s",
                WpfInferenceStatusPresentationService.BuildInteractiveCompletionCommandStatus(successResult, "1.2s"));
            AssertEqual(
                "\uC644\uB8CC: \uD6C4\uBCF4 2\uAC1C / 1.2s",
                WpfInferenceStatusPresentationService.BuildInteractiveCompletionInferenceStatus(successResult, "1.2s"));
            AssertTrue(
                WpfInferenceStatusPresentationService.BuildInteractiveCompletionLog(successResult, "1.2s", "\uCD94\uB860 \uC2E4\uD589\uAE30").Contains("\uACBD\uB85C \uCD94\uB860 \uC2E4\uD589\uAE30", StringComparison.Ordinal),
                "single-image success log should include the execution path");

            var failedResult = new YoloWorkerSmokeTestResult
            {
                Succeeded = false,
                Summary = "\uBAA8\uB378 \uC5F0\uACB0 \uC2E4\uD328"
            };
            AssertEqual(
                "\uCD94\uB860 \uC2E4\uD328: \uBAA8\uB378 \uC5F0\uACB0 \uC2E4\uD328 / 2.0s",
                WpfInferenceStatusPresentationService.BuildInteractiveCompletionCommandStatus(failedResult, "2.0s"));
            AssertEqual(
                "\uC2E4\uD328: \uBAA8\uB378 \uC5F0\uACB0 \uC2E4\uD328",
                WpfInferenceStatusPresentationService.BuildInteractiveCompletionInferenceStatus(failedResult, "2.0s"));
            string clippedFailure = WpfInferenceStatusPresentationService.BuildInteractiveDetectionFailureSummary(
                new YoloWorkerSmokeTestResult { Succeeded = false, Summary = new string('\uAC00', 100) });
            AssertTrue(clippedFailure.Length <= 83 && clippedFailure.EndsWith("...", StringComparison.Ordinal), "single-image failure summary should be clipped for the status chip");

            AssertEqual("\uAC80\uC0AC \uC774\uBBF8\uC9C0\uB97C \uCC3E\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4.", WpfInferenceStatusPresentationService.BuildWorkerImageMissingSummary());
            AssertTrue(
                WpfInferenceStatusPresentationService.BuildWorkerImageMissingError(Path.Combine(root, "missing.jpg")).Contains("missing.jpg", StringComparison.Ordinal),
                "missing-image worker error should include the image name/path context");
            AssertEqual(
                "\uD604\uC7AC \uC774\uBBF8\uC9C0 \uCD94\uB860 \uC900\uBE44 \uC911",
                WpfInferenceStatusPresentationService.BuildWorkerPreparingInferenceStatus(applyToCanvas: true, imagePath: string.Empty));
            AssertTrue(
                WpfInferenceStatusPresentationService.BuildWorkerPreparingInferenceStatus(applyToCanvas: false, imagePath: Path.Combine(root, "queue-a.jpg")).Contains("queue-a.jpg", StringComparison.Ordinal),
                "batch worker preparation status should include the current file");
            AssertEqual("\uCD94\uB860 \uC2E4\uD589\uAE30 \uC900\uBE44 \uC911...", WpfInferenceStatusPresentationService.BuildWorkerPreparingCommandStatus());
            AssertTrue(
                WpfInferenceStatusPresentationService.BuildWorkerConnectionFailureLog("2.0s").Contains("\uBAA8\uB378 \uC124\uC815", StringComparison.Ordinal),
                "worker connection failure log should tell the operator what to check");
            AssertEqual("AI \uCD94\uB860 \uC694\uCCAD \uC911...", WpfInferenceStatusPresentationService.BuildWorkerRequestCommandStatus());
            AssertEqual("\uCD94\uB860 \uAC80\uCD9C \uC2DC\uAC04 \uCD08\uACFC.", WpfInferenceStatusPresentationService.BuildWorkerTimedOutSummary());
            AssertEqual("\uCD94\uB860 \uAC80\uCD9C \uCDE8\uC18C.", WpfInferenceStatusPresentationService.BuildWorkerCanceledSummary());
            AssertEqual(
                "\uCD94\uB860 \uC644\uB8CC. \uBAA8\uB378:YOLO11 / yolo11n.pt / \uD6C4\uBCF4:3",
                WpfInferenceStatusPresentationService.BuildWorkerSuccessSummary("YOLO11 / yolo11n.pt", 3));
        }
        finally
        {
            DeleteDirectoryIfExists(root);
        }
    }

    private static void TestWpfInferenceStatusPresentationService()
    {
        string root = CreateTempRoot();
        try
        {
            string weightsPath = Path.Combine(root, "runs", "train", "exp7", "weights", "best.pt");
            Directory.CreateDirectory(Path.GetDirectoryName(weightsPath));
            File.WriteAllText(weightsPath, "weights");

            var settings = new PythonModelSettings { WeightsPath = weightsPath };
            string idleText = WpfInferenceStatusPresentationService.BuildStatusText("대기", settings, hasPendingModelCandidate: false);
            AssertTrue(idleText.Contains("대기", StringComparison.Ordinal), "inference status should keep the base state");
            AssertTrue(idleText.Contains("검사 모델", StringComparison.Ordinal), "inference status should show the current inspection model");
            AssertTrue(idleText.Contains("best.pt", StringComparison.Ordinal), "inference status should show the weights file name");

            string candidateText = WpfInferenceStatusPresentationService.BuildStatusText("검토 대기", settings, hasPendingModelCandidate: true);
            AssertTrue(candidateText.Contains("모델 후보", StringComparison.Ordinal), "inference status should distinguish an unsaved trained model candidate");

            string missingText = WpfInferenceStatusPresentationService.BuildStatusText("대기", new PythonModelSettings { WeightsPath = Path.Combine(root, "missing.pt") }, hasPendingModelCandidate: false);
            AssertTrue(missingText.Contains("검사 모델 없음", StringComparison.Ordinal), "inference status should tell the user when no inspection model is available");

            string toolTip = WpfInferenceStatusPresentationService.BuildToolTip("대기", settings, hasPendingModelCandidate: false);
            AssertTrue(toolTip.Contains(weightsPath, StringComparison.Ordinal), "inference status tooltip should keep the full model path");
        }
        finally
        {
            DeleteDirectoryIfExists(root);
        }
    }

    private static void TestWpfSingleDetectionManualStartupPath()
    {
        string source = ReadWpfLabelingShellWindowSources();
        string repositoryRoot = FindRepositoryRoot();
        string inferencePresentationSource = File.ReadAllText(Path.Combine(repositoryRoot, "0. UI", "9) WPF", "Services", "Detection", "WpfInferenceStatusPresentationService.cs"));

        AssertTrue(!source.Contains("WarmupPythonWorkerAsync", StringComparison.Ordinal), "WPF shell should not keep startup worker warm-up code");
        AssertTrue(!source.Contains("GetWorkerWarmupTimeoutMilliseconds", StringComparison.Ordinal), "WPF shell should not keep a separate startup warm-up timeout");
        AssertTrue(source.Contains("추론은 사용자가 명시적으로 실행", StringComparison.Ordinal), "startup should tell the user inference is manual");
        AssertTrue(source.Contains("RunInteractiveDetectionAsync(allowSmokeFallback: false)", StringComparison.Ordinal), "current-image detection should not use smoke fallback");
        AssertTrue(source.Contains("RunInteractiveDetectionAsync(item.ImagePath, allowSmokeFallback: false)", StringComparison.Ordinal), "selected-image detection should not use smoke fallback");
        AssertTrue(source.Contains("RunInteractiveDetectionAsync(allowSmokeFallback: true)", StringComparison.Ordinal), "YOLO diagnostic test may use smoke fallback");
        AssertTrue(source.Contains("GetInteractiveWorkerConnectTimeoutMilliseconds(allowSmokeFallback)", StringComparison.Ordinal), "single-image detection should pass its fallback contract to the interactive worker wait helper");
        AssertTrue(source.Contains("return GetWorkerConnectTimeoutMilliseconds();", StringComparison.Ordinal), "first interactive worker connection should allow model preload to finish");
        AssertTrue(source.Contains("if (allowSmokeFallback && !autoStartClient)", StringComparison.Ordinal), "manual-client diagnostic fallback should not wait through the full model-startup window");
        AssertTrue(source.Contains("Math.Clamp(detectionTimeoutSeconds, 1, 30) * 1000", StringComparison.Ordinal), "manual-client diagnostic fallback should use the bounded configured detection timeout");
        AssertTrue(!source.Contains("return 1500;", StringComparison.Ordinal), "current-image detection should allow enough time for a restarted trained-model worker to connect");
        AssertTrue(source.Contains("detectionTimeoutSeconds + 90", StringComparison.Ordinal), "worker startup should add model-load grace time before reporting a connection failure");
        AssertTrue(source.Contains("120, 300", StringComparison.Ordinal), "worker startup wait should allow slow CPU model loading before timing out");
        AssertTrue(source.Contains("FormatElapsed(totalStopwatch.Elapsed)", StringComparison.Ordinal), "single-image detection should log elapsed time for UX diagnostics");
        AssertTrue(source.Contains("GetInteractiveWorkerConnectTimeoutMilliseconds(allowSmokeFallback)", StringComparison.Ordinal), "single-image detection should tell the operator when it is waiting for the worker");
        AssertTrue(source.Contains("SetGlobalInferenceStatus(", StringComparison.Ordinal), "single-image detection should report request progress through the status surface");
        AssertTrue(source.Contains("result.CandidateCount", StringComparison.Ordinal), "single-image detection should show completion with candidate count");
        AssertTrue(source.Contains("BuildRuntimeModelLabel", StringComparison.Ordinal), "single-image detection should keep the runtime/model source in result summaries and logs");
        AssertTrue(source.Contains("modelSourceText", StringComparison.Ordinal), "single-image detection should reuse one runtime/model label instead of rebuilding display text in multiple places");
        AssertTrue(source.Contains("BuildWorkerSuccessSummary(modelSourceText, candidates.Count)", StringComparison.Ordinal), "worker detection should build success summaries outside the shell");
        AssertTrue(inferencePresentationSource.Contains("\\uBAA8\\uB378:{0} / \\uD6C4\\uBCF4:{1}", StringComparison.Ordinal), "single-image detection summary should include the runtime/model source before the candidate count");
        AssertTrue(source.Contains("BuildWorkerPreparingInferenceStatus(applyToCanvas, imagePath)", StringComparison.Ordinal), "worker preparing status should be built outside the shell");
        AssertTrue(source.Contains("BuildWorkerConnectionFailureLog(FormatElapsed(stopwatch.Elapsed))", StringComparison.Ordinal), "worker connection failure log should be built outside the shell");
        AssertTrue(source.Contains("BuildWorkerRequestCommandStatus()", StringComparison.Ordinal), "worker request command status should be built outside the shell");
        AssertTrue(source.Contains("BuildWorkerTimedOutSummary()", StringComparison.Ordinal), "worker timeout summary should be built outside the shell");
        AssertTrue(source.Contains("BuildWorkerCanceledSummary()", StringComparison.Ordinal), "worker cancellation summary should be built outside the shell");
        AssertTrue(!source.Contains("AI 추론 요청 중...", StringComparison.Ordinal), "WPF shell should not inline worker request status text");
        AssertTrue(!source.Contains("추론 취소", StringComparison.Ordinal), "WPF shell should not inline worker cancellation status text");
        AssertTrue(source.Contains("BuildInteractiveDetectionFailureSummary(result)", StringComparison.Ordinal), "single-image detection should surface the failure reason in status text");
        AssertTrue(source.Contains("BuildInteractiveCompletionCommandStatus(result, elapsed)", StringComparison.Ordinal), "single-image command status should be built outside the shell");
        AssertTrue(source.Contains("BuildInteractiveCompletionInferenceStatus(result, elapsed)", StringComparison.Ordinal), "top inference status should be built outside the shell");
        AssertTrue(source.Contains("BuildInteractiveCompletionLog(result, elapsed, inferencePathText)", StringComparison.Ordinal), "single-image completion log should be built outside the shell");
        AssertTrue(!source.Contains("string failureSummary = BuildInteractiveDetectionFailureSummary(result)", StringComparison.Ordinal), "WPF shell should not own interactive failure-summary variables");
        AssertTrue(source.Contains("bool shouldLoadTargetImage = applyToCanvas", StringComparison.Ordinal), "worker detection should not reload the already-active image and erase manual labels");
        AssertTrue(source.Contains("!string.Equals(result.ImagePath, activeImagePath", StringComparison.Ordinal), "smoke detection should preserve manual labels when the result is for the active image");
        AssertTrue(source.Contains("isBatchDetectionRunning = false", StringComparison.Ordinal), "batch detection should clear busy command status on completion");
        AssertTrue(source.Contains("TryStartImagePathDetection", StringComparison.Ordinal), "batch detection should use the path-based worker request");
