    }

    private static bool ContainsControlText(Control root, string text)
    {
        if (root == null)
        {
            return false;
        }

        foreach (Control control in root.Controls)
        {
            if (string.Equals(control.Text, text, StringComparison.Ordinal))
            {
                return true;
            }

            if (ContainsControlText(control, text))
            {
                return true;
            }
        }

        return false;
    }

    private static bool ContainsControlType<T>(Control root)
        where T : Control
    {
        if (root == null)
        {
            return false;
        }

        foreach (Control control in root.Controls)
        {
            if (control is T)
            {
                return true;
            }

            if (ContainsControlType<T>(control))
            {
                return true;
            }
        }

        return false;
    }

    private static void TestWpfImageQueueLoadsSupportedFiles()
    {
        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        string root = CreateTempRoot();
        try
        {
            using (Bitmap image = new Bitmap(4, 3))
            {
                image.Save(Path.Combine(root, "b.PNG"), System.Drawing.Imaging.ImageFormat.Png);
                image.Save(Path.Combine(root, "a.jpg"), System.Drawing.Imaging.ImageFormat.Jpeg);
                image.Save(Path.Combine(root, "c.tiff"), System.Drawing.Imaging.ImageFormat.Tiff);
            }

            File.WriteAllText(Path.Combine(root, "ignore.txt"), "not an image");

            WpfLabelingShellWindow window = new WpfLabelingShellWindow();
            try
            {
                TestSupport.ConfigureHeadlessWpfImageLoading(window);
                int count = window.LoadImageQueueFromRoot(root, loadFirstImage: false, refreshDetails: false);

                AssertEqual(3, count);
                AssertEqual(3, window.ImageQueueItems.Count);
                AssertEqual("a.jpg", window.ImageQueueItems[0].FileName);
                AssertEqual("b.PNG", window.ImageQueueItems[1].FileName);
                AssertEqual("c.tiff", window.ImageQueueItems[2].FileName);
                AssertEqual(root, window.ImageQueueViewModel.CurrentImageFolderPath);
                AssertTrue(window.ImageQueueViewModel.IsOpenCurrentImageFolderEnabled, "WPF image queue should enable current-folder open after loading a real image folder");
                AssertTrue(window.ImageQueueViewModel.CurrentImageFolderDisplayText.Contains(Path.GetFileName(root), StringComparison.Ordinal),
                    "WPF image queue should show the current folder location in the queue panel");
                PumpWpfDispatcher(TimeSpan.FromMilliseconds(20));
                var currentFolderText = (System.Windows.Controls.TextBlock)window.FindName("CurrentImageFolderPathText");
                var openCurrentFolderButton = (System.Windows.Controls.Control)window.FindName("OpenCurrentImageFolderButton");
                AssertTrue(currentFolderText != null && currentFolderText.Text.Contains(Path.GetFileName(root), StringComparison.Ordinal),
                    "WPF image queue current folder text was not visible after loading images");
                AssertTrue(openCurrentFolderButton != null && openCurrentFolderButton.IsEnabled,
                    "WPF image queue current-folder open button was not enabled after loading images");

                string activeImagePath = Path.Combine(root, "a.jpg");
                AssertTrue(window.TryLoadImage(activeImagePath), "WPF shell did not load the selected queue image");
                AssertEqual(System.Drawing.Imaging.PixelFormat.Format24bppRgb, CGlobal.Inst.ImageWorkspace.ActiveImage.PixelFormat);

                string nextRoot = Path.Combine(root, "next-root");
                string nextImagePath = Path.Combine(nextRoot, "next.png");
                Directory.CreateDirectory(nextRoot);
                using (Bitmap nextImage = new Bitmap(5, 4))
                {
                    nextImage.Save(nextImagePath, System.Drawing.Imaging.ImageFormat.Png);
                }

                int switchedCount = window.LoadImageQueueFromRoot(
                    nextRoot,
                    activeImagePath,
                    loadFirstImage: true,
                    refreshDetails: false);
                AssertEqual(1, switchedCount);
                AssertEqual(1, window.ImageQueueItems.Count);
                AssertEqual(nextImagePath, window.ImageQueueItems[0].ImagePath);
                AssertEqual(nextImagePath, GetPrivateField<string>(window, "activeImagePath"));
                AssertEqual(nextRoot, window.ImageQueueViewModel.CurrentImageFolderPath);

                string emptyRoot = Path.Combine(root, "empty-root");
                Directory.CreateDirectory(emptyRoot);
                int emptyCount = window.LoadImageQueueFromRoot(
                    emptyRoot,
                    nextImagePath,
                    loadFirstImage: true,
                    refreshDetails: false);
                AssertEqual(0, emptyCount);
                AssertEqual(0, window.ImageQueueItems.Count);
                AssertEqual(string.Empty, GetPrivateField<string>(window, "activeImagePath"));
                AssertEqual(System.Drawing.Size.Empty, GetPrivateField<System.Drawing.Size>(window, "activeImageSize"));
                AssertEqual(0, window.MainCanvasViewModel.LoadedTextureGroupCount);
                AssertTrue(CGlobal.Inst.ImageWorkspace.ActiveImage == null, "empty image root should clear the shared active image");
                AssertTrue(CDisplayManager.ImageSrc.Empty(), "empty image root should clear the display-manager image");

                CData previousData = CGlobal.Inst.Data;
                try
                {
                    string sourceRoot = Path.Combine(root, "operator-images");
                    string outputRoot = Path.Combine(root, "dataset-output");
                    Directory.CreateDirectory(sourceRoot);
                    var data = new CData();
                    data.ConfigureOutputRoot(outputRoot);
                    data.EnsureYoloOutputDirectories();
                    data.ProjectSettings.PythonModel.ImageRootPath = sourceRoot;
                    CreateVisualSmokeImage(Path.Combine(sourceRoot, "source-a.jpg"));
                    CreateVisualSmokeImage(Path.Combine(data.TrainImagesPath, "copied-a.jpg"));
                    CGlobal.Inst.Data = data;

                    string resolvedRoot = InvokePrivateResult<string>(window, "ResolveActiveDatasetImageRoot");
                    AssertEqual(sourceRoot, resolvedRoot);
                }
                finally
                {
                    CGlobal.Inst.Data = previousData;
                }
            }
            finally
            {
                window.Close();
            }
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestWpfImageQueueLargeFolderKeepsBulkAndLazyThumbnails()
    {
        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        string root = CreateTempRoot();
        try
        {
            const int imageCount = 1200;
            using (Bitmap image = new Bitmap(4, 3))
            {
                image.Save(Path.Combine(root, "queue-0000.jpg"), System.Drawing.Imaging.ImageFormat.Jpeg);
            }

            for (int i = 1; i < imageCount; i++)
            {
                File.WriteAllText(Path.Combine(root, $"queue-{i:0000}.jpg"), string.Empty);
            }

            WpfLabelingShellWindow window = new WpfLabelingShellWindow();
            try
            {
                var collectionActions = new List<NotifyCollectionChangedAction>();
                ((INotifyCollectionChanged)window.ImageQueueItems).CollectionChanged += (_, args) => collectionActions.Add(args.Action);

                Stopwatch stopwatch = Stopwatch.StartNew();
                int count = window.LoadImageQueueFromRoot(root, loadFirstImage: false, refreshDetails: false);
                stopwatch.Stop();

                AssertEqual(imageCount, count);
                AssertEqual(imageCount, window.ImageQueueItems.Count);
                AssertEqual(1, collectionActions.Count);
                AssertEqual(NotifyCollectionChangedAction.Reset, collectionActions[0]);

                FieldInfo thumbnailAttemptedField = typeof(WpfImageQueueItem).GetField(
                    "thumbnailLoadAttempted",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                AssertTrue(thumbnailAttemptedField != null, "WPF image queue thumbnail lazy flag was not found");
                AssertTrue(window.ImageQueueItems.All(item => !(bool)thumbnailAttemptedField.GetValue(item)),
                    "large queue load should not decode thumbnails before rows are realized");

                _ = window.ImageQueueItems[0].ThumbnailSource;
                AssertTrue((bool)thumbnailAttemptedField.GetValue(window.ImageQueueItems[0]),
                    "thumbnail should load lazily when a row binding asks for it");
                AssertTrue(window.ImageQueueItems.Skip(1).All(item => !(bool)thumbnailAttemptedField.GetValue(item)),
                    "loading one thumbnail should not decode the rest of a large queue");

                Console.WriteLine($"LARGE_QUEUE_LOAD_MS={stopwatch.Elapsed.TotalMilliseconds:0.0}; ITEMS={imageCount}; COLLECTION_ACTIONS={collectionActions.Count}");
                AssertTrue(stopwatch.Elapsed < TimeSpan.FromSeconds(5), "large image queue shell load became unexpectedly slow");
            }
            finally
            {
                window.Close();
            }
        }
        finally
        {
            DeleteTempRoot(root);
        }
    }

    private static void TestWpfImageQueueSaveUpdatesOnlyActiveRow()
    {
        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        CData previousData = CGlobal.Inst.Data;
        string root = CreateTempRoot();
        try
        {
            const int imageCount = 125;
            string imageRoot = Path.Combine(root, "images");
            string outputRoot = Path.Combine(root, "output");
            Directory.CreateDirectory(imageRoot);
            for (int index = 0; index < imageCount; index++)
            {
                CreateVisualSmokeImage(Path.Combine(imageRoot, $"save-{index:000}.jpg"), index + 1);
            }

            var data = new CData();
            data.ConfigureOutputRoot(outputRoot);
            data.EnsureYoloOutputDirectories();
            data.ProjectSettings.DatasetPurpose = LabelingDatasetPurpose.ObjectDetection;
            data.ProjectSettings.PythonModel.ImageRootPath = imageRoot;
            data.ProjectSettings.YoloDataset.ValidationPercent = 0;
            data.ProjectSettings.YoloDataset.TestPercent = 0;
            data.ClassNamedList.Add(new CClassItem { Text = "Defect", DrawColor = Color.LimeGreen });
            CGlobal.Inst.Data = data;

            WpfLabelingShellWindow window = new WpfLabelingShellWindow();
            try
            {
                TestSupport.ConfigureHeadlessWpfImageLoading(window);
                AssertEqual(imageCount, window.LoadImageQueueFromRoot(imageRoot, loadFirstImage: true, refreshDetails: false));
                PumpWpfDispatcher(TimeSpan.FromMilliseconds(100));

                string activePath = GetPrivateField<string>(window, "activeImagePath");
                int catalogVersion = GetPrivateField<int>(window, "imageQueueCatalogLoadVersion");
                WpfImageQueueItem[] originalItems = window.ImageQueueItems.ToArray();
                ICollectionView queueView = GetPrivateField<ICollectionView>(window, "imageQueueView");
                Predicate<object> originalFilter = queueView.Filter;
                int filterEvaluationCount = 0;
                queueView.Filter = value =>
                {
                    filterEvaluationCount++;
                    return originalFilter?.Invoke(value) ?? true;
                };
                PumpWpfDispatcher(TimeSpan.FromMilliseconds(20));

                var sourceActions = new List<NotifyCollectionChangedAction>();
                var viewActions = new List<NotifyCollectionChangedAction>();
                ((INotifyCollectionChanged)window.ImageQueueItems).CollectionChanged += (_, args) => sourceActions.Add(args.Action);
                ((INotifyCollectionChanged)queueView).CollectionChanged += (_, args) => viewActions.Add(args.Action);
                Size activeImageSize = GetPrivateField<Size>(window, "activeImageSize");

                for (int saveIndex = 0; saveIndex < 2; saveIndex++)
                {
                    sourceActions.Clear();
                    viewActions.Clear();
                    filterEvaluationCount = 0;

                    int offset = 20 + (saveIndex * 10);
                    window.MainCanvasViewModel.OnRoiAdded(
                        new CanvasRect<float>(offset, activeImageSize.Height - offset, offset + 40, activeImageSize.Height - offset - 40)
                        {
                            UniqueId = $"queue-local-create-{saveIndex}",
                            ShapeKind = CanvasRoiShapeKind.Rectangle
                        },
                        null);
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(50));

                    Console.WriteLine(
                        $"LABEL_CREATE_{saveIndex + 1}_SOURCE_RESETS={sourceActions.Count(action => action == NotifyCollectionChangedAction.Reset)}; "
                        + $"VIEW_RESETS={viewActions.Count(action => action == NotifyCollectionChangedAction.Reset)}; "
                        + $"FILTER_EVALUATIONS={filterEvaluationCount}; CATALOG_VERSION={GetPrivateField<int>(window, "imageQueueCatalogLoadVersion")}");

                    AssertTrue(!sourceActions.Contains(NotifyCollectionChangedAction.Reset),
                        "creating one label must not reset the image queue source collection");
                    AssertTrue(!viewActions.Contains(NotifyCollectionChangedAction.Reset),
                        "creating one label must not refresh and reset the entire image queue view");
                    AssertTrue(filterEvaluationCount < imageCount,
                        $"creating one label reevaluated the whole image queue filter: {filterEvaluationCount}/{imageCount}");
                    AssertEqual(catalogVersion, GetPrivateField<int>(window, "imageQueueCatalogLoadVersion"));
                    AssertEqual(imageRoot, window.ImageQueueViewModel.CurrentImageFolderPath);
                    AssertEqual(activePath, GetPrivateField<string>(window, "activeImagePath"));
                    AssertEqual(imageCount, window.ImageQueueItems.Count);
                    AssertTrue(originalItems.SequenceEqual(window.ImageQueueItems),
                        "creating one label must preserve every existing queue row instance");
                    WpfImageQueueItem activeItem = window.ImageQueueItems.Single(item =>
                        string.Equals(item.ImagePath, activePath, StringComparison.OrdinalIgnoreCase));
                    AssertTrue(activeItem.IsSaveRequired,
                        "the active queue row should show save-required after creating a label without rebuilding the queue");

                    sourceActions.Clear();
                    viewActions.Clear();
                    filterEvaluationCount = 0;

                    InvokePrivateResult<object>(window, "ExecuteSaveAnnotationsCommand");
                    PumpWpfDispatcher(TimeSpan.FromMilliseconds(50));

                    Console.WriteLine(
                        $"LABEL_SAVE_{saveIndex + 1}_SOURCE_RESETS={sourceActions.Count(action => action == NotifyCollectionChangedAction.Reset)}; "
                        + $"VIEW_RESETS={viewActions.Count(action => action == NotifyCollectionChangedAction.Reset)}; "
                        + $"FILTER_EVALUATIONS={filterEvaluationCount}; CATALOG_VERSION={GetPrivateField<int>(window, "imageQueueCatalogLoadVersion")}");

                    AssertTrue(!sourceActions.Contains(NotifyCollectionChangedAction.Reset),
                        "saving one label must not reset the image queue source collection");
                    AssertTrue(!viewActions.Contains(NotifyCollectionChangedAction.Reset),
                        "saving one label must not refresh and reset the entire image queue view");
                    AssertTrue(filterEvaluationCount < imageCount,
                        $"saving one label reevaluated the whole image queue filter: {filterEvaluationCount}/{imageCount}");
                    AssertEqual(catalogVersion, GetPrivateField<int>(window, "imageQueueCatalogLoadVersion"));
                    AssertEqual(imageRoot, window.ImageQueueViewModel.CurrentImageFolderPath);
                    AssertEqual(activePath, GetPrivateField<string>(window, "activeImagePath"));
                    AssertEqual(imageCount, window.ImageQueueItems.Count);
                    AssertTrue(originalItems.SequenceEqual(window.ImageQueueItems),
                        "saving one label must preserve every existing queue row instance");
                    activeItem = window.ImageQueueItems.Single(item =>
                        string.Equals(item.ImagePath, activePath, StringComparison.OrdinalIgnoreCase));
                    AssertTrue(activeItem.IsLabeled && !activeItem.IsSaveRequired,
                        "the active queue row should show the saved label without rebuilding the queue");
                }
            }
            finally
            {
                window.Close();
            }
        }
        finally
        {
            CGlobal.Inst.Data = previousData;
            DeleteTempRoot(root);
        }
    }

    private static void TestWpfImageQueueTenThousandAsyncCatalogLoad()
    {
        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        const int imageCount = 10_000;
        string root = CreateTempRoot();
        string replacementRoot = CreateTempRoot();
        CData previousData = CGlobal.Inst.Data;
        try
        {
            var data = new CData();
            data.ConfigureOutputRoot(Path.Combine(root, "output"));
            CGlobal.Inst.Data = data;
            for (int index = 0; index < imageCount; index++)
            {
                File.WriteAllText(Path.Combine(root, FormattableString.Invariant($"queue-{index:00000}.jpg")), string.Empty);
            }

            for (int index = 0; index < 3; index++)
            {
                File.WriteAllText(Path.Combine(replacementRoot, FormattableString.Invariant($"replacement-{index:00}.jpg")), string.Empty);
            }

            WpfLabelingShellWindow window = new WpfLabelingShellWindow();
            try
            {
                var collectionActions = new List<NotifyCollectionChangedAction>();
                ((INotifyCollectionChanged)window.ImageQueueItems).CollectionChanged += (_, args) => collectionActions.Add(args.Action);

                Stopwatch startStopwatch = Stopwatch.StartNew();
                Task<int> loadTask = window.LoadImageQueueFromRootAsync(root, loadFirstImage: false, refreshDetails: false);
                startStopwatch.Stop();
                AssertTrue(startStopwatch.Elapsed < TimeSpan.FromMilliseconds(250),
                    "10K queue command should return to the dispatcher before catalog enumeration completes");

                bool inputProbeRan = false;
                window.Dispatcher.BeginInvoke(
                    System.Windows.Threading.DispatcherPriority.Input,
                    new Action(() => inputProbeRan = true));
                AssertTrue(WaitUntilWpf(() => inputProbeRan, TimeSpan.FromSeconds(2)),
                    "dispatcher input should run while the 10K catalog is loading");
                AssertTrue(WaitUntilWpf(() => loadTask.IsCompleted, TimeSpan.FromSeconds(30)),
                    "10K image queue catalog did not complete");

                AssertEqual(imageCount, loadTask.GetAwaiter().GetResult());
                AssertEqual(imageCount, window.ImageQueueItems.Count);
                AssertEqual(1, collectionActions.Count);
                AssertEqual(NotifyCollectionChangedAction.Reset, collectionActions[0]);

                FieldInfo thumbnailAttemptedField = typeof(WpfImageQueueItem).GetField(
                    "thumbnailLoadAttempted",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                AssertTrue(thumbnailAttemptedField != null, "WPF image queue thumbnail lazy flag was not found");
                AssertTrue(window.ImageQueueItems.All(item => !(bool)thumbnailAttemptedField.GetValue(item)),
                    "10K catalog loading should not decode thumbnails before rows are realized");

                Task<int> supersededTask = window.LoadImageQueueFromRootAsync(root, loadFirstImage: false, refreshDetails: false);
                Task<int> replacementTask = window.LoadImageQueueFromRootAsync(replacementRoot, loadFirstImage: false, refreshDetails: false);
                AssertTrue(WaitUntilWpf(() => replacementTask.IsCompleted, TimeSpan.FromSeconds(30)),
                    "replacement image queue catalog did not complete");
                AssertTrue(WaitUntilWpf(() => supersededTask.IsCompleted, TimeSpan.FromSeconds(30)),
                    "superseded image queue catalog did not finish after cancellation");

                AssertEqual(3, replacementTask.GetAwaiter().GetResult());
                AssertEqual(3, window.ImageQueueItems.Count);
                AssertTrue(window.ImageQueueItems.All(item => item.ImagePath.StartsWith(replacementRoot, StringComparison.OrdinalIgnoreCase)),
                    "a superseded catalog result must not overwrite the replacement queue");

                Console.WriteLine($"ASYNC_10K_QUEUE_START_MS={startStopwatch.Elapsed.TotalMilliseconds:0.0}; ITEMS={imageCount}; REPLACEMENT_ITEMS={window.ImageQueueItems.Count}");
            }
            finally
            {
                window.Close();
            }
        }
        finally
        {
            CGlobal.Inst.Data = previousData;
            DeleteTempRoot(root);
            DeleteTempRoot(replacementRoot);
        }
    }

    private static void TestWpfImageQueueTenThousandDetailRefreshKeepsDispatcherResponsive()
    {
        if (System.Windows.Application.Current == null)
        {
            _ = new System.Windows.Application
            {
                ShutdownMode = System.Windows.ShutdownMode.OnExplicitShutdown
            };
        }

        const int imageCount = 10_000;
        string root = CreateTempRoot();
        CData previousData = CGlobal.Inst.Data;
        try
        {
            string seedImagePath = Path.Combine(root, "detail-00000.jpg");
            using (Bitmap image = new Bitmap(4, 3))
            {
                image.Save(seedImagePath, System.Drawing.Imaging.ImageFormat.Jpeg);
            }

            for (int index = 1; index < imageCount; index++)
            {
                File.Copy(seedImagePath, Path.Combine(root, FormattableString.Invariant($"detail-{index:00000}.jpg")));
            }

            var data = new CData();
            data.ConfigureOutputRoot(Path.Combine(root, "output"));
            CGlobal.Inst.Data = data;

            WpfLabelingShellWindow window = new WpfLabelingShellWindow();
            try
            {
                Stopwatch totalScanStopwatch = Stopwatch.StartNew();
                Task<int> catalogTask = window.LoadImageQueueFromRootAsync(root, loadFirstImage: false, refreshDetails: true);
                AssertTrue(WaitUntilWpf(() => catalogTask.IsCompleted, TimeSpan.FromSeconds(30)),
                    "10K image queue catalog did not complete before detail responsiveness verification");
                AssertEqual(imageCount, catalogTask.GetAwaiter().GetResult());

                Task detailTask = GetPrivateField<Task>(window, "imageQueueDetailLoadTask");
                AssertTrue(detailTask != null, "10K image queue detail refresh task was not started");
                AssertTrue(WaitUntilWpf(
                        () => window.StatusBarViewModel.DatasetStatusText.Contains("\uC0C1\uD0DC \uD655\uC778", StringComparison.Ordinal),
                        TimeSpan.FromSeconds(10)),
                    "10K detail refresh should show its progress in the visible dataset status");

                ICollectionView queueView = GetPrivateField<ICollectionView>(window, "imageQueueView");
                Predicate<object> originalQueueFilter = queueView.Filter;
                int filterEvaluationCount = 0;
                queueView.Filter = value =>
                {
                    filterEvaluationCount++;
                    return originalQueueFilter?.Invoke(value) ?? true;
                };
                PumpWpfDispatcher(TimeSpan.FromMilliseconds(100));
                filterEvaluationCount = 0;

                bool detailWasRunningAtProbe = !detailTask.IsCompleted;
                bool inputProbeRan = false;
                Stopwatch inputStopwatch = Stopwatch.StartNew();
                window.Dispatcher.BeginInvoke(
                    System.Windows.Threading.DispatcherPriority.Input,
                    new Action(() => inputProbeRan = true));
                AssertTrue(WaitUntilWpf(() => inputProbeRan, TimeSpan.FromSeconds(2)),
                    "dispatcher input did not run while the 10K detail refresh was active");
                inputStopwatch.Stop();
                AssertTrue(inputStopwatch.Elapsed < TimeSpan.FromSeconds(2),
                    "10K detail refresh delayed dispatcher input unexpectedly");

                AssertTrue(WaitUntilWpf(() => detailTask.IsCompleted, TimeSpan.FromSeconds(120)),
                    "10K image queue detail refresh did not complete");
                AssertTrue(filterEvaluationCount <= imageCount * 12,
                    "10K detail refresh should not repeatedly re-evaluate the full filtered view");
                AssertTrue(window.ImageQueueItems.All(item => string.Equals(item.Dimensions, "4x3", StringComparison.Ordinal)),
                    "10K detail refresh did not apply image dimensions to every queue row");

                totalScanStopwatch.Stop();
                Console.WriteLine($"DETAIL_10K_TOTAL_MS={totalScanStopwatch.Elapsed.TotalMilliseconds:0.0}; DETAIL_10K_INPUT_MS={inputStopwatch.Elapsed.TotalMilliseconds:0.0}; DETAIL_RUNNING_AT_PROBE={detailWasRunningAtProbe}; FILTER_EVALUATIONS={filterEvaluationCount}; ITEMS={imageCount}");
            }
            finally
            {
                window.Close();
            }
        }
        finally
        {
            CGlobal.Inst.Data = previousData;
            DeleteTempRoot(root);
        }
    }

