            AssertEqual(1, CDisplayManager.LayerCount);
            AssertEqual("Main", CDisplayManager.GetLayerTitle(0));
            AssertEqual(1, CDisplayManager.GetMainDisplayOrNull().DetectionOverlayCount);
        }
        finally
